    /// XRV1-L125: stage a probe fd at `target` (high —
    /// past the old 8192 fallback cap): wait out a
    /// sibling's fd-table confinement first (bounded
    /// 60s — mirrors stage_high_leak_copy's wait-out —
    /// a concurrent confine-apply would move the
    /// ceiling under the gate), then capacity-gate
    /// (ambient soft ≤ target ⟹ loud skip
    /// (constrained runner — R20-015 precedent),
    /// never fail), then F_DUPFD-stage `src`. No hold
    /// needed after (every verdict below is
    /// table-driven (fcntl/getdents) — a later sibling
    /// confine-lowering cannot corrupt it). None ⟹
    /// caller returns (skip printed).
    #[cfg(target_arch = "x86_64")]
    fn stage_high_shed_probe_fd(
        src: libc::c_int,
        target: libc::c_int,
    ) -> Option<std::os::unix::io::OwnedFd> {
        use std::os::unix::io::FromRawFd as _;
        use std::time::{Duration, Instant};
        let end = Instant::now() + Duration::from_secs(60);
        loop {
            let slot = CONFINEMENT_STATE
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if slot.is_some() {
                drop(slot);
                if Instant::now() >= end {
                    eprintln!("skip: confinement held past 60s (high-fd probe unstageable)");
                    return None;
                }
                std::thread::sleep(Duration::from_millis(10));
                continue;
            }
            // SAFETY: getrlimit on self only.
            let mut rlim = libc::rlimit {
                rlim_cur: 0,
                rlim_max: 0,
            };
            let rc = unsafe { libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) };
            // (Boundary exclusive — fd N needs soft > N.)
            if rc != 0 || rlim.rlim_cur <= target as u64 {
                let soft = if rc == 0 { rlim.rlim_cur } else { 0 };
                eprintln!(
                    "skip: soft NOFILE {soft} ≤ {target} (high-fd probe unstageable on a constrained runner)"
                );
                return None;
            }
            // SAFETY: duplicates our own open end; the
            // slot-empty serial holds the ceiling stable
            // across gate→fcntl (a confine-apply needs
            // this lock). Plain F_DUPFD (NO cloexec — a
            // cloexec probe would vanish at exec (vacuous
            // for exec paths) — the shed (not cloexec)
            // must close it).
            let hi = unsafe { libc::fcntl(src, libc::F_DUPFD, target) };
            drop(slot);
            if hi < 0 {
                eprintln!("skip: high-fd stage refused (transient table churn?)");
                return None;
            }
            assert!(hi >= target, "high probe fd staged (fd {hi})");
            // SAFETY: fcntl reported success — owned.
            return Some(unsafe { std::os::unix::io::OwnedFd::from_raw_fd(hi) });
        }
    }
