    /// XRV1-L119 P119b probe body (fresh image,
    /// SCOPEBASE_L119B_STEERED_STRANGER=1): the
    /// unreadable-at-arm twin of the v3 staged
    /// murder — arm bare under outage on a freed
    /// number, steer a live replacement onto it,
    /// drop: the stranger MUST survive (pre-fix
    /// the blind drop murdered it). Steering
    /// refused/contended ⟹ loud skip.
    #[cfg(target_arch = "x86_64")]
    fn l119b_steered_stranger_probe() {
        let Some(_serial) = steer_hold() else {
            eprintln!("STAGING-L119B skip: no reuse control");
            return;
        };
        // Birth B1 at X, then reap (X freed).
        let mut b1 = std::process::Command::new("/bin/sh")
            .arg("-c")
            .arg("exit 7")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("B1 spawns");
        let want = b1.id() as libc::pid_t;
        // XRV1-L130: custody BEFORE the fallible
        // identity reads (an expect panic with only
        // the silent Child handle strands a live B1
        // — the guard retires on unwind).
        let mut bguard = FixtureGuard::new(want);
        let orig_tick = proc_starttime(want)
            .expect("B1 stat readable")
            .expect("B1 visible");
        let status = b1.wait().expect("B1 reaps");
        // XRV1-L122: disarm on CONFIRMED discharge
        // (the wait reaped B1) BEFORE judging.
        bguard.disarm();
        assert_eq!(status.code(), Some(7), "B1 was ours");
        assert_eq!(proc_starttime(want), Ok(None), "number must free");
        // Outage, then arm bare (read fails ⟹
        // disarm loud).
        let _confined = confine_fd_table_for_exhaustion();
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "fault hold must consume fds");
        assert!(
            proc_starttime(want).is_err(),
            "staging broken (outage must break reads)"
        );
        let guard = FixtureGuard::new(want);
        assert!(guard.tick.is_none(), "guard must be tickless (outage)");
        assert!(
            guard.disarmed,
            "bare construction must disarm on unreadable"
        );
        // Release (steering needs fds to spawn).
        drop(held);
        drop(_confined);
        // Different jiffy (isolates the None path
        // from same-tick residuals).
        std::thread::sleep(std::time::Duration::from_millis(20));
        // Steer a live replacement onto X.
        let mut sleep = match steer_sleep_onto(want, false) {
            Some(sleep) => sleep,
            None => {
                eprintln!("STAGING-L119B skip: replacement steer contended");
                return;
            }
        };
        // XRV1-L130: custody BEFORE the fallible
        // identity reads (never panics — ticked —
        // the bounded-loop drop retires on unwind
        // (strictly stronger than the old
        // single-attempt KillOnDrop it replaces)).
        let _backstop = FixtureGuard::new(want);
        let retick = proc_starttime(want)
            .expect("replacement stat readable")
            .expect("replacement visible");
        if retick == orig_tick {
            let _ = sleep.kill();
            let _ = sleep.wait();
            eprintln!("STAGING-L119B skip: same-tick retake (untestable this run)");
            return;
        }
        // THE DROP (the murder moment pre-fix).
        drop(guard);
        // The stranger must SURVIVE settled-live.
        // SAFETY: kill(want, 0) (existence probe).
        let alive = unsafe { libc::kill(want, 0) } == 0;
        assert!(
            alive && proc_starttime(want) == Ok(Some(retick)),
            "stranger must survive the blind-abandon drop (murdered?)"
        );
        // Explicit cleanup (the backstop no-ops).
        let _ = sleep.kill();
        let _ = sleep.wait();
        eprintln!("STAGING-L119B stranger-survived");
    }

