    /// XRV1-L120 P120a: a co-armed owner whose
    /// FixtureGuard retired first stands DOWN
    /// (tick-gated — no blind signal+wait on the
    /// freed number): arm owner+guard, drop the
    /// guard (retires ours), steer a live
    /// replacement onto the number, drop the
    /// owner — the stranger MUST survive
    /// (pre-fix the blind drop murdered it).
    /// In-suite (no outage needed); steering
    /// refused/contended ⟹ loud skip.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn l120a_owner_drop_stands_down_after_guard_retired() {
        let Some(_serial) = steer_hold() else {
            return;
        };
        let child = std::process::Command::new("/bin/sleep")
            .arg("185")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("sleeper spawns");
        let pid = child.id() as libc::pid_t;
        // XRV1-L130: custody BEFORE the fallible
        // identity reads (an expect panic with only
        // the silent Child handle strands a live
        // sleeper — transferred below).
        let mut bguard = FixtureGuard::new(pid);
        let orig_tick = proc_starttime(pid)
            .expect("sleeper stat readable")
            .expect("sleeper visible");
        // Co-armed (the L120 shape: owner FIRST,
        // guard SECOND (guard drops first)).
        let owner = UnpinnedStagingOwner::new(child);
        let guard = FixtureGuard::new(pid);
        // Custody TRANSFERRED (owner+guard cover
        // everything below — the bridge stands
        // down).
        bguard.disarm();
        // XRV1-L131: retain the proof pin BEFORE
        // the retire (vacancy asserts break on
        // legitimate replacement — the pin names
        // OUR birth).
        // SAFETY: pidfd_open success ⟹ owned fd.
        use std::os::unix::io::FromRawFd as _;
        let proof_pin = unsafe {
            std::os::unix::io::OwnedFd::from_raw_fd(
                super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (proof pin)"),
            )
        };
        // Guard retires FIRST (explicit — the
        // L120 unwind order).
        drop(guard);
        // Retired ⟹ the pin proves OUR birth
        // consumed (ECHILD — replacement-immune).
        // SAFETY: own pidfd + zeroed siginfo +
        // probe flags (WNOHANG — never blocks).
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                std::os::unix::io::AsRawFd::as_raw_fd(&proof_pin) as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            (ret, std::io::Error::last_os_error().raw_os_error())
        };
        drop(proof_pin);
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "guard must have retired ours (pin-proof ECHILD)"
        );
        // Different jiffy (isolates from
        // same-tick residuals).
        std::thread::sleep(std::time::Duration::from_millis(20));
        // Steer a live replacement onto the
        // freed number.
        let mut sleep = match steer_sleep_onto(pid, false) {
            Some(sleep) => sleep,
            None => {
                eprintln!("skip: replacement steer contended");
                return;
            }
        };
        // XRV1-L130: custody BEFORE the fallible
        // identity reads (never panics — ticked —
        // the bounded-loop drop retires on unwind
        // (strictly stronger than the old
        // single-attempt KillOnDrop it replaces)).
        let _backstop = FixtureGuard::new(pid);
        let retick = proc_starttime(pid)
            .expect("replacement stat readable")
            .expect("replacement visible");
        if retick == orig_tick {
            let _ = sleep.kill();
            let _ = sleep.wait();
            eprintln!("skip: same-tick retake (S100 — untestable this run)");
            return;
        }
        // THE DROP (the murder moment pre-fix).
        drop(owner);
        // The stranger must SURVIVE settled-live.
        // SAFETY: kill(pid, 0) (existence probe).
        let alive = unsafe { libc::kill(pid, 0) } == 0;
        assert!(
            alive && proc_starttime(pid) == Ok(Some(retick)),
            "stranger must survive the stood-down owner drop (murdered?)"
        );
        // Explicit cleanup (the backstop no-ops).
        let _ = sleep.kill();
        let _ = sleep.wait();
    }

