    /// R20-011: forced post-parent-death placement failures
    /// must retire orphaned c1 before the skip returns — the
    /// seam orphans c1 (kills+reaps pub1), then the
    /// steering-fail and misplaced-reform paths skipped with
    /// c1 live (912s strand holding a spent write end). Runs
    /// the pin-failure probe twice (pre-steer and post-spawn
    /// forcing — both post-parent-death shapes) and requires
    /// the skip + the c1-retired citation each time. RED
    /// (this shape): the skip returns with no citation (c1
    /// stranded). GREEN: explicit skip-path cleanup cites.
    /// Environmental probe skips propagate as skips; a
    /// citation-less placement skip fails.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pin_failure_skip_retires_orphaned_c1() {
        if std::fs::read_to_string("/proc/sys/kernel/ns_last_pid").is_err() {
            eprintln!("skip: ns_last_pid unreadable (no reuse control)");
            return;
        }
        for mode in ["pre-steer", "post-spawn"] {
            let exe = std::env::current_exe().expect("own test binary");
            let mut out = std::process::Command::new(exe);
            out.arg("--exact")
                .arg("fixture::linux::audit::tests::frame_pin_failure_reverifies_before_keeping_union")
                .arg("--nocapture")
                .env("SCOPEBASE_R19003_PINFAIL", "1")
                .env("SCOPEBASE_R20011_FORCE_MISS", mode)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            // L144: pre-exec IGN (a group-HUP
            // mid-startup murders default probes).
            arm_hup_immune_spawn(&mut out);
            let out = out.output().expect("probe child runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            assert!(
                out.status.success(),
                "probe must complete the forced-miss case ({mode})\n{stderr}"
            );
            if stderr.contains("R20011-C1-RETIRED") {
                assert!(
                    stderr.contains("skip: replacement steering missed"),
                    "forced miss must still skip ({mode})\n{stderr}"
                );
                continue;
            }
            // No citation: environmental skips propagate;
            // a citation-less placement skip fails.
            if stderr.lines().any(|line| {
                line.contains("skip: ns_last_pid unreadable")
                    || line.contains("skip: ns_last_pid unwritable")
            }) {
                eprintln!("skip (probe environmental, {mode})");
                continue;
            }
            panic!("forced miss skipped without retiring c1 ({mode})\n{stderr}");
        }
    }

    /// R21-011 outage probe (fresh-image: exhausts the fd
    /// table — the limit dies with the probe). Under held
    /// EMFILE every stat read errors (a genuine observation
    /// outage over a LIVE fixture): (a) the
    /// birth-retirement await must fail loud (never certify
    /// retirement — the old break-on-Err cited
    /// R20011-C1-RETIRED over a possibly-live c1); (b) the
    /// stray park must report unresolved (never claim
    /// parked), for known AND unknown birth. Duration 930
    /// is unique to this test.
    #[cfg(target_arch = "x86_64")]
    fn outage_oracles_refuse_to_certify_probe() {
        let _confined = confine_fd_table_for_exhaustion();
        let mut child = std::process::Command::new("/bin/sleep")
            .arg("930")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("sleeper spawns");
        let pid = child.id() as libc::pid_t;
        // R22-014: guard at birth (pre-exhaust — the tick
        // read below must not strand the sleeper; no
        // unwind path exists under EMFILE here (the await
        // is caught, parks return, drop/kill/wait are
        // infallible), so the drop always verifies).
        let mut _guard = FixtureGuard::new(pid);
        let tick = proc_starttime(pid)
            .expect("sleeper stat readable")
            .expect("sleeper visible");
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "exhaustion must consume fds");
        // (a): the await must panic (loud), never certify.
        let failed_loud = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            await_birth_retired(pid, tick, false, Duration::from_secs(5), "probe fixture")
        })) {
            Err(payload) => payload
                .downcast_ref::<String>()
                .is_some_and(|message| message.contains("unreadable")),
            Ok(_) => false,
        };
        // (b): the park must report unresolved, never parked.
        let parked_known = park_stray_bounded(pid, Some(tick), Duration::from_millis(200));
        let parked_unknown = park_stray_bounded(pid, None, Duration::from_millis(200));
        drop(held);
        let _ = kill_tick_gated(pid, tick);
        let _ = child.wait();
        _guard.disarm();
        assert!(
            failed_loud,
            "(a) outage must fail loud on unreadable retirement, never certify"
        );
        assert!(!parked_known, "(b) outage must not park a known birth");
        assert!(!parked_unknown, "(b) outage must not park an unknown birth");
        eprintln!("R21011-OUTAGE-DONE");
    }

