    /// XRV1-L132 denymap probe body (fresh image,
    /// SCOPEBASE_STAGING_CONSUME_DENYMAP=1) — under a
    /// deny-ALL-waitid filter the middle-consume must
    /// map EPERM ⟹ EIO (Some — verdict unproven,
    /// never a hang/crash/wrong errno) and the middle
    /// must EXIT (its work done — the status is
    /// unreadable, not the birth unretired). The
    /// zombie LINGERS soundly (deny-all forbids every
    /// reap route — numeric wait is recycle-unsound;
    /// image exit reaps via init) — so NO census
    /// sweep (a Z-stray assert would false-RED);
    /// instead the probe polls the middle to Z (its
    /// exit proves the linger is a status-outage, not
    /// a wedged birth). The middle stages UNFILTERED
    /// (its spawn needs waitid) — the deny lands only
    /// over the consume.
    #[cfg(target_arch = "x86_64")]
    fn consume_denymap_probe() {
        use super::super::seccomp::{install_deny_one, DenyAction};
        // XRV1-L127: capability gate FIRST (a
        // pidfd/waitid-denied host skips loud — the
        // middle stages unfiltered (needs a pin)).
        if probe_waitid_capability() != ProbeVerdict::Supported {
            eprintln!("STAGING-CONSUME-DENYMAP skip: no pidfd+waitid power");
            return;
        }
        let (middle, pin) = spawn_held_fork_child(qualify_middle_body, false, "denymap middle")
            .expect("staging broken (denymap spawn)");
        if install_deny_one(libc::SYS_waitid, DenyAction::Eperm).is_err() {
            // Filter unavailable (container shape) —
            // retire the middle PLAIN (no filter: kill
            // + waitpid are unfiltered) then skip loud.
            // SAFETY: SIGKILL to our own unreaped middle.
            unsafe {
                libc::kill(middle, libc::SIGKILL);
            }
            let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                let mut st = 0;
                // SAFETY: waitpid on our own middle.
                let got = unsafe { libc::waitpid(middle, &mut st, libc::WNOHANG) };
                if got == middle || got < 0 || std::time::Instant::now() >= end {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            eprintln!("STAGING-CONSUME-DENYMAP skip: waitid deny-all would not install");
            return;
        }
        let verdict = consume_middle_through_pin(&pin);
        assert_eq!(verdict, Some(libc::EIO), "denied consume must map EIO");
        // The middle must EXIT (bounded Z-poll — it
        // exits in ms; expiry is loud, never a pass).
        let zend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(middle) == Some('Z') {
                break;
            }
            assert!(
                std::time::Instant::now() < zend,
                "staging broken (denymap middle never exits)"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        eprintln!("STAGING-CONSUME-DENYMAP denied-maps-eio");
    }

