    /// XRV1-L132 hang-pin probe body (fresh image,
    /// SCOPEBASE_STAGING_CONSUME_HANG=1 (+ PARK=1 +
    /// BOUND=2s)): a parked middle (never surfaces)
    /// must EIO at the bound (elapsed in [2s, 15s) —
    /// the lower edge proves the bound FIRED (not an
    /// instant fail); the upper edge proves BOUNDED
    /// (not a hang)) with the middle RETIRED (the
    /// pin guard kills + reaps — census-clean).
    /// Cleanup-before-judge (a guard failure leaves
    /// a LIVE parked middle holding this image's
    /// pipes — asserting first would wedge the
    /// driver's EOF (the D1 shape — observed under
    /// MZ2): the probe snapshots the survivors,
    /// retires them ALL, then judges the memory (a
    /// regression REDs clean instead of wedging).
    /// No skip shape (no fallible staging — PARK
    /// always parks).
    #[cfg(target_arch = "x86_64")]
    fn consume_hang_probe() {
        // XRV1-L127: capability gate FIRST (a
        // pidfd/waitid-denied host skips loud — the
        // qualifier needs a pin).
        if probe_waitid_capability() != ProbeVerdict::Supported {
            eprintln!("STAGING-CONSUME-HANG skip: no pidfd+waitid power");
            return;
        }
        let t0 = std::time::Instant::now();
        let verdict = waitid_pidfd_sigkill_qualify_errno();
        let elapsed = t0.elapsed();
        // Snapshot + REMEMBER (no assert yet!) +
        // retire-all (sole waiter — this fresh image
        // forked nothing else — numeric wait SOUND).
        let survivors = live_own_children();
        let leaked = !survivors.is_empty();
        for (pid, _state) in &survivors {
            // SAFETY: SIGKILL to our own probe-image
            // children (unreaped ⟹ ours).
            unsafe { libc::kill(*pid, libc::SIGKILL) };
        }
        let rend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let mut st = 0;
            // SAFETY: waitpid(-1) WNOHANG on our own
            // children (sole waiter — consumes OURS
            // or ECHILDs (done)).
            let got = unsafe { libc::waitpid(-1, &mut st, libc::WNOHANG) };
            if got < 0 {
                if std::io::Error::last_os_error().raw_os_error() == Some(libc::EINTR) {
                    continue;
                }
                break;
            }
            if live_own_children().is_empty() {
                break;
            }
            if std::time::Instant::now() >= rend {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert_eq!(
            verdict,
            Some(libc::EIO),
            "parked middle must EIO at the bound"
        );
        assert!(
            elapsed >= std::time::Duration::from_millis(1900),
            "bound must FIRE (not instant): elapsed {elapsed:?}"
        );
        assert!(
            elapsed < std::time::Duration::from_secs(15),
            "consume must be BOUNDED (not a hang): elapsed {elapsed:?}"
        );
        // Judge the MEMORY (the guard's work — the
        // retire-all above already un-wedged EOF, so
        // a regression REDs clean here).
        assert!(
            !leaked,
            "guard must retire the parked middle (leaked: {survivors:?})"
        );
        // Post-cleanup census (the retire-all must
        // have worked — else THIS image litters).
        assert_no_live_own_children("consume-hang probe");
        eprintln!("STAGING-CONSUME-HANG bound-fired-retired");
    }

