    /// XRV1-L118 theft pin probe body (fresh image,
    /// SCOPEBASE_STAGING_QUALIFY_THEFT=1 (+ WIDEN=1)):
    /// a poll-steal main thread (waitpid(-1) every
    /// 10ms inside three 800ms windows) must NOT
    /// flip the qualifier (isolated (sole-waiter
    /// child + pin-supervised helper) ⟹ TRUE, zero
    /// stolen). Pre-fix RED: all three sacrificials
    /// stolen ⟹ ECHILD x3 ⟹ FALSE. Windows
    /// ([0,800], [1000,1800], [2000,2800]ms) sit
    /// inside each attempt's hook-widened kill→poll
    /// gap ([k·1000, k·1000+1000]ms) with 200ms
    /// margins both sides (pre-fix: the zombie sits
    /// the whole gap (stolen within 10ms of
    /// appearance); post-fix: the helper exits at
    /// ~1000ms (hook!) — polls stop 200ms before
    /// its zombie can exist (never touch it)).
    #[cfg(target_arch = "x86_64")]
    fn qualify_theft_probe() {
        // XRV1-L127: capability gate FIRST (a
        // pidfd/waitid-denied host skips loud — the
        // qualifier needs a pin).
        if probe_waitid_capability() != ProbeVerdict::Supported {
            eprintln!("STAGING-QUALIFY-THEFT skip: no pidfd+waitid power");
            return;
        }
        let t0 = std::time::Instant::now();
        // Qualifier thread (the victim pre-fix!).
        let handle = std::thread::spawn(qualify_numeric_retire);
        let windows = [(0, 800), (1000, 1800), (2000, 2800)];
        let mut stolen = 0u32;
        for (wstart, wend) in windows {
            loop {
                let ms = t0.elapsed().as_millis() as u64;
                if ms >= wend {
                    break;
                }
                if ms >= wstart {
                    let mut st = 0;
                    // SAFETY: waitpid(-1) WNOHANG (this
                    // fresh image's children only — no
                    // suite siblings to touch).
                    let got = unsafe { libc::waitpid(-1, &mut st, libc::WNOHANG) };
                    if got > 0 {
                        stolen += 1;
                    }
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
        }
        let qualified = handle.join().expect("qualifier thread joins");
        eprintln!("qualifier-theft pin: stole {stolen} statuses");
        assert!(qualified, "qualifier must survive poll-steal (isolated!)");
        assert_eq!(
            stolen, 0,
            "isolated qualifier loses zero statuses to same-process sweepers"
        );
        assert_no_live_own_children("qualify-theft probe");
        eprintln!("STAGING-QUALIFY-THEFT isolated-survives-steal");
    }

