    /// XRV1-L117 P1 probe body (fresh image,
    /// SCOPEBASE_PROBE_WINDOW_PIN=1): runs the
    /// retire-power probe under the widened window
    /// hook while a sampler thread try-sweeps —
    /// the sampler must observe Deferred ≥1 (the
    /// probe's window guard excludes cooperative
    /// sweeps across [fork, pin-or-fallback-done];
    /// without it the helper's ~ms-exit + a sweep
    /// + recycle hands pidfd_open a stranger).
    /// The probe verdict is IGNORED (any host).
    #[cfg(target_arch = "x86_64")]
    fn probe_window_pin_body() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        let stop = AtomicBool::new(false);
        let deferred = AtomicUsize::new(0);
        std::thread::scope(|scope| {
            scope.spawn(|| {
                while !stop.load(Ordering::SeqCst) {
                    if try_sweep_stragglers() == SweepAttempt::Deferred {
                        deferred.fetch_add(1, Ordering::SeqCst);
                    }
                    std::thread::sleep(std::time::Duration::from_millis(5));
                }
            });
            // Verdict ignored (any host — the pin
            // is the guard, not the power).
            let _ = probe_numeric_retire_power();
            stop.store(true, Ordering::SeqCst);
        });
        let seen = deferred.load(Ordering::SeqCst);
        assert!(
            seen >= 1,
            "sampler must observe the probe window guard (Deferred ≥1, got {seen})"
        );
        eprintln!("STAGING-PROBE-WINDOW guard-observed({seen})");
    }

    /// XRV1-L117 P1: the retire-power probe holds
    /// the exclusion guard across its fork→open
    /// window (fresh image — the widen hook must
    /// not leak into the suite).
    #[test]
