    /// XRV1-L143 body (fresh image,
    /// SCOPEBASE_L143_EMFILE=1): under fd
    /// exhaustion a PRESENT zombie's stat
    /// read fails EMFILE — both readers
    /// must fail LOUD, never whisper
    /// gone. Fresh image: filling the fd
    /// table in-suite would break sibling
    /// threads sharing the process table.
    #[cfg(target_arch = "x86_64")]
    fn l143_emfile_body() {
        // Stage a PROVEN zombie first
        // (fds still open).
        let pid = unsafe { libc::fork() };
        assert!(pid >= 0, "L143 fork failed");
        if pid == 0 {
            unsafe { libc::_exit(0) };
        }
        let t0 = std::time::Instant::now();
        loop {
            assert!(
                t0.elapsed() < std::time::Duration::from_secs(30),
                "L143 setup: child never Z in 30s"
            );
            match l133_zombie_state(pid) {
                Some(true) => break,
                Some(false) => std::hint::spin_loop(),
                None => panic!("L143 setup: fast-exit child reaped?!"),
            }
        }
        // Fill the fd table to EMFILE.
        let mut fillers = Vec::new();
        let setup_err = loop {
            let fd = unsafe { libc::open(c"/dev/null".as_ptr(), libc::O_RDONLY) };
            if fd < 0 {
                break std::io::Error::last_os_error();
            }
            fillers.push(fd);
        };
        assert_eq!(
            setup_err.raw_os_error(),
            Some(libc::EMFILE),
            "L143 setup must exhaust fds, got {setup_err}"
        );
        // Both readers must panic LOUD —
        // never report the live zombie
        // gone.
        let gate = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| l133_proc_gone(pid)));
        let state =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| l133_zombie_state(pid)));
        for fd in fillers {
            unsafe { libc::close(fd) };
        }
        let mut status = 0;
        let got = unsafe { libc::waitpid(pid, &mut status, 0) };
        assert_eq!(got, pid, "L143 setup must reap its zombie");
        // Box<dyn Any> Debug is opaque
        // ("Any { .. }") — downcast to
        // read the message.
        let cites = |p: Box<dyn std::any::Any + Send>| {
            if let Some(s) = p.downcast_ref::<String>() {
                s.contains("L143")
            } else if let Some(s) = p.downcast_ref::<&str>() {
                s.contains("L143")
            } else {
                false
            }
        };
        let gate_loud = match gate {
            Err(p) => cites(p),
            Ok(v) => panic!("L143 RED: gate whispered gone={v} under EMFILE"),
        };
        let state_loud = match state {
            Err(p) => cites(p),
            Ok(v) => {
                panic!("L143 RED: reader whispered state={v:?} under EMFILE")
            }
        };
        assert!(gate_loud && state_loud, "L143 panics must cite L143");
        eprintln!("L143-EMFILE loud(2)");
    }

    /// XRV1-L143: EMFILE must never
    /// masquerade as a reaped canary
