        // (Guard-held (sweeps deferred) — the pre-reap
        // poll below must observe OUR corpse (a TT04
        // sweep would steal it (ROUND-2 LESSON)).)
        let _guard = NumericSupervisionGuard::enter();
        use std::os::unix::io::FromRawFd as _;
        // SAFETY: fork; the child only naps.
        let canary = unsafe { libc::fork() };
