    /// XRV1-L116 collateral probe body (fresh
    /// image, SCOPEBASE_L116_SWEEP_DEFER=1): a held
    /// supervision guard DEFERS straggler sweeps
    /// (try-sweep reports Deferred + the zombie
    /// survives); dropped guard ⟹ the sweep collects
    /// (Swept(1) — EXACT (fresh image: the victim is
    /// the only child — no foreign zombies, no
    /// foreign guards)). Fresh-image because the
    /// sweep is a waitpid(-1) vacuum: in-suite it
    /// eats SIBLING zombies (ROUND-2 LESSON: it stole
    /// an expiry test's inheritor status) — the image
    /// confines it to own children (both directions).
    /// Deterministic (flag-gated, zero timing).
    #[cfg(target_arch = "x86_64")]
    fn straggler_sweep_defers_probe() {
        // Fork a victim (instant exit — zombie).
        // SAFETY: fork; the child exits at once.
        let pid = unsafe { libc::fork() };
        assert!(pid >= 0, "staging broken (fork failed)");
        if pid == 0 {
            unsafe { libc::_exit(7) };
        }
        // Wait for the zombie (bounded — instant
        // exit; expiry is loud, never a pass).
        let zend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('Z') {
                break;
            }
            assert!(
                std::time::Instant::now() < zend,
                "staging broken (victim never zombies)"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Guard HELD ⟹ try-sweep defers (victim
        // survives).
        let guard = NumericSupervisionGuard::enter();
        assert_eq!(
            try_sweep_stragglers(),
            SweepAttempt::Deferred,
            "sweep must DEFER under a held guard"
        );
        assert_eq!(
            proc_state(pid),
            Some('Z'),
            "deferred sweep must NOT reap (victim survives)"
        );
        drop(guard);
        // Guard DROPPED ⟹ try-sweep collects
        // (Swept(1) — single try (no foreign guards
        // in-image — depth hits 0 at the drop)).
        assert_eq!(
            try_sweep_stragglers(),
            SweepAttempt::Swept(1),
            "dropped-guard sweep must collect exactly the own victim"
        );
        // Own-victim terminality (belt — the sweep
        // above reaped it ⟹ ECHILD here).
        // SAFETY: waitpid(own pid, WNOHANG).
        let st = unsafe { libc::waitpid(pid, std::ptr::null_mut(), libc::WNOHANG) };
        // SAFETY: errno (this thread).
        let errno = unsafe { libc::__errno_location().read() };
        assert!(
            st == -1 && errno == libc::ECHILD,
            "own victim must be reaped (got waitpid={st} errno={errno})"
        );
        eprintln!("STAGING-SWEEP-DEFER deferred-then-collected");
    }
