    /// XRV1-L114 probe body (fresh image,
    /// SCOPEBASE_HELD_SPAWN_WRONG_TICK=tbreak|open|cont)
    /// — forces the named tick-verify to mismatch (the
    /// hook swaps that point's expected tick for an
    /// impossible one): the verify must disarm (NOT
    /// ours — never touch!) + panic LOUD with its
    /// per-point message. The birth must SURVIVE T
    /// (untouched!) — found via the own-children scan
    /// and retired explicitly (cleanup the mismatch
    /// correctly refused).
    #[cfg(target_arch = "x86_64")]
    fn held_spawn_wrong_tick_probe() {
        let mode = std::env::var("SCOPEBASE_HELD_SPAWN_WRONG_TICK").expect("mode set");
        assert!(
            ["tbreak", "open", "cont"].contains(&mode.as_str()),
            "known mode, got {mode}"
        );
        fn park_body(_: ()) -> ! {
            loop {
                unsafe {
                    libc::pause();
                }
            }
        }
        let out = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _ = spawn_held_fork_child(park_body, (), "held-spawn wrong-tick probe");
        }));
        // Cleanup BEFORE judging (a live birth holds
        // this image's pipes — asserting first would
        // wedge the driver's EOF (the D1 shape!)):
        // snapshot the survivors, REMEMBER T-ness (no
        // assert yet!), retire every own child
        // explicitly, THEN judge the catch + T-ness.
        // SAFETY: gettid (own thread id — the children
        // file lists this thread's forked children).
        let tid = unsafe { libc::gettid() };
        let children = std::fs::read_to_string(format!("/proc/self/task/{tid}/children"))
            .expect("children readable");
        let kids: Vec<libc::pid_t> = children
            .split_whitespace()
            .filter_map(|s| s.parse().ok())
            .collect();
        let mut t_seen = false;
        for kid in &kids {
            if proc_state(*kid) == Some('T') {
                t_seen = true;
            }
            // SAFETY: SIGKILL + reap of our own child
            // (best-effort — errors ignored, the census
            // below judges).
            unsafe {
                libc::kill(*kid, libc::SIGKILL);
            }
            let mut st = 0;
            unsafe {
                libc::waitpid(*kid, &mut st, 0);
            }
        }
        let err = out.err().expect("tick mismatch must panic");
        let msg = err
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| err.downcast_ref::<&str>().map(|s| s.to_string()))
            .unwrap_or_default();
        let want = match mode.as_str() {
            "tbreak" => "T-break tick mismatch",
            "open" => "open tick mismatch",
            "cont" => "CONT tick mismatch",
            _ => unreachable!("mode checked above"),
        };
        assert!(
            msg.contains(want),
            "mode {mode} must fire its arm, got: {msg}"
        );
        assert_eq!(
            kids.len(),
            1,
            "exactly the untouched birth must survive, got {kids:?}"
        );
        assert!(t_seen, "survivor must be T-stopped (untouched!)");
        assert_no_live_own_children("held-spawn wrong-tick");
        eprintln!("STAGING-HELD-WRONG-TICK-{mode} fired");
    }

    /// XRV1-L114 collateral: every tick-verify arm
    /// disarms + panics on mismatch (a forced mismatch
    /// at each of the three points fires exactly its
    /// arm — never touches the stranger). Fresh image
    /// per mode (the hook env must not leak into the
    /// suite).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn held_spawn_wrong_tick_mismatch_disarms() {
        if std::env::var("SCOPEBASE_HELD_SPAWN_WRONG_TICK").is_ok() {
            held_spawn_wrong_tick_probe();
            return;
        }
        for mode in ["tbreak", "open", "cont"] {
            let exe = std::env::current_exe().expect("own test binary");
            let mut out = std::process::Command::new(exe);
            out.arg("--exact")
                .arg("fixture::linux::audit::tests::held_spawn_wrong_tick_mismatch_disarms")
                .arg("--nocapture")
                .env("SCOPEBASE_HELD_SPAWN_WRONG_TICK", mode)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            // L144: pre-exec IGN (a group-HUP
            // mid-startup murders default probes).
            arm_hup_immune_spawn(&mut out);
            let out = out.output().expect("probe child runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            assert!(out.status.success(), "probe must run ({mode})\n{stderr}");
            assert!(
                stderr.contains(&format!("STAGING-HELD-WRONG-TICK-{mode} fired")),
                "probe must cite its fired arm ({mode})\n{stderr}"
            );
        }
    }

    /// XRV1-L93 collateral: qualifier middle body (runs
    /// post-CONT under the held-spawn contract — never
    /// returns into the harness).
    #[cfg(target_arch = "x86_64")]
    fn qualify_middle_body(park: bool) -> ! {
        // XRV1-L132 hang-pin hook (payload-routed —
        // the PARENT reads SCOPEBASE_QUALIFY_PARK, so
        // no child-side env touch): park INSTEAD of
        // running inner (childless — the pin-retire
        // guard kills a lone parked birth, never an
        // orphan-maker).
        if park {
            loop {
                unsafe { libc::pause() };
            }
        }
        let code = qualify_code_of(waitid_pidfd_sigkill_qualify_inner());
        unsafe {
            libc::_exit(code);
        }
    }
    /// XRV1-L58: the SIGKILL-leg outer wrapper — spawns
    /// the isolated sole-owner helper (middle) HELD
    /// (XRV1-L93 — self-stop first, pin over STOPPED),
    /// waits it PINNED (XRV1-L132 — bounded
    /// nonblocking WNOHANG-poll through the shared
    /// pin probe + pin-bound RAII retire — the old
    /// blocking waitid is gone), and decodes its
    /// exit code. The middle's ECHILD (a sweep stole
    /// its status) ⟹ EIO (verdict unproven —
    /// conservative); a signaled middle ⟹ EIO. Pin-open
    /// failure ⟹ the STOPPED middle retires un-CONTed
    /// and the errno reports preserved (XRV1-L94 — no
    /// numeric wait on a live middle, ever). The caller
    /// NEVER waits numerically here (the only numeric
    /// waits in the qualification run inside the helper,
    /// sole-waiter sound).
    #[cfg(target_arch = "x86_64")]
    fn waitid_pidfd_sigkill_qualify_errno() -> Option<i32> {
        // XRV1-L93: held spawn (the child self-stops
        // FIRST — the pin opens over a STOPPED birth:
        // stopped ⟹ alive ⟹ unreaped ⟹ ours —
        // authoritative, no timing argument).
        // XRV1-L132: the hang-pin hook reads here
        // (parent-side — the payload routes it to the
        // middle, so the child never touches env).
        let park = std::env::var("SCOPEBASE_QUALIFY_PARK").is_ok();
        let (_middle, pin) =
            match spawn_held_fork_child(qualify_middle_body, park, "sigkill-qualifier middle") {
                Ok(pair) => pair,
                Err(errno) => {
                    // XRV1-L94: pin-open failure (TOCTOU outage —
                    // the probe gates capability before calling,
                    // so only direct callers + bursts hit this):
                    // the STOPPED middle was retired by the
                    // spawn guard (never CONTed unpinned —
                    // L11!); the errno reports preserved (L52 —
                    // EMFILE/ENFILE/ENOMEM/EAGAIN ⟹ Transient;
                    // EPERM/ENOSYS ⟹ Unsupported-skip; ESRCH ⟹
                    // Unsupported (impossible — the middle was
                    // just T — model violation, loud). No
                    // numeric wait on a live middle, ever (the
                    // old blocking fallback could hang on /
                    // consume a recycled replacement).
                    if errno == libc::ESRCH {
                        eprintln!("qualifier: middle vanished pre-pin (ESRCH — verdict unproven)");
                    }
                    return Some(errno);
                }
            };
        consume_middle_through_pin(&pin)
    }

    /// XRV1-L132: pin-bound middle retire guard
    /// (the consume's RAII — a middle unconsumed at
    /// scope exit (bound fired, status denied,
    /// verdict unproven) is SIGKILLed through its
    /// PIN (pidfd — no numeric recycle risk) +
    /// reaped through the pin (bounded 1s — a
    /// SIGKILLed birth surfaces in µs; a denied
    /// reap (deny-all) expires soundly (the zombie
    /// lingers to image exit — init reaps — never a
    /// numeric wait)). Disarmed by the success path
    /// (status consumed — nothing to retire). Never
    /// panics (drop-safe — no asserts, no unwraps).
    #[cfg(target_arch = "x86_64")]
    struct MiddleConsumeGuard {
        pin_fd: libc::c_int,
        armed: bool,
    }
    #[cfg(target_arch = "x86_64")]
    impl MiddleConsumeGuard {
        fn arm(pin_fd: libc::c_int) -> Self {
            Self {
                pin_fd,
                armed: true,
            }
        }
        fn disarm(&mut self) {
            self.armed = false;
        }
    }
    #[cfg(target_arch = "x86_64")]
    impl Drop for MiddleConsumeGuard {
        fn drop(&mut self) {
            if !self.armed {
                return;
            }
            // Pin-bound SIGKILL (ours — the pin names
            // OUR middle or reports it gone; ESRCH =
            // already discharged (the reap-poll below
            // confirms ECHILD at once)).
            let _ = super::pidfd_signal(self.pin_fd, libc::SIGKILL);
            // Bounded pin-reap (1s — expiry (D-state,
            // denied reap) lingers soundly to image
            // exit, never a numeric wait).
            let end = std::time::Instant::now() + std::time::Duration::from_secs(1);
            loop {
                match probe_victim_pin(self.pin_fd) {
                    PinProbe::Reaped(_) | PinProbe::ReapedElsewhere => return,
                    PinProbe::NotReady | PinProbe::Unverifiable(_) => {
                        if std::time::Instant::now() >= end {
                            return;
                        }
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    }
                }
            }
        }
    }

    /// XRV1-L132: qualified bounded nonblocking
    /// middle-consume (the blocking waitid is gone):
    /// WNOHANG-poll through the SHARED pin probe
    /// (probe_victim_pin — one classification text)
    /// to the bound (CONSUME_BOUND_SECS, hookable via
    /// SCOPEBASE_QUALIFY_BOUND_SECS — the middle's
    /// 11s worst + margin), with a pin-bound RAII
    /// retire guard (bound-fire / denied-status /
    /// unproven-verdict retires the middle through
    /// its pin — never numeric, never leaked).
    /// Reaped(exit code) ⟹ the shared verdict map;
    /// signaled ⟹ EIO (loud — never happens);
    /// swept ⟹ EIO (loud); denied/unverifiable ⟹
    /// EIO (loud, evidence cited); bound fired ⟹
    /// EIO (loud) + the guard retires. EINTR and
    /// spurious si_pid==0 absorb as NotReady (the
    /// probe's mode-appropriate shape — a WNOHANG
    /// zero-report is not-ready, never a verdict).
    #[cfg(target_arch = "x86_64")]
    fn consume_middle_through_pin(pin: &std::os::unix::io::OwnedFd) -> Option<i32> {
        use std::os::unix::io::AsRawFd as _;
        let bound_secs = std::env::var("SCOPEBASE_QUALIFY_BOUND_SECS")
            .ok()
            .and_then(|v| v.parse::<u64>().ok())
            .filter(|&s| s > 0)
            .unwrap_or(CONSUME_BOUND_SECS);
        let raw = pin.as_raw_fd();
        let mut guard = MiddleConsumeGuard::arm(raw);
        let end = std::time::Instant::now() + std::time::Duration::from_secs(bound_secs);
        loop {
            match probe_victim_pin(raw) {
                PinProbe::Reaped(st) => {
                    // Consumed through the pin (ours —
                    // disarm: nothing to retire).
                    guard.disarm();
                    use std::os::unix::process::ExitStatusExt as _;
                    match std::process::ExitStatus::from_raw(st).code() {
                        Some(n) => return qualify_verdict_of(n),
                        None => {
                            // Signaled (never happens —
                            // nothing signals the middle).
                            eprintln!("qualifier: middle signaled (status {st:#x} — EIO)");
                            return Some(libc::EIO);
                        }
                    }
                }
                PinProbe::ReapedElsewhere => {
                    // Swept (a waitpid(-1) stole the
                    // middle's status) ⟹ verdict
                    // unproven ⟹ EIO (conservative —
                    // loud: this should be rare). The
                    // guard's drop finds ECHILD (gone —
                    // instant no-op).
                    eprintln!("qualifier: helper reaped-elsewhere (sweep — EIO)");
                    return Some(libc::EIO);
                }
                PinProbe::NotReady => {
                    if std::time::Instant::now() >= end {
                        // Bound fired (the middle never
                        // surfaced — parked or wedged) ⟹
                        // EIO + the guard retires it
                        // through its pin (loud).
                        eprintln!(
                            "qualifier: middle unconsumed past {bound_secs}s bound (EIO — guard retires)"
                        );
                        return Some(libc::EIO);
                    }
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                PinProbe::Unverifiable(evidence) => {
                    // Denied status (deny-all) or outage
                    // ⟹ EIO (conservative — loud, the
                    // evidence cited) + the guard
                    // attempts the pin-retire (a denied
                    // reap expires soundly — the zombie
                    // lingers to image exit, never a
                    // numeric wait).
                    eprintln!("qualifier: middle status unverifiable ({evidence} — EIO)");
                    return Some(libc::EIO);
                }
            }
        }
    }

    /// XRV1-H1: peek whether the pinned birth is a zombie
    /// dead by OUR SIGKILL (WNOWAIT — observed, never
    /// consumed). True ONLY for CLD_KILLED with signo
    /// SIGKILL (XRV1-I1: a death by another signal — a
    /// SIGTERM landing between our state check and our
    /// send, a core dump — was not caused by us, and its
    /// status belongs to whoever reaps first, never us;
    /// SIGKILL never dumps, so DUMPED is never ours).
    /// CLD_EXITED, not-ready, reaped-elsewhere (ECHILD),
    /// and errors all read false (observe-only / keep
    /// polling).
    #[cfg(target_arch = "x86_64")]
    fn pin_peek_signaled(pin_fd: libc::c_int) -> bool {
        let mut info: libc::siginfo_t = unsafe { std::mem::zeroed() };
        // SAFETY: pidfd + zeroed siginfo + WNOHANG peek.
        let ret = unsafe {
            libc::waitid(
                libc::P_PIDFD,
                pin_fd as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG | libc::WNOWAIT,
            )
        };
        if ret != 0 {
            return false;
        }
        // SAFETY: as in probe_victim_pin — zeroed reads
        // valid zero; a report fills _sigchld.
        if unsafe { info.si_pid() } == 0 {
            return false;
        }
        let code = info.si_code;
        let status = unsafe { info.si_status() };
        code == libc::CLD_KILLED && status == libc::SIGKILL
    }

    /// XRV1-K3: spawn a possibly instant-exit `sh`
    /// body under a guard, SOUNDLY. Observation-anchored
    /// construction (sample→open→verify) still admits a
    /// descheduled mid-construction window (exit +
    /// sweep-reap + recycle + same-jiffy re-observe pins
    /// a stranger — the murder vector). A STOPPED child
    /// cannot exit and cannot be reaped (waitpid without
    /// WUNTRACED never reports stops — all three in-tree
    /// sweeps use plain WNOHANG), so pinning a stopped
    /// birth has no observation race at all. The stop is
    /// POST-EXEC self-stop (`kill -STOP $$` as the body's
    /// first command — NOT pre-exec: `Command::spawn`
    /// blocks on its exec-error pipe until the child
    /// execs, so a pre-exec stop deadlocks the spawn;
    /// observed as a 30-minute wedge, fixed here): the
    /// child cannot exit before running its first command
    /// (nothing signals it in the exec→STOP window), the
    /// T-await is a closed loop (bounded — expiry is
    /// staging-broken, loud), the guard pins the
    /// provably-unreaped birth, then SIGCONT releases a
    /// PROVABLY-stopped child (a blind CONT races the
    /// stop and strands it stopped). Returns the RUNNING
    /// child + its guard. XRV1-L2: sleepers (`sleep N`)
    /// MUST use this too (as `exec sleep N` — argv and
    /// tick are post-exec-identical to a direct spawn;
    /// nominal sleep duration is NO reservation — a
    /// descheduled expiry plus an ambient in-process
    /// sweep reaps and recycles before the sample, and
    /// sample+open+verify then authenticate the
    /// replacement). Every guarded birth is stopped at
    /// pin time — `KillReapGuard::new` asserts T. The
    /// `_held` variant returns the child STILL STOPPED
    /// (for callers that must pin further oracle state
    /// before release — CONT via [`cont_held_birth`]).
    /// Non-`sh` instant-exit argv has no stopped spawn
    /// (none exists in-tree — add a post-exec stop shape
    /// with the argv).
    /// The stopped-spawn `sh -c` text, shared (every
    /// self-stop body — the L10 denial test exercises
    /// the REAL text, never a copy). XRV1-L10: the stop
    /// is CHECKED (`|| exit 99` — a denied stop must die
    /// loud (99), never silently run the body: kill()
    /// to self fails only under kill-denying seccomp
    /// (the suite never self-confines — and kill() is
    /// load-bearing suite-wide, so such a host voids the
    /// suite generally — but a failed stop must never
    /// silently proceed regardless). 99 is distinct from
    /// every body exit (42/7/9).
    #[cfg(target_arch = "x86_64")]
    fn stopped_spawn_argv(body: &str) -> String {
        format!("kill -STOP $$ || exit 99; {body}")
    }

    /// XRV1-L11: hold-read retry outcome (pure
    /// decision — see `hold_read_retry`).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq, Clone, Copy)]
    enum HoldRead {
        Proceed,
        Retry,
        PanicWrongState,
        PanicOutage,
    }

    /// XRV1-L11: hold-read retry decision, pure (T
    /// proceeds; any other OBSERVED state is never
    /// transient ⟹ panic; unreadable retries in-bound).
    /// Pinned by `hold_read_retry_decision_maps_outage_outcomes`.
    #[cfg(target_arch = "x86_64")]
    fn hold_read_retry(state: Option<char>, expired: bool) -> HoldRead {
        match (state, expired) {
            (Some('T'), _) => HoldRead::Proceed,
            (Some(_), _) => HoldRead::PanicWrongState,
            (None, false) => HoldRead::Retry,
            (None, true) => HoldRead::PanicOutage,
        }
    }

    /// XRV1-L11/L24: construct-retry decision, pure
    /// (Unpinned retries while the probe is NOT
    /// Unsupported — Supported-with-outage (TOCTOU) or
    /// Transient (burst) both converge by retry; a
    /// settled Unsupported (old kernel/confinement)
    /// returns degraded, no retry; Discharged never
    /// retries). Pinned by
    /// `construct_retry_decision_maps_pin_outcomes`.
    #[cfg(target_arch = "x86_64")]
    fn should_retry_construct(pin: &GuardPin, probe: ProbeVerdict) -> bool {
        matches!(pin, GuardPin::Unpinned) && !matches!(probe, ProbeVerdict::Unsupported)
    }

    /// XRV1-L22: construct-identity lock outcome (pure
    /// decision — see `check_construct_identity`).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq)]
    enum ConstructIdentity {
        /// First observation — lock this tick.
        Lock(u64),
        /// Matches the locked tick (same birth).
        Match,
        /// No observation now (outage pre-lock, or a
        /// tick blip post-lock — a stopped-held birth
        /// cannot die, so a lost tick is outage-likely
        /// ⟹ retry, bounded by the loop; persistent
        /// loss expires into the loop's loud arm,
        /// never a silent drop over a live birth).
        Transient,
        /// A DIFFERENT tick since the lock (proven
        /// recycle — impossible on a stopped-held
        /// birth ⟹ hold-premise break — terminal,
        /// never a fresh-sample pin; the handle is
        /// proven stale ⟹ silent drop + loud).
        Changed,
    }

    /// XRV1-L22: construct-identity lock, pure (the
    /// retry must not wander across births — a tick
    /// change on a stopped-held birth is impossible,
    /// so firing means the hold premise broke ⟹ loud).
    /// Pinned by `construct_identity_lock_gates_retries`.
    #[cfg(target_arch = "x86_64")]
    fn check_construct_identity(expected: Option<u64>, now: Option<u64>) -> ConstructIdentity {
        match (expected, now) {
            (None, Some(tick)) => ConstructIdentity::Lock(tick),
            (None, None) => ConstructIdentity::Transient,
            (Some(want), Some(got)) if want == got => ConstructIdentity::Match,
            (Some(_), None) => ConstructIdentity::Transient,
            (Some(_), Some(_)) => ConstructIdentity::Changed,
        }
    }

    /// XRV1-L49/L75: retire an AUTHENTICATED
    /// premise-break zombie (a `new` that observed
    /// Z on a T-awaited number — the hold premise
    /// broke: the birth ran and died) through the
    /// CALLER'S pin (retained from the T-hold —
    /// stopped ⟹ unreaped ⟹ the open named OUR
    /// birth — birth-bound, never a numeric wait
    /// (L43)). XRV1-L75: NO fresh open inside (a
    /// fresh open races: A reaped + same-tick B
    /// zombies between check and open ⟹ the pin
    /// names B ⟹ consume steals B — the pin MUST be
    /// retained from the hold). The pin ALONE
    /// authenticates (no tick checks — ticks cannot
    /// see through a same-tick recycle; the pin
    /// cannot see B at all): Reaped ⟹ OUR status
    /// consumed ⟹ Discharged; ReapedElsewhere ⟹ a
    /// sweep took A's status ⟹ Discharged (nothing
    /// of ours remains); NotReady ⟹ A ALIVE (the Z
    /// sighting named a recycled number — B belongs
    /// to B's waiter) ⟹ Untouched; Unverifiable ⟹
    /// Untouched (sweep-or-exit reaps). Returns a
    /// STRUCTURED outcome + forensics text
    /// (XRV1-L63 — the caller disarms on Discharged
    /// BEFORE judging anything; premise-break is
    /// always staging-broken loud). `pid` is
    /// forensics-only. Precondition: `pin` names the
    /// premise-break birth (opened while held —
    /// callers pin at the T-hold; a wrong pin is a
    /// caller bug — garbage in).
    /// XRV1-L63: the zombie-retire outcome —
    /// Discharged (consumed or proven reaped —
    /// the caller stands down) vs Untouched (no
    /// consume happened — the caller keeps
    /// custody).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum ZombieRetire {
        Discharged,
        Untouched,
    }
    #[cfg(target_arch = "x86_64")]
    fn retire_zombie_premise_break(pin: libc::c_int, pid: libc::pid_t) -> (ZombieRetire, String) {
        use ZombieRetire::*;
        // The pin is BORROWED (the caller retains
        // ownership — this probe never closes).
        match probe_victim_pin(pin) {
            PinProbe::Reaped(_) => (
                Discharged,
                format!("{pid} consumed (pin-bound reap of ours)"),
            ),
            PinProbe::ReapedElsewhere => (
                Discharged,
                format!("{pid} reaped-elsewhere (sweep won — discharged)"),
            ),
            PinProbe::NotReady => (
                Untouched,
                format!("{pid} untouched (live under a premise-break sighting — untrusted)"),
            ),
            PinProbe::Unverifiable(evidence) => (
                Untouched,
                format!("{pid} unverifiable ({evidence} — sweep-or-exit reaps)"),
            ),
        }
    }
    /// XRV1-L78a: discharge gate verdict — TerminalAbsent
    /// (proven disappearance ⟹ returned WITHOUT touching)
    /// vs TerminalMismatch (proven recycle ⟹ same) vs
    /// Proceeded (the gate passed — open/signal attempted
    /// (which may still ESRCH-out silently)). The verdict
    /// exists because terminal-absence is otherwise
    /// UNOBSERVABLE (a µs recycle window + libtest's
    /// fork-inherited output capture swallowing eprintln
    /// evidence): untestable safety ⟹ structured outcome
    /// (the L63 shape). Callers ignore it (`let _ =`) —
    /// zero behavior change. Must-use (a dropped verdict
    /// is a dropped gate decision — acknowledge it).
    #[cfg(target_arch = "x86_64")]
    #[must_use]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum DischargeOutcome {
        TerminalAbsent,
        TerminalMismatch,
        Proceeded,
    }
    /// XRV1-L12/L21/L30: discharge a held birth —
    /// best-effort retirement before a staging-broken
    /// panic. Birth-bound FIRST (pidfd kill +
    /// waitid-consume — a numeric try_wait past a
    /// sweep-reap can steal a recycled sibling
    /// zombie's status; the pin consumes ONLY our
    /// birth). Proven discharge returns IMMEDIATELY
    /// (open-ESRCH, kill-ESRCH ⟹ already reaped ⟹ no
    /// wait at all — never a numeric wait past
    /// retirement). The numeric Child-handle leg
    /// survives ONLY as the isolated no-pidfd
    /// fallback (old-kernel ENOSYS / confinement
    /// EPERM — loud, and NEVER waits (XRV1-L41
    /// kill-only — no birth-bound wait exists
    /// without a pidfd)). XRV1-L42/L65: birth
    /// authority FIRST — `locked` carries the
    /// caller's T-await lock (a reaped-then-recycled
    /// number would otherwise hand us a stranger to
    /// kill); proven ABSENCE (Ok(None) — XRV1-L78a)
    /// or a positive mismatch (lock + tick both
    /// present and differing) returns WITHOUT
    /// touching. Outage shapes (no lock, unreadable
    /// tick) proceed reservation-backed (LOUD —
    /// abandoning would strand a live stopped
    /// birth). Precondition (all callers): pre-T or
    /// stopped-held AND unretired — proven-retired
    /// callers must NOT call (their handle already
    /// consumed; any lookup past retirement risks a
    /// same-tick stranger — drop silently instead).
    /// CONT survives ONLY as the kill-denied
    /// fallback (run-to-exit), followed by a
    /// signal-free drain (post-CONT signals could
    /// land on a recycled stranger — never sent).
    /// The Child handle is never waited on the
    /// birth-bound path (the pin consumed it — the
    /// caller drops the stale handle silently,
    /// XRV1-L34).
    #[cfg(target_arch = "x86_64")]
    fn discharge_held_child<C: StagedChildHandle>(
        child: &mut C,
        pid: libc::pid_t,
        locked: Option<u64>,
    ) -> DischargeOutcome {
        use std::os::unix::io::{AsRawFd as _, FromRawFd as _};
        // XRV1-L42/L65: the tick gate fires ONLY on
        // a POSITIVE mismatch (lock + tick both
        // present and differing ⟹ proven recycle ⟹
        // the number names a stranger ⟹ return
        // WITHOUT touching (no kill, no wait, no
        // CONT)). Every outage shape (no lock, an
        // unreadable tick) PROCEEDS
        // reservation-backed: all callers hold the
        // birth unreaped with no zombie ever
        // existing — it cannot have recycled, so
        // the number is still ours. LOUD on outage
        // (an outage never retires silently —
        // abandoning here would strand a live
        // stopped birth). XRV1-L78a: proven absence
        // (Ok(None)) returned terminally above — only
        // UNREADABLE (Err) reaches this rule.
        // XRV1-L78a: proven disappearance is TERMINAL
        // (proc_starttime's Ok(None) ⟹ ENOENT/ESRCH ⟹ no
        // such task ⟹ return WITHOUT touching — no open,
        // no signal (the number may already name a
        // replacement)). Unreadable (Err) PROCEEDS
        // reservation-backed (L65 — loud below).
        // pin_birth_tick CANNOT serve here (it conflates
        // absent + unreadable into None — the L78a hole).
        // Precondition (all callers): a working /proc — a
        // mount outage reads ENOENT (absent) and safely
        // defers retirement to the owner drop.
        let tick0 = match proc_starttime(pid) {
            Ok(None) => return DischargeOutcome::TerminalAbsent,
            Err(_) => None,
            Ok(tick) => tick,
        };
        if matches!((locked, tick0), (Some(w), Some(g)) if g != w) {
            return DischargeOutcome::TerminalMismatch;
        }
        if locked.is_none() {
            eprintln!("discharge: {pid} no locked tick (outage — proceeding reservation-backed)");
        } else if tick0.is_none() {
            eprintln!("discharge: {pid} tick unreadable (outage — proceeding reservation-backed)");
        }
        // Birth-bound path (XRV1-L30): open-ESRCH ⟹
        // proven gone ⟹ return (no touch at all).
        match super::super::seccomp::pidfd_open_raw(pid) {
            Err(errno) if errno == libc::ESRCH => return DischargeOutcome::Proceeded,
            Err(_) => {
                // Unopenable (NOT gone — old kernel or
                // confinement) ⟹ the isolated numeric
                // fallback below (loud — this is the
                // only numeric-wait leg).
                eprintln!("discharge: no pidfd for {pid} (numeric fallback — isolated)");
            }
            Ok(fd) => {
                let owned = unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) };
                let raw = owned.as_raw_fd();
                // Kill through the pin (ESRCH ⟹ ours
                // reaped by a sweep ⟹ proven
                // discharged ⟹ return immediately).
                match super::super::seccomp::pidfd_send_signal_raw(raw, libc::SIGKILL) {
                    Ok(()) => {}
                    Err(errno) if errno == libc::ESRCH => return DischargeOutcome::Proceeded,
                    Err(_) => {
                        // Pin-kill denied (a filter that
                        // allows kill(2) but denies pidfd
                        // SIGKILL — the L38 shape) ⟹
                        // numeric Child-kill (sound:
                        // precondition — no zombie ever,
                        // number-held), then the
                        // birth-bound consume below (the
                        // consume stays pinned — a
                        // recycled sibling's status is
                        // never consumed). A kill(2)
                        // denial too (double-deny) gives
                        // up loud (a kill-denying host
                        // voids staging generally —
                        // no CONT here (the numeric leg
                        // below owns run-to-exit)).
                        match child.staged_kill() {
                            Ok(()) => {}
                            Err(error) if error.raw_os_error() == Some(libc::ESRCH) => {
                                return DischargeOutcome::Proceeded
                            }
                            Err(error) => {
                                eprintln!(
                                    "discharge: kill to {pid} doubly denied ({error:?} — \
                                     kill-denying host voids staging)"
                                );
                                return DischargeOutcome::Proceeded;
                            }
                        }
                    }
                }
                // Birth-bound consume (the pin names OUR
                // birth or reports it gone — a recycled
                // sibling's status is never consumed).
                let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
                loop {
                    match probe_victim_pin(raw) {
                        PinProbe::Reaped(_) | PinProbe::ReapedElsewhere => {
                            return DischargeOutcome::Proceeded
                        }
                        PinProbe::NotReady => {
                            if std::time::Instant::now() >= end {
                                eprintln!(
                                    "discharge: {pid} unreaped past 5s bound (pin-bound wait)"
                                );
                                return DischargeOutcome::Proceeded;
                            }
                            std::thread::sleep(std::time::Duration::from_millis(10));
                        }
                        PinProbe::Unverifiable(evidence) => {
                            eprintln!("discharge: {pid} wait unverifiable ({evidence})");
                            return DischargeOutcome::Proceeded;
                        }
                    }
                }
            }
        }
        // XRV1-L41: kill-only numeric fallback (no
        // pidfd at all — old kernel / confinement).
        // NO birth-bound wait exists without a pidfd
        // ⟹ this leg NEVER waits (any numeric wait
        // past a sweep-reap could steal a recycled
        // sibling's status — the fallback kills and
        // PROVES death by poll only; the zombie
        // lingers to process exit (bounded — one per
        // fallback run — a sweep or exit reaps it).
        match child.staged_kill() {
            Ok(()) => {}
            Err(error) if error.raw_os_error() == Some(libc::ESRCH) => {
                return DischargeOutcome::Proceeded
            }
            Err(error) => {
                // Kill DENIED (or otherwise failed): the
                // only sound fallback is run-to-exit.
                // SAFETY: SIGCONT to our own unreaped
                // child (still stopped — nothing CONTed
                // it yet — so still stably ours).
                eprintln!("discharge: kill to {pid} failed ({error:?} — run-to-exit fallback)");
                if unsafe { libc::kill(pid, libc::SIGCONT) } != 0 {
                    eprintln!(
                        "discharge: CONT to {pid} failed ({0:?} — already reaped?)",
                        std::io::Error::last_os_error().raw_os_error()
                    );
                    return DischargeOutcome::Proceeded;
                }
                // Run-to-exit: the CONTed birth runs
                // its body and dies alone — death
                // proven by the poll below (never
                // waited — the zombie lingers, as
                // above).
            }
        }
        // Death proof by proc-poll ONLY (never a
        // wait). Single-sample per iteration (state +
        // tick read once — no mid-match TOCTOU); the
        // mismatch rule matches the entry gate
        // (POSITIVE mismatch only — outage reads
        // ours-or-outage, reservation-backed).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let state = proc_state(pid);
            let tick = pin_birth_tick(pid);
            let mismatched = matches!((locked, tick), (Some(w), Some(g)) if g != w);
            match (state, mismatched) {
                // Ours-or-outage zombie ⟹ our kill
                // landed and nothing reaped (the
                // kill-only proof — lingering).
                (Some('Z'), false) => return DischargeOutcome::Proceeded,
                // Gone ⟹ reaped-elsewhere (a sweep
                // won — discharged, benign).
                (None, _) => return DischargeOutcome::Proceeded,
                // Positive mismatch ⟹ recycled under
                // us (a same-number stranger — fail
                // closed, loud, no touch — the
                // stranger is not ours).
                (Some(_), true) => {
                    eprintln!("discharge: {pid} recycled under kill-only fallback (untouched)");
                    return DischargeOutcome::Proceeded;
                }
                // Ours-and-live (dying), or live with
                // an unreadable tick (outage — death
                // unproven) ⟹ poll to the bound.
                (Some(_), false) => {}
            }
            if std::time::Instant::now() >= end {
                eprintln!("discharge: {pid} unreaped past 5s bound (kill-only — lingering?)");
                return DischargeOutcome::Proceeded;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// XRV1-L2: T-await + pin a self-stopped child,
    /// shared core (the child self-stops as its first
    /// instruction — the ONLY sound hold: STOP-by-number
    /// can land on a recycled stranger). Closed loop:
    /// the child MUST show T (it cannot pass its own
    /// first-command stop unstopped, and cannot exit
    /// before running it). Expiry discharges through the
    /// handle (XRV1-L4) and panics staging-broken loud.
    /// XRV1-L11: construction retries transient
    /// Unpinned (EMFILE/outage on a capable host —
    /// absorbed, never CONTed unpinned); old-kernel
    /// returns degraded (hygiene-only callers); post-hold
    /// Discharged is impossible ⟹ discharge + loud.
    /// XRV1-L22: the retry locks the first-observed
    /// tick — a mid-construct change is terminal loud
    /// (never a fresh-sample Pinned stranger).
    /// Returns the guard with the child STILL STOPPED
    /// (the caller CONTs via [`cont_held_birth`] when no
    /// further pre-release pinning is needed).
    #[cfg(target_arch = "x86_64")]
    fn pin_stopped_child(child: &mut std::process::Child) -> KillReapGuard {
        let pid = child.id() as libc::pid_t;
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        // XRV1-L31: the T-await locks the first tick
        // too (every spawner-path retry binds its
        // re-reads — a change is terminal, never a
        // re-await on the replacement).
        let mut await_expected: Option<u64> = None;
        loop {
            let state = proc_state(pid);
            match check_construct_identity(await_expected, pin_birth_tick(pid)) {
                ConstructIdentity::Lock(tick) => await_expected = Some(tick),
                ConstructIdentity::Match | ConstructIdentity::Transient => {}
                // XRV1-L32: proven identity change ⟹
                // the handle is proven stale — drop it
                // SILENTLY (no kill, no wait — the
                // number names the replacement) + LOUD.
                ConstructIdentity::Changed => {
                    panic!(
                        "staging broken (stopped child changed mid-await: \
                         {await_expected:?} — proven stale handle, untouched)"
                    );
                }
            }
            match state {
                Some('T') => break,
                other => {
                    if std::time::Instant::now() >= end {
                        // XRV1-L4: expiry must not abandon
                        // a stopped child (no guard is
                        // armed yet — dropping the handle
                        // would leak it stopped-forever).
                        // The birth is unreaped ⟹ ours
                        // (it never ran — no zombie ever
                        // existed for a sweep to take —
                        // so the number cannot have
                        // recycled — and no Changed fired
                        // above, so the lock still names
                        // this birth).
                        // XRV1-L42: the T-await lock is
                        // the discharge authority.
                        let _ = discharge_held_child(child, pid, await_expected);
                        panic!("staging broken (stopped child never shows T: {other:?})");
                    }
                }
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // XRV1-L75: retain the HOLD pin (T-held ⟹
        // stopped ⟹ unreaped ⟹ the open names OUR
        // birth — birth-bound premise-break
        // retirement (no fresh open later (L75
        // race))). Open failure (EMFILE/outage) ⟹
        // None-carry (a later premise-break reports
        // unpinned instead of retiring —
        // sweep-or-exit reaps; the loud panic still
        // fires).
        use std::os::unix::io::{AsRawFd as _, FromRawFd as _};
        let hold_pin: Option<std::os::unix::io::OwnedFd> =
            match super::super::seccomp::pidfd_open_raw(pid) {
                Ok(fd) => Some(unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) }),
                Err(_) => None,
            };
        // Pinned while provably unreaped (stopped ⟹ no
        // exit ⟹ no reap ⟹ ours) — with transient
        // retry (the birth stays stopped throughout —
        // nobody CONTs before return).
        let build_end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        // XRV1-L22/L31: the retry must not wander
        // across births — lock the FIRST CONSTRUCTOR
        // SAMPLE and require it every iteration (a
        // post-new re-read can name a replacement
        // after a sample→verify mismatch degrades to
        // Unpinned — the lock feeds `new`'s own
        // sample, never a fresh read). A change on a
        // stopped-held birth is impossible ⟹ firing
        // means the hold premise broke ⟹ terminal
        // loud, never a fresh-sample Pinned stranger.
        // XRV1-L45: carry the T-await lock
        // (never reset it — a first sample naming
        // a replacement is Changed, not a lock).
        let mut expected: Option<u64> = await_expected;
        loop {
            let mut constructed = match KillReapGuard::new(pid, await_expected) {
                Ok(constructed) => constructed,
                // XRV1-L31: construction errors map to
                // the loud arms (the handle is ours —
                // T-awaited above with no Changed —
                // except where the error proves
                // otherwise).
                Err(ConstructError::Outage) => {
                    // Unreadable (T-awaited ⟹ still
                    // ours) ⟹ retire, then loud.
                    // XRV1-L42: the T-await lock is
                    // the discharge authority.
                    let _ = discharge_held_child(child, pid, await_expected);
                    panic!("staging broken (birth {pid} unreadable past 5s — host outage?)");
                }
                Err(ConstructError::WrongState { seen: Some('Z') }) => {
                    // XRV1-L49/L75: observed-ZOMBIE on
                    // a T-awaited number (the hold
                    // premise broke — the birth ran and
                    // died) ⟹ retire through the HELD
                    // pin (birth-bound — never a numeric
                    // wait), THEN loud (the forensics
                    // ride the panic). No pin (hold-pin
                    // open failed) ⟹ unpinned forensics
                    // (sweep-or-exit reaps — still
                    // loud).
                    let forensics = match hold_pin.as_ref() {
                        Some(pinned) => {
                            let (_, forensics) =
                                retire_zombie_premise_break(pinned.as_raw_fd(), pid);
                            forensics
                        }
                        None => {
                            format!("{pid} unpinned (hold-pin open failed — sweep-or-exit reaps)")
                        }
                    };
                    panic!(
                        "staging broken (held birth died mid-construct: \
                         {forensics} — premise break)"
                    );
                }
                Err(ConstructError::WrongState { seen }) => {
                    // Observed-live (possibly a recycled
                    // stranger — T-then-live means the
                    // hold premise broke) ⟹ silent drop
                    // + loud, never cleanup.
                    panic!(
                        "staging broken (held birth went live mid-construct: \
                         {seen:?} — untrusted handle, untouched)"
                    );
                }
                Err(ConstructError::Changed { expected, got }) => {
                    // Proven recycle ⟹ the handle is
                    // proven stale ⟹ silent + loud.
                    panic!(
                        "staging broken (held birth changed mid-construct: \
                         {expected:?} vs {got:?} — proven stale handle, untouched)"
                    );
                }
                Err(ConstructError::LogicBreak) => {
                    // Classifier-totality break (birth
                    // state unknown — T-awaited, so
                    // probably ours — discharge through
                    // the ESRCH-safe helper, then loud).
                    // XRV1-L42: the T-await lock is
                    // the discharge authority.
                    let _ = discharge_held_child(child, pid, await_expected);
                    panic!("staging broken (construct classifier broke — logic break?)");
                }
            };
            match check_construct_identity(expected, constructed.sampled) {
                ConstructIdentity::Lock(tick) => expected = Some(tick),
                ConstructIdentity::Match | ConstructIdentity::Transient => {}
                // XRV1-L32: proven identity change ⟹
                // reject the replacement BEFORE arming
                // effects (the guard may hold the
                // replacement's pidfd — disarm it so
                // unwind never signals) + drop the
                // proven-stale handle SILENTLY + LOUD.
                ConstructIdentity::Changed => {
                    constructed.guard.disarm();
                    panic!(
                        "staging broken (held birth changed mid-construct: \
                         {expected:?} vs {0:?} — replacement rejected, handle untouched)",
                        constructed.sampled
                    );
                }
            }
            if matches!(&constructed.guard.pin, GuardPin::Pinned { .. }) {
                return constructed.guard;
            }
            if !should_retry_construct(&constructed.guard.pin, waitid_pidfd_probe()) {
                if matches!(&constructed.guard.pin, GuardPin::Discharged) {
                    // Impossible post-hold (a stopped
                    // birth cannot be gone) — and
                    // proven gone ⟹ the handle is
                    // proven stale ⟹ silent drop +
                    // loud (XRV1-L32 — no discharge
                    // against a proven-gone number).
                    panic!("staging broken (post-hold Discharged — model break?)");
                }
                // Old-kernel degraded (hygiene-only
                // callers — the L9 gates keep verdicts
                // off this path).
                return constructed.guard;
            }
            if std::time::Instant::now() >= build_end {
                // XRV1-L42: the T-await lock is
                // the discharge authority.
                let _ = discharge_held_child(child, pid, await_expected);
                panic!("staging broken (guard Unpinned past 5s on a capable host)");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    /// XRV1-L2: settle a released birth on its
    /// post-exec argv (cmdline argv0 match — the exec
    /// proof: a running state alone still shows pre-exec
    /// sh, whose cmdline CONTAINS the duration and would
    /// confuse dur scans). For stopped-spawned births
    /// that a scan or argv assert reads (scans match
    /// argv0~sleep — pre-exec sh matches nothing and
    /// silently undercounts). Bounded — expiry is
    /// staging-broken loud.
    #[cfg(target_arch = "x86_64")]
    fn await_exec_argv0(pid: libc::pid_t, argv0: &str) {
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let mut prefix = argv0.as_bytes().to_vec();
        prefix.push(0);
        loop {
            let cmdline = std::fs::read(format!("/proc/{pid}/cmdline"))
                .expect("staging broken (settle cmdline readable)");
            if cmdline.starts_with(&prefix) {
                return;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (birth {pid} never execs to {argv0:?})"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    /// XRV1-L2: release a held birth (the CONT half of
    /// the stopped-spawn handshake). ESRCH is impossible
    /// (held ⟹ unreaped) — staging-broken loud, never
    /// silent. A blind CONT races the stop and strands
    /// the birth stopped — only CONT a T-awaited birth.
    #[cfg(target_arch = "x86_64")]
    fn cont_held_birth(pid: libc::pid_t) {
        // SAFETY: SIGCONT to our own stopped child.
        assert_eq!(
            unsafe { libc::kill(pid, libc::SIGCONT) },
            0,
            "staging broken (CONT refused on stopped child)"
        );
    }

    /// XRV1-L2: open an oracle pidfd over a HELD birth
    /// (T-awaited — a try_wait(None) alone does not bind
    /// the open: the birth can exit and an ambient sweep
    /// can reap+recycle between the check and the open).
    /// The T-assert is the binding (stopped ⟹ unreaped
    /// ⟹ ours). Errors carry the errno (the caller's
    /// skip path reports it).
    #[cfg(target_arch = "x86_64")]
    fn pidfd_open_held(pid: libc::pid_t) -> Result<std::os::unix::io::OwnedFd, i32> {
        use std::os::unix::io::FromRawFd as _;
        assert_eq!(
            proc_state(pid),
            Some('T'),
            "staging broken (oracle requires a held birth — self-stop + T-await first)"
        );
        super::super::seccomp::pidfd_open_raw(pid)
            .map(|fd| unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) })
    }

    /// XRV1-L24: unwind custody for an Unpinned
    /// staging birth (old-kernel/confinement — no
    /// pidfd, so the Child handle is the owner). Owns
    /// the Child; `retire` (happy path) kill+waits
    /// strictly; Drop (unwind path) kill+waits
    /// best-effort over a BOUNDED try_wait (never
    /// panics, never hangs — a kill-denied live birth
    /// is loud-reported and given up). SOUND on
    /// stopped births (L21: stopped ⟹ no exit ⟹ the
    /// kill lands on ours) and on live births held
    /// unreaped (live ⟹ unreaped ⟹ ours; kill-first
    /// ordering ⟹ our kill always precedes any reap of
    /// ours — a sweep can only steal status (benign,
    /// ECHILD-tolerant), never enable a stranger kill).
    #[cfg(target_arch = "x86_64")]
    /// XRV1-L110: the staged-child handle
    /// contract (kill/wait/id — the ONLY Child
    /// surface the staging owner and the discharge
    /// helper touch). Implemented by std Child
    /// (delegate) and by the raw fork-child-safe
    /// handle below (raw syscalls — no Command, no
    /// env lock).
    #[cfg(target_arch = "x86_64")]
    trait StagedChildHandle {
        fn staged_id(&self) -> u32;
        fn staged_kill(&mut self) -> std::io::Result<()>;
        fn staged_wait(&mut self) -> std::io::Result<std::process::ExitStatus>;
        fn staged_try_wait(&mut self) -> std::io::Result<Option<std::process::ExitStatus>>;
    }

    #[cfg(target_arch = "x86_64")]
    impl StagedChildHandle for std::process::Child {
        fn staged_id(&self) -> u32 {
            self.id()
        }
        fn staged_kill(&mut self) -> std::io::Result<()> {
            self.kill()
        }
        fn staged_wait(&mut self) -> std::io::Result<std::process::ExitStatus> {
            self.wait()
        }
        fn staged_try_wait(&mut self) -> std::io::Result<Option<std::process::ExitStatus>> {
            self.try_wait()
        }
    }

    /// XRV1-L110: a raw-spawned staged child (no
    /// std Child — fork-child-safe by construction:
    /// every method is a raw syscall — never a
    /// process-global lock). No Drop (dropping is
    /// silent, exactly like dropping a std Child —
    /// custody lives in the owner, never here).
    #[cfg(target_arch = "x86_64")]
    struct RawStagedChild {
        pid: libc::pid_t,
    }

    #[cfg(target_arch = "x86_64")]
    impl StagedChildHandle for RawStagedChild {
        fn staged_id(&self) -> u32 {
            self.pid as u32
        }
        fn staged_kill(&mut self) -> std::io::Result<()> {
            // SAFETY: SIGKILL to our staged birth.
            if unsafe { libc::kill(self.pid, libc::SIGKILL) } == 0 {
                Ok(())
            } else {
                Err(std::io::Error::last_os_error())
            }
        }
        fn staged_wait(&mut self) -> std::io::Result<std::process::ExitStatus> {
            use std::os::unix::process::ExitStatusExt as _;
            loop {
                let mut status = 0;
                // SAFETY: blocking reap of our own
                // staged birth.
                let got = unsafe { libc::waitpid(self.pid, &mut status, 0) };
                if got == self.pid {
                    return Ok(std::process::ExitStatus::from_raw(status));
                }
                let error = std::io::Error::last_os_error();
                // EINTR retries (matching std
                // Child::wait); anything else
                // reports (ECHILD ⟹ stolen).
                if got < 0 && error.raw_os_error() == Some(libc::EINTR) {
                    continue;
                }
                return Err(error);
            }
        }
        fn staged_try_wait(&mut self) -> std::io::Result<Option<std::process::ExitStatus>> {
            use std::os::unix::process::ExitStatusExt as _;
            let mut status = 0;
            // SAFETY: WNOHANG reap of our own
            // staged birth.
            let got = unsafe { libc::waitpid(self.pid, &mut status, libc::WNOHANG) };
            if got == self.pid {
                return Ok(Some(std::process::ExitStatus::from_raw(status)));
            }
            if got == 0 {
                return Ok(None);
            }
            Err(std::io::Error::last_os_error())
        }
    }

    // XRV1-L129: the trait bound is x86_64-
    // only (raw-fork staging), so the struct
    // must be too — else aarch64 E0405.
    #[cfg(target_arch = "x86_64")]
    struct UnpinnedStagingOwner<C: StagedChildHandle = std::process::Child> {
        child: Option<C>,
        // XRV1-L120: birth binding (the tick at
        // arm — the unwind drop re-verifies before
        // killing (a co-armed FixtureGuard may
        // have retired first — without the gate
        // the drop signals+waits the freed
        // number (murder on recycle))). None ⟺
        // unreadable-at-arm (outage — the drop
        // never blind-kills (loud give-up)).
        tick: Option<u64>,
    }

    #[cfg(target_arch = "x86_64")]
    impl<C: StagedChildHandle> UnpinnedStagingOwner<C> {
        fn new(child: C) -> Self {
            // Birth binding (best-effort read —
            // None ⟺ outage (the drop stands down
            // loud, never blind)).
            // SAFETY: staged_id names our own
            // just-spawned child (unreaped ⟹ the
            // read names OUR birth).
            let tick = proc_starttime(child.staged_id() as libc::pid_t)
                .ok()
                .flatten();
            UnpinnedStagingOwner {
                child: Some(child),
                tick,
            }
        }
        fn pid(&self) -> libc::pid_t {
            self.child.as_ref().expect("owner holds").staged_id() as libc::pid_t
        }
        /// XRV1-L33: stand down COMPLETELY (custody
        /// transfers elsewhere — kill AND reap both
        /// covered (detached sole reaper + kill-only
        /// guard)): drops the Child silently (no kill,
        /// no wait — a later numeric cleanup would run
        /// against the freed number). Consumes (like
        /// `retire` — irreversible).
        fn disarm(mut self) {
            let child = self.child.take().expect("owner holds");
            drop(child);
        }
        /// Strict retire (happy path — expects a live
        /// birth (all Unpinned-staged bodies are
        /// long-lived); ESRCH/ECHILD (exited+reaped
        /// early) also pass (already retired)).
        fn retire(mut self) {
            let mut child = self.child.take().expect("owner holds");
            match child.staged_kill() {
                Ok(()) => {}
                Err(error) if error.raw_os_error() == Some(libc::ESRCH) => {}
                Err(error) => panic!("staging broken (owner kill refused: {error:?})"),
            }
            match child.staged_wait() {
                Ok(_) => {}
                Err(error) if error.raw_os_error() == Some(libc::ECHILD) => {}
                Err(error) => panic!("staging broken (owner reap refused: {error:?})"),
            }
        }
    }

    #[cfg(target_arch = "x86_64")]
    impl<C: StagedChildHandle> Drop for UnpinnedStagingOwner<C> {
        fn drop(&mut self) {
            use std::io::Write as _;
            let Some(mut child) = self.child.take() else {
                return;
            };
            // XRV1-L120: re-verify BEFORE killing (a
            // co-armed guard may have retired first —
            // mismatch/gone ⟹ stand down SILENT (no
            // blind signal+wait on a freed number);
            // unreadable ⟹ loud give-up (never
            // blind, never panic (Drop during unwind
            // must not abort — J7)). Matches the
            // FixtureGuard drop discipline (mutual
            // re-verification ⟹ single-flight,
            // order-independent).
            let pid = child.staged_id() as libc::pid_t;
            match (self.tick, proc_starttime(pid)) {
                (Some(was), Ok(Some(now))) if was == now => {}
                (Some(_), Ok(_)) => return,
                _ => {
                    let _ = writeln!(
                        std::io::stderr(),
                        "owner: birth {pid} unverifiable at drop (no baseline or unreadable — standing down loud)"
                    );
                    return;
                }
            }
            let _ = child.staged_kill();
            // Bounded (a kill-denied LIVE birth must
            // not hang the unwind — loud give-up).
            let end = std::time::Instant::now() + std::time::Duration::from_secs(2);
            loop {
                match child.staged_try_wait() {
                    Ok(Some(_)) | Err(_) => return,
                    Ok(None) => {}
                }
                if std::time::Instant::now() >= end {
                    // XRV1-L36: fallible write — never
                    // eprintln! (panics on broken stderr;
                    // in Drop during unwind that aborts —
                    // J7).
                    let _ = writeln!(
                        std::io::stderr(),
                        "owner: birth {} unreaped past 2s bound (leaked — loud)",
                        child.staged_id()
                    );
                    return;
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
        }
    }

    /// XRV1-L24: post-spawn custody split — Pinned
    /// (spawner already CONTed, guard owns retirement)
    /// carries the Child; Unpinned (spawner left it
    /// STOPPED) carries the Child-handle owner (cont
    /// explicitly at the split — running needs the
    /// owner FIRST). Drop is structural: Pinned drops
    /// the bare Child (silent — the Pinned guard owns);
    /// Unpinned drops the owner (retires — see above).
    #[cfg(target_arch = "x86_64")]
    enum StagingCustody {
        Pinned(std::process::Child),
        Unpinned(UnpinnedStagingOwner),
    }

    #[cfg(target_arch = "x86_64")]
    impl StagingCustody {
        fn pid(&self) -> libc::pid_t {
            match self {
                StagingCustody::Pinned(child) => child.id() as libc::pid_t,
                StagingCustody::Unpinned(owner) => owner.pid(),
            }
        }
        /// Borrow the live Child (stdio takes and
        /// similar — the borrow must end before
        /// `retire`, which consumes).
        fn child_mut(&mut self) -> &mut std::process::Child {
            match self {
                StagingCustody::Pinned(child) => child,
                StagingCustody::Unpinned(owner) => owner.child.as_mut().expect("owner holds"),
            }
        }
        /// XRV1-L33: stand down over a custody
        /// transfer (kill AND reap both covered
        /// elsewhere): Pinned drops the bare Child
        /// (silent — the Pinned guard owns
        /// retirement); Unpinned disarms the owner
        /// (silent — no later numeric cleanup against
        /// the freed number).
        fn disarm_owner(self) {
            match self {
                StagingCustody::Pinned(child) => drop(child),
                StagingCustody::Unpinned(owner) => owner.disarm(),
            }
        }
        /// Strict retire (happy path — same
        /// kill+wait discipline on both arms).
        fn retire(self) {
            match self {
                StagingCustody::Pinned(mut child) => {
                    match child.kill() {
                        Ok(()) => {}
                        Err(error) if error.raw_os_error() == Some(libc::ESRCH) => {}
                        Err(error) => panic!("staging broken (retire kill refused: {error:?})"),
                    }
                    match child.wait() {
                        Ok(_) => {}
                        Err(error) if error.raw_os_error() == Some(libc::ECHILD) => {}
                        Err(error) => panic!("staging broken (retire reap refused: {error:?})"),
                    }
                }
                StagingCustody::Unpinned(owner) => owner.retire(),
            }
        }
    }

    /// XRV1-L48: skip-if-Unpinned for the J6
    /// pin-semantics transfer sites — Pinned ⟹
    /// returns the custody (Some — the caller
    /// proceeds to the waiter install + transfer);
    /// Unpinned/Discharged ⟹ retires explicitly
    /// (kill+reap — nothing stranded) + LOUD skip
    /// (returns None — the caller returns). An
    /// Unpinned transfer is kill-INERT (the
    /// KillOnly drops silently with pidfd=None)
    /// while the detached waiter only waits, so
    /// proceeding would strand the live birth on
    /// any staging panic. Call BEFORE the waiter
    /// spawns. Pinned by
    /// `pinned_custody_or_skip_round_trips_pinned`
    /// and `pinned_custody_or_skip_retires_unpinned_loud`.
    #[cfg(target_arch = "x86_64")]
    fn pinned_custody_or_skip(
        custody: StagingCustody,
        pin: &GuardPin,
        what: &str,
    ) -> Option<StagingCustody> {
        if matches!(pin, GuardPin::Pinned { .. }) {
            return Some(custody);
        }
        custody.retire();
        eprintln!("skip: {what} (Unpinned — pin semantics untestable)");
        None
    }

    /// XRV1-L24/L39: split post-spawn custody on the pin —
    /// Pinned (already running, guard owns): the Child
    /// back; Unpinned (spawner left it STOPPED): the
    /// Child-handle owner (unwind-safe retirement
    /// without a pidfd) + an explicit CONT IFF `run`
    /// (running needs the owner FIRST — armed above
    /// the cont — and HELD callers pass `run=false`
    /// (the owner holds the birth STOPPED; the caller
    /// CONTs manually after its own pinning — a split
    /// that CONTed unconditionally would release a
    /// held birth early and strand it on unwind
    /// under Unsupported (XRV1-L39))).
    #[cfg(target_arch = "x86_64")]
    fn split_staging_custody(
        child: std::process::Child,
        guard: &KillReapGuard,
        run: bool,
    ) -> StagingCustody {
        match guard.pin {
            GuardPin::Pinned { .. } => StagingCustody::Pinned(child),
            _ => {
                let owner = UnpinnedStagingOwner::new(child);
                if run {
                    cont_held_birth(owner.pid());
                }
                StagingCustody::Unpinned(owner)
            }
        }
    }

    /// Stopped spawn that returns the child RUNNING +
    /// guard — XRV1-L24: CONTs ONLY Pinned
    /// (pidfd-owned). Unpinned (old-kernel/confinement
    /// — Child-handle custody) returns STOPPED — the
    /// caller splits custody explicitly via
    /// [`split_staging_custody`] (running needs an
    /// owner first — never CONT-after-Unpinned).
    #[cfg(target_arch = "x86_64")]
    fn spawn_stopped_sh_with_guard(body: &str) -> (std::process::Child, KillReapGuard) {
        let mut child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv(body))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (stopped spawn)");
        let pid = child.id() as libc::pid_t;
        let guard = pin_stopped_child(&mut child);
        if matches!(guard.pin, GuardPin::Pinned { .. }) {
            cont_held_birth(pid);
            // The child runs the body now (it may exit
            // fast — the guard is established, so later
            // recycle is handled by the guard's arms,
            // not by pinning).
        }
        // No status touch here (the caller owns the reap —
        // via the guard (Pinned) or the split owner
        // (Unpinned)).
        (child, guard)
    }

    /// XRV1-L2: stopped spawn that returns the child
    /// STILL STOPPED (same self-stop body shape — for
    /// callers that must pin further oracle state (their
    /// own pidfd via [`pidfd_open_held`]) before release;
    /// CONT via [`cont_held_birth`] when pinning is
    /// done). The returned guard covers the held window
    /// ONLY when Pinned (staging panics before CONT
    /// retire a stopped birth — SIGKILL lands on
    /// stopped). XRV1-L24/L39 invariant: every held
    /// caller EITHER gates on `probe_waitid_capability`
    /// (Supported ⟹ the pin-core returns Pinned-or-panic
    /// — Unpinned is unreachable, so the guard always
    /// owns there) OR splits custody FIRST via
    /// [`split_staging_custody`] with `run=false` (the
    /// owner holds the birth STOPPED — an ungated
    /// caller that CONTs manually without a split
    /// strands the birth on unwind under Unsupported
    /// (the guard is inert there)).
    #[cfg(target_arch = "x86_64")]
    fn spawn_stopped_sh_with_guard_held(body: &str) -> (std::process::Child, KillReapGuard) {
        let mut child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv(body))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (stopped spawn)");
        let guard = pin_stopped_child(&mut child);
        (child, guard)
    }

    /// XRV1-L2: stopped spawn into a NEW session
    /// (pre_exec setsid + self-stop body — for the
    /// third-session stranger: the stop must be
    /// self-inflicted (STOP-by-number can land on a
    /// recycled stranger) and setsid(1) would fork on
    /// group-leader (pid change under the pin), so the
    /// session op runs pre_exec (post-fork, pre-exec —
    /// syscall-only) and the stop runs post-exec in sh.
    /// setsid(2) fails EPERM only for a group leader;
    /// the child inherits the test's group (whose leader
    /// is a live ancestor) ⟹ direct success, never a
    /// fork. Returns RUNNING + guard when Pinned;
    /// STOPPED + Unpinned guard otherwise (XRV1-L24 —
    /// split custody explicitly).
    #[cfg(target_arch = "x86_64")]
    fn spawn_stopped_sh_with_guard_setsid(body: &str) -> (std::process::Child, KillReapGuard) {
        use std::os::unix::process::CommandExt as _;
        let mut command = std::process::Command::new("sh");
        command
            .arg("-c")
            .arg(stopped_spawn_argv(body))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        // SAFETY: setsid on the forked child pre-exec
        // (not a group leader — inherits ours).
        unsafe {
            command.pre_exec(|| {
                if libc::setsid() < 0 {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        let mut child = command
            .spawn()
            .expect("staging broken (setsid stopped spawn)");
        let pid = child.id() as libc::pid_t;
        let guard = pin_stopped_child(&mut child);
        // XRV1-L24: CONT only Pinned (Unpinned ⟹
        // STOPPED — split custody explicitly).
        if matches!(guard.pin, GuardPin::Pinned { .. }) {
            cont_held_birth(pid);
        }
        (child, guard)
    }

    /// XRV1-L2: stopped spawn of the controlled pair
    /// publisher (sh-wrapped `exec` — the bin cannot
    /// self-stop, so sh stops first and the pin's birth
    /// tick survives the exec; argv/env/stdio identical
    /// to a direct spawn). Args are single-quoted into
    /// the sh body (fail-closed on embedded quotes —
    /// staging-broken, never an injection). Returns
    /// RUNNING + guard when Pinned; STOPPED + Unpinned
    /// guard otherwise (XRV1-L24 — split custody
    /// explicitly).
    #[cfg(target_arch = "x86_64")]
    fn spawn_stopped_publisher(
        secs: &str,
        tail: &str,
        envs: &[(&str, &str)],
        pipe_stderr: bool,
    ) -> (std::process::Child, KillReapGuard) {
        let bin = pair_publisher_bin();
        let bin_text = bin.to_str().expect("publisher path utf8");
        for piece in std::iter::once(bin_text)
            .chain(std::iter::once(secs))
            .chain(std::iter::once(tail))
        {
            assert!(
                !piece.contains('\''),
                "staging broken (publisher arg unquotable: {piece:?})"
            );
        }
        let mut command = std::process::Command::new("sh");
        command
            .arg("-c")
            .arg(stopped_spawn_argv(&format!(
                "exec '{bin_text}' '{secs}' '{tail}'"
            )))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(if pipe_stderr {
                std::process::Stdio::piped()
            } else {
                std::process::Stdio::null()
            });
        for (key, value) in envs {
            command.env(key, value);
        }
        let mut child = command
            .spawn()
            .expect("staging broken (publisher stopped spawn)");
        let pid = child.id() as libc::pid_t;
        let guard = pin_stopped_child(&mut child);
        // XRV1-L24: CONT only Pinned (Unpinned ⟹
        // STOPPED — split custody explicitly).
        if matches!(guard.pin, GuardPin::Pinned { .. }) {
            cont_held_birth(pid);
        }
        (child, guard)
    }

    /// XRV1-L2: stopped spawn of the controlled pair
    /// publisher self-grouped (pre_exec setpgid + sh
    /// self-stop + exec — the R19-015 rule (pgid ==
    /// publisher pid from microseconds after the fork)
    /// holds: setpgid runs pre_exec in sh, and the exec
    /// preserves pid+group). Stdout AND stderr piped
    /// (read stderr only after group cleanup — see
    /// [`spawn_self_grouped_publisher`]). Returns RUNNING
    /// + guard.
    #[cfg(target_arch = "x86_64")]
    fn spawn_stopped_self_grouped_publisher(
        secs: &str,
        tail: &str,
        envs: &[(&str, &str)],
    ) -> (std::process::Child, KillReapGuard) {
        use std::os::unix::process::CommandExt as _;
        let bin = pair_publisher_bin();
        let bin_text = bin.to_str().expect("publisher path utf8");
        for piece in std::iter::once(bin_text)
            .chain(std::iter::once(secs))
            .chain(std::iter::once(tail))
        {
            assert!(
                !piece.contains('\''),
                "staging broken (publisher arg unquotable: {piece:?})"
            );
        }
        let mut command = std::process::Command::new("sh");
        command
            .arg("-c")
            .arg(stopped_spawn_argv(&format!(
                "exec '{bin_text}' '{secs}' '{tail}'"
            )))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        for (key, value) in envs {
            command.env(key, value);
        }
        // SAFETY: setpgid on self pre-exec, no userspace state.
        unsafe {
            command.pre_exec(|| {
                if libc::setpgid(0, 0) == 0 {
                    Ok(())
                } else {
                    Err(std::io::Error::last_os_error())
                }
            });
        }
        let mut child = command
            .spawn()
            .expect("self-grouped publisher stopped spawn");
        let pid = child.id() as libc::pid_t;
        let guard = pin_stopped_child(&mut child);
        // XRV1-L24: CONT only Pinned (Unpinned ⟹
        // STOPPED — split custody explicitly).
        if matches!(guard.pin, GuardPin::Pinned { .. }) {
            cont_held_birth(pid);
        }
        (child, guard)
    }

    /// XRV1-H1 collateral: a naturally-exited birth (exit
    /// 42, the reviewer's isolated check) peeks NOT
    /// signaled — and its status SURVIVES the peek for its
    /// owner (no theft).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pin_peek_spares_natural_exit_status() {
        // XRV1-L9: the verdict peeks through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin verdict untestable)");
                return;
            }
        }
        // XRV1-H6 shape: cleanup custody from spawn —
        // HELD (XRV1-L2: the oracle pin below must open
        // during the initial stop — a post-CONT open
        // races exit + ambient-sweep reap + recycle).
        let (mut child, mut _kguard) = spawn_stopped_sh_with_guard_held("exit 42");
        let pid = child.id() as libc::pid_t;
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                if _kguard.skip_discharge(&mut child) {
                    _kguard.disarm();
                } else {
                    eprintln!("pin-test skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        cont_held_birth(pid);
        use std::os::unix::io::AsRawFd as _;
        let pin_fd = pin.as_raw_fd();
        // Settle zombie WITHOUT reaping (state reads only).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while proc_state(pid) != Some('Z') {
            assert!(
                std::time::Instant::now() < end,
                "exiter must zombify (still {0:?})",
                proc_state(pid)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            !pin_peek_signaled(pin_fd),
            "a natural exit must never peek signaled (else the await would steal it)"
        );
        // The owner's status survived our peek, intact.
        let status = child.wait().expect("owner reaps");
        _kguard.disarm();
        assert_eq!(status.code(), Some(42), "exit status must survive the peek");
    }

    /// XRV1-H1 collateral: a SIGKILLed birth peeks
    /// signaled (the await may consume it).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pin_peek_admits_signaled_death() {
        use std::os::unix::process::ExitStatusExt as _;
        // XRV1-L9: the verdict peeks through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin verdict untestable)");
                return;
            }
        }
        // XRV1-L2: HELD stopped-sleep (guard + oracle pin
        // during the stop; CONT once pinned — the victim
        // must run to be killed).
        let (mut child, mut _kguard) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                if _kguard.skip_discharge(&mut child) {
                    _kguard.disarm();
                } else {
                    eprintln!("pin-test skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        cont_held_birth(pid);
        use std::os::unix::io::AsRawFd as _;
        let pin_fd = pin.as_raw_fd();
        child.kill().expect("kill lands");
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            if pin_peek_signaled(pin_fd) {
                break;
            }
            assert!(std::time::Instant::now() < end, "victim must die signaled");
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Sole consumer: reap via the handle (the pin only
        // peeked — WNOWAIT consumed nothing).
        let status = child.wait().expect("owner reaps");
        _kguard.disarm();
        assert!(
            status.signal() == Some(libc::SIGKILL),
            "signaled death must survive the peek (status {status:?})"
        );
    }

    /// XRV1-I1 collateral: a SIGTERM death peeks NOT
    /// signaled-ours (another signal's status is never
    /// ours to consume — the reviewer's isolated check).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pin_peek_spares_foreign_signal_death() {
        use std::os::unix::process::ExitStatusExt as _;
        // XRV1-L9: the verdict peeks through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin verdict untestable)");
                return;
            }
        }
        // XRV1-L2: HELD stopped-sleep (guard + oracle pin
        // during the stop; CONT once pinned).
        let (mut child, mut _kguard) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                if _kguard.skip_discharge(&mut child) {
                    _kguard.disarm();
                } else {
                    eprintln!("pin-test skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        cont_held_birth(pid);
        use std::os::unix::io::AsRawFd as _;
        let pin_fd = pin.as_raw_fd();
        assert_eq!(unsafe { libc::kill(pid, libc::SIGTERM) }, 0, "term lands");
        // Settle zombie WITHOUT reaping (state reads only).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while proc_state(pid) != Some('Z') {
            assert!(
                std::time::Instant::now() < end,
                "termed birth must zombify (still {0:?})",
                proc_state(pid)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            !pin_peek_signaled(pin_fd),
            "a SIGTERM death must never peek signaled-ours (else the await would steal it)"
        );
        // The owner's status survived our peek, intact.
        let status = child.wait().expect("owner reaps");
        _kguard.disarm();
        assert_eq!(
            status.signal(),
            Some(libc::SIGTERM),
            "foreign signal must survive the peek (status {status:?})"
        );
    }

    /// XRV1-J1 collateral: deterministic status-theft
    /// proof — the guard's drop over a sweep-reaped birth
    /// must not consume a recycled same-tick zombie's
    /// status. Staging (userns+pidns+mountns, all
    /// rootless): `ns_last_pid` (writable as userns-root)
    /// forces PID recycle; jiffy-edge sync + tick verify
    /// forces same-tick; pure fork (no exec) keeps the
    /// pair inside one jiffy. The scenario runs in a
    /// twice-forked child (the middle fork is a
    /// malloc-free raw-syscall zone — fork in a threaded
    /// test binary — the inner child is single-threaded
    /// and runs full Rust); the verdict crosses a pipe.
    /// Bad control: the same staging with a bare numeric
    /// waitpid MUST steal (a non-stealing bad control is
    /// broken staging — fail loud, never a vacuous
    /// green). Unstageable hosts (no userns, read-only
    /// sysctl, unalignable clock) skip loud. A BAD leg
    /// that never stages while MAIN reads ok skips loud
    /// too (R13 gate — partial staging is a control-leg
    /// staging limitation, not a product verdict; a
    /// stolen MAIN REDs regardless).

    /// J1 partial-staging rule (R13 gate round 20):
    /// MAIN ok + BAD unstageable (empty + the SKIP
    /// bad-leg marker present) ⟹ loud SKIP. Every
    /// other shape flows to the asserts: a stolen
    /// MAIN REDs even with an unstageable BAD (no
    /// masking — main == "ok" is required), a
    /// missing marker REDs (a dead scenario must
    /// never skip), and any BAD verdict (stole or
    /// nosteal) judges normally. Pinned by
    /// `j1_partial_skip_needs_ok_main_and_unstageable_bad`.
    #[cfg(target_arch = "x86_64")]
    fn j1_partial_skip(main: &str, bad: &str, verdict: &str) -> bool {
        bad.is_empty() && main == "ok" && verdict.contains("SKIP bad-leg")
    }

    /// R13-gate collateral: the J1 partial-skip rule
    /// fires ONLY for (ok, unstageable-with-marker)
    /// — a mutant dropping any conjunct either
    /// skips a must-RED shape or REDs the genuine
    /// partial shape (mutant-checked).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn j1_partial_skip_needs_ok_main_and_unstageable_bad() {
        // The genuine partial shape skips.
        assert!(j1_partial_skip(
            "ok",
            "",
            "MAIN ok\nSKIP bad-leg pair unalignable\n"
        ));
        // A stolen MAIN never skips (no masking).
        assert!(!j1_partial_skip(
            "stolen (waitpid(99) got=-1 errno=10)",
            "",
            "MAIN stolen (waitpid(99) got=-1 errno=10)\nSKIP bad-leg pair unalignable\n"
        ));
        // A missing marker never skips (dead
        // scenario ⟹ RED below).
        assert!(!j1_partial_skip("ok", "", "MAIN ok\n"));
        // Any BAD verdict judges normally.
        assert!(!j1_partial_skip("ok", "stole", "MAIN ok\nBAD stole\n"));
        assert!(!j1_partial_skip(
            "ok",
            "nosteal (waitpid(99) got=-1 errno=10)",
            "MAIN ok\nBAD nosteal (waitpid(99) got=-1 errno=10)\n"
        ));
    }

    /// XRV1-L90 collateral: the J1 inner/outer oracle
    /// fires ONLY on a PROVEN wrong procfs view — an
    /// inner Unsupported with a WRONG view tag while
    /// the outer probe reads Supported. An inner
    /// Unsupported with an OWN view is legitimate
    /// contextual denial (e.g. a filter denying
    /// pidfd_open(1) hits the namespace init's
    /// precheck but not the outer process — same
    /// correct view) ⟹ skip, never RED. Untagged /
    /// unknown views and outer-nonsupported also skip
    /// (unproven ⟹ never RED — the L82 philosophy).
    #[cfg(target_arch = "x86_64")]
    fn j1_view_oracle(inner_skip_reason: &str, outer_supported: bool) -> bool {
        inner_skip_reason.contains("waitid(P_PIDFD) Unsupported")
            && inner_skip_reason.contains("(procview WRONG)")
            && outer_supported
    }

    /// XRV1-L90 collateral: the view oracle needs a
    /// WRONG tag plus a Supported outer — a mutant
    /// dropping any conjunct either REDs legitimate
    /// denial or greens a wrong view (mutant-checked).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn j1_view_oracle_needs_wrong_view_and_supported_outer() {
        // The genuine wrong view REDs.
        assert!(j1_view_oracle(
            "waitid(P_PIDFD) Unsupported (procview WRONG)",
            true
        ));
        // Legitimate contextual denial skips (L90).
        assert!(!j1_view_oracle(
            "waitid(P_PIDFD) Unsupported (procview own)",
            true
        ));
        // Unknown / unproven views never RED.
        assert!(!j1_view_oracle(
            "waitid(P_PIDFD) Unsupported (procview unknown)",
            true
        ));
        assert!(!j1_view_oracle("waitid(P_PIDFD) Unsupported", true));
        // Outer-nonsupported never REDs (agreement).
        assert!(!j1_view_oracle(
            "waitid(P_PIDFD) Unsupported (procview WRONG)",
            false
        ));
        // Transient never REDs.
        assert!(!j1_view_oracle(
            "waitid(P_PIDFD) Transient (procview WRONG)",
            true
        ));
    }

    /// XRV1-L111 collateral: the self-PID view
    /// predicate — the PID field of a stat body
    /// (before the FIRST paren — comm parens
    /// cannot shift it) equals the caller's
    /// getpid ⟺ the view names us. Match,
    /// mismatch, comm-with-parens, and garbage
    /// (fail-closed: unparseable ⟹ NOT own —
    /// an alien /proc is a wrong view).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn procview_self_pid_table() {
        assert!(procview_self_matches(b"12345 (sleep) S 1 2 3", 12345));
        assert!(procview_self_matches(b"99 (my (weird) sleep) S 1 2 3", 99));
        assert!(!procview_self_matches(b"99 (sleep) S 1 2 3", 100));
        assert!(!procview_self_matches(b"not a stat line", 1));
        assert!(!procview_self_matches(b"", 1));
        assert!(!procview_self_matches(b"abc (x) S 1", 1));
    }

    /// XRV1-L111: the self-PID view predicate,
    /// pure — the stat body's PID field (before
    /// the FIRST paren — comm parens cannot
    /// shift it) equals the caller's getpid ⟺
    /// the view names us. Unparseable ⟹ false
    /// (fail-closed — an alien /proc is a
    /// wrong view). Pinned by
    /// `procview_self_pid_table`.
    #[cfg(target_arch = "x86_64")]
    fn procview_self_matches(stat: &[u8], me: libc::pid_t) -> bool {
        let field = match stat.split(|byte| *byte == b'(').next() {
            Some(field) => field,
            None => return false,
        };
        let text = match std::str::from_utf8(field) {
            Ok(text) => text.trim(),
            Err(_) => return false,
        };
        match text.parse::<libc::pid_t>() {
            Ok(pid) => pid == me,
            Err(_) => false,
        }
    }

    /// XRV1-L90/L111 collateral: direct
    /// procfs-view proof — /proc/self/stat names
    /// OUR getpid ⟺ this /proc is the
    /// namespace's own view. The old tick(1) ==
    /// tick(self) compare answered "am I init",
    /// not "is this my view" (a non-init under
    /// its OWN view misread WRONG). Under an
    /// inherited (outer) view /proc/self
    /// resolves to the outer PID ≠ getpid ⟹
    /// foreign. Unreadable ⟹ unknown (the
    /// caller cites unknown ⟹ skip, never RED).
    #[cfg(target_arch = "x86_64")]
    fn j1_procview_own() -> Option<bool> {
        let stat = std::fs::read("/proc/self/stat").ok()?;
        // SAFETY: getpid (no effect — identity only).
        let me = unsafe { libc::getpid() };
        Some(procview_self_matches(&stat, me))
    }

    /// XRV1-L90/L111 collateral: under the
    /// process's OWN /proc the view check reads
    /// own — for ANY process, init or not (the
    /// old own⟺is_init agreement pinned the L111
    /// bug: a non-init under its own view
    /// misread WRONG). STRICT (no skip):
    /// /proc/self/stat is readable even under
    /// hidepid (it is self), and a suite-wide
    /// foreign view indicts every tick
    /// observation (the J1 consumer's WRONG arm
    /// is loud too). The ns-init test below pins
    /// the foreign direction (loud skip where
    /// unshare is refused).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn j1_procview_check_reads_own_under_own_view() {
        assert_eq!(
            j1_procview_own(),
            Some(true),
            "own /proc must read own (a foreign suite-wide view indicts every tick observation)"
        );
    }

    /// XRV1-L111 probe body (fresh image,
    /// SCOPEBASE_PROCVIEW_NSINIT) — a pidns init
    /// (getpid() == 1) under the INHERITED outer
    /// /proc (no mount — the L111 shape) must read
    /// FOREIGN (/proc/self resolves to the outer
    /// PID ≠ 1). The grandchild is raw-only past
    /// the fork (a verdict word down the pipe +
    /// _exit — the parent judges). Unshare/map
    /// refusal ⟹ loud skip (confined host).
    #[cfg(target_arch = "x86_64")]
    fn procview_ns_init_probe() {
        // SAFETY: getuid/getgid pre-unshare
        // (post-unshare they report the
        // overflow id — identity FIRST).
        let euid = unsafe { libc::getuid() };
        let egid = unsafe { libc::getgid() };
        // SAFETY: unshare (effect confined to
        // this fresh image).
        if unsafe { libc::unshare(libc::CLONE_NEWUSER | libc::CLONE_NEWPID) } != 0 {
            eprintln!("PROCVIEW-NS-INIT skip: unshare refused");
            return;
        }
        // Identity maps (deny setgroups first —
        // best-effort; the maps are required).
        let _ = std::fs::write("/proc/self/setgroups", "deny\n");
        if std::fs::write("/proc/self/uid_map", format!("0 {euid} 1\n")).is_err() {
            eprintln!("PROCVIEW-NS-INIT skip: uid_map refused");
            return;
        }
        if std::fs::write("/proc/self/gid_map", format!("0 {egid} 1\n")).is_err() {
            eprintln!("PROCVIEW-NS-INIT skip: gid_map refused");
            return;
        }
        let mut pipe = [0; 2];
        // SAFETY: pipe (ends closed below).
        assert_eq!(unsafe { libc::pipe(pipe.as_mut_ptr()) }, 0, "pipe");
        // SAFETY: fork (the child is raw-only +
        // _exits — never returns).
        let kid = unsafe { libc::fork() };
        assert!(kid >= 0, "ns fork stages");
        if kid == 0 {
            // SAFETY: raw close/write/_exit only.
            unsafe {
                libc::close(pipe[0]);
                // SAFETY: getpid (identity only).
                let word: &[u8] = if libc::getpid() != 1 {
                    b"NOTINIT"
                } else {
                    match j1_procview_own() {
                        Some(true) => b"OWNBUG",
                        Some(false) => b"FOREIGN",
                        None => b"UNKNOWN",
                    }
                };
                let mut at = 0;
                while at < word.len() {
                    let wrote = libc::write(
                        pipe[1],
                        word.as_ptr().add(at) as *const libc::c_void,
                        (word.len() - at) as libc::size_t,
                    );
                    if wrote <= 0 {
                        break;
                    }
                    at += wrote as usize;
                }
                libc::close(pipe[1]);
                libc::_exit(0);
            }
        }
        // SAFETY: close our write end; blocking
        // read + reap of our own fork child.
        unsafe { libc::close(pipe[1]) };
        let mut verdict = [0u8; 8];
        let mut len = 0;
        loop {
            // SAFETY: bounded read from our pipe.
            let got = unsafe {
                libc::read(
                    pipe[0],
                    verdict.as_mut_ptr().add(len) as *mut libc::c_void,
                    (verdict.len() - len) as libc::size_t,
                )
            };
            if got <= 0 {
                break;
            }
            len += got as usize;
            if len >= verdict.len() {
                break;
            }
        }
        // SAFETY: close + reap our own child.
        unsafe { libc::close(pipe[0]) };
        let mut status = 0;
        let got = unsafe { libc::waitpid(kid, &mut status, 0) };
        assert_eq!(got, kid, "ns child reaped");
        match &verdict[..len] {
            b"FOREIGN" => {
                eprintln!("PROCVIEW-NS-INIT foreign");
            }
            b"UNKNOWN" => {
                eprintln!("PROCVIEW-NS-INIT skip: stat unreadable in ns");
            }
            b"OWNBUG" => {
                panic!("oracle bug (ns-init under inherited /proc reads OWN)");
            }
            b"NOTINIT" => {
                panic!("staging broken (ns child is not init)");
            }
            _ => {
                panic!("staging broken (ns child died silent)");
            }
        }
    }

    /// XRV1-L111 collateral: the foreign direction
    /// — a pidns init under an inherited outer
    /// /proc (no fresh mount) reads FOREIGN. Runs
    /// the probe in a fresh image (unshare must
    /// not leak into the suite); confined hosts
    /// skip loud (unshare/map refusal).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn procview_detects_wrong_view_as_ns_init() {
        if std::env::var("SCOPEBASE_PROCVIEW_NSINIT").is_ok() {
            procview_ns_init_probe();
            return;
        }
        let exe = std::env::current_exe().expect("own test binary");
        let mut out = std::process::Command::new(exe);
        out.arg("--exact")
            .arg("fixture::linux::audit::tests::procview_detects_wrong_view_as_ns_init")
            .arg("--nocapture")
            .env("SCOPEBASE_PROCVIEW_NSINIT", "1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // L144: pre-exec IGN (a group-HUP
        // mid-startup murders default probes).
        arm_hup_immune_spawn(&mut out);
        let out = out.output().expect("probe child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(out.status.success(), "probe must run\n{stderr}");
        assert!(
            stderr.contains("PROCVIEW-NS-INIT foreign")
                || stderr.contains("PROCVIEW-NS-INIT skip:"),
            "probe must cite foreign or a loud skip\n{stderr}"
        );
    }
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn kill_reap_guard_drop_spares_sweep_recycled_status() {
        // SAFETY: pipe/fork/waitpid raw; the fork children
        // _exit (never return into the harness).
        let mut pipe = [0; 2];
        assert_eq!(unsafe { libc::pipe(pipe.as_mut_ptr()) }, 0, "pipe");
        // XRV1-L93: held spawn (self-stop first —
        // the middle is malloc-free (raw syscalls
        // only — see its doc)). Spawn failure (fork
        // or pin) ⟹ loud skip (L52 —
        // Transient-inexhaustion never REDs; no pin ⟹
        // C2 supervision unstageable — close both
        // pipe ends, nothing staged).
        let (first, _pin) =
            match spawn_held_fork_child(j1_held_body, (pipe[0], pipe[1]), "J1 middle") {
                Ok(pair) => pair,
                Err(errno) => {
                    unsafe {
                        libc::close(pipe[0]);
                        libc::close(pipe[1]);
                    }
                    eprintln!("skip: J1 middle unstageable (errno {errno})");
                    return;
                }
            };
        unsafe { libc::close(pipe[1]) };
        let mut verdict = String::new();
        {
            use std::io::Read as _;
            use std::os::unix::io::FromRawFd as _;
            let mut reader = unsafe { std::fs::File::from_raw_fd(pipe[0]) };
            reader
                .read_to_string(&mut verdict)
                .expect("verdict readable");
        }
        let mut status = 0;
        // SAFETY: our own fork-child, blocking.
        let got = unsafe { libc::waitpid(first, &mut status, 0) };
        assert_eq!(got, first, "middle child reaped");
        assert!(
            libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 0,
            "middle child must exit clean (status {status})"
        );
        if let Some(reason) = verdict.strip_prefix("SKIP ") {
            // XRV1-L67/L90: inner/outer capability
            // agreement — the scenario probes under the
            // namespace's OWN procfs (mount precedes
            // the probe). L90 revision: disagreement
            // ALONE is not a wrong view (a filter
            // denying pidfd_open(1) legitimately denies
            // the namespace init's precheck while
            // permitting the outer process — same
            // correct view) — the oracle fires ONLY on
            // the scenario's DIRECT WRONG-view proof
            // plus a Supported outer (an OWN view is
            // legitimate contextual denial ⟹ loud
            // skip). The contains pre-filter avoids
            // running the outer probe for unrelated
            // skips (the oracle itself is
            // authoritative). Transient stays a loud
            // skip.
            if reason.contains("waitid(P_PIDFD) Unsupported")
                && j1_view_oracle(reason, probe_waitid_capability() == ProbeVerdict::Supported)
            {
                panic!(
                    "J1 inner/outer probe disagreement (inner Unsupported under a WRONG procfs view, outer Supported)"
                );
            }
            eprintln!("skip: J1 theft staging unavailable ({reason})");
            return;
        }
        let mut main = "";
        let mut bad = "";
        for line in verdict.lines() {
            if let Some(rest) = line.strip_prefix("MAIN ") {
                main = rest;
            }
            if let Some(rest) = line.strip_prefix("BAD ") {
                bad = rest;
            }
        }
        // Partial staging (R13 gate round 20: MAIN
        // ok + SKIP bad-leg): the MAIN product
        // verdict is GENUINE (verified aligned pair)
        // but uncontrolled (the BAD leg missed
        // staging luck) ⟹ SKIP loud — a control that
        // never staged is a staging limitation, not
        // a product verdict. A stolen MAIN REDs
        // below regardless (no masking — the rule
        // requires main == "ok").
        if j1_partial_skip(main, bad, &verdict) {
            eprintln!("skip: J1 bad-leg unstageable (MAIN ok uncontrolled: {verdict:?})");
            return;
        }
        assert_eq!(
            bad, "stole",
            "bad control must steal (else staging never aligned recycle+tick: {verdict:?})"
        );
        assert_eq!(
            main, "ok",
            "guard drop over a sweep-reaped birth must spare the recycled status ({verdict:?})"
        );
    }

    /// XRV1-L6: alarm suicide handler (shared by the
    /// J1 scenario child and the plumbing test): a pidns
    /// init IGNORES default-disposition SIGALRM (fatal
    /// signals without handlers never land on any init —
    /// init must install a handler), so the scenario's
    /// deadline needs this installed handler, and the
    /// handler _exits (returning would resume into
    /// std's EINTR-retried reads — the hang would
    /// continue). Async-signal-safe (bare _exit, no
    /// captures) — callable from malloc-free fork
    /// children.
    #[cfg(target_arch = "x86_64")]
    extern "C" fn j6_alarm_suicide(_signal: libc::c_int) {
        unsafe { libc::_exit(60) };
    }

    /// XRV1-L6 collateral: the alarm-suicide plumbing —
    /// a fork child (NOT init — the init case is
    /// structural: same install, same handler) that
    /// installs the suicide handler, arms alarm(1), and
    /// pauses must exit 60 via the handler (proving
    /// install+delivery+suicide, not merely that alarm()
    /// was called). Deterministic (no timing: pause
    /// sleeps until the 1s delivery). The fork child is
    /// malloc-free (sigaction/alarm/pause/_exit only —
    /// sound in a threaded test binary). XRV1-L20: the
    /// parent blocks SIGALRM before forking (the child
    /// INHERITS a blocked mask — installing a handler
    /// does NOT unblock it) and the child must unblock
    /// explicitly; the parent's wait is BOUNDED (a
    /// wedged child fails loud, never hangs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn alarm_handler_suicides_hung_child() {
        // XRV1-L20: inherit-blocked mask (restored
        // immediately post-fork — never leaked into the
        // harness).
        let mut blocked: libc::sigset_t = unsafe { std::mem::zeroed() };
        let mut saved: libc::sigset_t = unsafe { std::mem::zeroed() };
        // SAFETY: zeroed sigset in/out params.
        unsafe {
            libc::sigemptyset(&mut blocked);
            libc::sigaddset(&mut blocked, libc::SIGALRM);
            libc::pthread_sigmask(libc::SIG_BLOCK, &blocked, &mut saved);
        }
        // SAFETY: fork in a threaded binary — the child
        // path below is malloc-free and _exits (never
        // returns into the harness); the parent waitpids.
        let pid = unsafe { libc::fork() };
        assert!(pid >= 0, "fork must succeed");
        if pid == 0 {
            unsafe {
                let mut action: libc::sigaction = std::mem::zeroed();
                action.sa_sigaction = j6_alarm_suicide as extern "C" fn(libc::c_int) as usize;
                libc::sigemptyset(&mut action.sa_mask);
                action.sa_flags = 0;
                if libc::sigaction(libc::SIGALRM, &action, std::ptr::null_mut()) != 0 {
                    libc::_exit(61);
                }
                // XRV1-L20: unblock SIGALRM explicitly
                // (installing a handler does NOT unblock
                // an inherited mask — malloc-free,
                // async-signal-safe).
                let mut unblock: libc::sigset_t = std::mem::zeroed();
                libc::sigemptyset(&mut unblock);
                libc::sigaddset(&mut unblock, libc::SIGALRM);
                if libc::pthread_sigmask(libc::SIG_UNBLOCK, &unblock, std::ptr::null_mut()) != 0 {
                    libc::_exit(63);
                }
                libc::alarm(1);
                libc::pause();
                // The handler _exits — reaching here
                // means delivery failed.
                libc::_exit(62);
            }
        }
        // Parent-only restore (the child above never
        // falls through — every path _exits — so the
        // child keeps the inherit-blocked mask while the
        // harness never sees it).
        // SAFETY: saved parent mask.
        unsafe {
            libc::pthread_sigmask(libc::SIG_SETMASK, &saved, std::ptr::null_mut());
        }
        // Bounded supervisor wait (a mask-wedged child
        // must fail loud here, never hang the suite).
        let mut status = 0;
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            // SAFETY: our own fork-child, WNOHANG poll.
            let got = unsafe { libc::waitpid(pid, &mut status, libc::WNOHANG) };
            if got == pid {
                break;
            }
            assert!(got >= 0, "suicide wait must not error");
            if std::time::Instant::now() >= end {
                // SAFETY: our own fork-child.
                unsafe {
                    libc::kill(pid, libc::SIGKILL);
                    libc::waitpid(pid, &mut status, 0);
                }
                panic!("alarm child wedged past 10s (masked SIGALRM?)");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(
            libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 60,
            "alarm handler must suicide the hung child (status {status})"
        );
    }

    /// XRV1-L93 collateral: J1 middle body adaptor
    /// (tuple args for the held-spawn contract).
    #[cfg(target_arch = "x86_64")]
    fn j1_held_body(args: (libc::c_int, libc::c_int)) -> ! {
        j1_theft_middle(args.0, args.1)
    }
    /// XRV1-J1 staging, middle fork: enters the namespaces
    /// (user+pid+mount — the pidns applies to OUR
    /// children) and forks the single-threaded scenario
    /// runner. MALLOC-FREE ZONE (forked from a threaded
    /// test binary): raw syscalls + stack buffers only —
    /// no format!/String/panic!/assert! (all allocate);
    /// failures write a static SKIP line to the pipe and
    /// _exit(0); logic violations _exit nonzero. Never
    /// returns.
    #[cfg(target_arch = "x86_64")]
    fn j1_theft_middle(pipe_read: libc::c_int, pipe_write: libc::c_int) -> ! {
        // SAFETY: all calls below are async-signal-safe
        // raw syscalls; buffers are stack-local.
        unsafe {
            libc::close(pipe_read);
            // u32 -> decimal into a stack buffer; returns
            // the filled length.
            fn push_u32(buf: &mut [u8; 64], mut at: usize, mut value: u32) -> usize {
                let mut digits = [0u8; 10];
                let mut len = 0;
                if value == 0 {
                    digits[0] = b'0';
                    len = 1;
                }
                while value > 0 {
                    digits[len] = b'0' + (value % 10) as u8;
                    value /= 10;
                    len += 1;
                }
                let mut i = len;
                while i > 0 {
                    i -= 1;
                    buf[at] = digits[i];
                    at += 1;
                }
                at
            }
            // Write the whole buffer (short helper — the
            // payloads are tiny; partial writes retry).
            unsafe fn write_all(fd: libc::c_int, mut ptr: *const u8, mut len: usize) -> bool {
                while len > 0 {
                    let wrote = libc::write(fd, ptr as *const libc::c_void, len);
                    if wrote <= 0 {
                        return false;
                    }
                    ptr = ptr.add(wrote as usize);
                    len -= wrote as usize;
                }
                true
            }
            unsafe fn skip_out(pipe_write: libc::c_int, reason: &[u8]) -> ! {
                let _ = write_all(pipe_write, c"SKIP ".as_ptr() as *const u8, 5);
                let _ = write_all(pipe_write, reason.as_ptr(), reason.len());
                let _ = write_all(pipe_write, c"\n".as_ptr() as *const u8, 1);
                libc::_exit(0);
            }
            // Identity FIRST (pre-unshare: after the
            // unshare getuid reports the overflow id and
            // the map write is refused).
            let euid = libc::getuid();
            let egid = libc::getgid();
            if libc::unshare(libc::CLONE_NEWUSER | libc::CLONE_NEWPID | libc::CLONE_NEWNS) != 0 {
                skip_out(pipe_write, b"unshare refused");
            }
            // Identity maps (deny setgroups first — else
            // the gid map is refused).
            let setgroups = libc::open(
                c"/proc/self/setgroups".as_ptr(),
                libc::O_WRONLY | libc::O_CLOEXEC,
            );
            if setgroups >= 0 {
                let _ = write_all(setgroups, c"deny\n".as_ptr() as *const u8, 5);
                libc::close(setgroups);
            }
            let mut map = [0u8; 64];
            let mut at = push_u32(&mut map, 0, 0);
            map[at] = b' ';
            at = push_u32(&mut map, at + 1, euid);
            map[at] = b' ';
            at = push_u32(&mut map, at + 1, 1);
            map[at] = b'\n';
            at += 1;
            let uid_map = libc::open(
                c"/proc/self/uid_map".as_ptr(),
                libc::O_WRONLY | libc::O_CLOEXEC,
            );
            if uid_map < 0 || !write_all(uid_map, map.as_ptr(), at) || libc::close(uid_map) != 0 {
                skip_out(pipe_write, b"uid_map refused");
            }
            let mut gmap = [0u8; 64];
            let mut gat = push_u32(&mut gmap, 0, 0);
            gmap[gat] = b' ';
            gat = push_u32(&mut gmap, gat + 1, egid);
            gmap[gat] = b' ';
            gat = push_u32(&mut gmap, gat + 1, 1);
            gmap[gat] = b'\n';
            gat += 1;
            let gid_map = libc::open(
                c"/proc/self/gid_map".as_ptr(),
                libc::O_WRONLY | libc::O_CLOEXEC,
            );
            if gid_map < 0 || !write_all(gid_map, gmap.as_ptr(), gat) || libc::close(gid_map) != 0 {
                skip_out(pipe_write, b"gid_map refused");
            }
            let second = libc::fork();
            if second < 0 {
                skip_out(pipe_write, b"second fork refused");
            }
            if second == 0 {
                j1_theft_scenario(pipe_write);
            }
            // XRV1-L6 supervisor deadline (the middle
            // SURVIVES to enforce it — a bare alarm would
            // merely suicide the middle (default
            // disposition) and orphan a hung scenario
            // holding the verdict pipe): poll the scenario
            // 25s (WNOHANG + nanosleep — all raw); on
            // expiry SIGKILL + blocking-reap it (a pidns
            // init ignores SIGALRM-without-handler, but
            // NOTHING ignores SIGKILL) and _exit(42) so
            // the parent fails LOUD on the non-clean exit
            // (hang ⟹ staging bug ⟹ loud, never a wedged
            // suite). Irreducible residual: D-state
            // (uninterruptible sleep ignores even SIGKILL
            // — no supervisor of any shape can cover it;
            // nothing here sleeps uninterruptibly: proc
            // mounts, forks, and a parent-drained pipe).
            let mut now: libc::timespec = std::mem::zeroed();
            libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut now);
            let deadline = now.tv_sec + 25;
            loop {
                let mut status = 0;
                let got = libc::waitpid(second, &mut status, libc::WNOHANG);
                if got == second {
                    break;
                }
                if got < 0 {
                    // ECHILD is impossible (we never
                    // reaped — the only waiter) — logic
                    // violation, loud.
                    libc::_exit(43);
                }
                libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut now);
                if now.tv_sec >= deadline {
                    libc::kill(second, libc::SIGKILL);
                    let mut status = 0;
                    libc::waitpid(second, &mut status, 0);
                    libc::_exit(42);
                }
                let nap = libc::timespec {
                    tv_sec: 0,
                    tv_nsec: 10_000_000,
                };
                libc::nanosleep(&nap, std::ptr::null_mut());
            }
            libc::_exit(0);
        }
    }

    /// XRV1-J1 staging, inner fork: single-threaded (child
    /// of a single-threaded child) — full Rust is sound
    /// here. Mounts a fresh /proc (private mountns), then
    /// stages two recycle+same-tick pairs: the MAIN leg
    /// drops a KillReapGuard over the sweep-reaped birth
    /// (verdict MAIN ok/stolen), the BAD leg reaps the
    /// recycled zombie with a bare numeric waitpid (the
    /// pre-fix shape — verdict BAD stole/nosteal). Never
    /// returns (writes the verdict + _exits).
    #[cfg(target_arch = "x86_64")]
    fn j1_theft_scenario(pipe_write: libc::c_int) -> ! {
        // SAFETY: mount over /proc inside our private
        // mountns only; the write end is ours.
        unsafe {
            use std::io::Write as _;
            use std::os::unix::io::FromRawFd as _;
            // Hang backstop, PRIMARY (XRV1-K8: set HERE —
            // the middle's context does not survive the
            // fork; XRV1-L6: WITH an installed handler —
            // this child is a pidns init, which IGNORES
            // default-disposition SIGALRM — and the
            // handler _exits (returning would resume into
            // EINTR-retried reads)). A hung scenario
            // suicides at 20s; the middle reaps it and
            // the parent fails loud on the short verdict
            // (hang ⟹ staging bug ⟹ loud, never a wedged
            // suite). The middle's 25s poll is the
            // backstop.
            let mut action: libc::sigaction = std::mem::zeroed();
            action.sa_sigaction = j6_alarm_suicide as extern "C" fn(libc::c_int) as usize;
            libc::sigemptyset(&mut action.sa_mask);
            action.sa_flags = 0;
            if libc::sigaction(libc::SIGALRM, &action, std::ptr::null_mut()) != 0 {
                libc::_exit(61);
            }
            // XRV1-L20: unblock SIGALRM explicitly (an
            // inherited blocked mask would wedge the
            // suicide — same class as the plumbing
            // test; malloc-free).
            let mut unblock: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&mut unblock);
            libc::sigaddset(&mut unblock, libc::SIGALRM);
            if libc::pthread_sigmask(libc::SIG_UNBLOCK, &unblock, std::ptr::null_mut()) != 0 {
                libc::_exit(63);
            }
            libc::alarm(20);
            let mut pipe = std::fs::File::from_raw_fd(pipe_write);
            macro_rules! skip {
                ($reason:expr) => {{
                    let _ = writeln!(pipe, "SKIP {}", $reason);
                    libc::_exit(0);
                }};
            }
            // XRV1-L67: the fresh /proc comes FIRST
            // (the probe's qualifier reads
            // /proc/PID/stat — under the INHERITED
            // view a namespace-local child number
            // resolves to a parent-namespace stranger
            // (a normal non-stopped PID 2 reads
            // capability-absent) ⟹ false skip before
            // the scenario runs — mount, THEN probe).
            // Fresh /proc for the new pidns (tick reads +
            // ns_last_pid need OUR namespace's view).
            if libc::mount(
                c"proc".as_ptr(),
                c"/proc".as_ptr(),
                c"proc".as_ptr(),
                0,
                std::ptr::null(),
            ) != 0
            {
                skip!("proc mount refused");
            }
            // XRV1-L9: the MAIN verdict IS a pin-drop —
            // without both capabilities the guard is
            // Unpinned and MAIN would pass vacuously (a
            // silent drop steals nothing). Skip loud.
            // XRV1-L24: settled verdict (Transient
            // spins bounded — alloc-free, fork-safe).
            // The verdict is CITED (the parent's L67
            // agreement oracle distinguishes Unsupported
            // from Transient).
            let inner_probe = probe_waitid_capability();
            if inner_probe != ProbeVerdict::Supported {
                // XRV1-L90: cite the DIRECT view proof
                // (an inner Unsupported with an OWN view
                // is legitimate contextual denial — only
                // a WRONG view indicts the staging).
                let view = match j1_procview_own() {
                    Some(true) => "own",
                    Some(false) => "WRONG",
                    None => "unknown",
                };
                skip!(&format!(
                    "waitid(P_PIDFD) {inner_probe:?} (procview {view})"
                ));
            }
            // One recycle+same-tick pair: fork A (pure
            // fork, _exit — no exec, keeps the pair inside
            // one jiffy), ARM THE GUARD WHILE A LIVES
            // (before any wait — the true J1 shape),
            // sweep-reap A via waitpid(-1) (the in-tree
            // sweep shape), pin the allocator with
            // ns_last_pid, fork B (recycled number),
            // verify number + tick. Retries across jiffy
            // edges; None past the bound (unalignable).
            // Misaligned attempts disarm explicitly (the
            // drop would be a silent no-op on a tick
            // mismatch anyway — hygiene, not soundness).
            fn stage_pair() -> Option<(KillReapGuard, libc::pid_t, libc::pid_t)> {
                for _ in 0..60 {
                    // Jiffy-edge sync: /proc/uptime ticks in
                    // centiseconds off the same clock as
                    // starttime — starting just after a flip
                    // maximizes the in-jiffy window.
                    let first = std::fs::read_to_string("/proc/uptime").ok()?;
                    let field = first.split_whitespace().next()?.to_string();
                    let edge = std::time::Instant::now() + std::time::Duration::from_millis(50);
                    loop {
                        let now = std::fs::read_to_string("/proc/uptime").ok()?;
                        let now_field = now.split_whitespace().next()?;
                        if now_field != field || std::time::Instant::now() >= edge {
                            break;
                        }
                    }
                    // SAFETY: fork in a single-threaded
                    // child; the fork-child self-stops
                    // FIRST (raw kill — no allocator, no
                    // destructors), then _exits on CONT.
                    let apid = unsafe { libc::fork() };
                    if apid < 0 {
                        return None;
                    }
                    if apid == 0 {
                        // XRV1-L10: CHECKED self-stop (a
                        // denied stop dies loud (99),
                        // never runs on).
                        unsafe {
                            if libc::kill(libc::getpid(), libc::SIGSTOP) != 0 {
                                libc::_exit(99);
                            }
                            libc::_exit(11)
                        };
                    }
                    // XRV1-L2: T-await A (self-stopped ⟹
                    // cannot exit ⟹ unreaped ⟹ the sample
                    // names A — the fork-isolation argument
                    // below is now the second layer, not
                    // the only one). Self-stop has no
                    // signal-delivery latency (synchronous
                    // self-infliction) — the T-await costs
                    // ~one stat read, inside the jiffy
                    // budget the 60 retries already absorb.
                    let stop_end = std::time::Instant::now() + std::time::Duration::from_secs(5);
                    // XRV1-L31: the A T-await locks the
                    // first tick too (every spawner-path
                    // retry binds its re-reads — the
                    // pidns already excludes waiters, so
                    // Changed is impossible here; the arm
                    // below is defense-in-depth).
                    let mut a_expected: Option<u64> = None;
                    loop {
                        let a_state = proc_state(apid);
                        match check_construct_identity(a_expected, pin_birth_tick(apid)) {
                            ConstructIdentity::Lock(tick) => a_expected = Some(tick),
                            ConstructIdentity::Match | ConstructIdentity::Transient => {}
                            // XRV1-L32: proven recycle ⟹
                            // proven stale — abandon the
                            // attempt WITHOUT touching the
                            // number (nothing of ours
                            // remains — next attempt mints
                            // a fresh A).
                            ConstructIdentity::Changed => return None,
                        }
                        if a_state == Some('T') {
                            break;
                        }
                        if std::time::Instant::now() >= stop_end {
                            // Attempt abandon: retire A
                            // (never strand it stopped —
                            // SIGKILL lands on stopped; the
                            // blocking wait is prompt —
                            // pidns-isolated (no second
                            // waiter exists), so the numeric
                            // wait cannot steal).
                            // SAFETY: our own fork-child.
                            unsafe {
                                libc::kill(apid, libc::SIGKILL);
                                let mut st = 0;
                                libc::waitpid(apid, &mut st, 0);
                            }
                            return None;
                        }
                        std::thread::sleep(std::time::Duration::from_micros(100));
                    }
                    // XRV1-L75: retain A's HOLD pin (T-held
                    // ⟹ stopped ⟹ unreaped ⟹ the open names
                    // OUR A — premise-break retirement
                    // consumes through it (no fresh open
                    // (L75 race))). Gated context (the
                    // scenario probed Supported) ⟹ open
                    // failure is staging-broken loud.
                    // SAFETY: fd owned by this guard.
                    let apin = unsafe {
                        std::os::unix::io::OwnedFd::from_raw_fd(
                            super::super::seccomp::pidfd_open_raw(apid)
                                .expect("staging broken (A hold-pin)"),
                        )
                    };
                    // A is unreaped (no waiter ran yet, and
                    // none EXISTS in this pidns — no sweep
                    // can interleave even across a
                    // deschedule) — and now provably
                    // stopped, so the guard pins A's birth
                    // under the L2 hold rule. XRV1-L11:
                    // transient-Unpinned (EMFILE/outage)
                    // abandons the attempt (the 60-attempt
                    // loop IS the retry — a fresh A, a
                    // fresh construct); post-hold
                    // Discharged is impossible ⟹ loud.
                    // Single-shot (each attempt mints a
                    // fresh A — XRV1-L45: the A T-await
                    // lock carries INTO `new`, so the
                    // within-call retries bind the same
                    // identity, never a fresh chain).
                    let constructed = match KillReapGuard::new(apid, a_expected) {
                        Ok(constructed) => constructed,
                        Err(ConstructError::Outage) => {
                            // Unreadable (T-awaited ⟹ still
                            // ours, pidns-held) ⟹ retire +
                            // abandon (next attempt mints a
                            // fresh A).
                            // SAFETY: our own fork-child
                            // (see the T-await abandon
                            // above).
                            unsafe {
                                libc::kill(apid, libc::SIGKILL);
                                let mut st = 0;
                                libc::waitpid(apid, &mut st, 0);
                            }
                            return None;
                        }
                        // XRV1-L49/L75: observed-ZOMBIE on
                        // the T-awaited A (premise break —
                        // A ran and died) ⟹ retire through
                        // the HELD pin (birth-bound — our
                        // own fork-child, so the pin is
                        // provably A's), then abandon (next
                        // attempt mints a fresh A).
                        Err(ConstructError::WrongState { seen: Some('Z') }) => {
                            use std::os::unix::io::AsRawFd as _;
                            let _ = retire_zombie_premise_break(apin.as_raw_fd(), apid);
                            return None;
                        }
                        // Observed-live or proven-recycled
                        // (untrusted number) ⟹ abandon
                        // WITHOUT touching (next attempt
                        // mints a fresh A; persistent
                        // premise-break exhausts the loop
                        // loud).
                        Err(ConstructError::WrongState { .. })
                        | Err(ConstructError::Changed { .. }) => return None,
                        Err(ConstructError::LogicBreak) => {
                            panic!("staging broken (construct classifier broke — model break?)");
                        }
                    };
                    let mut guard = constructed.guard;
                    if !matches!(&guard.pin, GuardPin::Pinned { .. }) {
                        if matches!(&guard.pin, GuardPin::Discharged) {
                            panic!("staging broken (post-hold Discharged — model break?)");
                        }
                        guard.disarm();
                        // SAFETY: our own fork-child (see
                        // the T-await abandon above).
                        unsafe {
                            libc::kill(apid, libc::SIGKILL);
                            let mut st = 0;
                            libc::waitpid(apid, &mut st, 0);
                        }
                        return None;
                    }
                    // XRV1-L75: the guard owns retirement
                    // now — the hold pin (premise-break
                    // only) retires here.
                    drop(apin);
                    // SAFETY: SIGCONT to our own stopped
                    // fork-child (ESRCH impossible —
                    // unreaped — so a refusal fails this
                    // attempt (None), never silent).
                    if unsafe { libc::kill(apid, libc::SIGCONT) } != 0 {
                        guard.disarm();
                        // SAFETY: our own fork-child (see
                        // the T-await abandon above).
                        unsafe {
                            libc::kill(apid, libc::SIGKILL);
                            let mut st = 0;
                            libc::waitpid(apid, &mut st, 0);
                        }
                        return None;
                    }
                    let atick = proc_starttime(apid).ok()??;
                    // Sweep-reap A (the in-tree waitpid(-1)
                    // shape): consume its status, free the
                    // number.
                    let reap_end = std::time::Instant::now() + std::time::Duration::from_secs(5);
                    loop {
                        // XRV1-L116: exclusion (a supervised
                        // birth's status is NOT ours to sweep —
                        // defer while active; expiry abandons
                        // THIS attempt (None — the caller
                        // retries past the window)).
                        if NumericSupervisionGuard::is_active() {
                            if std::time::Instant::now() >= reap_end {
                                return None;
                            }
                            std::thread::sleep(std::time::Duration::from_millis(10));
                            continue;
                        }
                        let mut status = 0;
                        // SAFETY: reap-any of our own dead
                        // child; bounded.
                        let got = unsafe { libc::waitpid(-1, &mut status, libc::WNOHANG) };
                        if got == apid {
                            break;
                        }
                        if std::time::Instant::now() >= reap_end {
                            return None;
                        }
                        std::thread::sleep(std::time::Duration::from_micros(100));
                    }
                    // Pin the allocator: the next fork
                    // reuses A's number.
                    if std::fs::write("/proc/sys/kernel/ns_last_pid", format!("{}\n", apid - 1))
                        .is_err()
                    {
                        return None;
                    }
                    let bpid = unsafe { libc::fork() };
                    if bpid < 0 {
                        return None;
                    }
                    if bpid == 0 {
                        unsafe { libc::_exit(22) };
                    }
                    // B must be a zombie before the tick
                    // read means anything (a live B could
                    // still... no — the tick is fixed at
                    // birth; but a live B spins below, so
                    // settle it).
                    let zend = std::time::Instant::now() + std::time::Duration::from_secs(5);
                    while proc_state(bpid) != Some('Z') {
                        if std::time::Instant::now() >= zend {
                            return None;
                        }
                        std::thread::sleep(std::time::Duration::from_micros(100));
                    }
                    let btick = proc_starttime(bpid).ok()??;
                    if bpid == apid && btick == atick {
                        return Some((guard, apid, bpid));
                    }
                    // Misaligned (jiffy edge crossed or
                    // allocator surprise): stand the guard
                    // down, reap B, retry.
                    guard.disarm();
                    let mut status = 0;
                    // SAFETY: our own staged zombie.
                    unsafe {
                        libc::waitpid(bpid, &mut status, 0);
                    }
                }
                None
            }
            // MAIN leg: guard armed over A, A sweep-reaped,
            // B recycled same-tick — the drop must spare
            // B's status (pre-fix: tick matches, waitpid
            // steals → ECHILD below).
            let Some((guard, apid, bpid)) = stage_pair() else {
                skip!("pair unalignable (clock too coarse?)");
            };
            drop(guard);
            let mut status = 0;
            // SAFETY: our own staged zombie (unless the
            // drop stole it — the asserted defect).
            let got = libc::waitpid(bpid, &mut status, libc::WNOHANG);
            if got == bpid && libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 22 {
                let _ = writeln!(pipe, "MAIN ok");
            } else {
                let _ = writeln!(
                    pipe,
                    "MAIN stolen (waitpid({bpid}) got={got} errno={})",
                    std::io::Error::last_os_error().raw_os_error().unwrap_or(-1)
                );
            }
            let _ = apid;
            // BAD leg: identical staging, but a bare
            // numeric waitpid (the pre-fix shape) instead
            // of the guard — it MUST steal B2's status
            // (proves the staging aligns recycle+tick; a
            // non-stealing bad control fails the test
            // loud, never a vacuous green).
            let Some((mut guard2, a2, b2)) = stage_pair() else {
                skip!("bad-leg pair unalignable");
            };
            guard2.disarm();
            let mut status2 = 0;
            // SAFETY: our own staged zombie — deliberately
            // the racy numeric shape.
            let got2 = libc::waitpid(a2, &mut status2, libc::WNOHANG);
            if got2 == b2 && libc::WIFEXITED(status2) && libc::WEXITSTATUS(status2) == 22 {
                let _ = writeln!(pipe, "BAD stole");
            } else {
                let _ = writeln!(
                    pipe,
                    "BAD nosteal (waitpid({a2}) got={got2} errno={})",
                    std::io::Error::last_os_error().raw_os_error().unwrap_or(-1)
                );
            }
            libc::_exit(0);
        }
    }

    /// XRV1-J2 collateral (contract pin, not a
    /// bug-catcher — theft discrimination needs forced
    /// recycle, proven by
    /// `kill_reap_guard_drop_spares_sweep_recycled_status`):
    /// skip-discharge over a sweep-reaped birth reports
    /// TRUE with no numeric effects. The return is
    /// asserted directly (a regression to false — or to
    /// a numeric wait — misreports discharge and risks
    /// stealing); the sibling zombie's status must
    /// survive intact. The sweep-reap is pid-specific
    /// (XRV1-K5 — waitpid(-1) here would eat parallel
    /// tests' statuses).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn skip_discharge_after_sweep_reap_confirms_without_stealing() {
        // XRV1-L9: the verdict runs through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (no pin to discharge through)");
                return;
            }
        }
        // Stopped (XRV1-K3: instant-exit bodies must pin
        // while provably unreaped).
        let (mut swept, mut _kguard) = spawn_stopped_sh_with_guard("exit 7");
        let spid = swept.id() as libc::pid_t;
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while proc_state(spid) != Some('Z') {
            assert!(
                std::time::Instant::now() < end,
                "exiter must zombify (still {0:?})",
                proc_state(spid)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Sweep-reap, PID-SPECIFIC (XRV1-K5: the
        // in-tree waitpid(-1) shape would consume
        // parallel tests' statuses — oldest-first — in
        // this in-process test; the pid-specific reap
        // reaches the identical post-state for OUR birth).
        loop {
            let mut status = 0;
            // SAFETY: WNOHANG reap of our own dead child;
            // bounded.
            let got = unsafe { libc::waitpid(spid, &mut status, libc::WNOHANG) };
            assert!(
                std::time::Instant::now() < end,
                "sweep must reap the exiter"
            );
            if got == spid {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // XRV1-K9: cleanup custody from spawn (the
        // settle/discharge asserts below can panic) —
        // stopped (XRV1-K3: instant-exit bodies).
        let (mut sibling, mut _sibguard) = spawn_stopped_sh_with_guard("exit 9");
        let sibpid = sibling.id() as libc::pid_t;
        while proc_state(sibpid) != Some('Z') {
            assert!(
                std::time::Instant::now() < end,
                "sibling must zombify (still {0:?})",
                proc_state(sibpid)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(
            _kguard.skip_discharge(&mut swept),
            "a sweep-reaped birth is discharged (proven gone — no numeric effects sound)"
        );
        _kguard.disarm();
        let status = sibling.wait().expect("sibling status survives");
        _sibguard.disarm();
        assert_eq!(status.code(), Some(9), "sibling status intact");
    }

    /// XRV1-K3 collateral: the construction state table,
    /// arm by arm — None-sampled ⟹ Unpinned; ESRCH-open
    /// ⟹ Discharged (never numeric effects after proven
    /// disappearance); other-open-errno ⟹ Unpinned
    /// (XRV1-L1: the numeric fallback is DELETED — no
    /// authority without a pin); opened, verify-match,
    /// and waitid ⟹ Pinned; opened with
    /// verify-mismatch/gone ⟹ Unpinned; opened with
    /// verify-match but WITHOUT waitid ⟹ Unpinned
    /// (XRV1-L9: an unwaitable pin cannot reap, so it
    /// claims nothing). Mutant-checked (swapping any two
    /// arms REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn guard_pin_classification_maps_construction_states() {
        use GuardPinKind as Kind;
        assert_eq!(classify_guard_pin(None, None, None, true), Kind::Unpinned);
        assert_eq!(
            classify_guard_pin(None, Some(libc::ESRCH), Some(7), true),
            Kind::Unpinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), Some(libc::ESRCH), Some(7), true),
            Kind::Discharged
        );
        assert_eq!(
            classify_guard_pin(Some(7), Some(libc::ESRCH), None, true),
            Kind::Discharged
        );
        // Proven-gone needs no waitid (capability
        // failure cannot un-prove disappearance).
        assert_eq!(
            classify_guard_pin(Some(7), Some(libc::ESRCH), Some(7), false),
            Kind::Discharged
        );
        assert_eq!(
            classify_guard_pin(Some(7), Some(libc::ENOSYS), Some(7), true),
            Kind::Unpinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), Some(libc::EMFILE), None, true),
            Kind::Unpinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), None, Some(7), true),
            Kind::Pinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), None, Some(7), false),
            Kind::Unpinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), None, Some(9), true),
            Kind::Unpinned
        );
        assert_eq!(
            classify_guard_pin(Some(7), None, None, true),
            Kind::Unpinned
        );
    }

    /// XRV1-L13 collateral: the capability probe
    /// qualifies BOTH flag sets it guards (cleanup
    /// consumes — WEXITED|WNOHANG without WNOWAIT;
    /// peeking passes WNOWAIT). Each leg runs
    /// fork-contained under a flag-selective seccomp
    /// filter (installed post-fork in the child only):
    /// deny-consuming ⟹ probe must report false (its
    /// cleanup would EPERM); deny-peeking ⟹ likewise.
    /// RED with a WNOWAIT-only probe (the consuming leg
    /// reports true under the consuming-deny filter).
    /// The probe path is raw syscalls only (no alloc),
    /// so calling it post-fork is async-signal-safe;
    /// seccomp-unavailable skips loud via exit 77.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn waitid_pidfd_probe_qualifies_both_flag_sets() {
        #[repr(C)]
        #[derive(Clone, Copy)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        // deny_when_set=false: EPERM waitid(247) whose
        // options lack WNOWAIT (deny consuming, allow
        // peeking); true: the reverse. JSET shape (6
        // insns): the DENY/ALLOW slots swap per leg.
        const WNOWAIT_FLAG: u32 = 0x01000000;
        const DENY: SockFilter = SockFilter {
            code: 0x06,
            jt: 0,
            jf: 0,
            k: 0x00050000 | 1,
        };
        const ALLOW: SockFilter = SockFilter {
            code: 0x06,
            jt: 0,
            jf: 0,
            k: 0x7fff0000,
        };
        fn deny_filter(deny_when_set: bool) -> [SockFilter; 6] {
            let (tail, allow_skip): ([SockFilter; 2], u8) = if deny_when_set {
                ([ALLOW, DENY], 2)
            } else {
                ([DENY, ALLOW], 3)
            };
            [
                SockFilter {
                    code: 0x20,
                    jt: 0,
                    jf: 0,
                    k: 0,
                },
                SockFilter {
                    code: 0x15,
                    jt: 0,
                    jf: allow_skip,
                    k: 247,
                },
                SockFilter {
                    code: 0x20,
                    jt: 0,
                    jf: 0,
                    k: 40,
                },
                SockFilter {
                    code: 0x45,
                    jt: 1,
                    jf: 0,
                    k: WNOWAIT_FLAG,
                },
                tail[0],
                tail[1],
            ]
        }
        // SAFETY: fork in a test thread; each child runs
        // raw syscalls + the alloc-free probe only.
        for (leg, deny_when_set) in [(0, false), (1, true)] {
            let kid = unsafe { libc::fork() };
            assert!(kid >= 0, "staging broken (probe fork leg {leg})");
            if kid == 0 {
                unsafe {
                    let filter = deny_filter(deny_when_set);
                    if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                        || libc::prctl(
                            libc::PR_SET_SECCOMP,
                            libc::SECCOMP_MODE_FILTER,
                            &SockFprog {
                                len: 6,
                                filter: filter.as_ptr(),
                            },
                            0,
                        ) != 0
                    {
                        libc::_exit(77);
                    }
                    // The probe under confinement: either
                    // denial must never read Supported
                    // (Unsupported expected; a Transient
                    // burst also exits 0 — the claim is
                    // only ¬Supported, which holds).
                    if waitid_pidfd_probe() == ProbeVerdict::Supported {
                        libc::_exit(1);
                    }
                    libc::_exit(0);
                }
            }
            let mut status = 0;
            let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
            loop {
                // SAFETY: our own fork-child, WNOHANG poll.
                let got = unsafe { libc::waitpid(kid, &mut status, libc::WNOHANG) };
                if got == kid {
                    break;
                }
                assert!(got >= 0, "staging broken (probe wait leg {leg})");
                if std::time::Instant::now() >= end {
                    // SAFETY: our own fork-child.
                    unsafe {
                        libc::kill(kid, libc::SIGKILL);
                        libc::waitpid(kid, &mut status, 0);
                    }
                    panic!("staging broken (probe child wedged leg {leg})");
                }
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
            assert!(
                libc::WIFEXITED(status),
                "probe child must exit leg {leg} (got {status})"
            );
            // (WIFEXITED proven above.)
            match libc::WEXITSTATUS(status) {
                0 => {}
                77 => {
                    eprintln!("skip: seccomp install refused leg {leg}");
                    return;
                }
                _ => panic!(
                    "probe must qualify both flag sets (leg {leg} reported supported under denial)"
                ),
            }
        }
    }

    /// XRV1-L11 collateral: the hold-read retry
    /// decision, pure — T proceeds; any other OBSERVED
    /// state panics immediately (wrong-state is never
    /// transient); an UNREADABLE stat retries while the
    /// bound holds (transient outage) and panics past it
    /// (persistent outage ⟹ host-broken). Mutant-checked
    /// (collapsing Retry/Panic REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn hold_read_retry_decision_maps_outage_outcomes() {
        assert_eq!(hold_read_retry(Some('T'), false), HoldRead::Proceed);
        assert_eq!(hold_read_retry(Some('T'), true), HoldRead::Proceed);
        assert_eq!(hold_read_retry(Some('R'), false), HoldRead::PanicWrongState);
        assert_eq!(hold_read_retry(Some('Z'), false), HoldRead::PanicWrongState);
        assert_eq!(hold_read_retry(Some('S'), true), HoldRead::PanicWrongState);
        assert_eq!(hold_read_retry(None, false), HoldRead::Retry);
        assert_eq!(hold_read_retry(None, true), HoldRead::PanicOutage);
    }

    /// XRV1-L11/L24 collateral: the construct-retry
    /// decision, pure — Pinned returns; Unpinned
    /// retries while the probe is not Unsupported
    /// (Supported-with-outage or Transient burst —
    /// absorbed by retry, never CONTed unpinned);
    /// Unpinned on Unsupported returns degraded
    /// (old-kernel/confinement hygiene-only path — the
    /// L9 gates keep verdicts off it); Discharged
    /// never retries (post-hold it is impossible ⟹
    /// firing is loud). Mutant-checked.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_retry_decision_maps_pin_outcomes() {
        use ProbeVerdict::*;
        assert!(!should_retry_construct(&GuardPin::Unpinned, Unsupported));
        assert!(should_retry_construct(&GuardPin::Unpinned, Supported));
        assert!(should_retry_construct(&GuardPin::Unpinned, Transient));
        assert!(!should_retry_construct(&GuardPin::Discharged, Supported));
        assert!(!should_retry_construct(&GuardPin::Discharged, Transient));
        assert!(!should_retry_construct(&GuardPin::Discharged, Unsupported));
    }

    /// XRV1-L22 collateral: the construct-identity lock
    /// table — first observation locks; matches pass;
    /// outage-before-lock is transient; a DIFFERENT
    /// tick after the lock ⟹ Changed (terminal —
    /// never a fresh-sample pin); a LOST tick after
    /// the lock is transient (a stopped-held birth
    /// cannot die ⟹ outage-likely ⟹ retry — a
    /// terminal-silent there would leak a live birth
    /// behind an outage). Mutant-checked
    /// (Changed→Match, Transient→Changed both RED).
    /// XRV1-L59: the K3 verify gate is total — a
    /// POSITIVE sample/verify mismatch is a proven
    /// identity change (Some); a match or any
    /// unreadable side is None (the classifier
    /// routes unreadable ⟹ retry — unproven, never
    /// a false Changed). XRV1-L76: a positive
    /// verify against a RETAINED lock fires even
    /// when the intermediate sample is unreadable
    /// (expected=A, sampled=None, verified=B≠A ⟹
    /// Changed — positive evidence of a replacement
    /// must never degrade to Unpinned); a
    /// consistent verify or no lock stays None.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn k3_verify_mismatch_is_changed() {
        assert_eq!(k3_verify_changed(None, Some(7), Some(8)), Some((7, 8)));
        assert_eq!(k3_verify_changed(None, Some(7), Some(7)), None);
        assert_eq!(k3_verify_changed(None, None, None), None);
        assert_eq!(k3_verify_changed(None, Some(7), None), None);
        assert_eq!(k3_verify_changed(None, None, Some(7)), None);
        // XRV1-L76 arms (retained lock vs positive
        // verify with an unreadable sample).
        assert_eq!(k3_verify_changed(Some(7), None, Some(8)), Some((7, 8)));
        assert_eq!(k3_verify_changed(Some(7), None, Some(7)), None);
        assert_eq!(k3_verify_changed(Some(7), Some(8), Some(9)), Some((8, 9)));
    }
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_identity_lock_gates_retries() {
        assert_eq!(
            check_construct_identity(None, Some(777)),
            ConstructIdentity::Lock(777)
        );
        assert_eq!(
            check_construct_identity(None, None),
            ConstructIdentity::Transient
        );
        assert_eq!(
            check_construct_identity(Some(777), Some(777)),
            ConstructIdentity::Match
        );
        assert_eq!(
            check_construct_identity(Some(777), Some(778)),
            ConstructIdentity::Changed
        );
        assert_eq!(
            check_construct_identity(Some(777), None),
            ConstructIdentity::Transient
        );
    }

    /// XRV1-L15/L24/L25 collateral: the probe's
    /// errno→verdict table, pure and deterministic —
    /// open must succeed; EACH wait flag set must
    /// succeed or prove dispatch (ECHILD); the SIGNAL
    /// leg (signal-0 on self) must succeed (no ECHILD
    /// arm — signal uses ESRCH, and self never reads
    /// gone); the SIGKILL leg (pidfd SIGKILL on a
    /// throwaway birth — XRV1-L38) must succeed
    /// (signal-0 proves dispatch, not kill power —
    /// the Drop kills through the pin). Denials
    /// (ENOSYS/EINVAL for missing P_PIDFD/signal,
    /// EPERM for confinement, anything unexpected)
    /// read Unsupported. Resource/transient failures
    /// (EMFILE/ENFILE/ENOMEM/EINTR/EAGAIN) read
    /// Transient (retry — never a degraded verdict),
    /// and Transient dominates denial (a burst
    /// clears; a denial persists into the next
    /// probe). Mutant-checked (dropping any arm
    /// REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn waitid_probe_classification_maps_errno_decisions() {
        use ProbeVerdict::*;
        // All-success ⟹ supported.
        assert_eq!(
            waitid_probe_classify(None, None, None, None, None),
            Supported
        );
        // ECHILD proves wait dispatch (self merely
        // not-waitable) — on either or both sets.
        assert_eq!(
            waitid_probe_classify(None, Some(libc::ECHILD), None, None, None),
            Supported
        );
        assert_eq!(
            waitid_probe_classify(None, None, Some(libc::ECHILD), None, None),
            Supported
        );
        assert_eq!(
            waitid_probe_classify(None, Some(libc::ECHILD), Some(libc::ECHILD), None, None),
            Supported
        );
        // Open denial ⟹ unsupported (ENOSYS pre-5.3,
        // EPERM confined).
        assert_eq!(
            waitid_probe_classify(Some(libc::ENOSYS), None, None, None, None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(Some(libc::EPERM), None, None, None, None),
            Unsupported
        );
        // Any wait errno but ECHILD, on either set ⟹
        // unsupported (ENOSYS/EINVAL no-P_PIDFD, EPERM
        // flag-selective denial, EFAULT unexpected).
        assert_eq!(
            waitid_probe_classify(None, Some(libc::ENOSYS), None, None, None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, Some(libc::EINVAL), None, None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, Some(libc::EPERM), None, None, None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, Some(libc::EPERM), None, None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, Some(libc::EFAULT), Some(libc::ECHILD), None, None),
            Unsupported
        );
        // XRV1-L25: the signal leg gates too (waits OK
        // + signal denied ⟹ unsupported — the Drop
        // cannot kill through the pin).
        assert_eq!(
            waitid_probe_classify(
                None,
                Some(libc::ECHILD),
                Some(libc::ECHILD),
                Some(libc::ENOSYS),
                None
            ),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, None, Some(libc::EPERM), None),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, None, Some(libc::ECHILD), None),
            Unsupported
        );
        // XRV1-L24: exhaustion/transient on ANY leg ⟹
        // Transient (retry — never degraded).
        assert_eq!(
            waitid_probe_classify(Some(libc::EMFILE), None, None, None, None),
            Transient
        );
        assert_eq!(
            waitid_probe_classify(Some(libc::ENFILE), None, None, None, None),
            Transient
        );
        assert_eq!(
            waitid_probe_classify(None, Some(libc::EMFILE), None, None, None),
            Transient
        );
        assert_eq!(
            waitid_probe_classify(None, None, Some(libc::ENOMEM), None, None),
            Transient
        );
        assert_eq!(
            waitid_probe_classify(None, None, None, Some(libc::EINTR), None),
            Transient
        );
        // Transient dominates denial (the burst clears;
        // the denial persists into the next probe).
        assert_eq!(
            waitid_probe_classify(Some(libc::EMFILE), Some(libc::EPERM), None, None, None),
            Transient
        );
        // XRV1-L38: the SIGKILL leg gates too
        // (signal-0 OK + SIGKILL denied ⟹
        // unsupported — the Drop cannot kill
        // through the pin).
        assert_eq!(
            waitid_probe_classify(
                None,
                Some(libc::ECHILD),
                Some(libc::ECHILD),
                None,
                Some(libc::EPERM)
            ),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, None, None, Some(libc::ESRCH)),
            Unsupported
        );
        assert_eq!(
            waitid_probe_classify(None, None, None, None, Some(libc::EINTR)),
            Transient
        );
        // XRV1-L52: kill-leg EAGAIN (throwaway-fork
        // exhaustion, or a SIGKILL-landed-but-alive
        // birth past the bound — either way the NEXT
        // probe mints a fresh birth) ⟹ Transient
        // (retry — never a permanent denial).
        assert_eq!(
            waitid_probe_classify(None, None, None, None, Some(libc::EAGAIN)),
            Transient
        );
    }

    /// XRV1-L28: UNAME26 persona bit (fakes
    /// uname-release as 2.6.x —
    /// `/usr/include/linux/personality.h`: `UNAME26 =
    /// 0x0020000`).
    #[cfg(target_arch = "x86_64")]
    const PERSONA_UNAME26: u32 = 0x0020000;

    /// XRV1-L40: decode a get-persona result, pure —
    /// (unknown, uname26). A DENIED query (any
    /// negative — EPERM or otherwise) is UNKNOWN
    /// (never proof of absence — the caller holds
    /// the version floor vacuous); a readable value
    /// decodes the UNAME26 bit. Pinned by
    /// `persona_query_denial_reads_unknown`.
    #[cfg(target_arch = "x86_64")]
    fn persona_uname26_bits(persona: libc::c_int) -> (bool, bool) {
        if persona < 0 {
            return (true, false);
        }
        (false, (persona as u32 & PERSONA_UNAME26) != 0)
    }

    /// XRV1-L28: persona-aware release check, pure
    /// (UNAME26 ⟹ vacuous-true (faked release —
    /// diagnostic only); otherwise the release must
    /// parse to ≥5.4 (garbage ⟹ false ⟹ loud)).
    /// Pinned by `release_check_is_vacuous_under_uname26`.
    #[cfg(target_arch = "x86_64")]
    fn release_meets_5_4(release: &str, uname26: bool) -> bool {
        if uname26 {
            return true;
        }
        let mut parts = release.split('.');
        let major: u64 = match parts.next().unwrap_or("").parse() {
            Ok(major) => major,
            Err(_) => return false,
        };
        let minor_raw = parts.next().unwrap_or("");
        let minor_digits: String = minor_raw
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .collect();
        let minor: u64 = match minor_digits.parse() {
            Ok(minor) => minor,
            Err(_) => return false,
        };
        (major, minor) >= (5, 4)
    }

    /// XRV1-L40 collateral: a DENIED persona query
    /// (personality(0xffffffff) → -1/EPERM) is UNKNOWN
    /// — never proof that UNAME26 is absent (treating
    /// it as absent rejects successful runtime
    /// capability evidence under a faked 2.6 release).
    /// Unknown ⟹ the version floor is vacuous
    /// (diagnostic only). Mutant-checked (dropping
    /// the unknown arm REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn persona_query_denial_reads_unknown() {
        // Denied (any negative — EPERM or otherwise) ⟹
        // unknown (uname26 meaningless — unused).
        assert_eq!(persona_uname26_bits(-1), (true, false));
        assert_eq!(
            persona_uname26_bits(-libc::EPERM as libc::c_int),
            (true, false)
        );
        // Readable ⟹ known (bit decides).
        assert_eq!(persona_uname26_bits(0), (false, false));
        assert_eq!(
            persona_uname26_bits(PERSONA_UNAME26 as libc::c_int),
            (false, true)
        );
        assert_eq!(
            persona_uname26_bits(0x00040000 | PERSONA_UNAME26 as libc::c_int),
            (false, true)
        );
    }

    /// XRV1-L28 collateral: the persona-aware
    /// release check — UNAME26 fakes the release
    /// (reviewer's contained check: `2.6.62-...` on a
    /// capable host) ⟹ the ≥5.4 check is vacuous
    /// there (diagnostic only); on a true release the
    /// parse decides (garbage ⟹ false ⟹ loud).
    /// Mutant-checked (dropping the UNAME26 arm REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn release_check_is_vacuous_under_uname26() {
        assert!(release_meets_5_4("6.8.0-41-generic", false));
        assert!(release_meets_5_4("5.4.0", false));
        assert!(!release_meets_5_4("5.3.18", false));
        assert!(!release_meets_5_4("4.19.0", false));
        assert!(release_meets_5_4("2.6.62-200.fc44.x86_64", true));
        assert!(!release_meets_5_4("2.6.62-200.fc44.x86_64", false));
        assert!(!release_meets_5_4("garbage", false));
        assert!(!release_meets_5_4("", false));
        assert!(!release_meets_5_4("5", false));
    }

    /// XRV1-L28 collateral: the UNAME26 kernel
    /// contract the persona-aware check relies on —
    /// setting UNAME26 makes the persona-bit visible
    /// AND fakes uname-release as 2.6.x (the
    /// reviewer's contained shape). Fork-contained
    /// (the persona change never escapes the child;
    /// post-fork code is raw syscalls only). Cannot
    /// set the persona (confined host) ⟹ loud skip
    /// (exit 77); set-but-not-faked ⟹ RED (contract
    /// broken — the L28 skip would be unsound).
    /// XRV1-L40: a DENIED persona query or a failed
    /// uname (unverifiable means) also skips (77) —
    /// only the MEANING (release faked as 2.6.x)
    /// hard-fails (75); a set-but-bit-invisible
    /// persona falls through to the meaning check
    /// (faked ⟹ green — the L28 skip's soundness
    /// rests on the faked release, not the bit).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn uname26_persona_fakes_release() {
        // SAFETY: fork in a test thread; the child runs
        // raw syscalls only until _exit (no alloc, no
        // locks — L10-shape containment).
        let kid = unsafe { libc::fork() };
        assert!(kid >= 0, "staging broken (persona fork)");
        if kid == 0 {
            unsafe {
                if libc::personality(PERSONA_UNAME26 as libc::c_ulong) != 0 {
                    libc::_exit(77);
                }
                // XRV1-L40: a DENIED query is unknown
                // (never proof of absence) ⟹ skip (77 —
                // unverifiable means, not a broken
                // meaning). A set-but-bit-invisible
                // persona falls THROUGH (the meaning
                // check below decides).
                let persona = libc::personality(0xffffffff);
                if persona < 0 {
                    libc::_exit(77);
                }
                let mut uts: libc::utsname = std::mem::zeroed();
                // XRV1-L40: uname failed ⟹ the meaning
                // is unverifiable ⟹ skip (77).
                if libc::uname(&mut uts) != 0 {
                    libc::_exit(77);
                }
                let rel = uts.release;
                if rel[0] as u8 != b'2' || rel[1] as u8 != b'.' || rel[2] as u8 != b'6' {
                    libc::_exit(75);
                }
                libc::_exit(0);
            }
        }
        let mut status = 0;
        loop {
            // SAFETY: reap our own fork-child (EINTR-
            // retried — a test alarm may interrupt).
            let got = unsafe { libc::waitpid(kid, &mut status, 0) };
            if got == kid {
                break;
            }
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::EINTR),
                "staging broken (persona wait)"
            );
        }
        if libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 0 {
            return;
        }
        if libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 77 {
            eprintln!("skip: UNAME26 persona unsettable on this host");
            return;
        }
        panic!("UNAME26 contract broken (status {status:#x} — L28 skip unsound?)");
    }

    /// XRV1-L40 collateral: a DENIED persona query
    /// skips (77 — unknown, never proof of absence),
    /// never REDs. Fork-contained (filter + persona
    /// change never escape the child; post-fork code
    /// is raw syscalls only — the query branch below
    /// duplicates the sibling test's arm in own text
    /// (a shared helper would alloc/lock post-fork)).
    /// The child installs a query-deny filter
    /// (personality(0xffffffff) ⟹ EPERM, sets
    /// allowed), sets UNAME26, then queries: denied
    /// ⟹ 77 (skip — the pinned arm); allowed ⟹ 75
    /// (RED — the filter did not apply (staging)).
    /// Mutant-checked (75-on-denied REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn persona_query_denial_skips_loud() {
        // SAFETY: fork in a test thread; the child runs
        // raw syscalls only until _exit (no alloc, no
        // locks — L10-shape containment).
        let kid = unsafe { libc::fork() };
        assert!(kid >= 0, "staging broken (persona fork)");
        if kid == 0 {
            unsafe {
                // BPF program in raw parts (no struct
                // alloc post-fork — fixed arrays only).
                // personality(135): arg0 == 0xffffffff
                // (query) ⟹ EPERM; else (set) ⟹ ALLOW.
                #[repr(C)]
                struct RawFilter {
                    code: u16,
                    jt: u8,
                    jf: u8,
                    k: u32,
                }
                #[repr(C)]
                struct RawProg {
                    len: u16,
                    filter: *const RawFilter,
                }
                let prog = [
                    RawFilter {
                        code: 0x20,
                        jt: 0,
                        jf: 0,
                        k: 0,
                    },
                    RawFilter {
                        code: 0x15,
                        jt: 0,
                        jf: 3,
                        k: 135,
                    },
                    RawFilter {
                        code: 0x20,
                        jt: 0,
                        jf: 0,
                        k: 16,
                    },
                    RawFilter {
                        code: 0x15,
                        jt: 0,
                        jf: 1,
                        k: 0xffffffff,
                    },
                    RawFilter {
                        code: 0x06,
                        jt: 0,
                        jf: 0,
                        k: 0x00050000 | 1,
                    },
                    RawFilter {
                        code: 0x06,
                        jt: 0,
                        jf: 0,
                        k: 0x7fff0000,
                    },
                ];
                if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                    || libc::prctl(
                        libc::PR_SET_SECCOMP,
                        libc::SECCOMP_MODE_FILTER,
                        &RawProg {
                            len: 6,
                            filter: prog.as_ptr(),
                        },
                        0,
                    ) != 0
                {
                    libc::_exit(77);
                }
                if libc::personality(PERSONA_UNAME26 as libc::c_ulong) != 0 {
                    libc::_exit(77);
                }
                // XRV1-L40: denied ⟹ 77 (skip —
                // unknown); allowed ⟹ 75 (RED — the
                // filter did not apply (staged BPF
                // wrong?)).
                if libc::personality(0xffffffff) < 0 {
                    libc::_exit(77);
                }
                libc::_exit(75);
            }
        }
        let mut status = 0;
        loop {
            // SAFETY: reap our own fork-child (EINTR-
            // retried — a test alarm may interrupt).
            let got = unsafe { libc::waitpid(kid, &mut status, 0) };
            if got == kid {
                break;
            }
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::EINTR),
                "staging broken (persona wait)"
            );
        }
        if libc::WIFEXITED(status) && libc::WEXITSTATUS(status) == 77 {
            eprintln!("skip: persona query denied on this host (unknown — vacuous)");
            return;
        }
        panic!("persona-query-denial contract broken (status {status:#x} — L40 skip unsound?)");
    }

    /// XRV1-L46/L64: the canary's K3 decision is
    /// total and conservative — Proceed ONLY on a
    /// positive tick match; a missing sample NEVER
    /// equals (even a missing re-read —
    /// unauthenticated is unauthenticated ⟹
    /// retire + Unsupported); an unreadable VERIFY
    /// against a good sample is an outage, NOT a
    /// recycle (⟹ retain cleanup + conservative
    /// verdict — L64); a positive mismatch ⟹ no
    /// touch (disarm + loud).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn canary_k3_decision_is_total_and_conservative() {
        // Fully-qualified variants (a glob-imported
        // matches! silently binds a misspelled
        // variant as always-true — qualification
        // fails closed at compile time).
        assert!(matches!(
            k3_decide(Some(7), Ok(Some(7))),
            K3Decision::Proceed
        ));
        assert!(matches!(
            k3_decide(None, Ok(None)),
            K3Decision::UnreadableSample
        ));
        assert!(matches!(
            k3_decide(None, Ok(Some(7))),
            K3Decision::UnreadableSample
        ));
        assert!(matches!(
            k3_decide(None, Err(())),
            K3Decision::UnreadableSample
        ));
        assert!(matches!(
            k3_decide(Some(7), Err(())),
            K3Decision::UnreadableVerify
        ));
        assert!(matches!(
            k3_decide(Some(7), Ok(Some(8))),
            K3Decision::Mismatched
        ));
        // XRV1-L100: a PROVEN-gone verify
        // (Ok(None) — the entry vanished) is
        // terminal silence, NEVER an outage
        // touch (cleanup must stand down —
        // the number is freed).
        assert!(matches!(
            k3_decide(Some(7), Ok(None)),
            K3Decision::VerifiedAbsent
        ));
    }

    /// XRV1-L55: the canary kill-leg poll step needs
    /// a consumed exit — ret==0 AND a nonzero
    /// reported PID. ret==0 with si_pid==0 is
    /// NotReady (the birth is still there — a
    /// no-effect signal filter reads exactly this)
    /// ⟹ poll on, never death-proof.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn canary_kill_leg_needs_reported_pid_for_consumed() {
        assert!(canary_kill_leg_consumed(0, 123));
        assert!(!canary_kill_leg_consumed(0, 0));
        assert!(!canary_kill_leg_consumed(-1, 0));
        assert!(!canary_kill_leg_consumed(-1, 123));
    }

    /// XRV1-L29 collateral: the canary's support
    /// rule, pure and INDEPENDENT of the probe's
    /// classifier (separate text, separate gathering —
    /// a constant-error regression in the probe path
    /// cannot green both sides). The rule mirrors the
    /// classifier's Supported arm (open-ok, waits
    /// ok-or-ECHILD, signal-ok, SIGKILL-ok —
    /// XRV1-L38) — drift between rule and classifier
    /// fails the agreement test below. Mutant-checked
    /// (dropping any leg REDs).
    /// XRV1-L71: attributes restored (a prior edit
    /// dropped them — the test must RUN).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn canary_support_rule_decides_five_legs() {
        assert!(canary_supports(None, None, None, None, None));
        assert!(canary_supports(
            None,
            Some(libc::ECHILD),
            Some(libc::ECHILD),
            None,
            None
        ));
        assert!(!canary_supports(Some(libc::EPERM), None, None, None, None));
        assert!(!canary_supports(Some(libc::ENOSYS), None, None, None, None));
        assert!(!canary_supports(Some(libc::EMFILE), None, None, None, None));
        assert!(!canary_supports(None, Some(libc::EPERM), None, None, None));
        assert!(!canary_supports(None, None, Some(libc::EINVAL), None, None));
        assert!(!canary_supports(None, None, None, Some(libc::ENOSYS), None));
        assert!(!canary_supports(None, None, None, Some(libc::EPERM), None));
        assert!(!canary_supports(None, None, None, Some(libc::ECHILD), None));
        // XRV1-L38: the SIGKILL leg gates too
        // (signal-0 OK + SIGKILL denied ⟹ no
        // support — kill power unproven).
        assert!(!canary_supports(None, None, None, None, Some(libc::EPERM)));
        assert!(!canary_supports(None, None, None, None, Some(libc::ESRCH)));
        assert!(!canary_supports(None, None, None, None, Some(libc::EINTR)));
    }

    /// XRV1-L46/L64: the shared K3 outcome (pure
    /// decision — see `k3_decide`; shared by the
    /// canary and the qualifier — one text, no
    /// forked copies to drift).
    #[cfg(target_arch = "x86_64")]
    enum K3Decision {
        /// Positive tick match (authenticated).
        Proceed,
        /// No sample (unreadable birth — cleanup
        /// retained + conservative verdict, never
        /// equality).
        UnreadableSample,
        /// Sampled but unverifiable (an OUTAGE, not
        /// a recycle — cleanup retained +
        /// conservative verdict).
        UnreadableVerify,
        /// XRV1-L100: sampled but PROVEN gone
        /// (the entry vanished — terminal
        /// silence, NEVER a touch: the number
        /// is freed and may already name a
        /// replacement).
        VerifiedAbsent,
        /// Positive sampled-vs-verified mismatch (no
        /// touch — the number may name a
        /// replacement).
        Mismatched,
    }

    /// XRV1-L46/L64: the K3 decision, pure —
    /// Proceed ONLY on a positive tick match. A
    /// missing sample NEVER equals (even a missing
    /// re-read — None==None is unauthenticated,
    /// not equality); an unreadable verify against
    /// a good sample is an outage, NOT a recycle.
    /// XRV1-L100: the verify side keeps its
    /// Result — Ok(None) (proven gone) ⟹
    /// VerifiedAbsent (terminal silence), Err
    /// (outage) ⟹ UnreadableVerify (cleanup
    /// retained). Pinned by
    /// `canary_k3_decision_is_total_and_conservative`.
    #[cfg(target_arch = "x86_64")]
    fn k3_decide(sampled: Option<u64>, verified: Result<Option<u64>, ()>) -> K3Decision {
        match (sampled, verified) {
            (Some(a), Ok(Some(b))) if a == b => K3Decision::Proceed,
            (None, _) => K3Decision::UnreadableSample,
            (Some(_), Err(())) => K3Decision::UnreadableVerify,
            (Some(_), Ok(None)) => K3Decision::VerifiedAbsent,
            _ => K3Decision::Mismatched,
        }
    }

    /// XRV1-L55: the canary kill-leg poll step, pure —
    /// a consumed exit needs ret==0 AND a nonzero
    /// reported PID (ret==0 with si_pid==0 is
    /// NotReady — poll on). Pinned by
    /// `canary_kill_leg_needs_reported_pid_for_consumed`.
    #[cfg(target_arch = "x86_64")]
    fn canary_kill_leg_consumed(ret: libc::c_int, si_pid: libc::pid_t) -> bool {
        ret == 0 && si_pid != 0
    }

    /// XRV1-L29: the canary's support rule, pure (see
    /// `canary_support_rule_decides_five_legs`).
    /// Deliberately NOT shared with
    /// `waitid_probe_classify` (independent text —
    /// probe-path regressions must not green the
    /// canary).
    #[cfg(target_arch = "x86_64")]
    fn canary_supports(
        open_errno: Option<i32>,
        consume_errno: Option<i32>,
        peek_errno: Option<i32>,
        signal_errno: Option<i32>,
        kill_errno: Option<i32>,
    ) -> bool {
        open_errno.is_none()
            && matches!(consume_errno, None | Some(libc::ECHILD))
            && matches!(peek_errno, None | Some(libc::ECHILD))
            && signal_errno.is_none()
            && kill_errno.is_none()
    }

    /// XRV1-L78: canary open-failure routing, pure
    /// — ESRCH (proven gone: fully reaped) ⟹ stand
    /// down silently (no numeric retire against the
    /// freed number); any other errno ⟹ the birth
    /// may live ⟹ strict retire. The ESRCH arm is
    /// unreachable live (needs a sweep inside the
    /// T-await→open µs gap) — the mapping is pinned
    /// here instead (a future edit widening the
    /// silent arm REDs). Pinned by
    /// `canary_open_esrch_stands_down_silently`.
    #[cfg(target_arch = "x86_64")]
    fn canary_open_proven_gone(errno: i32) -> bool {
        errno == libc::ESRCH
    }

    /// XRV1-L78 collateral: only ESRCH routes to
    /// the silent stand-down (EPERM/ENOENT/EMFILE —
    /// the birth may live — must retire strictly).
    /// Mutant-checked (widen the silent arm ⟹ RED).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn canary_open_esrch_stands_down_silently() {
        assert!(canary_open_proven_gone(libc::ESRCH));
        for errno in [libc::EPERM, libc::ENOENT, libc::EMFILE, libc::EACCES] {
            assert!(
                !canary_open_proven_gone(errno),
                "{errno} must retire strictly (birth may live)"
            );
        }
    }

    /// XRV1-L29/L35: one held-canary gathering
    /// (module-level so the sigkill-deny agreement
    /// test calls the SAME text as the live agreement
    /// test — no forked copy to drift). Owned HELD
    /// birth (self-stop + T-await — the hold
    /// authenticates the pin: stopped ⟹ cannot exit ⟹
    /// cannot be reaped ⟹ the open names OUR birth) +
    /// FULLY INLINE gathering (no shared gatherer, no
    /// shared classifier — a constant-error regression
    /// in the probe path cannot green both sides).
    /// Duration 153 is repo-wide unique. Custody via
    /// the Child-handle owner (unwind-safe,
    /// L1-clean); strict retire at every exit.
    #[cfg(target_arch = "x86_64")]
    fn canary_once() -> bool {
        let child = match std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 153"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return false,
        };
        let owner = UnpinnedStagingOwner::new(child);
        let pid = owner.pid();
        // T-await (bounded — the hold is the
        // authentication; expiry retires + panics
        // staging-broken loud (never a false
        // unsupported)).
        let tend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            if std::time::Instant::now() >= tend {
                owner.retire();
                panic!("staging broken (canary never shows T)");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // K3 sample→open→verify (inline — own text):
        // a recycle between sample and open (held ⟹
        // impossible) retires + panics staging-broken
        // loud, never a stranger pin.
        let sampled = pin_birth_tick(pid);
        let fd = match super::super::seccomp::pidfd_open_raw(pid) {
            Ok(fd) => fd,
            // XRV1-L78: open-ESRCH ⟹ PROVEN GONE
            // (fully reaped — a sweep took our
            // staged birth) ⟹ stand down SILENTLY
            // (a numeric retire against the freed
            // number could kill a replacement — the
            // verdict stays false: unproven). Any
            // other errno ⟹ the birth may LIVE ⟹
            // strict retire.
            Err(errno) if canary_open_proven_gone(errno) => {
                owner.disarm();
                return canary_supports(Some(errno), None, None, None, None);
            }
            Err(errno) => {
                let verdict = canary_supports(Some(errno), None, None, None, None);
                owner.retire();
                return verdict;
            }
        };
        // XRV1-L46/L64: the K3 decision (pure — no
        // None==None equality: unauthenticated is
        // unauthenticated; an unreadable verify is
        // an outage, NOT a recycle — both retain
        // cleanup).
        // XRV1-L100: the verify Result passes
        // through (Ok(None) is proven gone,
        // Err is outage — never merged).
        match k3_decide(sampled, proc_starttime(pid).map_err(|_| ())) {
            K3Decision::Proceed => {}
            K3Decision::VerifiedAbsent => {
                // SAFETY: close our pidfd copy.
                unsafe {
                    libc::close(fd);
                }
                // Proven gone (the staged birth is
                // fully reaped) ⟹ stand down
                // SILENTLY (mirrors the L78
                // open-ESRCH arm — a numeric
                // retire against the freed number
                // could kill a replacement) +
                // Unsupported (false — unproven).
                owner.disarm();
                return false;
            }
            K3Decision::UnreadableSample | K3Decision::UnreadableVerify => {
                // SAFETY: close our pidfd copy.
                unsafe {
                    libc::close(fd);
                }
                // Unreadable birth or verify (never
                // authenticated, or outage) ⟹ retire
                // what we staged + Unsupported
                // (false — unproven, never equality,
                // cleanup RETAINED).
                owner.retire();
                return false;
            }
            K3Decision::Mismatched => {
                // SAFETY: close our pidfd copy
                // (unconsumed — it may name a
                // stranger).
                unsafe {
                    libc::close(fd);
                }
                // Mismatch ⟹ the number may name a
                // replacement ⟹ NO TOUCH (disarm —
                // silent — never a numeric kill on
                // the current occupant) + panic loud
                // (staging-broken — hold premise
                // break).
                owner.disarm();
                panic!("staging broken (canary recycled mid-open — hold premise break?)");
            }
        }
        // Inline legs (raw waitids + raw signal-0 —
        // EINTR-tolerant, WNOHANG (never block)).
        let one_wait = |flags: libc::c_int| -> Option<i32> {
            for _ in 0..3 {
                let mut info: libc::siginfo_t = unsafe { std::mem::zeroed() };
                // SAFETY: own pidfd + zeroed siginfo.
                let ret =
                    unsafe { libc::waitid(libc::P_PIDFD, fd as libc::id_t, &mut info, flags) };
                if ret == 0 {
                    return None;
                }
                match std::io::Error::last_os_error().raw_os_error() {
                    Some(libc::EINTR) => continue,
                    other => return other,
                }
            }
            Some(libc::EINTR)
        };
        let consume = one_wait(libc::WEXITED | libc::WNOHANG);
        let peek = one_wait(libc::WEXITED | libc::WNOHANG | libc::WNOWAIT);
        let mut signal = Some(libc::EINTR);
        for _ in 0..3 {
            match super::super::seccomp::pidfd_send_signal_raw(fd, 0) {
                Ok(()) => {
                    signal = None;
                    break;
                }
                Err(errno) if errno == libc::EINTR => continue,
                Err(errno) => {
                    signal = Some(errno);
                    break;
                }
            }
        }
        // XRV1-L38: inline SIGKILL leg (own text —
        // signal-0 proves dispatch, not kill power):
        // pidfd SIGKILL + death-proven through the
        // pin (consumed-ours ⟹ None; ECHILD ⟹ None
        // (a sweep stole the status AFTER our kill
        // landed — benign); EPERM ⟹ Some(EPERM)
        // (kill power denied — no support);
        // bound-expiry (D-state) ⟹ Some(EAGAIN)).
        let mut kill = Some(libc::EINTR);
        let mut sent = false;
        for _ in 0..3 {
            match super::super::seccomp::pidfd_send_signal_raw(fd, libc::SIGKILL) {
                Ok(()) => {
                    sent = true;
                    break;
                }
                Err(errno) if errno == libc::EINTR => continue,
                Err(errno) => {
                    kill = Some(errno);
                    break;
                }
            }
        }
        if sent {
            kill = Some(libc::EAGAIN);
            let kend = std::time::Instant::now() + std::time::Duration::from_secs(1);
            loop {
                let mut info: libc::siginfo_t = unsafe { std::mem::zeroed() };
                // SAFETY: own pidfd + zeroed siginfo.
                let ret = unsafe {
                    libc::waitid(
                        libc::P_PIDFD,
                        fd as libc::id_t,
                        &mut info,
                        libc::WEXITED | libc::WNOHANG,
                    )
                };
                if ret == 0 {
                    // XRV1-L55: a consumed exit needs a
                    // nonzero reported PID (ret==0 with
                    // si_pid==0 is NotReady — a
                    // no-effect signal filter reads
                    // exactly this — poll on to the
                    // bound, never death-proof; the
                    // errno below would be STALE on
                    // success — never read it here).
                    // SAFETY: as in probe_victim_pin —
                    // zeroed reads valid zero; a report
                    // fills _sigchld.
                    if canary_kill_leg_consumed(ret, unsafe { info.si_pid() }) {
                        kill = None;
                        break;
                    }
                } else {
                    match std::io::Error::last_os_error().raw_os_error() {
                        Some(libc::ECHILD) => {
                            kill = None;
                            break;
                        }
                        // Still dying (or EINTR) — poll
                        // to the bound; anything else
                        // (including no errno) holds
                        // EAGAIN past expiry.
                        Some(_) | None => {}
                    }
                }
                if std::time::Instant::now() >= kend {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
        }
        // SAFETY: close our pidfd copy (the owner
        // retires the birth, not the fd).
        unsafe {
            libc::close(fd);
        }
        let verdict = canary_supports(None, consume, peek, signal, kill);
        // XRV1-L43: kill-None ⟺ DISCHARGED (consumed
        // through the pin — ours or swept) ⟹ stand
        // down SILENTLY (no numeric kill/wait past
        // discharge — the pin did the consuming).
        // kill-Some ⟺ live-or-unknown ⟹ strict
        // retire (the birth may still live).
        // XRV1-L60: kill-ESRCH ⟺ DISCHARGED (the pin
        // reported the birth gone) ⟹ stand down
        // SILENTLY with the consumed arm (no numeric
        // kill/wait on the freed number).
        if kill.is_none() || kill == Some(libc::ESRCH) {
            owner.disarm();
        } else {
            owner.retire();
        }
        verdict
    }

    /// XRV1-L15/L29/L35 collateral: the probe agrees
    /// with an independent HELD canary — an OWNED
    /// sleep birth (duration 153) established under the
    /// stopped hold (T-awaited + K3 sample→open→verify
    /// — the pin is authenticated: retirement +
    /// replacement before the open cannot bind it to a
    /// sibling) and observed through FULLY INLINE
    /// gathering (raw open + raw consuming-waitid +
    /// raw peeking-waitid + raw signal-0 + raw
    /// SIGKILL-with-death-proof, own text — NOT the
    /// probe's gatherers) and decided by the
    /// INDEPENDENT pure rule (`canary_supports` — NOT
    /// the probe's classifier). Under denial or
    /// exhaustion BOTH read false (agreement — no suite
    /// failure; the L9 gates skip loud instead —
    /// XRV1-L15). The old uname-assert is deleted (it
    /// reddened under legitimate denial); uname survives
    /// as a one-direction check (canary-true on a <5.4
    /// kernel is impossible ⟹ loud) plus diagnostic —
    /// persona-aware (XRV1-L28: vacuous under UNAME26).
    /// Transient disagreement (an EMFILE burst edge
    /// between the two gatherings) retries bounded;
    /// persistent disagreement is a real probe bug ⟹
    /// loud. The old-kernel live direction is untestable
    /// here — the pure table test covers it (ENOSYS
    /// arms) by construction.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn waitid_pidfd_probe_agrees_with_live_canary() {
        // Agreement with transient absorption (a burst
        // edge between gatherings must not RED).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(1);
        let (probe, canary) = loop {
            let probe = waitid_pidfd_probe() == ProbeVerdict::Supported;
            let canary = canary_once();
            if probe == canary {
                break (probe, canary);
            }
            assert!(
                std::time::Instant::now() < end,
                "probe/canary disagree persistently (probe={probe} canary={canary})"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        };
        let mut uts: libc::utsname = unsafe { std::mem::zeroed() };
        // SAFETY: zeroed utsname out-param.
        assert_eq!(unsafe { libc::uname(&mut uts) }, 0, "uname works");
        // SAFETY: uname NUL-terminates on success.
        let release = unsafe { std::ffi::CStr::from_ptr(uts.release.as_ptr()) }.to_string_lossy();
        eprintln!("probe/canary agree: {probe} (uname -r {release})");
        if canary {
            // XRV1-L28/L40: persona-aware (UNAME26 fakes
            // the release as 2.6.x — the version check
            // is vacuous there, diagnostic only — AND a
            // DENIED query is unknown (never proof of
            // absence — imposing the floor there would
            // reject successful runtime evidence under a
            // faked release)).
            // SAFETY: get-persona query (0xffffffff
            // reads without setting).
            let persona = unsafe { libc::personality(0xffffffff) };
            let (unknown, uname26) = persona_uname26_bits(persona);
            eprintln!("canary persona: {persona:#x} (unknown: {unknown} uname26: {uname26})");
            if !unknown {
                assert!(
                    release_meets_5_4(&release, uname26),
                    "canary-true on a pre-5.4 kernel ({release}) is impossible"
                );
            }
        }
    }

    /// XRV1-L58 collateral (helper exit codes):
    /// the isolated qualifier helper reports its
    /// verdict by exit code — 0 ⟺ kill landed
    /// (None); else the errno (EPERM/EAGAIN/EIO/…);
    /// an out-of-range errno degrades to EIO
    /// (conservative — never a false land-claim,
    /// never a code collision).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn qualifier_helper_exit_codes_round_trip() {
        assert_eq!(qualify_code_of(None), 0);
        assert_eq!(qualify_code_of(Some(libc::EPERM)), libc::EPERM);
        assert_eq!(qualify_code_of(Some(libc::EAGAIN)), libc::EAGAIN);
        assert_eq!(qualify_code_of(Some(libc::EIO)), libc::EIO);
        assert_eq!(qualify_code_of(Some(999)), libc::EIO);
        assert_eq!(qualify_code_of(Some(0)), libc::EIO);
        assert_eq!(qualify_verdict_of(0), None);
        assert_eq!(qualify_verdict_of(libc::EPERM), Some(libc::EPERM));
        assert_eq!(qualify_verdict_of(libc::EIO), Some(libc::EIO));
    }

    /// XRV1-L43/L53 collateral (qualifier never
    /// steals): the SIGKILL qualifier consumes its
    /// throwaway ONLY through the birth-bound pin
    /// (never a numeric wait) — a sibling zombie's
    /// status survives the qualification (any
    /// verdict — this test judges no-steal only,
    /// so no capability gate). Characterization
    /// (locks the pin-only consume — a
    /// waitpid(-1)-shape mutant steals the sibling
    /// ⟹ RED).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn sigkill_qualifier_spares_sibling_zombie() {
        use std::os::unix::process::ExitStatusExt as _;
        let mut sibling = std::process::Command::new("sh")
            .arg("-c")
            .arg("exit 3")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (sibling spawn)");
        let spid = sibling.id() as libc::pid_t;
        let mut _sguard = FixtureGuard::new(spid);
        let send = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(spid) == Some('Z') {
                break;
            }
            assert!(
                std::time::Instant::now() < send,
                "staging broken (sibling never zombies)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // Qualify (stages + kills + consumes its OWN
        // throwaway — the sibling must survive).
        let _ = waitid_pidfd_sigkill_qualify_errno();
        let status = sibling.wait().expect("sibling reaps its own");
        // XRV1-L122: disarm on CONFIRMED discharge
        // (the wait above reaped ours) BEFORE
        // judging the captured status (an assert
        // panic with the guard armed unwinds numeric
        // cleanup over a discharged number).
        _sguard.disarm();
        assert_eq!(status.code(), Some(3), "sibling status must survive");
        assert_eq!(status.signal(), None, "no signal");
    }

    /// XRV1-L73: fork-child alarm arming (shared
    /// by the qualifier child and the mask
    /// collateral — one text): reset SIGALRM to
    /// default (an inherited handler would survive
    /// into the deadline), UNBLOCK it (an
    /// inherited mask would wedge the suicide —
    /// the L73 shape — same class as L20), then
    /// arm. _exit(13) on any setup failure (loud
    /// at the parent's exit-code assert — never a
    /// silently unarmed child). Malloc-free +
    /// lock-free (fork-child-safe). Pinned by
    /// `fork_child_alarm_survives_inherited_block`.
    #[cfg(target_arch = "x86_64")]
    fn fork_child_arm_alarm(secs: libc::c_uint) {
        // SAFETY: sigaction/mask/alarm only (no
        // locks, no allocator — fork-child-safe).
        unsafe {
            let mut dfl: libc::sigaction = std::mem::zeroed();
            dfl.sa_sigaction = libc::SIG_DFL;
            libc::sigemptyset(&mut dfl.sa_mask);
            dfl.sa_flags = 0;
            if libc::sigaction(libc::SIGALRM, &dfl, std::ptr::null_mut()) != 0 {
                libc::_exit(13);
            }
            let mut unblock: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&mut unblock);
            libc::sigaddset(&mut unblock, libc::SIGALRM);
            if libc::pthread_sigmask(libc::SIG_UNBLOCK, &unblock, std::ptr::null_mut()) != 0 {
                libc::_exit(13);
            }
            libc::alarm(secs);
        }
    }

    /// XRV1-L104: one wait-error class (the rule
    /// the pinless supervisor shares with the
    /// canonical pin probe — ECHILD ⟺ confirmed
    /// discharge; EINTR ⟺ retry; anything else ⟺
    /// unverifiable, never stolen).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq)]
    enum SuperviseWaitClass {
        Discharged,
        Retry,
        Unverifiable,
    }

    /// XRV1-L104: classify one wait errno (pure —
    /// pinned by `supervise_classifies_wait_errors`).
    #[cfg(target_arch = "x86_64")]
    fn classify_supervise_wait_errno(errno: libc::c_int) -> SuperviseWaitClass {
        if errno == libc::ECHILD {
            SuperviseWaitClass::Discharged
        } else if errno == libc::EINTR {
            SuperviseWaitClass::Retry
        } else {
            SuperviseWaitClass::Unverifiable
        }
    }

    /// XRV1-L104 collateral: wait-error
    /// classification truth table (ECHILD ⟺
    /// confirmed discharge — the ONLY stolen
    /// shape; EINTR ⟺ retry-with-deadline; every
    /// other errno ⟺ unverifiable — never
    /// stolen, never retried blind). Pins the rule
    /// the pinless supervisor shares with the
    /// canonical pin probe.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn supervise_classifies_wait_errors() {
        assert_eq!(
            classify_supervise_wait_errno(libc::ECHILD),
            SuperviseWaitClass::Discharged
        );
        assert_eq!(
            classify_supervise_wait_errno(libc::EINTR),
            SuperviseWaitClass::Retry
        );
        for errno in [
            libc::EPERM,
            libc::EBADF,
            libc::EINVAL,
            libc::EACCES,
            libc::EIO,
            libc::EAGAIN,
        ] {
            assert_eq!(
                classify_supervise_wait_errno(errno),
                SuperviseWaitClass::Unverifiable,
                "errno {errno} must be unverifiable, never stolen"
            );
        }
    }

    /// XRV1-L95/L104: birth-held supervision
    /// outcome (Reaped = OUR status through OUR
    /// authority; Stolen = confirmed discharge —
    /// terminal, nothing lingers; Unverifiable =
    /// the wait channel failed and cleanup could
    /// not confirm — the caller must fail loud,
    /// never skip).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq)]
    enum SuperviseOutcome {
        Reaped(libc::c_int),
        Stolen,
        Unverifiable(String),
    }

    /// XRV1-L104: one bounded-drain verdict
    /// (Reaped = OUR corpse collected; Stolen =
    /// consumed elsewhere — nothing lingers;
    /// Expired = still uncollectable past the
    /// bound).
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq)]
    enum DrainVerdict {
        Reaped(libc::c_int),
        Stolen,
        Expired,
    }

    /// XRV1-L95/L104/L105: bounded pin-drain (5s —
    /// the L85 bound): every probe classifies
    /// (Reaped ⟹ collected; ReapedElsewhere ⟹
    /// Stolen — confirmed discharge;
    /// NotReady/Unverifiable ⟹ the deadline check
    /// runs BEFORE the next poll — L105, never
    /// bypassed — then sleep 10ms).
    #[cfg(target_arch = "x86_64")]
    fn drain_pinned_birth(pin: libc::c_int, what: &str) -> DrainVerdict {
        let dend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match probe_victim_pin(pin) {
                PinProbe::Reaped(st) => return DrainVerdict::Reaped(st),
                PinProbe::ReapedElsewhere => return DrainVerdict::Stolen,
                PinProbe::NotReady | PinProbe::Unverifiable(_) => {}
            }
            // XRV1-L105: the deadline binds EVERY
            // iteration (no continue-before-check —
            // interrupted/unverifiable polls expire
            // too).
            if std::time::Instant::now() >= dend {
                eprintln!("{what}: pin drain expired (birth uncollectable past 5s)");
                return DrainVerdict::Expired;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// XRV1-L95/L104/L105: birth-held bounded
    /// supervisor (the pinned path — waits AND
    /// kills through the pin: ZERO numeric effects,
    /// so no wait can consume a replacement and no
    /// kill can land on one — L95). Polls the pin
    /// to `secs` (WNOHANG + 1ms nap): Reaped ⟹ OUR
    /// status; ReapedElsewhere ⟹ Stolen —
    /// TERMINAL (confirmed discharge — zero further
    /// effects); Unverifiable ⟹ custody retained
    /// (L104): a pin kill-probe — ESRCH ⟹ Stolen
    /// (kill-proven gone), landed ⟹ bounded drain,
    /// refused ⟹ immediate Unverifiable (a dead
    /// channel has no custody to drain — no
    /// theater). EINTR maps inside the probe
    /// (NotReady) and the deadline binds every
    /// iteration (L105). On expiry kills through
    /// the pin + drains FIRST (never abandons the
    /// birth to the unwind), THEN panics loud
    /// (wedged — the drain verdict rides in the
    /// message). Callers: qualifier fork-child,
    /// wedge (both own held pins). Pinned by
    /// `fork_supervisor_kills_and_reaps_on_expiry`
    /// (expiry path) +
    /// `supervise_pinned_stolen_reads_terminal` +
    /// `supervise_pinned_unverifiable_on_bad_pin`.
    #[cfg(target_arch = "x86_64")]
    fn supervise_pinned_birth(pin: libc::c_int, secs: u64, what: &str) -> SuperviseOutcome {
        let end = std::time::Instant::now() + std::time::Duration::from_secs(secs);
        loop {
            match probe_victim_pin(pin) {
                PinProbe::Reaped(st) => return SuperviseOutcome::Reaped(st),
                // XRV1-L95: confirmed discharge is
                // TERMINAL — zero further effects
                // (no kill, no drain, no numeric
                // anything).
                PinProbe::ReapedElsewhere => return SuperviseOutcome::Stolen,
                PinProbe::NotReady => {}
                PinProbe::Unverifiable(evidence) => {
                    // XRV1-L104: retain custody — the
                    // kill-probe runs on a DIFFERENT
                    // syscall (a wait denial does not
                    // imply a kill denial).
                    let kill_errno = super::pidfd_signal(pin, libc::SIGKILL);
                    if kill_errno == libc::ESRCH {
                        // Kill-proven gone (the pin's
                        // birth reaped) ⟹ confirmed
                        // discharge ⟹ Stolen.
                        return SuperviseOutcome::Stolen;
                    }
                    if kill_errno != 0 {
                        // Dead channel (probe failed
                        // AND kill refused — nothing
                        // is addressable through this
                        // pin): immediate, no drain
                        // theater.
                        return SuperviseOutcome::Unverifiable(format!(
                            "{what}: pin probe failed ({evidence}) and kill refused (errno {kill_errno})"
                        ));
                    }
                    // Kill landed ⟹ the corpse must
                    // arrive — drain bounded.
                    match drain_pinned_birth(pin, what) {
                        DrainVerdict::Reaped(st) => return SuperviseOutcome::Reaped(st),
                        DrainVerdict::Stolen => return SuperviseOutcome::Stolen,
                        DrainVerdict::Expired => {
                            return SuperviseOutcome::Unverifiable(format!(
                                "{what}: pin probe failed ({evidence}), kill landed, drain expired"
                            ))
                        }
                    }
                }
            }
            // XRV1-L105: the deadline binds EVERY
            // iteration (NotReady AND EINTR-mapped —
            // never bypassed).
            if std::time::Instant::now() >= end {
                // Expiry: kill + drain FIRST (never
                // abandon the birth to the unwind),
                // THEN panic loud (wedged — the drain
                // verdict rides in the message).
                let kill_errno = super::pidfd_signal(pin, libc::SIGKILL);
                if kill_errno != 0 {
                    // XRV1-L85: diagnose a refused kill
                    // IMMEDIATELY (the drain below then
                    // confirms or times out).
                    eprintln!(
                        "{what}: supervisor kill refused (errno {kill_errno} — draining anyway)"
                    );
                }
                let drained = drain_pinned_birth(pin, what);
                panic!("{what} wedged past {secs}s (kill errno {kill_errno}, drain {drained:?})");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    /// XRV1-L95/L104/L105: bounded numeric drain
    /// for the pinless path (5s — the L85 bound):
    /// every wait classifies through the shared
    /// rule (reaped ⟹ collected; ECHILD ⟹ Stolen;
    /// EINTR/unverifiable ⟹ the deadline check runs
    /// BEFORE the next poll — L105 — then sleep
    /// 10ms). Sole-waiter sound (see
    /// `supervise_own_child`).
    #[cfg(target_arch = "x86_64")]
    fn drain_own_child(pid: libc::pid_t, what: &str) -> DrainVerdict {
        // XRV1-L116: belt+suspenders guard (callers
        // hold the [fork, drained] guard; this covers
        // forgetful direct callers for the drain span
        // itself (nests — never clears early)).
        let _supervision = NumericSupervisionGuard::enter();
        let dend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let mut st = 0;
            // SAFETY: bounded drain of our own
            // fork-child (sole waiter — see the
            // supervisor's contract).
            let got = unsafe { libc::waitpid(pid, &mut st, libc::WNOHANG) };
            if got == pid {
                return DrainVerdict::Reaped(st);
            }
            if got < 0 {
                match classify_supervise_wait_errno(
                    std::io::Error::last_os_error()
                        .raw_os_error()
                        .unwrap_or(libc::EIO),
                ) {
                    SuperviseWaitClass::Discharged => return DrainVerdict::Stolen,
                    SuperviseWaitClass::Retry | SuperviseWaitClass::Unverifiable => {}
                }
            }
            // XRV1-L105: the deadline binds EVERY
            // iteration (no continue-before-check —
            // interrupted/unverifiable polls expire
            // too).
            if std::time::Instant::now() >= dend {
                eprintln!("{what}: numeric drain expired (child uncollectable past 5s)");
                return DrainVerdict::Expired;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// XRV1-L116: process-wide numeric-supervision
    /// depth (nest-count — >0 ⟺ a numeric
    /// supervision window is open somewhere in this
    /// process (L81 middle, pinless expiry/drain —
    /// each holds a guard across [fork, reaped])).
    /// Straggler sweeps (waitpid(-1) — the TT04
    /// end-of-test loops) DEFER while >0 (they would
    /// otherwise steal a supervised birth's status
    /// mid-window (sweep+recycle ⟹ stranger
    /// verdicts)). Fresh-image waitpid(-1) users
    /// (hang-pin retire-all, theft-pin poll-steal)
    /// are EXEMPT (different processes — their -1
    /// cannot touch suite children).
    #[cfg(target_arch = "x86_64")]
    static NUMERIC_SUPERVISION_DEPTH: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(0);

    /// XRV1-L133/L134: sweep-exclusion spinlock
    /// (the L116 depth check alone TOCTOUs: a
    /// supervisor registering after the check
    /// but before the drain loses its child
    /// (proven by the L133 race pin)). The lock
    /// serializes guard registration against
    /// the WHOLE sweep: enter() adds under
    /// it, try_sweep checks+drains under it,
    /// the defer-bound fallback drains under
    /// it. A late registration lands strictly
    /// before (sweep defers) or strictly
    /// after (its fork postdates the drain —
    /// the [fork, reaped] guard contract
    /// forks only after enter). A spinlock
    /// (not a mutex): fork-children that
    /// enter post-fork (the L116
    /// isolated-stolen shape) inherit the
    /// state — a mutex would copy locked with
    /// no thread able to unlock it (proven by
    /// the L134 pin); the spinlock resets via
    /// atfork (below). Leaf lock (never held
    /// across another acquisition; the
    /// defer-sleep runs outside it) —
    /// deadlock-free by construction.
    /// Non-reentrant (same as the mutex was —
    /// no signal handler enters (the HUP
    /// handler is a no-op)). Critical
    /// sections are short + nonblocking
    /// (fetch_add (enter), WNOHANG-only
    /// drain (sweep)) — a spinner always
    /// observes release promptly.
    #[cfg(target_arch = "x86_64")]
    static SWEEP_EXCLUSION_HELD: std::sync::atomic::AtomicBool =
        std::sync::atomic::AtomicBool::new(false);

    /// XRV1-L134: RAII spinlock guard (Drop
    /// releases — panic-safe (an unwinding
    /// holder releases on its way out)).
    #[cfg(target_arch = "x86_64")]
    struct SweepExclusionGuard;
    #[cfg(target_arch = "x86_64")]
    impl Drop for SweepExclusionGuard {
        fn drop(&mut self) {
            SWEEP_EXCLUSION_HELD.store(false, std::sync::atomic::Ordering::Release);
        }
    }

    /// XRV1-L134: atfork child reset (a plain
    /// atomic store — async-signal-safe; the
    /// child's exclusion domain is fresh (its
    /// guard/depth copies are private, and
    /// its grandchildren are unreapable by
    /// parent sweeps so child-side exclusion
    /// guards nothing parental) — releasing
    /// a possibly-inherited hold is sound,
    /// and REQUIRED (no thread in the child
    /// could release it otherwise).
    #[cfg(target_arch = "x86_64")]
    extern "C" fn reset_sweep_exclusion_in_fork_child() {
        SWEEP_EXCLUSION_HELD.store(false, std::sync::atomic::Ordering::SeqCst);
    }

    /// XRV1-L134: register the reset before
    /// main/libtest (the `.init_array` idiom
    /// — cf. DEDICATE_SESSION_AT_LOAD:
    /// registration precedes every thread
    /// and fork, so no fork-child can ever
    /// observe an unregistered lock).
    #[cfg(target_arch = "x86_64")]
    #[used]
    #[link_section = ".init_array.00002"]
    static REGISTER_SWEEP_AT_FORK: extern "C" fn() = register_sweep_at_fork;

    /// Pre-main entry for
    /// `REGISTER_SWEEP_AT_FORK`. Pre-main-safe
    /// (single-threaded; pthread_atfork with
    /// NULL prepare/parent and a store-only
    /// child handler; a registration failure
    /// aborts loud (fail-closed at load)).
    #[cfg(target_arch = "x86_64")]
    extern "C" fn register_sweep_at_fork() {
        // SAFETY: pre-main, single-threaded.
        let rc =
            unsafe { libc::pthread_atfork(None, None, Some(reset_sweep_exclusion_in_fork_child)) };
        assert_eq!(rc, 0, "pthread_atfork registers the sweep reset");
    }

    /// XRV1-L133: lock the sweep exclusion
    /// (spinlock acquire — see the static).
    #[cfg(target_arch = "x86_64")]
    fn lock_sweep_exclusion() -> SweepExclusionGuard {
        while SWEEP_EXCLUSION_HELD
            .compare_exchange_weak(
                false,
                true,
                std::sync::atomic::Ordering::Acquire,
                std::sync::atomic::Ordering::Relaxed,
            )
            .is_err()
        {
            std::hint::spin_loop();
        }
        SweepExclusionGuard
    }

    /// XRV1-L116: RAII numeric-supervision guard
    /// (enter() +1, drop -1 — nest-safe (an outer
    /// [fork, reaped] guard + an inner supervisor
    /// guard stack (neither drop clears early))).
    /// Panic-safe (drop on unwind).
    /// XRV1-L133: enter() registers under the
    /// sweep-exclusion lock (released before
    /// the guard's lifetime begins — a held
    /// guard never holds the lock).
    #[cfg(target_arch = "x86_64")]
    struct NumericSupervisionGuard;
    #[cfg(target_arch = "x86_64")]
    impl NumericSupervisionGuard {
        fn enter() -> Self {
            let _exclusion = lock_sweep_exclusion();
            NUMERIC_SUPERVISION_DEPTH.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Self
        }
        fn is_active() -> bool {
            NUMERIC_SUPERVISION_DEPTH.load(std::sync::atomic::Ordering::SeqCst) > 0
        }
    }
    #[cfg(target_arch = "x86_64")]
    impl Drop for NumericSupervisionGuard {
        fn drop(&mut self) {
            NUMERIC_SUPERVISION_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
        }
    }

    /// XRV1-L116: try-sweep outcome.
    #[cfg(target_arch = "x86_64")]
    #[derive(Debug, PartialEq, Eq)]
    enum SweepAttempt {
        /// Supervision active — NOTHING reaped (the
        /// caller defers (sleeps + retries)).
        Deferred,
        /// Swept (count reaped — the classic drain).
        Swept(usize),
    }

    /// XRV1-L116/L133: locked straggler drain (the
    /// TT04 end-of-test waitpid(-1) loop, extracted
    /// (one text — every sweeper routes here):
    /// reaps ALL owned zombies (RED runs stay
    /// clean) + reports the count (callers require
    /// zero). Takes the exclusion guard as PROOF
    /// (type-enforced: no drain runs outside the
    /// lock — late registrations serialize
    /// strictly before or after it).
    #[cfg(target_arch = "x86_64")]
    fn drain_stragglers_locked(_held: &SweepExclusionGuard) -> usize {
        let mut stragglers = 0;
        loop {
            let mut status = 0;
            // SAFETY: waitpid(-1) reaps any owned child.
            let got = unsafe { libc::waitpid(-1, &mut status, libc::WNOHANG) };
            if got > 0 {
                stragglers += 1;
                continue;
            }
            if got < 0 {
                let error = std::io::Error::last_os_error();
                if error.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
            }
            break;
        }
        stragglers
    }

    /// XRV1-L116: straggler try-sweep (exclusion-
    /// checked: supervision active ⟹ Deferred (zero
    /// reaps — the zombies survive for their
    /// supervisors); else the classic drain).
    /// XRV1-L133: the check+drain run ATOMICALLY
    /// under the exclusion mutex (no TOCTOU —
    /// a concurrent enter lands strictly
    /// before (⟹ Deferred) or after (its
    /// fork postdates the drain)).
    #[cfg(target_arch = "x86_64")]
    fn try_sweep_stragglers() -> SweepAttempt {
        let exclusion = lock_sweep_exclusion();
        if NumericSupervisionGuard::is_active() {
            return SweepAttempt::Deferred;
        }
        SweepAttempt::Swept(drain_stragglers_locked(&exclusion))
    }

    /// XRV1-L116: deferring straggler sweep (the TT04
    /// callers' entry: try-sweep + bounded defer-wait
    /// (90s — the L81 worst (~60s: 30s supervise +
    /// 25s scenario + margins) + 30s scheduler
    /// margin; expiry proceeds + reports LOUD
    /// (documented degradation — a wedged
    /// supervisor unblocks sweeps rather than
    /// hanging the suite; the require-zero assert
    /// then judges what it finds (a stolen foreign
    /// zombie REDs the sweeper (loud!)))).
    /// XRV1-L133: the expiry fallback drains
    /// UNDER the exclusion mutex (degraded
    /// against pre-existing supervision, but
    /// atomic against NEW registrations —
    /// a late enter lands strictly after it).
    #[cfg(target_arch = "x86_64")]
    fn sweep_stragglers_deferring() -> usize {
        sweep_stragglers_deferring_bounded(
            std::time::Instant::now() + std::time::Duration::from_secs(90),
        )
    }

    /// XRV1-L133: bounded deferring sweep (the
    /// 90s entry above delegates here; the
    /// L133 fallback pin passes an expired
    /// bound (pins fallback-under-lock
    /// without a 90s wait)).
    #[cfg(target_arch = "x86_64")]
    fn sweep_stragglers_deferring_bounded(end: std::time::Instant) -> usize {
        loop {
            match try_sweep_stragglers() {
                SweepAttempt::Swept(n) => return n,
                SweepAttempt::Deferred => {
                    if std::time::Instant::now() >= end {
                        eprintln!(
                            "sweep: supervision still active past defer bound (proceeding — degradation, never silent)"
                        );
                        let exclusion = lock_sweep_exclusion();
                        return drain_stragglers_locked(&exclusion);
                    }
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
            }
        }
    }

    /// XRV1-L95/L104/L105: pinless bounded
    /// supervisor (the numeric path — own-child
    /// supervision where NO pin exists: the L81
    /// middle runs under a pidfd-denying filter,
    /// the test's SUBJECT — a pin is
    /// unestablishable there, C1 ruling).
    /// SOLE-WAITER CONTRACT (XRV1-L116): the caller
    /// must be the only waiter of `pid` — ENFORCED
    /// BY EXCLUSION (not by parenthood: the L81
    /// middle is a child of the SHARED test process
    /// (in-process waitpid(-1) sweeps COULD steal
    /// its status)). Every supervised birth holds a
    /// `NumericSupervisionGuard` across [fork,
    /// reaped], and every in-suite waitpid(-1) sweep
    /// (the TT04 straggler loops, the J1 staging
    /// sweep) DEFERS while any guard is held (no
    /// sweep ⟹ no freed number ⟹ no recycled
    /// stranger). Fresh-image -1 users are exempt
    /// (different processes). ECHILD ⟹ Stolen —
    /// TERMINAL (confirmed discharge — zero further
    /// effects — L95); other wait errors classify
    /// through the shared rule (L104 — EINTR retries
    /// WITH the deadline, L105; unverifiable ⟹
    /// numeric kill-probe: ESRCH ⟹ Stolen, landed ⟹
    /// bounded drain, refused ⟹ immediate
    /// Unverifiable). On expiry kills + drains
    /// FIRST, THEN panics loud (wedged — the drain
    /// verdict rides in the message).
    /// L95-PINLESS-RESIDUAL (documented, no false
    /// bound claimed): the expiry kill is numeric
    /// — the poll proves alive µs before (no sleep
    /// between), but an exit + foreign reap +
    /// number recycle inside that window could
    /// misdirect the kill or let the drain consume
    /// a sibling's status. The FOREIGN REAP leg is
    /// excluded by the exclusion protocol (sweeps
    /// defer — no second waiter exists during any
    /// supervised window); the defer-bound expiry
    /// (90s) degrades LOUD (the sweeper proceeds +
    /// its require-zero assert judges (a stolen
    /// foreign zombie REDs the sweeper — never
    /// silent)). The L82 stolen scenario runs
    /// fork-child-isolated (sole waiter by
    /// construction — no replacement can appear).
    /// Callers: L81 middle, L82 stolen
    /// test — NO other caller (a pinnable birth
    /// uses the pinned path). Pinned by
    /// `supervise_pinless_stolen_reads_terminal` +
    /// `supervise_pinless_kills_and_reaps_on_expiry`
    /// + `drain_own_child_reports_consumed`.
    #[cfg(target_arch = "x86_64")]
    fn supervise_own_child(pid: libc::pid_t, secs: u64, what: &str) -> SuperviseOutcome {
        // XRV1-L116: belt+suspenders guard (callers
        // hold the [fork, reaped] guard; this covers
        // forgetful direct callers for the supervise
        // span itself (nests — never clears early)).
        let _supervision = NumericSupervisionGuard::enter();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(secs);
        loop {
            let mut status = 0;
            // SAFETY: waitpid on our own fork-child
            // (sole waiter by the contract above — a
            // foreign waitpid(-1) is the L82 shape).
            let got = unsafe { libc::waitpid(pid, &mut status, libc::WNOHANG) };
            if got == pid {
                return SuperviseOutcome::Reaped(status);
            }
            if got < 0 {
                match classify_supervise_wait_errno(
                    std::io::Error::last_os_error()
                        .raw_os_error()
                        .unwrap_or(libc::EIO),
                ) {
                    // XRV1-L95: confirmed discharge is
                    // TERMINAL — zero further effects.
                    SuperviseWaitClass::Discharged => return SuperviseOutcome::Stolen,
                    // XRV1-L105: EINTR falls THROUGH to
                    // the deadline check below (never
                    // continue-before-check).
                    SuperviseWaitClass::Retry => {}
                    SuperviseWaitClass::Unverifiable => {
                        // XRV1-L104: retain custody — the
                        // numeric kill-probe (defense in
                        // depth: waitpid on an own child
                        // fails only under a
                        // wait-denying filter — no live
                        // caller runs under one; the
                        // classification itself is
                        // pinned by the truth table).
                        let kill_rc = unsafe { libc::kill(pid, libc::SIGKILL) };
                        if kill_rc != 0 {
                            let kill_errno = std::io::Error::last_os_error()
                                .raw_os_error()
                                .unwrap_or(libc::EIO);
                            if kill_errno == libc::ESRCH {
                                // Kill-proven gone ⟹
                                // confirmed discharge.
                                return SuperviseOutcome::Stolen;
                            }
                            return SuperviseOutcome::Unverifiable(format!(
                                "{what}: numeric wait failed and kill refused (errno {kill_errno})"
                            ));
                        }
                        match drain_own_child(pid, what) {
                            DrainVerdict::Reaped(st) => return SuperviseOutcome::Reaped(st),
                            DrainVerdict::Stolen => return SuperviseOutcome::Stolen,
                            DrainVerdict::Expired => {
                                return SuperviseOutcome::Unverifiable(format!(
                                    "{what}: numeric wait failed, kill landed, drain expired"
                                ))
                            }
                        }
                    }
                }
            }
            // XRV1-L105: the deadline binds EVERY
            // iteration — including post-EINTR (the
            // loop's own poll is the fresh
            // alive-confirm: no sleep sits between it
            // and the expiry kill below — L95 window
            // minimization).
            if std::time::Instant::now() >= end {
                // Expiry: kill + drain FIRST (never
                // abandon the child to the unwind),
                // THEN panic loud (wedged — the drain
                // verdict rides in the message).
                let kill_rc = unsafe { libc::kill(pid, libc::SIGKILL) };
                // Capture BEFORE the drain (the
                // drain's syscalls clobber errno).
                let kill_errno = if kill_rc == 0 {
                    0
                } else {
                    std::io::Error::last_os_error()
                        .raw_os_error()
                        .unwrap_or(libc::EIO)
                };
                if kill_rc != 0 {
                    // XRV1-L85: diagnose a refused
                    // kill IMMEDIATELY (the drain
                    // below then confirms or times
                    // out).
                    eprintln!(
                        "{what}: supervisor kill refused (errno {kill_errno} — draining anyway)"
                    );
                }
                let drained = drain_own_child(pid, what);
                panic!("{what} wedged past {secs}s (kill errno {kill_errno}, drain {drained:?})");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    /// XRV1-L95/L104 collateral: stage a consumed
    /// held birth for the terminal-shape tests (an
    /// instant exiter, reaped through its own pin
    /// — the simulated foreign waiter; None ⟹ a
    /// real foreign sweep stole it in setup ⟹ the
    /// caller skips loud, L82 shape).
    #[cfg(target_arch = "x86_64")]
    fn stage_consumed_held_birth(what: &str) -> Option<(libc::pid_t, std::os::unix::io::OwnedFd)> {
        // XRV1-L127: capability gate FIRST (a
        // pidfd/waitid-denied host skips (None) loud
        // — the old bare spawn panicked where no pin
        // can open).
        if probe_waitid_capability() != ProbeVerdict::Supported {
            eprintln!(
                "skip: no pidfd+waitid power ({what} unprovable here — capability, not stolen)"
            );
            return None;
        }
        fn exit_7(_: ()) -> ! {
            unsafe {
                libc::_exit(7);
            }
        }
        let (pid, pin) =
            spawn_held_fork_child(exit_7, (), what).expect("staging broken (held spawn)");
        use std::os::unix::io::AsRawFd as _;
        let raw = pin.as_raw_fd();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match probe_victim_pin(raw) {
                PinProbe::Reaped(_) => return Some((pid, pin)),
                PinProbe::ReapedElsewhere => return None,
                PinProbe::NotReady => {
                    assert!(
                        std::time::Instant::now() < end,
                        "staging broken ({what} instant exiter never exits)"
                    );
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                PinProbe::Unverifiable(evidence) => {
                    panic!("staging broken ({what} pin unverifiable: {evidence})")
                }
            }
        }
    }

    /// XRV1-L95 collateral: a pinned birth consumed
    /// before supervision reads terminal Stolen (no
    /// panic, no timeout, no further effect — the
    /// L82 shape through birth-held authority).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn supervise_pinned_stolen_reads_terminal() {
        let Some((_pid, pin)) = stage_consumed_held_birth("pinned-stolen test") else {
            // (None ⟹ stolen (foreign waiter) or
            // capability-gated (the helper printed its
            // specific reason) — either way a skip.)
            eprintln!("skip: pinned-stolen setup unprovable (stolen or ungated)");
            return;
        };
        use std::os::unix::io::AsRawFd as _;
        // The supervisor must read Stolen (no panic,
        // no timeout — ECHILD is terminal).
        assert_eq!(
            supervise_pinned_birth(pin.as_raw_fd(), 1, "pinned stolen probe"),
            SuperviseOutcome::Stolen
        );
    }

    /// XRV1-L104 collateral: a dead pin channel
    /// (EBADF probe + EBADF kill — nothing is
    /// addressable through it) reads Unverifiable
    /// FAST (no drain theater on a dead channel —
    /// a 5s drain would observe nothing new).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn supervise_pinned_unverifiable_on_bad_pin() {
        let start = std::time::Instant::now();
        let out = supervise_pinned_birth(-1, 30, "bad-pin probe");
        assert!(
            matches!(out, SuperviseOutcome::Unverifiable(_)),
            "dead pin must read Unverifiable, got {out:?}"
        );
        assert!(
            start.elapsed() < std::time::Duration::from_secs(4),
            "dead channel must not drain-theater (5s)"
        );
    }

    /// XRV1-L104 collateral: the pinned drain reaps
    /// a killed birth (kill lands → corpse arrives
    /// → Reaped — the drain never invents Stolen
    /// over a collectable corpse).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn drain_pinned_birth_reaps_killed_birth() {
        // XRV1-L128: sole waiter BY EXCLUSION (a
        // SIGKILL does not reserve its status — a
        // legitimate concurrent sweep could steal
        // the corpse and fail this oracle — so the
        // WHOLE test holds the supervision guard
        // (cooperative sweeps defer (every in-suite
        // -1 scavenger respects it — attributed
        // scan) ⟹ Stolen is IMPOSSIBLE here ⟹ the
        // Stolen arm below means mutant-or-
        // corruption, never a valid schedule).
        let _sole = NumericSupervisionGuard::enter();
        // XRV1-L127: capability gates FIRST (L85
        // order — retire power before the waitid
        // gate (the waitid probe itself needs
        // numeric kill)). A denied host skips loud
        // — the old bare staging panicked where no
        // kill can land / no pin can open.
        if !qualify_numeric_retire() {
            eprintln!("skip: no numeric retire power (drain positive unprovable here)");
            return;
        }
        if probe_waitid_capability() != ProbeVerdict::Supported {
            eprintln!("skip: no pidfd+waitid power (drain positive unprovable here)");
            return;
        }
        let (_pid, pin) = spawn_held_fork_child(wedge_sleeper_body, (), "drain test")
            .expect("staging broken (held spawn)");
        use std::os::unix::io::AsRawFd as _;
        let raw = pin.as_raw_fd();
        assert_eq!(
            super::pidfd_signal(raw, libc::SIGKILL),
            0,
            "staging broken (drain-test kill refused)"
        );
        match drain_pinned_birth(raw, "drain test") {
            DrainVerdict::Reaped(st) => {
                use std::os::unix::process::ExitStatusExt as _;
                let exited = std::process::ExitStatus::from_raw(st);
                assert_eq!(
                    exited.signal(),
                    Some(libc::SIGKILL),
                    "drain must collect OUR kill, got {exited:?}"
                );
            }
            DrainVerdict::Stolen => {
                // Fail-closed (NOT a skip): exclusion
                // makes Stolen IMPOSSIBLE here (see
                // the guard above) — a Stolen means
                // the drain invented it over a
                // collectable corpse (a skip would
                // let a Reaped→Stolen mutant
                // survive).
                panic!(
                    "drain saw Stolen over OUR just-killed birth under exclusion (mutant-suspect)"
                );
            }
            DrainVerdict::Expired => {
                panic!("drain must collect a SIGKILLed birth within 5s")
            }
        }
        // XRV1-L128 self-assert (the exclusion this
        // oracle stands on — a held guard ⟹
        // try-sweep defers; deterministic under the
        // pin filter (no siblings); in full suite a
        // sibling guard also defers (same verdict)).
        assert_eq!(
            try_sweep_stragglers(),
            SweepAttempt::Deferred,
            "drain oracle must run under exclusion (sole waiter)"
        );
    }

    /// XRV1-L104 collateral: the pinned drain over
