    /// XRV1-L95/L104 collateral: the pinless drain
    /// over an already-consumed child reads Stolen
    /// (no corpse to collect — confirmed discharge,
    /// not expiry theater).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn drain_own_child_reports_consumed() {
        // XRV1-L116: exclusion guard across [fork,
        // drained] (a concurrent straggler sweep
        // would steal the corpse ⟹ false Stolen).
        let _supervision = NumericSupervisionGuard::enter();
        // SAFETY: fork in a multithreaded test binary
        // — the child exits immediately (never
        // returns into the harness).
        let pid = unsafe { libc::fork() };
        assert!(pid >= 0, "staging broken (fork failed)");
        if pid == 0 {
            unsafe {
                libc::_exit(7);
            }
        }
        let mut st = 0;
        // SAFETY: blocking reap of our own
        // instant-exiter (prompt).
        let got = unsafe { libc::waitpid(pid, &mut st, 0) };
        assert_eq!(got, pid, "staging broken (must consume first)");
        assert_eq!(
            drain_own_child(pid, "drain-consumed pinless test"),
            DrainVerdict::Stolen
        );
    }

    /// XRV1-L95/L104/L105 collateral: pinless
    /// supervision kills + reaps a 30s sleeper past
    /// a 1s bound, then panics (wedged — the drain
    /// verdict rides in the message, asserted
    /// below). The bare fork IS the subject (a
    /// pinless birth under test — sole waiter by
    /// parenthood + immediate supervision; no pin
    /// attempt exists, so L93's race has no pin leg
    /// — the L81 shape in miniature).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn supervise_pinless_kills_and_reaps_on_expiry() {
        use std::panic::{catch_unwind, AssertUnwindSafe};
        // XRV1-L116: exclusion guard across [fork,
        // reaped] (a concurrent straggler sweep would
        // steal the sleeper's corpse in the µs
        // kill→drain gap ⟹ false Stolen).
        let _supervision = NumericSupervisionGuard::enter();
        // SAFETY: fork in a multithreaded test binary
        // — the child only sleeps (the shared wedge
        // body) then _exits (never returns into the
        // harness).
        let pid = unsafe { libc::fork() };
        assert!(pid >= 0, "staging broken (fork failed)");
        if pid == 0 {
            wedge_sleeper_body(());
        }
        let out = catch_unwind(AssertUnwindSafe(|| {
            supervise_own_child(pid, 1, "pinless expiry probe")
        }));
        match out {
            Ok(outcome) => {
                panic!("pinless supervisor must panic on a 30s sleeper, got {outcome:?}")
            }
            Err(payload) => {
                let msg = payload
                    .downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| payload.downcast_ref::<&str>().copied())
                    .unwrap_or("<non-string panic>");
                assert!(
                    msg.contains("wedged"),
                    "expiry panic must say wedged, got: {msg}"
                );
                if msg.contains("Stolen") {
                    // Fail-closed (NOT a skip):
                    // supervise_own_child holds the
                    // exclusion guard across the
                    // supervise span (XRV1-L116
                    // belt+suspenders) + the victim is
                    // a live sleeper from fork to
                    // supervise (unsweepable) ⟹ Stolen
                    // is IMPOSSIBLE here — a Stolen
                    // drain means the corpse never
                    // presented (a skip would let a
                    // Reaped→Stolen drain mutant
                    // survive).
                    panic!("pinless-expiry drain saw Stolen over OUR kill under exclusion (mutant-suspect)");
                }
                assert!(
                    msg.contains("Reaped"),
                    "expiry panic must carry the drain verdict, got: {msg}"
                );
            }
        }
    }

    /// XRV1-L38/L53 collateral (qualifier lands):
    /// on a capable host (Supported probe verdict
    /// — the gate) the SIGKILL qualifier reports
    /// None (the pidfd kill LANDED on the held
    /// throwaway — death-proven through the pin).
    /// Pins the qualifier end-to-end (a broken
    /// staging — bad exec path, skipped hold,
    /// unconsumed pin — reports Some ⟹ RED).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn sigkill_qualifier_kill_lands_on_capable_host() {
        // Gate on the 4-leg pre-check (NOT the full
        // probe — the probe's kill leg IS this
        // test's subject; gating on it would skip
        // exactly when the qualifier breaks).
        let (open, consume, peek, signal) = waitid_pidfd_probe_precheck();
        match waitid_probe_classify(open, consume, peek, signal, None) {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) pre-check {verdict:?} (kill-land untestable)");
                return;
            }
        }
        // XRV1-L69: kill-POWER gate through the
        // INDEPENDENT canary (own birth, own text,
        // own kill leg — NOT the probe's kill leg,
        // which is this test's subject). A filter
        // allowing signal-0 but denying pidfd
        // SIGKILL passes the 4-leg pre-check — only
        // the canary's own kill proves the host can
        // do what this test asserts (canary-false ⟹
        // skip, never a failure on legitimate
        // confinement; canary-true + qualifier-Some
        // ⟹ the qualifier broke ⟹ RED).
        if !canary_once() {
            eprintln!("skip: no pidfd kill power (canary — kill-land untestable)");
            return;
        }
        assert_eq!(
            waitid_pidfd_sigkill_qualify_errno(),
            None,
            "qualifier must land its kill on a capable host"
        );
    }

    /// XRV1-L35/L38 collateral: under SIGKILL-denying
    /// confinement the probe AND the held canary BOTH
    /// read false (agreement on denial — the canary's
    /// inline SIGKILL leg EPERMs exactly like the
    /// probe's throwaway leg). Pins the canary's kill
    /// leg end-to-end (a canary that ignored its kill
    /// errno would read true here while the probe
    /// reads false ⟹ RED — mutant-checked).
    /// Thread-confined (sigkill-deny filter, same
    /// shape as the probe's filter worker); filter
    /// refused ⟹ loud skip.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn probe_and_canary_agree_false_when_pidfd_sigkill_denied() {
        enum Outcome {
            AgreeFalse,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    if !install_pidfd_sigkill_deny_filter() {
                        return Outcome::FilterRefused;
                    }
                    // The SAME canary text as the live
                    // agreement test (module-level —
                    // no forked copy).
                    assert_eq!(
                        waitid_pidfd_probe(),
                        ProbeVerdict::Unsupported,
                        "staging broken (probe must read Unsupported under sigkill-deny)"
                    );
                    assert!(
                        !canary_once(),
                        "canary must read false under sigkill-deny (kill power denied)"
                    );
                    Outcome::AgreeFalse
                })
                .join()
        });
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::AgreeFalse => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (canary-deny worker)");
            }
        }
    }

    /// XRV1-L69: install the pidfd-SIGKILL-deny
    /// filter on the CALLING thread (no TSYNC —
    /// confined to this worker; spawned children
    /// inherit): pidfd_send_signal with a nonzero
    /// signal ⟹ EPERM, signal-0 and every other
    /// syscall ⟹ allow (the L69 shape — a 4-leg
    /// gate passes here while kill power is
    /// denied). Shared by the probe/canary
    /// agreement test and the qualifier-gate test
    /// (one text — no forked filter copy to
    /// drift). False ⟹ install refused (loud skip
    /// at the caller, never a false verdict).
    #[cfg(target_arch = "x86_64")]
    fn install_pidfd_sigkill_deny_filter() -> bool {
        #[repr(C)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        const PIDFD_SEND_SIGNAL: u32 = 424;
        // Load syscall nr; if pidfd_send_signal
        // load args[1] (the signal); nonzero ⟹
        // EPERM, else (and every other syscall) ⟹
        // allow.
        let filter = [
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x15,
                jt: 0,
                jf: 3,
                k: PIDFD_SEND_SIGNAL,
            },
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 24,
            },
            SockFilter {
                code: 0x15,
                jt: 1,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x00050000 | 1,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x7fff0000,
            },
        ];
        // SAFETY: calling-thread-only seccomp
        // install (no TSYNC via prctl — the filter
        // confines this worker alone).
        unsafe {
            libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) == 0
                && libc::prctl(
                    libc::PR_SET_SECCOMP,
                    libc::SECCOMP_MODE_FILTER,
                    &SockFprog {
                        len: 6,
                        filter: filter.as_ptr(),
                    },
                    0,
                ) == 0
        }
    }

    /// XRV1-L85 collateral: numeric-kill deny filter
    /// (the kill-denied host shape — the generic
    /// deny-one installer, thread-confined (no TSYNC —
    /// sibling tests keep their kill)). Workers assert
    /// the denial is live before any verdict may skip.
    #[cfg(target_arch = "x86_64")]
    fn install_numeric_kill_deny_filter() -> bool {
        use super::super::seccomp::{install_deny_one, DenyAction};
        install_deny_one(libc::SYS_kill, DenyAction::Eperm).is_ok()
    }

    /// XRV1-L74 collateral: pidfd-open deny filter
    /// (the no-pidfd host shape — the generic
    /// deny-one installer, thread-confined).
    #[cfg(target_arch = "x86_64")]
    fn install_pidfd_open_deny_filter() -> bool {
        use super::super::seccomp::{install_deny_one, DenyAction};
        install_deny_one(libc::SYS_pidfd_open, DenyAction::Eperm).is_ok()
    }

    /// XRV1-L84 collateral: pidfd-send success-noop
    /// filter (SECCOMP_RET_ERRNO with errno 0 — the
    /// syscall RETURNS SUCCESS without delivering —
    /// the L84 shape; thread-confined (no TSYNC)).
    /// Hand-rolled (no zero-errno DenyAction — the
    /// 4-insn shape mirrors the L41 installer).
    #[cfg(target_arch = "x86_64")]
    fn install_pidfd_send_noop_filter() -> bool {
        #[repr(C)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        const PIDFD_SEND_SIGNAL: u32 = 424;
        // nr == 424 ⟹ RET_ERRNO|0 (success-noop);
        // every other syscall ⟹ ALLOW.
        let filter = [
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x15,
                jt: 0,
                jf: 1,
                k: PIDFD_SEND_SIGNAL,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x00050000 | 0,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x7fff0000,
            },
        ];
        // SAFETY: calling-thread-only seccomp install
        // (no TSYNC via prctl — the filter confines
        // this worker alone).
        unsafe {
            if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0 {
                return false;
            }
            libc::prctl(
                libc::PR_SET_SECCOMP,
                libc::SECCOMP_MODE_FILTER,
                &SockFprog {
                    len: 4,
                    filter: filter.as_ptr(),
                },
                0,
            ) == 0
        }
    }

    /// XRV1-L103: isolated-subreaper orphan probe,
    /// child side (fresh image — never returns):
    /// mode from SCOPEBASE_L103_MODE (child = clean
    /// run; plant = abandon one R-state decoy;
    /// skipprobe = emit L103-SKIP immediately).
    /// Marks itself subreaper (adoptees MUST land
    /// here), installs the noop filter, runs the
    /// qualifier (the verdict MUST be EAGAIN — the
    /// expiry path ran, never a vacuous CLEAN),
    /// then scans ONLY its own children (the middle
    /// is already reaped by the qualifier — every
    /// remainder IS qualifier-attributable by
    /// isolation — no T/exe/ppid predicates).
    /// T-state is a diagnostic note in the message,
    /// never a predicate. Any found are retired
    /// through retained sole-waiter authority (OUR
    /// children — kill + bounded reap — no litter
    /// even when RED) and reported (ORPHAN-FOUND
    /// with found/retired counts) before _exit(1);
    /// empty ⟹ CLEAN + _exit(0).
    #[cfg(target_arch = "x86_64")]
    fn l103_subreaper_probe_child() -> ! {
        let mode = std::env::var("SCOPEBASE_L103_MODE").unwrap_or_default();
        if mode == "skipprobe" {
            eprintln!("L103-SKIP (forced unavailable probe)");
            unsafe {
                libc::_exit(0);
            }
        }
        // Subreaper FIRST (adoptees must land here —
        // the nearest subreaper ancestor adopts).
        // SAFETY: prctl set-only.
        if unsafe { libc::prctl(libc::PR_SET_CHILD_SUBREAPER, 1, 0, 0, 0) } != 0 {
            eprintln!("L103-SKIP (subreaper unavailable in probe child)");
            unsafe {
                libc::_exit(0);
            }
        }
        if !install_pidfd_send_noop_filter() {
            eprintln!("L103-SKIP (seccomp unavailable in probe child)");
            unsafe {
                libc::_exit(0);
            }
        }
        if mode == "plant" {
            // R-state decoy (a RUNNING sleeper —
            // duration repo-wide unique — the old
            // T-gated sweep would MISS it; the
            // isolation scan must find it). The
            // handle drops unreaped on purpose
            // (abandoned by design).
            let _plant = std::process::Command::new("/bin/sleep")
                .arg("174")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("L103 plant spawns");
        }
        // The expiry path MUST run (EAGAIN — a None
        // verdict is a filter miss ⟹ loud, never a
        // vacuous CLEAN).
        assert_eq!(
            waitid_pidfd_sigkill_qualify_errno(),
            Some(libc::EAGAIN),
            "L103: noop filter missed (kill really landed?)"
        );
        // Adopt-scan: OUR children only (middle
        // already reaped — every remainder is
        // qualifier-attributable by isolation).
        let found = live_own_children();
        if found.is_empty() {
            eprintln!("L103-CHILD-DONE clean");
            unsafe {
                libc::_exit(0);
            }
        }
        // Retire each through retained sole-waiter
        // authority (no litter even when RED).
        let mut retired = 0;
        for (opid, ostate) in &found {
            // SAFETY: SIGKILL to our own child
            // (same uid — lands even on stopped).
            unsafe {
                libc::kill(*opid, libc::SIGKILL);
            }
            let dend = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                let mut st = 0;
                // SAFETY: WNOHANG reap of our own
                // child (sole waiter in this image —
                // no sibling sweepers exist here).
                let got = unsafe { libc::waitpid(*opid, &mut st, libc::WNOHANG) };
                if got == *opid || got < 0 {
                    retired += 1;
                    break;
                }
                if std::time::Instant::now() >= dend {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            eprintln!("L103 note: retired adoptee {opid} (state {ostate})");
        }
        let pids: Vec<libc::pid_t> = found.iter().map(|(pid, _)| *pid).collect();
        eprintln!(
            "L103-ORPHAN-FOUND found={} retired={} pids={pids:?}",
            found.len(),
            retired
        );
        unsafe {
            libc::_exit(1);
        }
    }

    /// XRV1-L84/L103 collateral (noop-proof retirement):
    /// under a success-noop pidfd-SIGKILL filter (the
    /// syscall returns Ok WITHOUT delivering —
    /// SECCOMP_RET_ERRNO with errno 0) the qualifier's
    /// throwaway never dies by the pin — the consume
    /// loop MUST still retire it (sole-owner numeric
    /// fallback) instead of abandoning an orphan.
    /// Isolated-subreaper probe (L103 — the old
    /// in-process /proc sweep with T/exe/ppid
    /// predicates is deleted: those predicates
    /// cannot identify OUR births): the fresh-image
    /// child marks itself subreaper, installs the
    /// noop filter, runs the qualifier (the verdict
    /// MUST be Some(EAGAIN) — the expiry path ran),
    /// then scans ONLY its own children (every
    /// adoptee here IS qualifier-attributable by
    /// isolation — no predicates). Any found are
    /// retired through retained sole-waiter
    /// authority (no litter even when RED) and fail
    /// with their pids. Filter/subreaper refused ⟹
    /// loud skip. A mutant dropping the fallback
    /// orphans ⟹ RED (mutant-checked).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn qualifier_noop_send_still_retires_throwaway() {
        if std::env::var("SCOPEBASE_L103_MODE").as_deref() == Ok("child") {
            l103_subreaper_probe_child();
        }
        let exe = std::env::current_exe().expect("own test binary");
        let mut out = std::process::Command::new(exe);
        out.arg("--exact")
            .arg("fixture::linux::audit::tests::qualifier_noop_send_still_retires_throwaway")
            .arg("--nocapture")
            .env("SCOPEBASE_L103_MODE", "child")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // L144: pre-exec IGN (a group-HUP
        // mid-startup murders default probes).
        arm_hup_immune_spawn(&mut out);
        let out = out.output().expect("probe child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        if stderr.contains("L103-SKIP") {
            eprintln!("skip: subreaper/seccomp unavailable for the L103 probe");
            return;
        }
        assert!(
            out.status.success(),
            "L103: probe child must exit 0 (no orphans)\n{stderr}"
        );
        assert!(
            stderr.contains("L103-CHILD-DONE clean"),
            "L103: completion marker missing\n{stderr}"
        );
    }

    /// XRV1-L103 collateral: the isolation scan
