    /// XRV1-L74/L94 collateral (middle-pin denial):
    /// under pidfd-open denial the qualifier still
    /// reports its kill-leg verdict (Some(EPERM) —
    /// the STOPPED middle retires un-CONTed and the
    /// errno reports preserved (no hang, no EIO
    /// masking, no numeric wait on a live middle —
    /// the old blocking fallback could hang on /
    /// consume a recycled replacement)). Pins the
    /// denial arm (a mutant returning EIO on pin-open
    /// failure REDs here — mutant-checked).
    /// Thread-confined deny worker; filter refused ⟹
    /// loud skip.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn qualifier_middle_reports_errno_when_pin_denied() {
        enum Outcome {
            DeniedVerdict,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    if !install_pidfd_open_deny_filter() {
                        return Outcome::FilterRefused;
                    }
                    // Denial LIVE (filter-miss guard — a
                    // pidfd_open of self must EPERM before
                    // the verdict below is meaningful).
                    match super::super::seccomp::pidfd_open_raw(
                        std::process::id() as libc::pid_t
                    ) {
                        Err(errno) => assert_eq!(
                            errno,
                            libc::EPERM,
                            "staging broken (pidfd_open must EPERM under open-deny)"
                        ),
                        Ok(fd) => {
                            // SAFETY: fd owned here.
                            unsafe { libc::close(fd) };
                            panic!("staging broken (pidfd_open succeeded under open-deny)");
                        }
                    }
                    assert_eq!(
                        waitid_pidfd_sigkill_qualify_errno(),
                        Some(libc::EPERM),
                        "qualifier must report the denial verdict (retired stopped, errno preserved)"
                    );
                    Outcome::DeniedVerdict
                })
                .join()
        });
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::DeniedVerdict => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (middle-fallback worker)");
            }
        }
    }

    /// XRV1-L118: numeric-retire verdict
    /// (child-side 3-state — the helper _exits the
    /// code).
    #[cfg(target_arch = "x86_64")]
    enum NumericQualify {
        /// OUR kill landed AND the corpse died by
        /// SIGKILL (exit 0).
        Power,
        /// Unproven (kill refused / corpse other /
        /// wedged / fork failed (exit 1)).
        Unproven,
        /// ECHILD inside a sole waiter (IMPOSSIBLE —
        /// nobody else can reap — model violation
        /// (exit 3 — the parent reports LOUD)).
        SoleViolated,
    }

    /// XRV1-L112/L118: the numeric-retire work —
    /// SOLE-WAITER-ONLY (runs ONLY in the isolated
    /// fork-child (no threads — the sacrificial is
    /// the only child — numeric wait SOUND);
    /// in-suite callers REINTRODUCE L118 (shared
    /// theft + replacement — use
    /// `qualify_numeric_retire` (the isolated
    /// wrapper)). Bare-fork a sacrificial (the REAL
    /// shared throwaway body — never a copy),
    /// IMMEDIATELY kill it numerically (unreaped ⟹
    /// ours — no window), and reap it bounded.
    /// Power ⟺ OUR kill landed (rc 0) AND the
    /// corpse died by SIGKILL. Under kill-deny the
    /// kill EPERMs and the body _exit(99)s (its
    /// self-stop is denied too) ⟹ Unproven in ms
    /// (no alarm wait — the 3s alarm is the
    /// backstop only). ECHILD ⟹ SoleViolated (no
    /// retry — a sole waiter is never stolen).
    /// Numeric-only (no pidfd — pidfd-denied hosts
    /// may still retire numerically).
    #[cfg(target_arch = "x86_64")]
    fn qualify_numeric_retire_sole_waiter() -> NumericQualify {
        // SAFETY: fork (the child runs the shared
        // throwaway body — never returns into the
        // harness).
        let kid = unsafe { libc::fork() };
        if kid < 0 {
            return NumericQualify::Unproven;
        }
        if kid == 0 {
            qualifier_throwaway_body();
        }
        // SAFETY: SIGKILL to our own unreaped
        // sacrificial (ours — just forked; sole
        // waiter — the only child).
        let landed = unsafe { libc::kill(kid, libc::SIGKILL) } == 0;
        // XRV1-L118 theft-window hook (child-side
        // (single-threaded — no lock risk);
        // fresh-image pin ONLY — the suite never
        // sets it): widen the kill→first-poll gap
        // to 1000ms so the pin's poll-steal lands
        // deterministically (200ms margins both
        // sides — see the pin).
        if std::env::var("SCOPEBASE_QUALIFY_WIDEN_THEFT_WINDOW").is_ok() {
            std::thread::sleep(std::time::Duration::from_millis(1000));
        }
        let dend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        let mut reaped: Option<libc::c_int> = None;
        loop {
            let mut status = 0;
            // SAFETY: WNOHANG reap of our own
            // sacrificial (sole waiter — the only
            // child reaps here).
            let got = unsafe { libc::waitpid(kid, &mut status, libc::WNOHANG) };
            if got == kid {
                reaped = Some(status);
                break;
            }
            if got < 0 {
                // SAFETY: errno (this thread).
                let errno = unsafe { libc::__errno_location().read() };
                if errno == libc::ECHILD {
                    // Sole-waiter inconsistency (no
                    // prior reap exists — nobody else
                    // can reap) ⟹ model violation
                    // (exit 3 — the parent reports
                    // LOUD).
                    return NumericQualify::SoleViolated;
                }
                if errno != libc::EINTR {
                    // Any other wait error ⟹
                    // unverifiable ⟹ Unproven (never
                    // a power claim — the L104 rule).
                    return NumericQualify::Unproven;
                }
                // EINTR ⟹ repoll (falls to the
                // deadline check — L105: the bound
                // holds every iteration).
            }
            if std::time::Instant::now() >= dend {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        match reaped {
            Some(status) => {
                if landed && libc::WIFSIGNALED(status) && libc::WTERMSIG(status) == libc::SIGKILL {
                    NumericQualify::Power
                } else {
                    NumericQualify::Unproven
                }
            }
            // Wedged past 5s (the 3s alarm backstop
            // died unreaped ⟹ D-state — unkillable,
            // nothing retires it) ⟹ unproven.
            None => NumericQualify::Unproven,
        }
    }

    /// XRV1-L118: the isolated qualifier's helper
    /// body (runs the sole-waiter work + _exits its
    /// code — 0/1/3 — never returns into the
    /// harness; silent (no locks post-fork — the
    /// parent reports exit 3 LOUD)).
    #[cfg(target_arch = "x86_64")]
    fn qualify_numeric_retire_body() -> ! {
        let code = match qualify_numeric_retire_sole_waiter() {
            NumericQualify::Power => 0,
            NumericQualify::Unproven => 1,
            NumericQualify::SoleViolated => 3,
        };
        unsafe {
            libc::_exit(code);
        }
    }

    /// XRV1-L118: the numeric-retire qualifier (the
    /// positive test's skip gate — the L96 probe's
    /// isolation shape: fork-and-pin a sole-waiter
    /// helper under exclusion (XRV1-L117 — the
    /// shared text (bare fork (NOT held spawn —
    /// the self-stop kill is denied under
    /// kill-deny filters, which would
    /// T-await-expire into a panic instead of the
    /// required false) + guard-authenticated pin))
    /// + pin-supervised consume (10s — the
    /// helper's 5s worst + margin). True ⟺ the
    /// helper _exit(0) (power proven inside
    /// isolation — no shared-process numeric wait
    /// anywhere on this path). Stolen/unverifiable/
    /// expired/pin-denied ⟹ false (unproven — a
    /// qualifier never fails loud — false skips
    /// upstream). Exit 3 (sole-waiter violated —
    /// impossible) reports LOUD + false.
    #[cfg(target_arch = "x86_64")]
    fn qualify_numeric_retire() -> bool {
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::process::ExitStatusExt as _;
        use std::panic::{catch_unwind, AssertUnwindSafe};
        // Qualifier child + pin under exclusion
        // (XRV1-L117 — the shared fork-and-pin
        // text (no hand-rolled window)).
        let helper_pin = match fork_and_pin_helper_child(qualify_numeric_retire_body) {
            // Cannot stage / pinless ⟹ unprovable
            // ⟹ false (the helper is already
            // retired on the Pinless leg).
            ForkPinOutcome::ForkFailed | ForkPinOutcome::Pinless(_) => return false,
            ForkPinOutcome::Pinned(pin) => pin,
        };
        // Birth-held supervision (the parent↔helper
        // boundary HAS foreign sweepers — the pin is
        // load-bearing here, unlike inside the
        // helper). The helper is bounded (~6s worst:
        // 5s drain + 1s theft-hook (pin-only)).
        let out = catch_unwind(AssertUnwindSafe(|| {
            supervise_pinned_birth(helper_pin.as_raw_fd(), 10, "numeric-retire qualifier")
        }));
        match out {
            Ok(SuperviseOutcome::Reaped(st)) => {
                match std::process::ExitStatus::from_raw(st).code() {
                    Some(0) => true,
                    // Sole-waiter violated (IMPOSSIBLE
                    // — nobody else can reap inside
                    // the helper) ⟹ LOUD + false.
                    Some(3) => {
                        eprintln!(
                            "qualifier: sole-waiter violated (helper ECHILD — model violation — false)"
                        );
                        false
                    }
                    _ => false,
                }
            }
            // Stolen (a foreign sweep reaped OUR
            // helper — unprovable), Unverifiable
            // (wait channel failed), expiry panic
            // (helper wedged): power UNPROVEN ⟹
            // false (a qualifier never fails loud —
            // false skips upstream).
            _ => false,
        }
    }

    /// XRV1-L112 collateral (qualifier denial leg):
    /// under numeric-kill denial the retire
    /// qualifier reads false (the positive test's
    /// skip gate — a qualifier that claimed power
    /// without its kill landing would read true
    /// here ⟹ RED). Thread-confined deny worker;
    /// filter refused ⟹ loud skip.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_probe_positive_skips_when_kill_denied() {
        enum Outcome {
            DeniedFalse,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    if !install_numeric_kill_deny_filter() {
                        return Outcome::FilterRefused;
                    }
                    assert!(
                        !qualify_numeric_retire(),
                        "qualifier must read false under kill-deny (no retire power)"
                    );
                    Outcome::DeniedFalse
                })
                .join()
        });
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::DeniedFalse => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (qualifier worker)");
            }
        }
    }

