    /// XRV1-L85 collateral (retire-power gate): the
    /// wedge test skips under numeric-kill denial (it
    /// must NEVER stage its 30s kill-or-nothing wedge
    /// where no kill can retire it). Thread-confined
    /// deny worker (same shape as the qualifier-gate
    /// test): the worker proves the denial is live (a
    /// signal-0 kill of self EPERMs — a filter miss
    /// fails loud here, never a vacuous skip), then
    /// runs the REAL wedge body and requires the
    /// RETIRE skip (the retire gate is the body's
    /// FIRST gate — but the waitid gate is a backstop
    /// that ALSO skips under kill-deny (the
    /// qualifier's self-stop needs kill), so a bare
    /// "body returned" assert is vacuous — only the
    /// outcome discriminates: a gate mutant skips via
    /// waitid instead ⟹ RED — mutant-checked).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn wedge_gate_skips_when_numeric_kill_denied() {
        enum Outcome {
            Skipped,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    if !install_numeric_kill_deny_filter() {
                        return Outcome::FilterRefused;
                    }
                    // Denial LIVE (filter-miss guard).
                    // SAFETY: signal-0 self-kill (no
                    // effect — errno only).
                    let (rc, errno) = unsafe {
                        let rc = libc::kill(libc::getpid(), 0);
                        let errno =
                            std::io::Error::last_os_error().raw_os_error();
                        (rc, errno)
                    };
                    assert!(
                        rc != 0 && errno == Some(libc::EPERM),
                        "staging broken (numeric kill must EPERM under kill-deny)"
                    );
                    // The REAL body (must SKIP via its
                    // RETIRE gate — a waitid skip here
                    // is a gate mutant RED; staging
                    // under denial REDs inside).
                    match fork_supervisor_wedge_inner() {
                        WedgeOutcome::RetireSkipped => Outcome::Skipped,
                        WedgeOutcome::WaitidSkipped => {
                            panic!("gate mutant? body skipped via waitid backstop (retire gate missed)")
                        }
                        WedgeOutcome::Proven => {
                            panic!("unreachable (staging under deny REDs in the pin-proof)")
                        }
                    }
                })
                .join()
        });
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::Skipped => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (wedge-gate worker)");
            }
        }
    }

