    /// XRV1-L2 collateral: the stopped-sleep shape (every
    /// L2 sleeper conversion relies on it) — `exec sleep
    /// N` under self-stop yields a birth whose argv is
    /// exactly [sleep, N] and whose tick survives the
    /// stop→CONT→exec path (the tick read while held
    /// equals the tick read while running — the pin
    /// taken during the stop names the sleep birth).
    /// Also pins the `_held` handshake (T while held,
    /// running after CONT). No capability gate (shape
    /// only — asserts never touch the pin — but
    /// custody still splits FIRST (XRV1-L39: under
    /// Unsupported a cmdline panic past the CONT must
    /// not strand the running birth with only an inert
    /// Unpinned guard)).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn stopped_sleep_spawn_reports_running_sleep() {
        let (child_spawn, mut _guard) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        // XRV1-L37/L39: split FIRST
        // (owner-holds-STOPPED, run=false — custody
        // before ANY assert; the manual CONT below
        // runs owner-armed on both arms).
        let custody = split_staging_custody(child_spawn, &_guard, false);
        let pid = custody.pid();
        assert_eq!(proc_state(pid), Some('T'), "held ⟹ stopped");
        let held_tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        cont_held_birth(pid);
        // Settle EXEC'D (argv is the exec-proof — a
        // running state alone still shows pre-exec sh:
        // settle on the cmdline flipping to the sleep).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let argv: Vec<String> = loop {
            let cmdline = std::fs::read(format!("/proc/{pid}/cmdline")).expect("cmdline readable");
            let argv: Vec<String> = cmdline
                .split(|b| *b == 0)
                .filter(|piece| !piece.is_empty())
                .map(|piece| std::str::from_utf8(piece).expect("argv utf8").to_string())
                .collect();
            if argv == ["sleep", "30"] {
                break argv;
            }
            assert!(
                std::time::Instant::now() < end,
                "sleep must exec after CONT (still {argv:?})"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        let run_tick: u64 = proc_starttime(pid)
            .expect("running stat readable")
            .expect("running birth visible");
        assert_eq!(
            held_tick, run_tick,
            "tick survives stop→CONT→exec (else the held pin misnames)"
        );
        assert_eq!(argv, vec!["sleep", "30"], "post-exec argv is a plain sleep");
        // Strict retire through the split custody
        // (same kill+wait discipline on both arms).
        custody.retire();
        _guard.disarm();
        // The CONTaining variant releases before return
        // (settle exec'd — same argv proof).
        let (child2_spawn, mut _guard2) = spawn_stopped_sh_with_guard("exec sleep 31");
        // XRV1-L24: split (Unpinned ⟹ cont + owner).
        let child2 = split_staging_custody(child2_spawn, &_guard2, true);
        let pid2 = child2.pid();
        let end2 = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let cmdline2 =
                std::fs::read(format!("/proc/{pid2}/cmdline")).expect("cmdline2 readable");
            if cmdline2.starts_with(b"sleep\x0031\x00") {
                break;
            }
            assert!(
                std::time::Instant::now() < end2,
                "plain variant must run to exec"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        child2.retire();
        _guard2.disarm();
    }

    /// XRV1-L21 collateral: discharge retires a
    /// stopped spawn WITHOUT running its body (kill
    /// lands while stopped) and reaps it. Proof: the
    /// body touches a flag iff it ever runs — no flag
    /// + reaped pins the realistic regression (any
    /// CONT-with-a-gap shape runs the body ⟹ RED).
    /// The µs-gap CONT-then-instant-kill shape is
    /// benign-in-practice (the kill lands pre-schedule)
    /// but unsound-in-model — the kill-FIRST ordering
    /// itself is reviewer-verified in
    /// `discharge_held_child`, not lottery-pinned here.
    /// XRV1-L30/L34: the reap is consumed through the
    /// birth-bound pin (proven by an independently
    /// retained pin — L44 — the stale Child handle
    /// drops silently, never waited). Gated (L51 —
    /// the fallback path is covered by the
    /// kill-only deny-worker test).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn discharge_kills_before_cont_body_never_runs() {
        use std::time::{Duration, Instant};
        // XRV1-L51: the proof IS a pin-proof —
        // gate BEFORE staging (zero cleanup on
        // skip).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-proof untestable)");
                return;
            }
        }
        let flag =
            std::env::temp_dir().join(format!("scopebase-l21-discharge-{}", std::process::id()));
        let _ = std::fs::remove_file(&flag);
        let mut child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv(&format!(
                "touch {}; exit 42",
                flag.display()
            )))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (stopped spawn)");
        let pid = child.id() as libc::pid_t;
        // Unwind custody (staging panics must not leak
        // a stopped birth).
        let mut _sguard = FixtureGuard::new(pid);
        // T-await (bounded — staging must present
        // stopped before discharge).
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            assert!(
                Instant::now() < end,
                "staging broken (stopped spawn never shows T)"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        // XRV1-L42: the staged tick is the
        // discharge authority (first read on our
        // own unreaped birth — the chain's link).
        let tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        // XRV1-L44: retain the INDEPENDENT pin
        // BEFORE the helper retires (a reaped
        // number ESRCHes — the pin must name OUR
        // birth).
        let pin = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (pin)");
        let _ = discharge_held_child(&mut child, pid, Some(tick));
        // XRV1-L124: read the pin-proof BEFORE
        // standing down (the proof CONFIRMS the
        // discharge — an unconditional disarm here
        // strands a live birth when the helper
        // failed to retire (the Child drops silent
        // below either way)).
        // SAFETY: own pidfd + zeroed siginfo + probe
        // flags (WNOHANG — never blocks).
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                pin as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            let errno = std::io::Error::last_os_error().raw_os_error();
            libc::close(pin);
            (ret, errno)
        };
        // XRV1-L80/L122: stand down ONLY on the
        // confirmed discharge (ECHILD ⟹ consumed;
        // anything else ⟹ authority RETAINED —
        // the assert below then fails loud and
        // unwind completes cleanup (a leak beats a
        // murder, but a retained guard beats a
        // leak)).
        drop(child);
        _sguard.disarm_if_discharged(proof == (-1, Some(libc::ECHILD)));
        // Pin-proof verdict (birth-bound — the
        // helper consumed through ITS pin; ours
        // observes ECHILD).
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "pin must prove OUR birth consumed (post-retire ECHILD)"
        );
        assert!(
            !flag.exists(),
            "discharged body must never run (kill-before-CONT violated?)"
        );
        let _ = std::fs::remove_file(&flag);
    }

    /// XRV1-L23 collateral (wrong-state-Z): a
    /// XRV1-L31/L34 collateral (wrong-state-Z): a
    /// `new` that observes a zombie (caller bug —
    /// never T-awaited) returns WrongState LOUD and
    /// touches NOTHING (no kill — a kill could land
    /// on a recycled live stranger; no wait —
    /// nothing dead to reap); the caller retires
    /// explicitly through the live handle, proves
    /// discharge through an independently retained
    /// pidfd ONLY (birth-bound — no post-retirement
    /// numeric wait at all (L44)), disarms the
    /// numeric guard immediately after retirement
    /// (L54), and drops the reaped handle silently
    /// (L34). Gated on both capabilities BEFORE
    /// staging (L51). Custody (tick-gated guard)
    /// arms at spawn, before the settle asserts
    /// (L37).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_wrong_state_zombie_reaps_without_kill() {
        // XRV1-L51: the verdict IS a pin-proof —
        // gate BEFORE staging (no pin without both
        // capabilities — zero cleanup on skip).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-proof untestable)");
                return;
            }
        }
        let mut child = std::process::Command::new("sh")
            .arg("-c")
            .arg("exit 3")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (fast spawn)");
        let pid = child.id() as libc::pid_t;
        // XRV1-L37: custody BEFORE fallible staging
        // (a settle panic must not abandon the
        // zombie — tick-gated: zombie ⟹ tick-bound
        // ⟹ the guard reaps ours, never a stranger).
        let mut _sguard = FixtureGuard::new(pid);
        // Settle zombie (dead, unreaped — ours).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('Z') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (never zombies)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // XRV1-L31: construction returns its errors
        // (no panic-before-custody — the caller owns
        // the handle and retires explicitly). A zombie
        // is wrong-state (never held).
        // XRV1-L45: bare discovery (no lock — the
        // immediate WrongState never reaches K3).
        let err = KillReapGuard::new(pid, None).expect_err("non-held birth must fail loud");
        assert!(
            matches!(err, ConstructError::WrongState { seen: Some('Z') }),
            "a zombie must read wrong-state-Z, got {err:?}"
        );
        // XRV1-L34: retain the INDEPENDENT pin
        // BEFORE retiring (a reaped number ESRCHes —
        // the pin must name OUR zombie).
        let pin = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (zombie pin)");
        // Explicit retire through the live handle (the
        // failed construction touched nothing — the
        // zombie is still ours, unreaped).
        child.wait().expect("owner reaps the zombie");
        // XRV1-L54: disarm IMMEDIATELY after the
        // confirmed retirement (before the proof
        // asserts below — a denied-waitid panic must
        // not leave the numeric guard armed over a
        // freed number).
        _sguard.disarm();
        // SAFETY: close our pidfd copy after the proof.
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                pin as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            let errno = std::io::Error::last_os_error().raw_os_error();
            libc::close(pin);
            (ret, errno)
        };
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "pin must prove OUR birth consumed (post-retire ECHILD)"
        );
        // XRV1-L44: NO post-retirement numeric wait
        // (the pin-proof above is the WHOLE proof —
        // a waitpid past retirement could consume a
        // recycled sibling's zombie).
        // XRV1-L34: the reaped handle drops SILENTLY
        // (no stale try_wait — a numeric wait past
        // retirement can steal a recycled sibling
        // zombie's status).
        drop(child);
    }

    /// XRV1-L23/L31 collateral (wrong-state-live):
    /// a `new` that observes a RUNNING birth returns
    /// WrongState LOUD and touches NOTHING (no kill —
    /// an observed-live number may be a recycled
    /// stranger; no wait — nothing dead to reap).
    /// Characterization (locks the no-touch
    /// decision).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_wrong_state_live_touches_nothing() {
        let mut child = std::process::Command::new("sh")
            .arg("-c")
            .arg("exec sleep 150")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (live spawn)");
        let pid = child.id() as libc::pid_t;
        let mut _sguard = FixtureGuard::new(pid);
        // Settle running (live — never stopped).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match proc_state(pid) {
                Some('R') | Some('S') => break,
                other => assert!(
                    std::time::Instant::now() < end,
                    "staging broken (never runs: {other:?})"
                ),
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // XRV1-L31: construction returns its errors
        // (a loud Err, never a panic-before-custody).
        // XRV1-L45: bare discovery (no lock — the
        // immediate WrongState never reaches K3).
        let err = KillReapGuard::new(pid, None).expect_err("non-held birth must fail loud");
        assert!(
            matches!(
                err,
                ConstructError::WrongState {
                    seen: Some('R') | Some('S')
                }
            ),
            "a running birth must read wrong-state-live, got {err:?}"
        );
        // Untouched: still our live birth (same tick,
        // still running).
        let tick = proc_starttime(pid)
            .expect("live stat readable")
            .expect("live visible");
        assert!(
            matches!(proc_state(pid), Some('R') | Some('S')),
            "live birth must survive the loud error (tick {tick})"
        );
        // XRV1-L124: confirm discharge BEFORE
        // standing down (an ignored wait-error
        // strands a live birth — freed ⟹ disarm;
        // else authority RETAINED (unwind
        // completes cleanup)).
        let _ = child.kill();
        let _ = child.wait();
        _sguard.disarm_if_discharged(proc_starttime(pid) == Ok(None));
    }

    /// XRV1-L31 collateral: a successful construction
    /// carries its FIRST sample with the guard (the
    /// retry loop locks this tick — never a post-new
    /// re-read, which can name a replacement after a
    /// sample→verify mismatch degrades to Unpinned).
    /// Either pin arm (Pinned/Unpinned) carries the
    /// held birth's tick. Custody (Child-handle
    /// owner) arms at spawn, before the T-await
    /// asserts (L37); exclusive cleanup transfer
    /// once Pinned (L61) + pin-proof (L44 — gated
    /// (L51), no numeric wait).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_carries_first_sample_with_guard() {
        // XRV1-L51: the proof IS a pin-proof —
        // gate BEFORE staging (zero cleanup on
        // skip).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-proof untestable)");
                return;
            }
        }
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 155"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        // XRV1-L37: custody BEFORE fallible staging.
        let owner = UnpinnedStagingOwner::new(child);
        let pid = owner.pid();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (never stops)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        // XRV1-L45: carry the staged tick as the
        // lock (sighted-live above — the chain's
        // first link).
        let constructed = KillReapGuard::new(pid, Some(tick)).expect("held birth must construct");
        // XRV1-L61/L77: exclusive cleanup (shared
        // transfer — the owner stands down under
        // Pinned authority or proven Discharged; a
        // pin-open/proof panic below meets ONE
        // owner).
        let owner = exclusive_transfer_owner(owner, &constructed.guard.pin);
        assert_eq!(
            constructed.sampled,
            Some(tick),
            "construction must carry its first sample (retry-lock identity)"
        );
        // XRV1-L44: retain the INDEPENDENT pin
        // BEFORE retiring (a reaped number ESRCHes —
        // the pin must name OUR birth).
        let pin = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (pin)");
        // Exclusive retire (Pinned: the guard
        // retires through its pin; Unpinned/
        // Discharged: the retained owner retires
        // strictly) — the pin-proof below verifies
        // it (a failed retire fails loud there).
        match owner {
            None => drop(constructed),
            Some(o) => {
                o.retire();
                drop(constructed);
            }
        }
        // Pin-proof ONLY (birth-bound — no numeric
        // wait past retirement).
        // SAFETY: own pidfd + zeroed siginfo + probe
        // flags (WNOHANG — never blocks).
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                pin as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            let errno = std::io::Error::last_os_error().raw_os_error();
            libc::close(pin);
            (ret, errno)
        };
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "pin must prove OUR birth consumed (post-retire ECHILD)"
        );
    }

    /// XRV1-L45 collateral (one immutable identity):
    /// a construction whose locked identity does not
    /// match the live sample fails Changed LOUD and
    /// pins NOTHING (no fresh-sample stranger —
    /// the K3 gate compares BEFORE the open).
    /// Custody (Child-handle owner) arms at spawn,
    /// before the T-await asserts (L37).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_rejects_sample_mismatching_locked_identity() {
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 160"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        // XRV1-L37: custody BEFORE fallible staging.
        let owner = UnpinnedStagingOwner::new(child);
        let pid = owner.pid();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (never stops)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        // A lock naming any OTHER birth (fabricated
        // successor — never the live sample) must
        // fail Changed, never pin the stranger.
        let err = KillReapGuard::new(pid, Some(tick.wrapping_add(1)))
            .expect_err("mismatched lock must fail loud");
        assert!(
            matches!(
                err,
                ConstructError::Changed { expected, got: Some(seen) }
                    if expected == tick.wrapping_add(1) && seen == tick
            ),
            "a mismatched lock must read Changed with both ticks, got {err:?}"
        );
        owner.retire();
    }

    /// XRV1-L45 collateral (one immutable identity):
    /// a construction whose locked identity MATCHES
    /// the live sample proceeds (no false Changed —
    /// the gate compares equality, not mere
    /// presence). Custody (Child-handle owner) arms
    /// at spawn, before the T-await asserts (L37);
    /// exclusive cleanup transfer (L61/L77); the
    /// Pinned retire is pin-proven (L89 — gated
    /// (L51) — no numeric vacancy assert).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn construct_accepts_sample_matching_locked_identity() {
        // XRV1-L89/L51: the Pinned retire is
        // pin-proven — gate BEFORE staging (zero
        // cleanup on skip).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-proof untestable)");
                return;
            }
        }
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 161"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        // XRV1-L37: custody BEFORE fallible staging.
        let owner = UnpinnedStagingOwner::new(child);
        let pid = owner.pid();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (never stops)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        let constructed =
            KillReapGuard::new(pid, Some(tick)).expect("matching lock must construct");
        // XRV1-L61/L77: exclusive cleanup (shared
        // transfer — the owner stands down under
        // Pinned authority or proven Discharged).
        let pinned = matches!(constructed.guard.pin, GuardPin::Pinned { .. });
        let owner = exclusive_transfer_owner(owner, &constructed.guard.pin);
        assert_eq!(
            constructed.sampled,
            Some(tick),
            "construction must carry its first sample"
        );
        // Exclusive retire (guard-drop is
        // loud-on-failure, not strict-panicking —
        // the Pinned path is pin-PROVEN below; the
        // Discharged path needs no proof (the
        // construction's open-ESRCH already proved
        // fully-reaped); Unpinned retires strictly
        // through the retained owner). XRV1-L89: NO
        // numeric vacancy assert anywhere (a
        // legitimate replacement breaks it —
        // R19003-FLAKE02).
        match owner {
            None if pinned => {
                // XRV1-L44: retain the INDEPENDENT
                // pin BEFORE retiring (a reaped
                // number ESRCHes — the pin must name
                // OUR birth).
                let pin = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (pin)");
                drop(constructed);
                // SAFETY: own pidfd + zeroed siginfo
                // + probe flags (WNOHANG — never
                // blocks).
                let proof = unsafe {
                    let mut info: libc::siginfo_t = std::mem::zeroed();
                    let ret = libc::waitid(
                        libc::P_PIDFD,
                        pin as libc::id_t,
                        &mut info,
                        libc::WEXITED | libc::WNOHANG,
                    );
                    let errno = std::io::Error::last_os_error().raw_os_error();
                    libc::close(pin);
                    (ret, errno)
                };
                assert_eq!(
                    proof,
                    (-1, Some(libc::ECHILD)),
                    "pin must prove OUR birth consumed (transferred cleanup retired)"
                );
            }
            None => {
                // Discharged: fully reaped already
                // (proven by the construction) —
                // silent drop, nothing to verify.
                drop(constructed);
            }
            Some(o) => {
                o.retire();
                drop(constructed);
            }
        }
    }

    /// XRV1-L61/L77: exclusive cleanup transfer —
    /// once Pinned authority exists the staging
    /// owner stands down NOW (consumed, silent Child
    /// drop — the guard retires through its pin; a
    /// later pin-open/proof panic meets ONE owner,
    /// never competing numeric-vs-pin cleanup over a
    /// freed number — a replacement could take those
    /// effects). XRV1-L77: Discharged (proven gone
    /// — pidfd-open ESRCHed, fully reaped) ALSO
    /// stands down (nothing of ours remains — a
    /// retained numeric owner would kill/retire
    /// against the freed number). ONLY unresolved
    /// Unpinned custody returns the owner ARMED (the
    /// guard drops silently — effectively one owner
    /// either way). Pinned by
    /// `exclusive_transfer_arms_owner_only_when_unpinned`.
    #[cfg(target_arch = "x86_64")]
    fn exclusive_transfer_owner(
        owner: UnpinnedStagingOwner,
        pin: &GuardPin,
    ) -> Option<UnpinnedStagingOwner> {
        match pin {
            GuardPin::Pinned { .. } | GuardPin::Discharged => {
                owner.disarm();
                None
            }
            GuardPin::Unpinned => Some(owner),
        }
    }

    /// XRV1-L107 collateral: Discharged transfer
    /// leg, factored (the real test + the denial
    /// test share it — one text): the owner is
    /// consumed (proven gone) and the staged birth
    /// retires explicitly through a fresh pin. An
    /// independent FixtureGuard spans the fallible
    /// pin-open + pin-retire (the transfer consumes
    /// `owner` — if the pin-open expect panics
    /// under selective denial, the guard drop still
    /// retires the T-stopped birth — never a
    /// stray); disarmed on confirmed discharge.
    #[cfg(target_arch = "x86_64")]
    fn transfer_discharged_leg() {
        // Discharged: the owner is consumed (proven
        // gone ⟹ nothing to retire — the live birth
        // here is staged only to exercise the
        // mapping; it retires explicitly through a
        // fresh pin below — live ⟹ unreaped ⟹ the
        // open is authoritative).
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 167"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        let owner = UnpinnedStagingOwner::new(child);
        let dpid = owner.pid();
        // XRV1-L107: independent retiring owner
        // across the fallible legs below (armed
        // BEFORE the transfer consumes `owner`).
        let mut lguard = FixtureGuard::new(dpid);
        match exclusive_transfer_owner(owner, &GuardPin::Discharged) {
            None => {}
            Some(o) => {
                // Cleanup-correct failure (retire,
                // THEN fail loud).
                o.retire();
                panic!("Discharged must consume the owner (proven gone)");
            }
        }
        // Pin-bound explicit retire (the Child went
        // with the disarm — kill + consume through
        // the pin, never numeric).
        let dfd = super::super::seccomp::pidfd_open_raw(dpid).expect("staging broken (pin)");
        use std::os::unix::io::{AsRawFd as _, FromRawFd as _};
        let downed = unsafe { std::os::unix::io::OwnedFd::from_raw_fd(dfd) };
        let draw = downed.as_raw_fd();
        match super::super::seccomp::pidfd_send_signal_raw(draw, libc::SIGKILL) {
            Ok(()) => {}
            Err(errno) if errno == libc::ESRCH => {}
            Err(errno) => panic!("staging broken (pin kill refused: {errno})"),
        }
        let dend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match probe_victim_pin(draw) {
                PinProbe::Reaped(_) | PinProbe::ReapedElsewhere => break,
                _ => {}
            }
            assert!(
                std::time::Instant::now() < dend,
                "staging broken (discharged-mapping birth never reaps)"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Confirmed discharge (consumed or observed
        // elsewhere — nothing lingers) ⟹ stand
        // down.
        lguard.disarm();
    }

    /// XRV1-L107 collateral: Pinned transfer leg,
    /// factored (shared like its twin): the owner
    /// is consumed (the guard owns retirement; the
    /// fabricated pin stands in for guard authority
    /// and retires the birth through ITSELF — never
    /// numeric (L79)). The independent FixtureGuard
    /// spans the pin-open + transfer + pin-retire
    /// (a pin-kill/drain panic post-transfer still
    /// tides through the drop); disarmed on
    /// confirmed discharge.
    #[cfg(target_arch = "x86_64")]
    fn transfer_pinned_leg() {
        use std::os::unix::io::FromRawFd as _;
        // Pinned: the owner is consumed (silent —
        // the guard owns retirement; the fabricated
        // pin below stands in for guard authority
        // and retires the birth through ITSELF —
        // never numeric (L79)).
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 168"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        let owner = UnpinnedStagingOwner::new(child);
        let pid = owner.pid();
        // XRV1-L107: independent retiring owner
        // (armed BEFORE the fallible pin-open —
        // covers the open expect AND the
        // post-transfer kill/drain panics).
        let mut lguard = FixtureGuard::new(pid);
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if proc_state(pid) == Some('T') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "staging broken (never stops)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let tick: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        let fd = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (pin)");
        // SAFETY: own pidfd (transferred into the pin token).
        let pin = GuardPin::Pinned {
            tick,
            pidfd: unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) },
        };
        match exclusive_transfer_owner(owner, &pin) {
            None => {}
            Some(o) => {
                // Cleanup-correct failure (no leak on
                // RED — retire, THEN fail loud).
                o.retire();
                panic!("Pinned must consume the owner");
            }
        }
        // Pin-bound retire through the HELD pin
        // (XRV1-L79 — the Child went with the
        // disarm; numeric kill/wait here could meet
        // a foreign discharge + recycled sibling).
        let GuardPin::Pinned { pidfd, .. } = &pin else {
            panic!("staging broken (pin token changed shape?)");
        };
        use std::os::unix::io::AsRawFd as _;
        let raw = pidfd.as_raw_fd();
        match super::super::seccomp::pidfd_send_signal_raw(raw, libc::SIGKILL) {
            Ok(()) => {}
            Err(errno) if errno == libc::ESRCH => {}
            Err(errno) => panic!("staging broken (pin kill refused: {errno})"),
        }
        let wend = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match probe_victim_pin(raw) {
                PinProbe::Reaped(_) | PinProbe::ReapedElsewhere => break,
                _ => {}
            }
            assert!(
                std::time::Instant::now() < wend,
                "staging broken (transferred birth never reaps)"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Confirmed discharge ⟹ stand down.
        lguard.disarm();
    }

    /// XRV1-L61/L77 collateral: the transfer
    /// returns the owner armed ONLY for unresolved
    /// Unpinned custody (Pinned ⟹ the guard owns
    /// retirement; Discharged ⟹ proven gone, nothing
    /// remains — a retained numeric owner would
    /// kill/retire against the freed number). Every
    /// arm pinned (mutant-checked both directions).
    /// XRV1-L79: consumed-owner legs retire through
    /// a HELD pin (never numeric kill/wait past the
    /// disarm — a foreign discharge between the
    /// calls could hand the loop a recycled
    /// sibling). XRV1-L86: the pin legs gate on
    /// capability BEFORE spawning (zero cleanup on
    /// skip). Durations repo-wide unique
    /// (166/167/168).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn exclusive_transfer_arms_owner_only_when_unpinned() {
        // Unpinned: the owner comes back armed
        // (strict retire proves it). No pin needed
        // (ungated — always runs).
        let child = std::process::Command::new("sh")
            .arg("-c")
            .arg(stopped_spawn_argv("exec sleep 166"))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("staging broken (held spawn)");
        let owner = UnpinnedStagingOwner::new(child);
        let back = exclusive_transfer_owner(owner, &GuardPin::Unpinned);
        assert!(back.is_some(), "Unpinned must keep the owner armed");
        back.expect("owner returned").retire();
        // XRV1-L86: the Discharged + Pinned legs
        // retire through pins — gate BEFORE staging
        // (nothing armed at this point — the
        // Unpinned leg above already retired).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-legs untestable)");
                return;
            }
        }
        // Discharged + Pinned legs (factored —
        // shared with the L107 denial tests; the
        // independent guard inside each tides any
        // fallible staging).
        transfer_discharged_leg();
        transfer_pinned_leg();
    }

    /// XRV1-L107/L103 collateral: enumerate live
    /// own children (fresh-image-safe /proc scan —
    /// ppid == our pid filter: attributable, never
    /// global; parallel suites cannot pollute it —
    /// their children carry different ppids).
    /// Returns every own child in ANY state (live,
    /// stopped, zombie) as (pid, state).
    #[cfg(target_arch = "x86_64")]
    fn live_own_children() -> Vec<(libc::pid_t, String)> {
        let me = std::process::id() as libc::pid_t;
        let mut found = Vec::new();
        let entries = std::fs::read_dir("/proc").expect("L107: /proc readable");
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let Ok(pid) = name.parse::<libc::pid_t>() else {
                continue;
            };
            if pid == me {
                continue;
            }
            let stat = match std::fs::read_to_string(format!("/proc/{pid}/stat")) {
                Ok(s) => s,
                Err(_) => continue,
            };
            // stat: pid (comm) state ppid ... — comm
            // may hold spaces/parens; the state
            // follows the LAST ')'.
            let Some(close) = stat.rfind(')') else {
                continue;
            };
            let mut fields = stat[close + 1..].split_whitespace();
            let state = fields.next().unwrap_or("?").to_string();
            let ppid: libc::pid_t = fields.next().and_then(|f| f.parse().ok()).unwrap_or(-1);
            if ppid == me {
                found.push((pid, state));
            }
        }
        found
    }

    /// XRV1-L107 collateral: assert zero live own
    /// children (any own child in ANY state fails
    /// loud with the enumerated evidence).
    #[cfg(target_arch = "x86_64")]
    fn assert_no_live_own_children(what: &str) {
        let strays = live_own_children();
        assert!(
            strays.is_empty(),
            "{what}: stray own children remain: {strays:?} (guard tide failed)"
        );
    }

