    /// XRV1-L97 collateral: stage a zombie under
    /// a pre-established pin (held-spawn an instant
    /// exiter: self-stop → the pin opens over T
    /// (birth-held from the stop — it CANNOT name
    /// a recycled replacement, no post-Z open
    /// exists) → CONT → exits → settle Z by
    /// OBSERVATION (procfs read — never a consuming
    /// probe, so the test helper below still has a
    /// corpse to consume). None ⟹ setup stolen
    /// (foreign sweep consumed the instant exiter,
    /// or spawn refused — caller skips loud, L82
    /// shape).
    #[cfg(target_arch = "x86_64")]
    fn stage_held_then_zombie(what: &str) -> Option<(std::os::unix::io::OwnedFd, libc::pid_t)> {
        fn exit_3(_: ()) -> ! {
            unsafe {
                libc::_exit(3);
            }
        }
        let (pid, pin) = match spawn_held_fork_child(exit_3, (), what) {
            Ok(pair) => pair,
            Err(errno) => {
                eprintln!("skip: {what} unstageable (errno {errno})");
                return None;
            }
        };
        // Tick at the hold (T-stopped ⟹ unreaped ⟹
        // authoritative — the continuity baseline).
        let tick0: u64 = proc_starttime(pid)
            .expect("held stat readable")
            .expect("held birth visible");
        // Settle zombie by OBSERVATION (dead,
        // unreaped — ours; the pin above already
        // names it).
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match proc_state(pid) {
                Some('Z') => break,
                Some(_) => {
                    assert!(
                        std::time::Instant::now() < end,
                        "staging broken ({what} never zombies)"
                    );
                    std::thread::sleep(std::time::Duration::from_millis(1));
                }
                None => {
                    eprintln!("skip: {what} setup stolen (foreign waiter — unprovable)");
                    return None;
                }
            }
        }
        // Continuity tripwire (a recycle between
        // the hold and the settle would hand the
        // helper a stranger's corpse — RED loud
        // instead of consuming B silently).
        let tick1: u64 = proc_starttime(pid)
            .expect("zombie stat readable")
            .expect("zombie birth visible");
        assert_eq!(
            tick0, tick1,
            "staging broken (birth recycled under the held pin — L97 tripwire)"
        );
        Some((pin, pid))
    }

    /// XRV1-L49/L75 collateral (premise-break zombie
    /// retire): a zombie authenticated by the HELD pin
    /// (opened over the STOPPED birth — pre-established
    /// before the death, never a post-Z open (L97) —
    /// birth-bound, never a numeric wait) IS our birth
    /// ⟹ the helper consumes it through that SAME pin
    /// (XRV1-L75: the pin is the CALLER's, retained
    /// from the hold — no fresh open inside the helper
    /// (a fresh open races: A reaped + same-tick B
    /// zombies between check and open ⟹ consume
    /// steals B)) and reports Discharged (the test
    /// disarms BEFORE judging). Retirement is proven
    /// through the pin (post-retire ECHILD).
    /// XRV1-L68: gated (pin-consume needs waitid).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn premise_break_zombie_with_held_pin_is_consumed() {
        // XRV1-L68: gate BEFORE staging (zero cleanup
        // on skip).
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-consume untestable)");
                return;
            }
        }
        // XRV1-L97: stage under a PRE-ESTABLISHED
        // pin (opened over the STOPPED birth —
        // predates the death, so it CANNOT name a
        // recycled replacement — no post-Z open
        // exists anymore).
        let Some((pin_fd, pid)) = stage_held_then_zombie("premise-break zombie") else {
            return;
        };
        use std::os::unix::io::AsRawFd as _;
        let pin = pin_fd.as_raw_fd();
        // XRV1-L37: custody BEFORE the helper call.
        let mut _sguard = FixtureGuard::new(pid);
        let (outcome, forensics) = retire_zombie_premise_break(pin, pid);
        assert_eq!(
            outcome,
            ZombieRetire::Discharged,
            "held-pin zombie must discharge, got {forensics:?}"
        );
        // XRV1-L80: stand down on AUTHORITATIVE
        // discharge (the helper consumed through the
        // held pin or observed reaped-elsewhere —
        // nothing of ours remains) BEFORE the
        // pin-proof (a proof-failure unwind through an
        // armed numeric guard could kill a same-tick
        // replacement — a leak beats a murder).
        _sguard.disarm();
        // Prove retirement through the HELD pin
        // (nothing armed now — a proof failure
        // leaks rather than murders).
        // SAFETY: own pidfd + zeroed siginfo + probe
        // flags (WNOHANG — never blocks).
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                pin as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            let errno = std::io::Error::last_os_error().raw_os_error();
            (ret, errno)
        };
        drop(pin_fd);
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "pin must prove OUR birth consumed (post-retire ECHILD)"
        );
        // XRV1-L89: NO numeric vacancy assert (a
        // legitimate replacement breaks it —
        // R19003-FLAKE02 — the pin-proof above is
        // the verdict).
    }

