        // consumes through the HELD pin (never numeric
        // — a numeric wait past a real foreign reap
        // could consume a recycled sibling; the pin
        // can only consume OUR birth — a concurrent
        // real sweep reads ReapedElsewhere ⟹ same
        // helper input, accepted).
        let swept = probe_victim_pin(pin);
        assert!(
            matches!(swept, PinProbe::Reaped(_) | PinProbe::ReapedElsewhere),
            "staging broken (must consume first: {swept:?})"
        );
        let (outcome, forensics) = retire_zombie_premise_break(pin, pid);
        // XRV1-L98: stand down on AUTHORITATIVE
