        // EXCLUSION (a pin-kill does not reserve its
        // status — a legitimate concurrent sweep could
        // steal the corpse and fail this oracle — the
        // guard makes Consumed DETERMINISTIC (our zombie
        // unsweepable); AlreadyGone legs stay ESRCH-path
        // (no sweep needed — unaffected)).
        let _sole = NumericSupervisionGuard::enter();
        let staged = stage_l78a_sleeper("179").expect("staging broken (sleeper+pin)");
        let pid = staged.pid;
