        let pin2 = super::super::seccomp::pidfd_open_raw(pid)
            .map(|fd| unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) })
            .expect("staging broken (second pin)");
        let mut staged = staged;
        let (first, _) = retire_live_pin(staged.pin_take());
        // XRV1-L122: disarm on CONFIRMED discharge
        // (Consumed (we consumed) or AlreadyGone
