    /// XRV1-L109 probe body (fresh image,
    /// SCOPEBASE_STAGING_HOOK_RESTORE) — a pin-deny
    /// staging panic must RESTORE the panic hook
    /// and release the hook serial CLEANLY (no
    /// poison): the REAL test body runs in an
    /// outer catch, the staging panic is required,
    /// the serial must try_lock (a bypassed
    /// restore poisons it ⟹ RED), and a caught
    /// canary panic must PRINT (a leaked noop
    /// hook swallows it ⟹ RED). Seccomp refused
    /// ⟹ loud skip.
    #[cfg(target_arch = "x86_64")]
    fn staging_owner_hook_restore_probe() {
        use super::super::seccomp::{install_deny_one, DenyAction};
        if install_deny_one(libc::SYS_pidfd_open, DenyAction::Eperm).is_err() {
            eprintln!("STAGING-HOOK-RESTORE skip: seccomp refused");
            return;
        }
        let out = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            staging_owner_armed_across_fallible_staging()
        }));
        assert!(out.is_err(), "staging must panic under pin-deny");
        assert!(
            PANIC_HOOK_SERIAL.try_lock().is_ok(),
            "staging panic must not poison the hook serial (restore bypassed?)"
        );
        // The hook half: a caught canary panic must
        // PRINT (the default hook restored — a
        // leaked noop hook swallows it ⟹ the
        // driver REDs on the missing line).
        let _ = std::panic::catch_unwind(|| panic!("hook-canary"));
        eprintln!("STAGING-HOOK-RESTORE restored");
    }

