    /// XRV1-L24 collateral: under pidfd-denying
    /// confinement (forced Unpinned on a capable host)
    /// the spawner returns the birth STOPPED (never
    /// CONT-after-Unpinned) and the split custody
    /// runs + retires it through the Child handle.
    /// Thread-confined (the seccomp filter installs
    /// calling-thread-only and dies with the worker —
    /// the suite itself never runs confined; no fork,
    /// so no fork+alloc hazard). Filter refused ⟹
    /// loud skip. RED pre-fix (spawner CONTs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn spawner_leaves_unpinned_birth_stopped_under_pidfd_deny() {
        #[repr(C)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        // Deny pidfd_open(434) → EPERM (4 insns: load
        // nr, jeq-deny-else-skip, errno, allow).
        const PIDFD_OPEN: u32 = 434;
        let filter = [
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x15,
                jt: 0,
                jf: 1,
                k: PIDFD_OPEN,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x00050000 | 1,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x7fff0000,
            },
        ];
        enum Outcome {
            Retired,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    // SAFETY: calling-thread-only seccomp
                    // install (no TSYNC via prctl — the
                    // filter confines this worker alone).
                    unsafe {
                        if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                            || libc::prctl(
                                libc::PR_SET_SECCOMP,
                                libc::SECCOMP_MODE_FILTER,
                                &SockFprog {
                                    len: 4,
                                    filter: filter.as_ptr(),
                                },
                                0,
                            ) != 0
                        {
                            return Outcome::FilterRefused;
                        }
                    }
                    // Forced Unpinned (pidfd_open →
                    // EPERM ⟹ Unsupported, no retry).
                    let (child, guard) = spawn_stopped_sh_with_guard("exec sleep 152");
                    // XRV1-L37/L39: split FIRST
                    // (owner-holds-STOPPED, run=false —
                    // custody before ANY assert; the
                    // T-assert below runs owner-armed
                    // AND proves the split did not CONT).
                    let custody = split_staging_custody(child, &guard, false);
                    assert!(
                        matches!(guard.pin, GuardPin::Unpinned),
                        "pidfd-deny must construct Unpinned, got {:?}",
                        guard.pin
                    );
                    let pid = custody.pid();
                    assert_eq!(
                        proc_state(pid),
                        Some('T'),
                        "spawner must leave an Unpinned birth STOPPED (never CONT-after-Unpinned)"
                    );
                    assert!(
                        matches!(custody, StagingCustody::Unpinned(_)),
                        "Unpinned birth must split to the Child-handle owner"
                    );
                    assert_eq!(custody.pid(), pid, "owner tracks the birth");
                    // Manual CONT (running needed — the
                    // owner armed above), then strict
                    // retire.
                    cont_held_birth(pid);
                    custody.retire();
                    assert_eq!(proc_state(pid), None, "retired birth must be reaped");
                    Outcome::Retired
                })
                .join()
        });
        // A worker panic (staging/assert failure) is a
        // REAL failure — resume it with its own payload
        // (never masked as a skip or rewrapped).
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::Retired => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (pidfd-deny worker)");
            }
        }
    }

    /// XRV1-L38 collateral: a filter that allows
    /// pidfd signal-0 but EPERMs pidfd SIGKILL must
    /// read Unsupported (signal-0 proves dispatch,
    /// not kill power — the old 4-leg probe read
    /// Supported here while the Drop could not kill
    /// through the pin). Thread-confined (same shape
    /// as the pidfd-deny worker — filter dies with
    /// the worker; the suite never runs confined).
    /// Filter refused ⟹ loud skip. RED without the
    /// SIGKILL leg (probe reads Supported).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn probe_reports_unsupported_when_pidfd_sigkill_denied() {
        #[repr(C)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        // pidfd_send_signal(424) with sig(arg1) != 0
        // ⟹ EPERM; sig == 0 ⟹ ALLOW (6 insns: load
        // nr, jeq-424-else-allow, load arg1-low,
        // jeq-0-allow-else-errno, errno, allow).
        const PIDFD_SEND_SIGNAL: u32 = 424;
        let filter = [
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x15,
                jt: 0,
                jf: 3,
                k: PIDFD_SEND_SIGNAL,
            },
            SockFilter {
                code: 0x20,
                jt: 0,
                jf: 0,
                k: 24,
            },
            SockFilter {
                code: 0x15,
                jt: 1,
                jf: 0,
                k: 0,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x00050000 | 1,
            },
            SockFilter {
                code: 0x06,
                jt: 0,
                jf: 0,
                k: 0x7fff0000,
            },
        ];
        enum Outcome {
            Unsupported,
            FilterRefused,
        }
        let outcome = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    // SAFETY: calling-thread-only seccomp
                    // install (no TSYNC via prctl — the
                    // filter confines this worker alone).
                    unsafe {
                        if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                            || libc::prctl(
                                libc::PR_SET_SECCOMP,
                                libc::SECCOMP_MODE_FILTER,
                                &SockFprog {
                                    len: 6,
                                    filter: filter.as_ptr(),
                                },
                                0,
                            ) != 0
                        {
                            return Outcome::FilterRefused;
                        }
                    }
                    // Selectivity proof (the filter
                    // denies SIGKILL specifically —
                    // signal-0 still dispatches, so the
                    // old 4-leg shape would pass here).
                    let self_pid = std::process::id() as libc::pid_t;
                    let self_fd = super::super::seccomp::pidfd_open_raw(self_pid)
                        .expect("staging broken (self pidfd under sigkill-deny)");
                    assert_eq!(
                        super::super::seccomp::pidfd_send_signal_raw(self_fd, 0),
                        Ok(()),
                        "staging broken (signal-0 must stay allowed)"
                    );
                    assert_eq!(
                        super::super::seccomp::pidfd_send_signal_raw(self_fd, libc::SIGKILL),
                        Err(libc::EPERM),
                        "staging broken (SIGKILL must be EPERMed)"
                    );
                    // SAFETY: close our self pidfd copy.
                    unsafe {
                        libc::close(self_fd);
                    }
                    assert_eq!(
                        waitid_pidfd_probe(),
                        ProbeVerdict::Unsupported,
                        "sigkill-denied capability must not read Supported"
                    );
                    Outcome::Unsupported
                })
                .join()
        });
        // A worker panic (staging/assert failure) is a
        // REAL failure — resume it with its own payload
        // (never masked as a skip or rewrapped).
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(payload) => std::panic::resume_unwind(payload),
        };
        match outcome {
            Outcome::Unsupported => {}
            Outcome::FilterRefused => {
                eprintln!("skip: seccomp install refused (sigkill-deny worker)");
            }
        }
    }

