    /// XRV1-L10 collateral: the self-stop is CHECKED —
    /// under kill-denying seccomp the wrapper must die
    /// with exit 99 (loud), never run its body. The
    /// filter is fork-contained (installed post-fork in
    /// the child only — the suite itself never runs
    /// confined; kill() is load-bearing everywhere, so a
    /// kill-denying host voids the suite generally, not
    /// just stopped-spawn). The child exercises the REAL
    /// [`stopped_spawn_argv`] text with body `exit 42`:
    /// RED without the check (body runs, exit 42),
    /// GREEN with it (exit 99). Post-fork code is raw
    /// syscalls only (async-signal-safe — no alloc, no
    /// Command); seccomp-unavailable (exotic kernels,
    /// nested confinement refusing the install) skips
    /// loud via exit 77.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn stopped_spawn_checked_stop_dies_loud_on_denial() {
        // BPF: deny kill(*, SIGSTOP) (reviewer's 6-insn
        // shape — syscall 62, arg1 == 19 ⟹ EPERM), allow
        // everything else.
        #[repr(C)]
        struct SockFilter {
            code: u16,
            jt: u8,
            jf: u8,
            k: u32,
        }
        #[repr(C)]
        struct SockFprog {
            len: u16,
            filter: *const SockFilter,
        }
        const DENY_STOP: [SockFilter; 6] = [
            SockFilter { code: 0x20, jt: 0, jf: 0, k: 0 },
            SockFilter { code: 0x15, jt: 0, jf: 3, k: 62 },
            SockFilter { code: 0x20, jt: 0, jf: 0, k: 24 },
            SockFilter { code: 0x15, jt: 0, jf: 1, k: 19 },
            SockFilter { code: 0x06, jt: 0, jf: 0, k: 0x00050000 | 1 },
            SockFilter { code: 0x06, jt: 0, jf: 0, k: 0x7fff0000 },
        ];
        let text =
            std::ffi::CString::new(stopped_spawn_argv("exit 42")).expect("argv cstring");
        // SAFETY: fork in a test thread; the child runs
        // raw syscalls only until _exit (no alloc, no
        // locks — the CString above is read-only shared).
        let kid = unsafe { libc::fork() };
        assert!(kid >= 0, "staging broken (denial fork)");
        if kid == 0 {
            unsafe {
                if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                    || libc::prctl(
                        libc::PR_SET_SECCOMP,
                        libc::SECCOMP_MODE_FILTER,
                        &SockFprog { len: 6, filter: DENY_STOP.as_ptr() },
                        0,
                    ) != 0
                {
                    libc::_exit(77);
                }
                let grand = libc::fork();
                if grand < 0 {
                    libc::_exit(76);
                }
                if grand == 0 {
                    let devnull = libc::open(
                        c"/dev/null".as_ptr(),
                        libc::O_RDWR | libc::O_CLOEXEC,
                    );
                    if devnull >= 0 {
                        libc::dup2(devnull, 0);
                        libc::dup2(devnull, 1);
                        libc::dup2(devnull, 2);
                        if devnull > 2 {
                            libc::close(devnull);
                        }
                    }
                    let sh = c"/bin/sh".as_ptr();
                    let dash_c = c"-c".as_ptr();
                    let argv = [sh, dash_c, text.as_ptr(), std::ptr::null()];
                    let envp = [std::ptr::null()];
                    libc::execve(sh, argv.as_ptr(), envp.as_ptr());
                    libc::_exit(127);
                }
                // Bounded reap (no unbounded waits — a
                // broken filter could let the stop land;
                // _exit(2) distinguishes confinement bugs
                // from body runs).
                let mut status = 0;
                let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
                let code = loop {
                    let got = libc::waitpid(grand, &mut status, libc::WNOHANG);
                    if got == grand {
                        break status;
                    }
                    if got < 0 {
                        libc::_exit(75);
                    }
                    if std::time::Instant::now() >= end {
                        libc::kill(grand, libc::SIGKILL);
                        libc::waitpid(grand, &mut status, 0);
                        libc::_exit(2);
                    }
                    libc::usleep(1000);
                };
                // WIFEXITED(99) ⟺ the check fired (loud);
                // anything else (42 = body ran!) is RED.
                if libc::WIFEXITED(code) && libc::WEXITSTATUS(code) == 99 {
                    libc::_exit(0);
                }
                libc::_exit(1);
            }
        }
        // Parent: bounded supervisor wait (L20 shape — a
        // wedged child must fail loud, never hang).
        let mut status = 0;
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            // SAFETY: our own fork-child, WNOHANG poll.
            let got = unsafe { libc::waitpid(kid, &mut status, libc::WNOHANG) };
            if got == kid {
                break;
            }
            assert!(got >= 0, "staging broken (denial wait)");
            if std::time::Instant::now() >= end {
                // SAFETY: our own fork-child.
                unsafe {
                    libc::kill(kid, libc::SIGKILL);
                    libc::waitpid(kid, &mut status, 0);
                }
                panic!("staging broken (denial child wedged past 10s)");
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(
            unsafe { libc::WIFEXITED(status) },
            "denial child must exit (got {status})"
        );
        // SAFETY: WIFEXITED proven above.
        match unsafe { libc::WEXITSTATUS(status) } {
            0 => {}
            77 => {
                eprintln!("skip: seccomp install refused (exotic/nested host)");
            }
            2 => panic!("staging broken (denial confinement let the stop land?)"),
            75 | 76 | 127 => panic!("staging broken (denial child error {status})"),
            other => panic!(
                "self-stop must be CHECKED (denied stop ran the body — child exit {other}, want 0 (grandchild 99))"
            ),
        }
    }

    /// XRV1-J6 collateral: the staging guard reaps on
    /// unwind (kill-only custody would strand a
    /// dying-live or zombie birth). A forced panic inside
    /// `catch_unwind`, then the drop must leave the birth
    /// reaped. Discharge is verified through an
    /// independent pidfd (XRV1-K6 — a post-drop numeric
    /// waitpid would address a freed number and could
    /// consume a recycled sibling's zombie): ESRCH ⟺
    /// died-and-reaped (a stranded zombie answers
    /// signal-0). Discriminates the guard TYPE (pins that
    /// staging custody is the reaping kind — swapping in
    /// KillOnlyGuard leaves signal-0 succeeding and
    /// fails). A concurrent sweep reaping ahead of the
    /// assert also reads ESRCH (same shape as the old
    /// ECHILD assert — the kill is still the guard's).
    /// XRV1-L2: the birth stays HELD throughout (no CONT
    /// — the oracle, the guard under test, and the
    /// unwinding drop all operate on the stopped birth;
    /// SIGKILL lands on stopped, and the stop binds
    /// every pin).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn staging_guard_reaps_on_unwind() {
        use std::os::unix::io::AsRawFd as _;
        // XRV1-L9: the verdict IS a pin-reap — no pin
        // without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin-reap untestable)");
                return;
            }
        }
        // XRV1-L7: INDEPENDENT cleanup custody from spawn
        // (the guard under test may be kill-only on a
        // regression — its zombie must still retire on
        // every unwind path below; the oracle is captured
        // before this guard drops, so it never masks the
        // verdict). Disarmed only after the verdict
        // asserts pass. XRV1-L2 HELD (the birth never
        // runs — every pin below binds through the stop).
        let (mut child, mut _cleanup) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        // Independent oracle, pinned while HELD (try_wait
        // None ⟹ live; the STOP binds the open —
        // XRV1-L2: try_wait alone does not bind it).
        assert!(
            child.try_wait().expect("try_wait").is_none(),
            "birth must be live at pin time"
        );
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                // XRV1-L17: disarm ONLY after confirmed
                // retirement (kill/wait below used to
                // panic with cleanup already disabled —
                // a failed kill would strand the held
                // birth stopped). skip_discharge retires
                // through the guard's pidfd; unresolved
                // ⟹ the guard stays armed (its drop
                // retires).
                if _cleanup.skip_discharge(&mut child) {
                    _cleanup.disarm();
                } else {
                    eprintln!("K6 skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        let result = std::panic::catch_unwind(|| {
            // XRV1-L11: construct-retry (transient
            // Unpinned (EMFILE/outage) must not run the
            // verdict degraded — a silent drop would
            // leave signal-0 succeeding (RED on
            // transient — a flake); the birth stays
            // stopped throughout (nobody CONTs).
            // Persistent failure panics (caught — then
            // the oracle below REDs on the live birth:
            // host-broken loud, never silent).
            let build_end = std::time::Instant::now() + std::time::Duration::from_secs(5);
            // XRV1-L45: carry the cleanup guard's
            // already-pinned tick (the chain — never a
            // fresh read past the spawn pin).
            let k6_locked = match &_cleanup.pin {
                GuardPin::Pinned { tick, .. } => Some(*tick),
                GuardPin::Discharged | GuardPin::Unpinned => None,
            };
            let _guard = loop {
                // XRV1-L31: construction errors return —
                // ANY error here is staging-broken loud
                // (the payload assert below REDs — a
                // non-forced payload never reads green).
                let constructed = match KillReapGuard::new(pid, k6_locked) {
                    Ok(constructed) => constructed,
                    Err(error) => {
                        panic!("staging broken (guard under test will not pin: {error:?})")
                    }
                };
                if matches!(&constructed.guard.pin, GuardPin::Pinned { .. }) {
                    break constructed.guard;
                }
                if matches!(&constructed.guard.pin, GuardPin::Discharged)
                    || std::time::Instant::now() >= build_end
                {
                    panic!("staging broken (guard under test will not pin)");
                }
                std::thread::sleep(std::time::Duration::from_millis(1));
            };
            panic!("forced staging panic");
        });
        // XRV1-L23/L31: the payload must be OURS (a
        // staging outage inside `new` returns Err ⟹ the
        // loop above panics staging-broken — accepting
        // any panic would mask a host outage as green).
        match result {
            Err(payload) => {
                let text = payload
                    .downcast_ref::<&str>()
                    .map(|s| s.to_string())
                    .or_else(|| payload.downcast_ref::<String>().cloned())
                    .unwrap_or_default();
                assert!(
                    text.contains("forced staging panic"),
                    "unexpected panic payload (staging masked?): {text:?}"
                );
            }
            Ok(()) => panic!("the forced panic must propagate"),
        }
        drop(child);
        // Birth reaped by the unwinding drop (kill-only
        // custody would leave signal-0 succeeding).
        // Captured BEFORE cleanup stands down (L7: the
        // assert below must not leak on its own RED path —
        // _cleanup retires the zombie on unwind).
        let oracle = super::super::seccomp::pidfd_send_signal_raw(pin.as_raw_fd(), 0);
        assert_eq!(
            oracle,
            Err(libc::ESRCH),
            "staging guard must have reaped"
        );
        _cleanup.disarm();
    }

    /// XRV1-L48 collateral (transfer inertness): a
    /// transfer from an UNPINNED staging guard is
    /// kill-INERT (pidfd None — the drop signals
    /// nothing). Characterization (locks the
    /// rationale for the skip-if-Unpinned at the J6
    /// transfer sites — an inert KillOnly beside a
    /// wait-only detached reaper strands live
    /// births on staging panic).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn kill_only_transfer_from_unpinned_is_kill_inert() {
        let staging = KillReapGuard {
            pid: 1,
            pin: GuardPin::Unpinned,
            disarmed: false,
        };
        let transferred = KillOnlyGuard::transfer_from(staging);
        assert!(
            transferred.pidfd.is_none(),
            "Unpinned transfer must carry no pidfd (kill-inert)"
        );
        // Drops here (inert — silent).
    }

    /// XRV1-L48 collateral (skip-if-Unpinned): the
    /// J6-transfer skip helper round-trips the
    /// custody (Some — the caller proceeds) on a
    /// Pinned pin. Gated (a Pinned guard needs both
    /// capabilities).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pinned_custody_or_skip_round_trips_pinned() {
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (Pinned untestable)");
                return;
            }
        }
        let (spawn, guard) = spawn_stopped_sh_with_guard("exec sleep 163");
        let custody = split_staging_custody(spawn, &guard, true);
        let pid = custody.pid();
        let custody = pinned_custody_or_skip(custody, &guard.pin, "test-pinned")
            .expect("Pinned must round-trip");
        assert_eq!(custody.pid(), pid, "custody returned intact");
        // XRV1-L89: birth-bound verdict (a numeric
        // vacancy assert could meet a recycled
        // replacement — R19003-FLAKE02).
        let pin = super::super::seccomp::pidfd_open_raw(pid).expect("staging broken (pin)");
        custody.retire();
        // SAFETY: own pidfd + zeroed siginfo + probe
        // flags (WNOHANG — never blocks).
        let proof = unsafe {
            let mut info: libc::siginfo_t = std::mem::zeroed();
            let ret = libc::waitid(
                libc::P_PIDFD,
                pin as libc::id_t,
                &mut info,
                libc::WEXITED | libc::WNOHANG,
            );
            let errno = std::io::Error::last_os_error().raw_os_error();
            libc::close(pin);
            (ret, errno)
        };
        assert_eq!(
            proof,
            (-1, Some(libc::ECHILD)),
            "pin must prove OUR birth consumed (custody retired)"
        );
        // The guard drops Pinned over the reaped
        // number (kill-ESRCH — silent).
    }

    /// XRV1-L48 collateral (skip-if-Unpinned): the
    /// J6-transfer skip helper retires the birth
    /// explicitly (kill+reap — proven gone) and
    /// reports None (the caller returns LOUD-skipped)
    /// on an Unpinned pin. The Unpinned pin is
    /// staged white-box (an Unpinned guard literal
    /// over a real held birth — the helper judges
    /// the PIN, not the staging path — ungated).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pinned_custody_or_skip_retires_unpinned_loud() {
        let (spawn, mut guard) = spawn_stopped_sh_with_guard("exec sleep 164");
        let spid = spawn.id() as libc::pid_t;
        // The REAL guard stands down (the fake
        // judges below).
        guard.disarm();
        let fake = KillReapGuard {
            pid: spid,
            pin: GuardPin::Unpinned,
            disarmed: true,
        };
        let custody = split_staging_custody(spawn, &fake, true);
        let pid = custody.pid();
        // XRV1-L89: birth-bound verdict when a pin
        // is available (the birth is live-held, so
        // a failed open ⟺ confinement, never
        // absence — the test stays ungated: its
        // None-return verdict above runs everywhere;
        // only the retire-proof degrades loud).
        let pin = super::super::seccomp::pidfd_open_raw(pid).ok();
        let back = pinned_custody_or_skip(custody, &fake.pin, "test-unpinned");
        assert!(back.is_none(), "Unpinned must skip (None)");
        match pin {
            Some(pin) => {
                // SAFETY: own pidfd + zeroed siginfo
                // + probe flags (WNOHANG — never
                // blocks).
                let proof = unsafe {
                    let mut info: libc::siginfo_t = std::mem::zeroed();
                    let ret = libc::waitid(
                        libc::P_PIDFD,
                        pin as libc::id_t,
                        &mut info,
                        libc::WEXITED | libc::WNOHANG,
                    );
                    let errno = std::io::Error::last_os_error().raw_os_error();
                    libc::close(pin);
                    (ret, errno)
                };
                assert_eq!(
                    proof,
                    (-1, Some(libc::ECHILD)),
                    "pin must prove OUR birth consumed (skipped birth retired)"
                );
            }
            None => {
                eprintln!("note: retire-proof unverified (no pidfd — confinement?)");
            }
        }
    }

    /// XRV1-K4 collateral: the kill-only transfer carries
    /// the staging guard's ESTABLISHED authority without
    /// re-reading the number (a re-read past the reaper's
    /// discharge would authorize a recycled stranger).
    /// Staging pins a live birth; the birth is then
    /// killed+reaped (the K4 shape); the transfer must
    /// still carry the moved pidfd. XRV1-L1: the
    /// tick-carry assert is deleted with the tick field
    /// (no-re-read is now STRUCTURAL — there is no
    /// numeric channel left to fill); the pidfd-move
    /// assert below pins the transfer. Mutant-checked
    /// (dropping the pin in transfer REDs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn kill_only_transfer_carries_staging_authority_without_reread() {
        // XRV1-L9: the transfer carries a pin — no pin
        // without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (no pin to transfer)");
                return;
            }
        }
        // XRV1-L2: stopped-sleep (staging pins during
        // the stop — stopped ⟹ held ⟹ Pinned
        // deterministically here).
        let (mut child, staging) = spawn_stopped_sh_with_guard("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        assert!(
            matches!(&staging.pin, GuardPin::Pinned { .. }),
            "staging must pin a live birth (got {:?})",
            staging.pin
        );
        // Discharge the birth BEFORE transfer (the K4
        // shape: the reaper got there first).
        child.kill().expect("kill lands");
        child.wait().expect("owner reaps");
        let mut transferred = KillOnlyGuard::transfer_from(staging);
        // XRV1-L3: stand down BEFORE judging (an assert
        // failure below must not unwind into armed cleanup
        // authority over a proven-retired number).
        transferred.disarm();
        assert_eq!(transferred.pid, pid, "transfer keeps the number");
        assert!(transferred.pidfd.is_some(), "the pidfd moves with the pin");
    }

    /// XRV1-G2 collateral: a pin probe of a birth
    /// reaped by a concurrent waiter reports
    /// ReapedElsewhere (ECHILD) — never the recycled
    /// sibling's status, never a hang.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn victim_pin_probe_reports_concurrent_reap() {
        // XRV1-L9: the verdict waits through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin verdict untestable)");
                return;
            }
        }
        // XRV1-H6: cleanup custody from spawn — XRV1-L2
        // HELD (guard + oracle pin during the stop; CONT
        // once pinned).
        let (mut child, mut _kguard) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                if _kguard.skip_discharge(&mut child) {
                    _kguard.disarm();
                } else {
                    eprintln!("pin-test skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        cont_held_birth(pid);
        use std::os::unix::io::AsRawFd as _;
        let pin_fd = pin.as_raw_fd();
        child.kill().expect("kill lands");
        child.wait().expect("concurrent waiter reaps");
        // Proven discharge (reaped) — stand down before
        // judging the probe.
        _kguard.disarm();
        match probe_victim_pin(pin_fd) {
            PinProbe::ReapedElsewhere => {}
            PinProbe::Reaped(st) => panic!("pin must not surface a reaped birth (st={st})"),
            PinProbe::NotReady => panic!("pin must not linger NotReady past a reap"),
            PinProbe::Unverifiable(evidence) => {
                panic!("pin probe must stay verifiable ({evidence})")
            }
        }
    }

    /// XRV1-G2 collateral: a pin probe reaps the pinned
    /// signaled birth and re-encodes waitpid shape
    /// (callers WIFSIGNALED-decode it).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn victim_pin_probe_reaps_signaled_birth() {
        // XRV1-L9: the verdict waits through a pin — no
        // pin without both capabilities.
        match probe_waitid_capability() {
            ProbeVerdict::Supported => {}
            verdict => {
                eprintln!("skip: waitid(P_PIDFD) {verdict:?} (pin verdict untestable)");
                return;
            }
        }
        // XRV1-H6: cleanup custody from spawn (see the
        // sibling test) — XRV1-L2 HELD.
        let (mut child, mut _kguard) = spawn_stopped_sh_with_guard_held("exec sleep 30");
        let pid = child.id() as libc::pid_t;
        let pin = match pidfd_open_held(pid) {
            Ok(pin) => pin,
            Err(errno) => {
                if _kguard.skip_discharge(&mut child) {
                    _kguard.disarm();
                } else {
                    eprintln!("pin-test skip-path cleanup unresolved — guard stays armed");
                }
                eprintln!("skip: pidfd_open unavailable (errno {errno})");
                return;
            }
        };
        cont_held_birth(pid);
        use std::os::unix::io::AsRawFd as _;
        let pin_fd = pin.as_raw_fd();
        child.kill().expect("kill lands");
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            match probe_victim_pin(pin_fd) {
                PinProbe::Reaped(st) => {
                    // XRV1-I3: disarm FIRST — the status is
                    // consumed (proven discharge), and the
                    // asserts below can panic; judging under
                    // an armed guard murders a same-tick
                    // replacement on unwind.
                    _kguard.disarm();
                    assert!(
                        libc::WIFSIGNALED(st),
                        "signaled birth must decode signaled (st={st})"
                    );
                    assert_eq!(
                        libc::WTERMSIG(st),
                        libc::SIGKILL,
                        "death signal must survive re-encoding"
                    );
                    break;
                }
                PinProbe::NotReady => {}
                PinProbe::ReapedElsewhere => {
                    // Discharged without us (reaped — gone)
                    // — stand down before the loud panic.
                    _kguard.disarm();
                    panic!("nothing else reaps this birth")
                }
                PinProbe::Unverifiable(evidence) => {
                    // Birth state UNKNOWN — keep the guard
                    // armed (drop best-effort retires).
                    panic!("pin probe must stay verifiable ({evidence})")
                }
            }
            assert!(std::time::Instant::now() < end, "victim must die");
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // Reaped via the pin above — drop the Child
        // handle WITHOUT waiting (XRV1-H2: try_wait would
        // numeric-waitpid the freed number and could steal
        // a recycled sibling's status; drop neither
        // signals nor reaps).
        drop(child);
    }

    /// Shared victim drain for the R19-006 halves — see
    /// [`VictimDrain`]. The caller drops its `Child`
    /// handle before calling (drop order is inert —
    /// drop neither signals nor reaps), disarms its
    /// guard on `Reaped`/`Stolen` (discharged — nothing
    /// to retire), and panics inconclusive on
    /// `Unverifiable` with the guard still ARMED (drop
    /// best-effort retires on unwind).
    #[cfg(target_arch = "x86_64")]
    fn drain_victim_status(vpid: libc::pid_t, vtick: u64) -> VictimDrain {
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::io::FromRawFd as _;
        use std::time::{Duration, Instant};
        let _ = kill_tick_gated(vpid, vtick);
        // XRV1-G2: anchor every wait below on a pidfd pin
        // of the EXACT victim birth.
        let pin = match super::super::seccomp::pidfd_open_raw(vpid) {
            Ok(fd) => unsafe { std::os::unix::io::OwnedFd::from_raw_fd(fd) },
            Err(errno) => match proc_starttime(vpid) {
                Ok(Some(t)) if t == vtick => {
                    return VictimDrain::Unverifiable(format!(
                        "present {vpid}/{vtick} but unopenable (pidfd_open errno {errno})"
                    ));
                }
                Ok(v) => {
                    return VictimDrain::Stolen(format!(
                        "discharged before drain: {vpid}/{vtick} now {v:?}"
                    ));
                }
                Err(error) => return VictimDrain::Unverifiable(format!("{error:?}")),
            },
        };
        // Open-then-verify: a zombie holds its number, so
        // a tick match proves the pin IS our victim birth
        // (a concurrent reap+recycle between open and
        // verify shows a foreign tick → Stolen, and the
        // pin is never waited — the stranger's status is
        // untouched). XRV1-H3: match explicitly — an
        // unreadable verify is Unverifiable (cleanup
        // custody RETAINED), never Stolen (both callers
        // disarm on Stolen, which would abandon a
        // possibly-live victim).
        match proc_starttime(vpid) {
            Ok(Some(t)) if t == vtick => {}
            Ok(v) => {
                return VictimDrain::Stolen(format!(
                    "discharged during pin grab: {vpid}/{vtick} now {v:?}"
                ));
            }
            Err(error) => {
                return VictimDrain::Unverifiable(format!("pin-grab verify unreadable: {error:?}"));
            }
        }
        let pin_fd = pin.as_raw_fd();
        let end = Instant::now() + Duration::from_secs(10);
        let mut reaped = None;
        loop {
            // Birth-bound: this status is OUR victim's —
            // no same-number sibling can surface here.
            match probe_victim_pin(pin_fd) {
                PinProbe::Reaped(st) => {
                    reaped = Some(st);
                }
                PinProbe::NotReady => {}
                // Our exact birth was reaped by a
                // concurrent waiter — Stolen NOW (the
                // waitpid shape had no ECHILD arm and spun
                // until proc showed gone).
                PinProbe::ReapedElsewhere => {
                    return VictimDrain::Stolen(format!(
                        "ECHILD on pinned {vpid}/{vtick}: a concurrent waiter holds the status"
                    ));
                }
                PinProbe::Unverifiable(evidence) => {
                    return VictimDrain::Unverifiable(evidence);
                }
            }
            if proc_starttime(vpid) != Ok(Some(vtick)) {
                break;
            }
            assert!(Instant::now() < end, "victim must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        match reaped {
            Some(st) => VictimDrain::Reaped(st),
            None => match proc_starttime(vpid) {
                // Transient outage blip broke the loop
                // above with the victim present (its kill
                // may have been suppressed by the same
                // outage — kill_tick_gated returns false
                // on unreadable). Retry the kill
                // (tick-gated, idempotent) and drain a
                // second time, BOUNDED: an unbounded
                // blocking wait would hang on a live
                // unkilled victim and race a concurrent
                // reap to ECHILD.
                Ok(Some(now)) if now == vtick => {
                    let _ = kill_tick_gated(vpid, vtick);
                    let end = Instant::now() + Duration::from_secs(10);
                    loop {
                        // Birth-bound re-await (XRV1-G2):
                        // the pin reports ONLY our victim —
                        // a recycled same-number sibling
                        // can neither surface nor be reaped
                        // (the waitpid shape it replaces
                        // reaped whatever zombie held the
                        // number).
                        match probe_victim_pin(pin_fd) {
                            PinProbe::Reaped(st) => {
                                break VictimDrain::Reaped(st);
                            }
                            PinProbe::NotReady => {}
                            PinProbe::ReapedElsewhere => {
                                // Discharged without us (our
                                // wait never hit, no waitable
                                // child remains): a concurrent
                                // waiter holds the status.
                                break VictimDrain::Stolen(format!(
                                    "ECHILD awaiting pinned {vpid}/{vtick}"
                                ));
                            }
                            PinProbe::Unverifiable(evidence) => {
                                break VictimDrain::Unverifiable(evidence);
                            }
                        }
                        match proc_starttime(vpid) {
                            Ok(Some(n)) if n == vtick => {}
                            Ok(v) => {
                                break VictimDrain::Stolen(format!(
                                    "discharged during re-await: {vpid}/{vtick} now {v:?}"
                                ));
                            }
                            Err(error) => {
                                break VictimDrain::Unverifiable(format!("{error:?}"));
                            }
                        }
                        if Instant::now() >= end {
                            break VictimDrain::Unverifiable(format!(
                                "present past second bound: {vpid}/{vtick}"
                            ));
                        }
                        std::thread::sleep(Duration::from_millis(10));
                    }
                }
                Ok(v) => VictimDrain::Stolen(format!(
                    "discharged without our wait: {vpid}/{vtick} now {v:?}"
                )),
                Err(error) => VictimDrain::Unverifiable(format!("{error:?}")),
            },
        }
    }

    /// R19-006: pipe discovery must verify identity and mode
    /// against the SAME descriptor — identity comes from our
    /// opened fd while the write-mode comes from the
    /// target's mutable slot, so a slot swap between the two
    /// merges the old identity with new flags and
    /// misclassifies (no PID reuse needed). The victim holds
    /// the collection write end, then swaps its slot to an
    /// unrelated writable file exactly inside the evidence
    /// window (hook-driven handshake — no timing); the
    /// discovered pairs then run through the production
    /// stray retire. RED (this shape): the stale identity +
    /// fresh flags attribute and the retire murders a task
    /// that already released the pipe. GREEN: the trailing
    /// slot re-check (fstat-path vs fstat-opened) plus the
    /// second mode read skip it, nothing retires, the
    /// victim survives with its status.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn discovery_verifies_slot_across_mode_read() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when discovery attribution is unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        let _pop = DISCOVERY_POPULATION_SERIAL
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Collection pipe: we keep the READ end; the victim
        // inherits the WRITE end at slot 1.
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let want_ino = pipe_dev_ino(read_fd).expect("collection pipe identified");
        // Swap choreography files (pid-unique).
        let me = std::process::id();
        let dir = std::env::temp_dir();
        let unrelated = dir.join(format!("scopebase-r19006-unrelated-{me}"));
        let flag_swap = dir.join(format!("scopebase-r19006-swap-{me}"));
        let flag_done = dir.join(format!("scopebase-r19006-done-{me}"));
        let _ = std::fs::remove_file(&flag_swap);
        let _ = std::fs::remove_file(&flag_done);
        let _ = std::fs::remove_file(&unrelated);
        // Victim: holds the write end at slot 1, waits for
        // the swap flag, dup2s an unrelated writable file
        // onto the slot, raises done, parks.
        let script = "import os, sys, time
u = os.open(sys.argv[1], os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
while not os.path.exists(sys.argv[2]):
    time.sleep(0.001)
os.dup2(u, 1)
os.close(u)
open(sys.argv[3], 'w').write('swapped\\n')
time.sleep(30)
";
        let victim = std::process::Command::new("python3")
            .arg("-c")
            .arg(script)
            .arg(&unrelated)
            .arg(&flag_swap)
            .arg(&flag_done)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("victim holder spawns");
        let vpid = victim.id() as libc::pid_t;
        let mut _vguard = FixtureGuard::new(vpid);
        let vtick = proc_starttime(vpid)
            .expect("victim stat readable")
            .expect("victim visible");
        // Non-vacuity: the victim genuinely holds the
        // collection write end at slot 1 (pre-swap).
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            let slot =
                std::fs::read_link(format!("/proc/{vpid}/fd/1")).expect("victim slot readable");
            if slot.to_string_lossy().into_owned() == format!("pipe:[{}]", want_ino.1) {
                break;
            }
            assert!(
                Instant::now() < end,
                "victim must hold the collection write end (non-vacuity)"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        // Steering state (the hook runs on this thread).
        struct Steer {
            fired: bool,
        }
        let state = std::cell::RefCell::new(Steer { fired: false });
        let (found, truncated) = extend_strays_with_pipe_writers_with(
            &[],
            Some(read_fd),
            None,
            Some(&|pid| {
                let mut state = state.borrow_mut();
                if state.fired {
                    return;
                }
                state.fired = true;
                assert_eq!(pid, vpid, "hook must fire for the victim only");
                // In-window slot swap: raise the swap flag,
                // wait for the victim's done (bounded).
                std::fs::write(&flag_swap, "swap\n").expect("swap flag raises");
                let end = Instant::now() + Duration::from_secs(10);
                loop {
                    if flag_done.exists() {
                        break;
                    }
                    assert!(
                        Instant::now() < end,
                        "victim must complete the slot swap (stage broken otherwise)"
                    );
                    std::thread::sleep(Duration::from_millis(1));
                }
            }),
            &PipeScanBudget::default(),
        );
        assert!(
            state.borrow().fired,
            "hook must fire (victim must match identity)"
        );
        assert!(!truncated, "small fixture population must scan fully");
        // End-to-end: run the discovered pairs through the
        // production stray retire (RED: the stale identity +
        // fresh flags attribute and the victim dies here —
        // gratuitously, since it already released the pipe).
        for (pid, tick) in &found {
            let _ = retire_stray_tree_best_effort(*pid, *tick, &[]);
        }
        // The victim survives with its status retained.
        assert_proc_settled_live(
            vpid,
            vtick,
            2,
            "swapped holder must survive discovery + retire",
        );
        // Cleanup: retire the victim ourselves and record
        // its status HERE (a concurrent wait — sibling
        // sweep or stale-discovery retire await — can
        // otherwise steal it; see drain_victim_status).
        drop(victim);
        // XRV1-F4: disarm ONLY on discharge (Reaped/Stolen)
        // — Unverifiable keeps cleanup custody (the guard
        // best-effort retires on the unwind below) and
        // fails inconclusive, never skipping a
        // possibly-live victim.
        let st = match drain_victim_status(vpid, vtick) {
            VictimDrain::Reaped(st) => {
                _vguard.disarm();
                st
            }
            VictimDrain::Stolen(evidence) => {
                _vguard.disarm();
                let _ = std::fs::remove_file(&flag_swap);
                let _ = std::fs::remove_file(&flag_done);
                let _ = std::fs::remove_file(&unrelated);
                eprintln!(
                    "skip: R19006-F16-THEFT victim status stolen by a concurrent \
                     waiter ({evidence}) — discovery verdicts above \
                     already green"
                );
                return;
            }
            VictimDrain::Unverifiable(evidence) => {
                let _ = std::fs::remove_file(&flag_swap);
                let _ = std::fs::remove_file(&flag_done);
                let _ = std::fs::remove_file(&unrelated);
                panic!(
                    "inconclusive (victim state unverifiable: {evidence}) — \
                     refusing to certify"
                );
            }
        };
        assert!(libc::WIFSIGNALED(st), "victim must die by our signal");
        let _ = std::fs::remove_file(&flag_swap);
        let _ = std::fs::remove_file(&flag_done);
        let _ = std::fs::remove_file(&unrelated);
    }

    /// R19-006 (second half): the second mode read is
    /// load-bearing on its own — a same-pipe END swap
    /// (write end → read end of the SAME collection pipe)
    /// keeps fstat-opened == fstat-path == want (same pipe —
    /// the slot re-check cannot exclude it), so only the
    /// fdinfo2 flags (read-only now) skip it. The victim
    /// holds the collection write end at slot 1 plus the
    /// read end at slot 3 (pre_exec dup, cloexec cleared),
    /// then dup2s the read end onto slot 1 exactly inside
    /// the evidence window (hook-driven handshake — no
    /// timing); the discovered pairs then run through the
    /// production stray retire. NOFDINFO2 (this shape): the
    /// stale write identity + same-pipe slot equality
    /// attribute and the retire murders a task holding only
    /// the read end. GREEN: fdinfo2 skips it, nothing
    /// retires, the victim survives with its status.
    /// Complement of
    /// `discovery_verifies_slot_across_mode_read` (which
    /// isolates fstat-path with an unrelated swap).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn discovery_mode_reread_excludes_same_pipe_end_swap() {
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when discovery attribution is unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        let _pop = DISCOVERY_POPULATION_SERIAL
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Collection pipe: we keep the READ end; the victim
        // inherits the WRITE end at slot 1 and the READ end
        // at slot 3 (for the same-pipe end swap).
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let want_ino = pipe_dev_ino(read_fd).expect("collection pipe identified");
        // Swap choreography files (pid-unique).
        let me = std::process::id();
        let dir = std::env::temp_dir();
        let flag_swap = dir.join(format!("scopebase-r19006s-swap-{me}"));
        let flag_done = dir.join(format!("scopebase-r19006s-done-{me}"));
        let _ = std::fs::remove_file(&flag_swap);
        let _ = std::fs::remove_file(&flag_done);
        // Victim: holds the write end at slot 1, waits for
        // the swap flag, dup2s the read end (slot 3) onto
        // the slot, raises done, parks.
        let script = "import os, sys, time\nwhile not os.path.exists(sys.argv[1]):\n    time.sleep(0.001)\nos.dup2(3, 1)\nopen(sys.argv[2], 'w').write('swapped\\\\n')\ntime.sleep(30)\n";
        let mut command = std::process::Command::new("python3");
        command
            .arg("-c")
            .arg(script)
            .arg(&flag_swap)
            .arg(&flag_done)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null());
        // SAFETY: dup2 + cloexec-clear pre-exec, no
        // userspace state touched.
        unsafe {
            command.pre_exec(move || {
                if libc::dup2(read_fd, 3) < 0 {
                    return Err(std::io::Error::last_os_error());
                }
                let flags = libc::fcntl(3, libc::F_GETFD);
                if flags < 0 {
                    return Err(std::io::Error::last_os_error());
                }
                if libc::fcntl(3, libc::F_SETFD, flags & !libc::FD_CLOEXEC) < 0 {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        let victim = command.spawn().expect("victim holder spawns");
        let vpid = victim.id() as libc::pid_t;
        let mut _vguard = FixtureGuard::new(vpid);
        let vtick = proc_starttime(vpid)
            .expect("victim stat readable")
            .expect("victim visible");
        // Non-vacuity: the victim genuinely holds the
        // collection write end at slot 1 (pre-swap) and the
        // read end at slot 3 (both ends of the same pipe —
        // the links agree, only the flags differ).
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            let slot1 =
                std::fs::read_link(format!("/proc/{vpid}/fd/1")).expect("victim slot readable");
            let slot3 = std::fs::read_link(format!("/proc/{vpid}/fd/3")).ok();
            let info1 = std::fs::read_to_string(format!("/proc/{vpid}/fdinfo/1")).ok();
            let info3 = std::fs::read_to_string(format!("/proc/{vpid}/fdinfo/3")).ok();
            let want = format!("pipe:[{}]", want_ino.1);
            if slot1.to_string_lossy() == want
                && slot3.is_some_and(|link| link.to_string_lossy() == want)
                && info1.is_some_and(|text| fdinfo_flags_grant_write(&text))
                && info3.is_some_and(|text| !fdinfo_flags_grant_write(&text))
            {
                break;
            }
            assert!(
                Instant::now() < end,
                "victim must hold write end at 1 + read end at 3 (non-vacuity)"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        // Steering state (the hook runs on this thread).
        struct Steer {
            fired: bool,
        }
        let state = std::cell::RefCell::new(Steer { fired: false });
        let (found, truncated) = extend_strays_with_pipe_writers_with(
            &[],
            Some(read_fd),
            None,
            Some(&|pid| {
                let mut state = state.borrow_mut();
                if state.fired {
                    return;
                }
                state.fired = true;
                assert_eq!(pid, vpid, "hook must fire for the victim only");
                // In-window end swap: raise the swap flag,
                // wait for the victim's done (bounded).
                std::fs::write(&flag_swap, "swap\n").expect("swap flag raises");
                let end = Instant::now() + Duration::from_secs(10);
                loop {
                    if flag_done.exists() {
                        break;
                    }
                    assert!(
                        Instant::now() < end,
                        "victim must complete the end swap (stage broken otherwise)"
                    );
                    std::thread::sleep(Duration::from_millis(1));
                }
                // Stage proof: the slot still names the SAME
                // pipe (fstat-path cannot exclude this swap)
                // but its flags are read-only now (only
                // fdinfo2 can).
                let slot = std::fs::read_link(format!("/proc/{vpid}/fd/1"))
                    .expect("swapped slot readable");
                assert_eq!(
                    slot.to_string_lossy().into_owned(),
                    format!("pipe:[{}]", want_ino.1),
                    "swap must stay on the same pipe"
                );
                let info = std::fs::read_to_string(format!("/proc/{vpid}/fdinfo/1"))
                    .expect("swapped fdinfo readable");
                assert!(
                    !fdinfo_flags_grant_write(&info),
                    "swapped slot must be read-only now"
                );
            }),
            &PipeScanBudget::default(),
        );
        assert!(
            state.borrow().fired,
            "hook must fire (victim must match identity)"
        );
        assert!(!truncated, "small fixture population must scan fully");
        // End-to-end: run the discovered pairs through the
        // production stray retire (NOFDINFO2: the stale write
        // identity + same-pipe slot equality attribute and
        // the victim dies here — gratuitously, since it
        // holds only the read end now).
        for (pid, tick) in &found {
            let _ = retire_stray_tree_best_effort(*pid, *tick, &[]);
        }
        // The victim survives with its status retained.
        assert_proc_settled_live(
            vpid,
            vtick,
            2,
            "end-swapped holder must survive discovery + retire",
        );
        // Cleanup: retire the victim ourselves and record
        // its status HERE (a concurrent wait — sibling
        // sweep or stale-discovery retire await — can
        // otherwise steal it; see drain_victim_status).
        drop(victim);
        // XRV1-F4: disarm ONLY on discharge (Reaped/Stolen)
        // — Unverifiable keeps cleanup custody (the guard
        // best-effort retires on the unwind below) and
        // fails inconclusive, never skipping a
        // possibly-live victim.
        let st = match drain_victim_status(vpid, vtick) {
            VictimDrain::Reaped(st) => {
                _vguard.disarm();
                st
            }
            VictimDrain::Stolen(evidence) => {
                _vguard.disarm();
                let _ = std::fs::remove_file(&flag_swap);
                let _ = std::fs::remove_file(&flag_done);
                eprintln!(
                    "skip: R19006-F16-THEFT victim status stolen by a concurrent \
                     waiter ({evidence}) — discovery verdicts above \
                     already green"
                );
                return;
            }
            VictimDrain::Unverifiable(evidence) => {
                let _ = std::fs::remove_file(&flag_swap);
                let _ = std::fs::remove_file(&flag_done);
                panic!(
                    "inconclusive (victim state unverifiable: {evidence}) — \
                     refusing to certify"
                );
            }
        };
        assert!(libc::WIFSIGNALED(st), "victim must die by our signal");
        let _ = std::fs::remove_file(&flag_swap);
        let _ = std::fs::remove_file(&flag_done);
    }

    /// R22-017: independent pidfd-grab capability gate —
    /// `pidfd_open(self)` + `pidfd_getfd` on an own fd
    /// must BOTH succeed. Direct-probe-positive tests
    /// (asserting `Some(true)`/`Some(false)`/`Holds`
    /// through the pidfd-pinned grab) skip loud when
    /// incapable — a pidfd-locked runner (Yama /
    /// deny-profile / old kernel) would otherwise fail
    /// in setup instead of exercising the unresolved
    /// path. The globally-denied regression below covers
    /// the unresolved legs without this gate.
    ///
    /// Kernel floor: 5.3 (pidfd_open) for the suite
    /// pervasively; 5.6 (pidfd_getfd) for the pinned-grab
    /// positives (old kernels were already out of scope —
    /// no per-test gating beyond the direct-probe
    /// positives). hidepid posture (unchanged): our own
    /// tasks stay stat-visible under every hidepid level.
    /// Residuals: (a) transient ambient EMFILE at gate
    /// time spuriously skips (loud — fail-closed);
    /// (b) a Yama-3 self-vs-child asymmetry (self-getfd
    /// passing while child-getfd fails) is untested here
    /// and would fail gated tests instead of skipping
    /// (no Yama-3 runner observed; seccomp / old-kernel /
    /// Yama-0-2 shapes are exact).
    fn pidfd_grab_capable() -> bool {
        use std::os::unix::io::AsRawFd as _;
        // Scratch fd (owned — validity certain; open
        // failure ⟹ incapable — fail-closed).
        let scratch = match std::fs::File::open("/dev/null") {
            Ok(file) => file,
            Err(_) => return false,
        };
        // SAFETY: direct syscalls; fds owned by this scope
        // (closed below on every path).
        let pidfd = match super::super::seccomp::pidfd_open_raw(std::process::id() as libc::pid_t) {
            Ok(fd) => fd,
            Err(_) => return false,
        };
        let grabbed = super::super::seccomp::pidfd_getfd_raw(pidfd, scratch.as_raw_fd());
        // SAFETY: both fds owned by this scope (the dup
        // only exists on success).
        unsafe {
            if let Ok(dup) = grabbed {
                libc::close(dup);
            }
            libc::close(pidfd);
        }
        grabbed.is_ok()
    }

    /// R21-004 (alternation leg): an alternating slot NEVER
    /// grants — mode+identity must describe ONE open file
    /// description. The alternator's slot 2 flips between
    /// the READ end of the WANTED pipe and the WRITE end of
    /// an unrelated pipe (free-running, no handshake — a
    /// write-grant on the wanted identity NEVER coincides
    /// in one description), while the strict probe samples
    /// the slot 500 times. RED (the 4-read shape): some
    /// sample forges (info1 mode from one phase, opened
    /// identity from the other — overwhelming over 500
    /// iterations). GREEN (pidfd-pinned grab): every grab
    /// is one consistent description — never a grant,
    /// structurally. Non-vacuity: both phases must be
    /// observed during the run (a static slot would never
    /// forge under EITHER shape), and the alternator must
    /// be alive at the end (a dead alternator is a static
    /// slot).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn alternating_slot_never_grants_write() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the Some(false) positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        // Wanted pipe (we keep the read end — the `want`
        // set; the write end is dropped — NOBODY holds a
        // wanted write end anywhere, so any grant is
        // doubly impossible) + unrelated pipe (its write
        // end is the alternating mode donor).
        let (read, write) = std::io::pipe().expect("wanted pipe");
        drop(write);
        let read_fd = read.as_raw_fd();
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "wanted pipe must identify");
        let wanted_ino = want[0].1;
        let (other_read, other_write) = std::io::pipe().expect("other pipe");
        let other_ino = pipe_dev_ino(other_read.as_raw_fd())
            .expect("other pipe identified")
            .1;
        assert_ne!(
            other_ino, wanted_ino,
            "pipes must be distinct (else the alternation is vacuous)"
        );
        // Alternator: slot 2 flips between fd 1 (read end
        // of the WANTED pipe — identity match, read-only)
        // and fd 0 (write end of the OTHER pipe — writable,
        // identity miss). Stdin/stdout carry the donors;
        // stderr starts null (clobbered by the first dup2).
        // Prebound dup2 + tight loop (fastest phase rate —
        // the RED forge needs phase flips inside the probe
        // window).
        let r_dup = read
            .try_clone()
            .expect("wanted read end clones for the alternator");
        let script = "import os\nd = os.dup2\nwhile True:\n    d(0, 2)\n    d(1, 2)\n";
        let alternator = std::process::Command::new("python3")
            .arg("-c")
            .arg(script)
            .stdin(std::process::Stdio::from(other_write))
            .stdout(std::process::Stdio::from(r_dup))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("alternator spawns");
        let apid = alternator.id() as libc::pid_t;
        let _aguard = FixtureGuard::new(apid);
        let atick = proc_starttime(apid)
            .expect("alternator stat readable")
            .expect("alternator visible");
        // Settle: slot 2 must be a PIPE before sampling
        // (stderr starts as /dev/null — mere existence
        // would settle before python starts; the first
        // dup2 lands in ms; bounded).
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            if let Ok(target) = std::fs::read_link(format!("/proc/{apid}/fd/2")) {
                if target.to_string_lossy().starts_with("pipe:[") {
                    break;
                }
            }
            assert!(Instant::now() < end, "alternator must reach its loop");
            std::thread::sleep(Duration::from_millis(1));
        }
        // Sample the slot 500 times (fresh readdir per
        // sample — production-shaped enumeration); record
        // every phase observed for the non-vacuity proof.
        let mut phases = std::collections::HashSet::new();
        for i in 0..500 {
            let fds = std::fs::read_dir(format!("/proc/{apid}/fd"))
                .expect("alternator fd table readable");
            let mut slot = None;
            for entry in fds.flatten() {
                if entry.file_name().to_string_lossy() == "2" {
                    slot = Some(entry);
                    break;
                }
            }
            let slot = slot.expect("slot 2 present every sample");
            // Phase sample (independent readlink — the
            // non-vacuity witness, not the verdict).
            if let Ok(target) = std::fs::read_link(slot.path()) {
                phases.insert(target.to_string_lossy().into_owned());
            }
            assert_eq!(
                fd_holds_wanted_write_end_strict(&slot, apid, &want, None),
                Some(false),
                "alternating slot must never grant (sample {i})"
            );
        }
        assert!(
            phases.contains(&format!("pipe:[{wanted_ino}]")),
            "non-vacuity: wanted phase observed ({phases:?})"
        );
        assert!(
            phases.contains(&format!("pipe:[{other_ino}]")),
            "non-vacuity: other phase observed ({phases:?})"
        );
        // The alternator must be alive (a dead alternator
        // is a static slot — vacuous).
        assert_proc_settled_live(apid, atick, 1, "alternator must survive sampling");
        // Cleanup: kill + reap (loud), drop the handle.
        assert!(
            retire_tick_gated_audit_child(apid, atick),
            "alternator retire readable"
        );
        assert!(
            await_proc_gone_reaping(apid, atick, Duration::from_secs(5)),
            "alternator must drain"
        );
        let _ = alternator;
        drop(other_read);
    }

    /// R21-004 (unavailability leg): a pidfd-unavailable
    /// probe stays UNRESOLVED — never the racy grant, never
    /// a false non-holder. A genuine holder (sleep + write
    /// end, duration 959) probes `Some(true)` unfiltered
    /// (baseline non-vacuity), `None` under a pidfd_open
    /// denial on this thread (skip loud when seccomp is
    /// unavailable), `Some(true)` again on an unfiltered
    /// helper thread (the hold persists — the `None` was
    /// unavailability, not non-holdership), and `None` on
    /// a pidfd_getfd-only-denied helper thread (the
    /// Yama/permission shape: open succeeds, grab fails).
    /// The bool discovery form folds `None` to `false`
    /// (unattributed — never killed by number).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pidfd_unavailable_probe_stays_unresolved() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the baseline Some(true) is unverifiable;
        // the globally-denied regression covers the
        // unresolved legs without this gate).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        // The seccomp-skip early return below retires via
        // the FixtureGuard drop (the skip means NO filter
        // was installed — the thread is unfiltered, so the
        // guard's pidfd-based drop works); every other
        // path reaps inline.
        #[allow(clippy::zombie_processes)]
        let holder = std::process::Command::new("/bin/sleep")
            .arg("959")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let mut hguard = FixtureGuard::new(hpid);
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "collection pipe must identify");
        // Each thread re-enumerates (no DirEntry crosses
        // threads).
        let probe_slot = |pid: libc::pid_t| -> Option<bool> {
            let fds =
                std::fs::read_dir(format!("/proc/{pid}/fd")).expect("holder fd table readable");
            for entry in fds.flatten() {
                if entry.file_name().to_string_lossy() == "1" {
                    return fd_holds_wanted_write_end_strict(&entry, pid, &want, None);
                }
            }
            panic!("holder slot 1 present");
        };
        // Baseline (unfiltered): genuine hold grants.
        assert_eq!(
            probe_slot(hpid),
            Some(true),
            "baseline: genuine holder must grant unfiltered"
        );
        // Legs 2+3 run BEFORE the denial install below
        // (seccomp filters inherit at clone — a helper
        // spawned after the install would inherit the
        // open-deny and could never be unfiltered or
        // getfd-only-denied).
        // Leg 2: unfiltered helper — the hold persists
        // (the denied `None` later is unavailability, not
        // non-holdership). Scoped (borrows `want`).
        let confirmed = std::thread::scope(|scope| {
            scope
                .spawn(|| {
                    let fds = std::fs::read_dir(format!("/proc/{hpid}/fd"))
                        .expect("holder fd table readable");
                    for entry in fds.flatten() {
                        if entry.file_name().to_string_lossy() == "1" {
                            return fd_holds_wanted_write_end_strict(&entry, hpid, &want, None);
                        }
                    }
                    panic!("holder slot 1 present");
                })
                .join()
                .expect("helper joins")
        });
        assert_eq!(
            confirmed,
            Some(true),
            "hold must persist (denied-None was unavailability)"
        );
        // Leg 3: getfd-only denial (the Yama/permission
        // shape — open succeeds, grab fails EPERM). Scoped
        // (borrows `want`).
        let grabbed = std::thread::scope(|scope| {
            scope
                .spawn(|| -> Option<Option<bool>> {
                    use super::super::seccomp::{install_deny_one, DenyAction};
                    if install_deny_one(libc::SYS_pidfd_getfd, DenyAction::Eperm).is_err() {
                        eprintln!("skip: seccomp unavailable (no getfd denial)");
                        return None;
                    }
                    let fds = std::fs::read_dir(format!("/proc/{hpid}/fd"))
                        .expect("holder fd table readable");
                    for entry in fds.flatten() {
                        if entry.file_name().to_string_lossy() == "1" {
                            return Some(fd_holds_wanted_write_end_strict(
                                &entry, hpid, &want, None,
                            ));
                        }
                    }
                    panic!("holder slot 1 present");
                })
                .join()
                .expect("helper joins")
        });
        // `None` = filter unavailable (skip loud above —
        // leg vacuous this run); `Some(v)` = denied, must
        // stay unresolved.
        match grabbed {
            None => eprintln!("note: getfd-deny filter unavailable (leg 3 vacuous this run)"),
            Some(verdict) => assert_eq!(
                verdict, None,
                "RED: getfd-denied probe must stay unresolved"
            ),
        }
        // Leg 1: pidfd_open denied on THIS thread (seccomp
        // is per-thread permanent — installed last, after
        // the helpers joined; skip loud when unavailable —
        // the guard below still retires the holder).
        {
            use super::super::seccomp::{install_deny_one, DenyAction};
            if install_deny_one(libc::SYS_pidfd_open, DenyAction::Eperm).is_err() {
                eprintln!("skip: seccomp unavailable (no pidfd denial)");
                return;
            }
        }
        assert_eq!(
            probe_slot(hpid),
            None,
            "RED: pidfd_open-denied probe must stay unresolved (never grant, never false-deny)"
        );
        // Cleanup under the pidfd_open denial: the suite's
        // tick-gated retires need pidfd (fail EPERM here),
        // so kill + reap by number — reservation-sound
        // (hpid is our unreaped child — the number cannot
        // recycle while we hold it). Then disarm (the
        // guard's pidfd-based drop must not run denied).
        // SAFETY: SIGKILL to our own unreaped child.
        assert_eq!(
            unsafe { libc::kill(hpid, libc::SIGKILL) },
            0,
            "holder signaled"
        );
        let end = Instant::now() + Duration::from_secs(5);
        let mut reaped = None;
        loop {
            let mut st = 0;
            // SAFETY: WNOHANG reap of our own killed child.
            if unsafe { libc::waitpid(hpid, &mut st, libc::WNOHANG) } == hpid {
                reaped = Some(st);
            }
            if proc_starttime(hpid) != Ok(Some(htick)) {
                break;
            }
            assert!(Instant::now() < end, "holder must drain");
            std::thread::sleep(Duration::from_millis(1));
        }
        let st = reaped.expect("holder status must drain to us");
        assert!(libc::WIFSIGNALED(st), "holder must die by our signal");
        hguard.disarm();
        let _ = holder;
    }

    /// R22-017 global-denial regression probe (fresh
    /// image): seccomp-deny BOTH pidfd syscalls for the
    /// whole probe (the globally-denied shape), then:
    /// (a) the denial bites (direct pidfd_open is EPERM —
    /// anti-vacuity); (b) the capability gate reports
    /// INCAPABLE (gate-negative leg); (c) the strict
    /// probe reports None over a genuine holder
    /// (unresolved — never a false grant, never a false
    /// non-hold); (d) the bool fold reports false
    /// (unattributed — never killed by number). Custody:
    /// FixtureGuard at birth (disarmed after numeric
    /// kill+reap — the guard's pidfd-based drop must not
    /// run denied) PLUS a printed birth for wrapper-side
    /// backstop (a staging panic before disarm would
    /// otherwise strand past the denied drop). Duration
    /// 900 is unique to this test. R23-002: x86-gated
    /// (uses `FixtureGuard`/`proc_starttime`; the wrapper
    /// is x86-gated, so the name-spawn never fires
    /// elsewhere).
    #[cfg(target_arch = "x86_64")]
    fn pidfd_globally_denied_probe_stays_unresolved_probe() {
        use super::super::seccomp::{install_deny_one, DenyAction};
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        install_deny_one(libc::SYS_pidfd_open, DenyAction::Eperm).expect("deny open installs");
        install_deny_one(libc::SYS_pidfd_getfd, DenyAction::Eperm).expect("deny getfd installs");
        // Anti-vacuity: the denial bites.
        assert_eq!(
            super::super::seccomp::pidfd_open_raw(std::process::id() as libc::pid_t),
            Err(libc::EPERM),
            "staging broken (pidfd_open not denied?)"
        );
        // Gate-negative leg.
        assert!(
            !pidfd_grab_capable(),
            "RED: gate must report incapable under pidfd denial"
        );
        eprintln!("R22017-GATE-INCAPABLE");
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let holder = std::process::Command::new("/bin/sleep")
            .arg("900")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let mut hguard = FixtureGuard::new(hpid);
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        println!("R22017-HOLDER {hpid} {htick}");
        std::io::Write::flush(&mut std::io::stdout()).expect("custody line flushed");
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "collection pipe must identify");
        let fds = std::fs::read_dir(format!("/proc/{hpid}/fd")).expect("holder fd table readable");
        let mut slot = None;
        for entry in fds.flatten() {
            if entry.file_name().to_string_lossy() == "1" {
                slot = Some(entry);
                break;
            }
        }
        let slot = slot.expect("holder slot 1 present");
        // Unresolved legs (the strict probe + bool fold
        // under global denial).
        assert_eq!(
            fd_holds_wanted_write_end_strict(&slot, hpid, &want, None),
            None,
            "RED: denied probe must stay unresolved (never grant, never false-deny)"
        );
        eprintln!("R22017-PROBE-NONE");
        assert!(
            !fd_holds_wanted_write_end(&slot, hpid, &want, None),
            "denied fold must stay unattributed (false)"
        );
        eprintln!("R22017-FOLD-FALSE");
        // Cleanup under denial: numeric kill + reap by
        // number (own unreaped child — no pidfd needed),
        // then disarm (pidfd-based drop must not run).
        // SAFETY: SIGKILL to our own unreaped child.
        assert_eq!(
            unsafe { libc::kill(hpid, libc::SIGKILL) },
            0,
            "holder signaled"
        );
        let end = Instant::now() + Duration::from_secs(5);
        let mut reaped = None;
        loop {
            let mut st = 0;
            // SAFETY: WNOHANG reap of our own killed child.
            if unsafe { libc::waitpid(hpid, &mut st, libc::WNOHANG) } == hpid {
                reaped = Some(st);
            }
            if proc_starttime(hpid) != Ok(Some(htick)) {
                break;
            }
            assert!(Instant::now() < end, "holder must drain");
            std::thread::sleep(Duration::from_millis(1));
        }
        let st = reaped.expect("holder status must drain to us");
        assert!(libc::WIFSIGNALED(st), "holder must die by our signal");
        hguard.disarm();
        let _ = holder;
        eprintln!("R22017-DONE");
    }

    /// R22-017 global-denial regression wrapper: the probe
    /// runs fresh-image (seccomp is irreversible) and
    /// green-lights the unresolved legs in a
    /// globally-denied env (no capability gate HERE —
    /// this test must RUN, not skip, where pidfd is
    /// gone). Wrapper-side custody (printed birth,
    /// tick-gated) backstops a staging panic before the
    /// probe's disarm; it no-ops on the clean path (the
    /// probe self-reaps).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pidfd_globally_denied_probe_stays_unresolved() {
        if std::env::var("SCOPEBASE_R22017_DENIED").is_ok() {
            pidfd_globally_denied_probe_stays_unresolved_probe();
            return;
        }
        let outcome = run_fresh_probe_collect(
            "SCOPEBASE_R22017_DENIED",
            "pidfd_globally_denied_probe_stays_unresolved",
        );
        let stdout = String::from_utf8_lossy(&outcome.out.stdout).into_owned();
        let stderr = String::from_utf8_lossy(&outcome.out.stderr).into_owned();
        // Backstop custody (optional line: the probe may
        // die before staging — e.g. the gate-negative
        // RED — in which case nothing needs draining and
        // the verdicts below surface the probe's
        // failure).
        if let Some((hpid, htick)) = stdout.lines().find_map(|line| {
            let rest = line.strip_prefix("R22017-HOLDER ")?;
            let (pid, tick) = rest.split_once(' ')?;
            let pid: libc::pid_t = pid.parse().ok()?;
            let tick: u64 = tick.parse().ok()?;
            Some((pid, tick))
        }) {
            kill_tick_gated(hpid, htick);
            assert!(
                await_proc_gone_reaping(hpid, htick, std::time::Duration::from_secs(5)),
                "wrapper must drain the holder"
            );
        }
        assert!(!outcome.timed_out, "probe must complete\n{stderr}");
        assert!(outcome.out.status.success(), "probe must exit 0\n{stderr}");
        assert!(
            stderr.contains("R22017-GATE-INCAPABLE"),
            "probe must pin gate-incapable\n{stderr}"
        );
        assert!(
            stderr.contains("R22017-PROBE-NONE"),
            "probe must pin strict-None\n{stderr}"
        );
        assert!(
            stderr.contains("R22017-FOLD-FALSE"),
            "probe must pin fold-false\n{stderr}"
        );
        assert!(
            stderr.contains("R22017-DONE"),
            "probe must cite completion\n{stderr}"
        );
    }

    /// R22-017 wiring audit: every direct-probe-positive
    /// test calls the capability gate (a refactor that
    /// drops a gate call fails here instead of failing
    /// locked runners in setup). The ten: R21-004 ×2
    /// (direct Some(false)/Some(true)), R19-006 ×2
    /// (discovery attribution halves), bigtable (R21-013;
    /// Holds/Shed controls), R21-003 + R22-010/011 frame
    /// tests ×5 (pre-prove Holds + Holds cells).
    #[test]
    fn pidfd_capability_gates_wired() {
        let root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        let audit_rs = std::fs::read_to_string(root.join("src/fixture/linux/audit.rs"))
            .expect("audit.rs readable");
        for name in [
            "alternating_slot_never_grants_write",
            "pidfd_unavailable_probe_stays_unresolved",
            "discovery_verifies_slot_across_mode_read",
            "discovery_mode_reread_excludes_same_pipe_end_swap",
            "reverify_budget_bounds_bigtable_and_reports",
            "retire_frame_shed_during_snapshot_survives",
            "retire_frame_shed_first_writer_second_retires_writer",
            "retire_frame_expired_deadline_entry_kills_nothing",
            "retire_frame_exhausted_screen_remainder_kills_nothing",
            "retire_frame_screen_spends_aggregate_across_family",
        ] {
            let head = format!("    fn {name}(");
            let start = audit_rs
                .find(&head)
                .unwrap_or_else(|| panic!("gated test {name} must exist (anti-vacuity)"));
            let rest = &audit_rs[start..];
            let tail = rest[head.len()..].find("\n    fn ").unwrap_or_else(|| {
                panic!("gated test {name} body must end at a sibling fn (anti-vacuity)")
            });
            let body = &rest[..head.len() + tail];
            assert!(
                body.len() > 500,
                "gated test {name} body implausibly small (extraction broken?)"
            );
            assert!(
                body.contains("pidfd_grab_capable()"),
                "RED: gated test {name} must call pidfd_grab_capable()"
            );
        }
    }

    /// R19-009: pipe-holder discovery is budgeted — the walk
    /// covers every readable process's whole fd table, so an
    /// unrelated process with a large table must truncate the
    /// scan (never silently certify a partial set, never hang
    /// the expiry prefix). An fd-holder parks with N open
    /// /dev/null fds (best-effort rlimit raise, count-checked —
    /// skip loud below 2000); a tight visited-budget reports
    /// truncated with a found-subset of the ample-budget scan
    /// (truncation removes, never invents — order-independent);
    /// an ample budget scans fully with exact pairs; the
    /// shipped default fits the 20k population; an expired
    /// deadline truncates at once with nothing found; a zero
    /// cap scans nothing. STUB-RED (this shape): detection
    /// unimplemented (always false) and the tight case
    /// fails. GREEN: all five cells hold.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn discovery_scan_budget_truncates_loud() {
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        let _pop = DISCOVERY_POPULATION_SERIAL
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Collection pipe: we keep the READ end; one KNOWN
        // writer holds the write end (the ample scan must
        // attribute exactly it).
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let writer = std::process::Command::new("/bin/sleep")
            .arg("918")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        // R21-009: guard at birth (before the fallible
        // first read — R20-014 armed it after).
        let _wguard = FixtureGuard::new(wpid);
        // R21-009 fault: fail the first observation (reads
        // dead at the stat below — the `.expect` panics
        // and the guard must unwind-retire before it).
        // Birth captured healthy first (birth-aware
        // wrapper check). Declared AFTER the guard (drops
        // first — restores reads before the retire
        // re-verifies).
        let _fault = std::env::var("SCOPEBASE_R21009_R20014_WRITER_FAIL")
            .is_ok()
            .then(|| {
                let tick = proc_starttime(wpid)
                    .expect("pre-fault birth readable")
                    .expect("pre-fault writer visible");
                eprintln!("R21009-WRITER pid={wpid} tick={tick}");
                let confined = confine_fd_table_for_exhaustion();
                let mut held = Vec::new();
                while let Ok(file) = std::fs::File::open("/dev/null") {
                    held.push(file);
                }
                assert!(!held.is_empty(), "fault exhaustion must consume fds");
                (confined, held)
            });
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        drop(_fault);
        assert!(
            _wguard.tick.is_some(),
            "writer custody must pin (stage broken otherwise)"
        );
        // Fd-holder: best-effort rlimit raise, then N
        // /dev/null fds, report the count, park.
        // R20-014: the report opens FIRST (held handle) —
        // opening after the fill EMFILEs under a
        // below-`want` limit (no report, no sleep, the
        // harness loop panics); writes through the held
        // handle need no new fd (explicit flush — the
        // handle stays open across the park).
        let script = "import os, resource, sys, time\nwant = int(sys.argv[1])\nreport = open(sys.argv[2], 'w')\ntry:\n    hard = resource.getrlimit(resource.RLIMIT_NOFILE)[1]\n    resource.setrlimit(resource.RLIMIT_NOFILE, (hard, hard))\nexcept Exception:\n    pass\nfds = []\nfor _ in range(want):\n    try:\n        fds.append(os.open('/dev/null', os.O_RDONLY))\n    except OSError:\n        break\nreport.write(str(len(fds)))\nreport.flush()\ntime.sleep(30)\n";
        let me = std::process::id();
        let dir = std::env::temp_dir();
        let flag_count = dir.join(format!("scopebase-r19009-count-{me}"));
        let _ = std::fs::remove_file(&flag_count);
        let mut holder_cmd = std::process::Command::new("python3");
        holder_cmd
            .arg("-c")
            .arg(script)
            .arg("20000")
            .arg(&flag_count)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        // R20-014: confinement injection — clamp the
        // holder to 1024 fds (soft AND hard, so the
        // script's own raise-to-hard caps there too).
        if std::env::var("SCOPEBASE_R20014_CONFINE").is_ok() {
            // SAFETY: setrlimit on self pre-exec, no userspace state.
            unsafe {
                holder_cmd.pre_exec(|| {
                    let lim = libc::rlimit {
                        rlim_cur: 1024,
                        rlim_max: 1024,
                    };
                    if libc::setrlimit(libc::RLIMIT_NOFILE, &lim) != 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                    Ok(())
                });
            }
        }
        let holder = holder_cmd.spawn().expect("fd-holder spawns");
        let hpid = holder.id() as libc::pid_t;
        // R20-014: unwind backstop (a report-loop panic
        // must not strand the holder mid-fill).
        let _hguard = FixtureGuard::new(hpid);
        assert!(
            _hguard.tick.is_some(),
            "holder custody must pin (stage broken otherwise)"
        );
        // Bounded count report; below 2000 the table cannot
        // isolate the tight budget (skip loud after cleanup).
        let end = Instant::now() + Duration::from_secs(30);
        let opened: usize = loop {
            if let Ok(text) = std::fs::read_to_string(&flag_count) {
                if let Ok(parsed) = text.trim().parse() {
                    break parsed;
                }
            }
            assert!(
                Instant::now() < end,
                "holder must report its fd count (stage broken otherwise)"
            );
            std::thread::sleep(Duration::from_millis(10));
        };
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        // Owned-child cleanup (kill gated, status drains to
        // us — the R19-005/006 self-reap discipline).
        let kill_and_reap = |pid: libc::pid_t, tick: u64, what: &str| {
            let _ = kill_tick_gated(pid, tick);
            let end = Instant::now() + Duration::from_secs(10);
            let mut reaped = None;
            loop {
                let mut st = 0;
                // SAFETY: WNOHANG assist only — our child.
                if unsafe { libc::waitpid(pid, &mut st, libc::WNOHANG) } == pid {
                    reaped = Some(st);
                }
                if proc_starttime(pid) != Ok(Some(tick)) {
                    break;
                }
                assert!(Instant::now() < end, "{what} must die");
                std::thread::sleep(Duration::from_millis(10));
            }
            let st = reaped.expect("status must drain to us (retained, never stolen)");
            assert!(libc::WIFSIGNALED(st), "{what} must die by our signal");
        };
        if opened < 2000 {
            kill_and_reap(hpid, htick, "fd-holder");
            kill_and_reap(wpid, wtick, "writer");
            drop(holder);
            drop(writer);
            let _ = std::fs::remove_file(&flag_count);
            eprintln!("skip: fd table too small ({opened} < 2000 — no budget isolation)");
            return;
        }
        // Non-vacuity: the table is really there (counted
        // our way — readdir, not trust).
        let table = std::fs::read_dir(format!("/proc/{hpid}/fd"))
            .expect("holder table readable")
            .count();
        assert!(
            table >= opened,
            "holder table must show the reported fds ({table} >= {opened})"
        );
        // Cell 1 (ample): full scan, exact pairs, bounded
        // wall (generous anti-hang bound, not a benchmark).
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let start = Instant::now();
        let (full, full_trunc) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &ample);
        let full_elapsed = start.elapsed();
        assert!(!full_trunc, "ample budget must scan fully");
        assert_eq!(
            full,
            vec![(wpid, wtick)],
            "ample scan attributes exactly the known writer"
        );
        assert!(
            full_elapsed < Duration::from_secs(30),
            "ample scan must stay bounded ({full_elapsed:?})"
        );
        // Cell 2 (default): the shipped budget fits this
        // population (20k < 100k cap — pins the default
        // against shrinking below fixture reality; the
        // population lock excludes the 150k neighbor).
        let (defaulted, default_trunc) = extend_strays_with_pipe_writers_with(
            &[],
            Some(read_fd),
            None,
            None,
            &PipeScanBudget::default(),
        );
        assert!(!default_trunc, "default budget must fit a 20k table");
        assert_eq!(
            defaulted, full,
            "default scan must agree with the ample scan"
        );
        // Cell 3 (tight): truncation + subset property
        // (truncation removes, never invents). The trip is
        // guaranteed: the holder's table alone exceeds
        // quadruple the budget, whatever the walk order.
        let tight = PipeScanBudget {
            max_visited_fds: opened / 4,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let (partial, partial_trunc) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &tight);
        assert!(
            partial_trunc,
            "tight budget must report truncation (never silent)"
        );
        for pair in &partial {
            assert!(
                full.contains(pair),
                "truncated scan must only remove, never invent: {pair:?}"
            );
        }
        // Cell 4 (expired deadline): immediate truncation,
        // nothing scanned.
        let spent = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() - Duration::from_secs(1),
        };
        let (none, none_trunc) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &spent);
        assert!(none_trunc, "expired deadline must truncate at once");
        assert!(none.is_empty(), "expired deadline must scan nothing");
        // Cell 5 (zero cap): likewise scans nothing.
        let zero = PipeScanBudget {
            max_visited_fds: 0,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let (nil, nil_trunc) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &zero);
        assert!(nil_trunc, "zero cap must truncate at once");
        assert!(nil.is_empty(), "zero cap must scan nothing");
        // Cleanup: both owned children reaped by us.
        kill_and_reap(hpid, htick, "fd-holder");
        kill_and_reap(wpid, wtick, "writer");
        drop(holder);
        drop(writer);
        let _ = std::fs::remove_file(&flag_count);
    }

    /// R21-013: retire-time re-verification shares the
    /// expiry's scan budget — a truncated walk reports
    /// `Unverifiable` (never partial-Shed), a hit reports
    /// `Holds` at once, and only a COMPLETE walk without a
    /// hit reports `Shed`. Seven cells: Holds/Shed controls
    /// (genuine verdicts under ample budget), tight cap
    /// (truncation + exact spend), expired deadline and zero
    /// cap (scan nothing — the deadline wins even over a
    /// held end), enlarged table (150k + default budget →
    /// Unverifiable at exactly the 100k cap), and
    /// shared-spent (two calls, one counter — the second
    /// truncates on the first's remainder, mirroring the
    /// frame loop). A moved end is covered by the removed
    /// shape (`want` names the pipe's (dev, ino), not the
    /// slot — a dup keeps the identity, a close drops it).
    /// Pre-fix RED: the uncapped walk returns Shed/Holds
    /// and ignores the budget (cells 3-7 fail). Duration 953
    /// is unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn reverify_budget_bounds_bigtable_and_reports() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the Holds/Shed controls are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        // R22-013: serialize with the discovery population
        // (R19-009 precedent — one-sided exclusion is
        // broken: our 150k table would otherwise overlap
        // `discovery_scan_budget_truncates_loud`'s
        // default-budget complete-discovery assert and
        // truncate its scan). Bound first (drops last —
        // every holder/guard below dies before release)
        // and held for the holders' whole lifetime.
        let _pop = DISCOVERY_POPULATION_SERIAL
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Collection pipe: we keep the READ end; one KNOWN
        // writer holds the write end.
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let writer = std::process::Command::new("/bin/sleep")
            .arg("953")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let _wguard = FixtureGuard::new(wpid);
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        // Fd-holders: best-effort rlimit raise, then N
        // /dev/null fds, report the count, park (the R19-009
        // script shape — report handle opened FIRST so a
        // below-`want` limit still reports).
        let script = "import os, resource, sys, time\nwant = int(sys.argv[1])\nreport = open(sys.argv[2], 'w')\ntry:\n    hard = resource.getrlimit(resource.RLIMIT_NOFILE)[1]\n    resource.setrlimit(resource.RLIMIT_NOFILE, (hard, hard))\nexcept Exception:\n    pass\nfds = []\nfor _ in range(want):\n    try:\n        fds.append(os.open('/dev/null', os.O_RDONLY))\n    except OSError:\n        break\nreport.write(str(len(fds)))\nreport.flush()\ntime.sleep(60)\n";
        let me = std::process::id();
        let dir = std::env::temp_dir();
        let stage_holder = |tag: &str, want: usize, bound_secs: u64| {
            let flag = dir.join(format!("scopebase-r21013-{tag}-{me}"));
            let _ = std::fs::remove_file(&flag);
            let holder = std::process::Command::new("python3")
                .arg("-c")
                .arg(script)
                .arg(want.to_string())
                .arg(&flag)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("fd-holder spawns");
            let hpid = holder.id() as libc::pid_t;
            let _hguard = FixtureGuard::new(hpid);
            let end = Instant::now() + Duration::from_secs(bound_secs);
            let opened: usize = loop {
                if let Ok(text) = std::fs::read_to_string(&flag) {
                    if let Ok(parsed) = text.trim().parse() {
                        break parsed;
                    }
                }
                assert!(
                    Instant::now() < end,
                    "holder must report its fd count (stage broken otherwise)"
                );
                std::thread::sleep(Duration::from_millis(10));
            };
            let htick = proc_starttime(hpid)
                .expect("holder stat readable")
                .expect("holder visible");
            (holder, _hguard, hpid, htick, opened, flag)
        };
        let (holder20k, _guard20k, hpid, htick, opened, flag_count) =
            stage_holder("count", 20_000, 30);
        // Owned-child cleanup (kill gated, status drains to
        // us — the R19-005/006 self-reap discipline).
        let kill_and_reap = |pid: libc::pid_t, tick: u64, what: &str| {
            let _ = kill_tick_gated(pid, tick);
            let end = Instant::now() + Duration::from_secs(10);
            let mut reaped = None;
            loop {
                let mut st = 0;
                // SAFETY: WNOHANG assist only — our child.
                if unsafe { libc::waitpid(pid, &mut st, libc::WNOHANG) } == pid {
                    reaped = Some(st);
                }
                if proc_starttime(pid) != Ok(Some(tick)) {
                    break;
                }
                assert!(Instant::now() < end, "{what} must die");
                std::thread::sleep(Duration::from_millis(10));
            }
            let st = reaped.expect("status must drain to us (retained, never stolen)");
            assert!(libc::WIFSIGNALED(st), "{what} must die by our signal");
        };
        if opened < 2000 {
            kill_and_reap(hpid, htick, "fd-holder");
            kill_and_reap(wpid, wtick, "writer");
            drop(holder20k);
            drop(writer);
            let _ = std::fs::remove_file(&flag_count);
            eprintln!("skip: fd table too small ({opened} < 2000 — no budget isolation)");
            return;
        }
        let (holder150k, _guard150k, bpid, btick, bopened, flag_big) =
            stage_holder("big", 150_000, 60);
        if bopened < 120_000 {
            kill_and_reap(hpid, htick, "fd-holder");
            kill_and_reap(bpid, btick, "big-holder");
            kill_and_reap(wpid, wtick, "writer");
            drop(holder20k);
            drop(holder150k);
            drop(writer);
            let _ = std::fs::remove_file(&flag_count);
            let _ = std::fs::remove_file(&flag_big);
            eprintln!("skip: big table too small ({bopened} < 120000 — default cap untrippable)");
            return;
        }
        // Non-vacuity: the tables are really there (counted
        // our way — flatten, the walk's own iterator shape).
        let table20k = std::fs::read_dir(format!("/proc/{hpid}/fd"))
            .expect("holder table readable")
            .flatten()
            .count();
        assert!(
            table20k >= opened,
            "holder table must show the reported fds ({table20k} >= {opened})"
        );
        let table150k = std::fs::read_dir(format!("/proc/{bpid}/fd"))
            .expect("big table readable")
            .flatten()
            .count();
        assert!(
            table150k >= bopened,
            "big table must show the reported fds ({table150k} >= {bopened})"
        );
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "collection pipe must identify");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        // Cell 1 (Holds control): the known writer holds a
        // wanted end — positive evidence at once.
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(wpid, wtick, &want, &ample, &mut spent),
            HoldVerdict::Holds,
            "known writer must verify Holds"
        );
        // Cell 2 (Shed control): the 20k holder never held
        // the end — a COMPLETE walk finds nothing (exact
        // spend proves the walk ran to the end).
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &ample, &mut spent),
            HoldVerdict::Shed,
            "end-absent holder must verify Shed under ample budget"
        );
        assert_eq!(
            spent, table20k,
            "complete walk must visit every fd exactly once"
        );
        // Cell 3 (tight cap): truncation reports
        // Unverifiable (never partial-Shed) with the spend
        // stopping AT the cap. The trip is guaranteed: the
        // table alone is quadruple the budget, whatever the
        // walk order.
        let tight = PipeScanBudget {
            max_visited_fds: opened / 4,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &tight, &mut spent),
            HoldVerdict::Unverifiable,
            "tight budget must truncate to Unverifiable (never Shed)"
        );
        assert_eq!(
            spent,
            opened / 4,
            "truncated walk must stop at the cap exactly"
        );
        // Cell 4 (expired deadline): scans nothing — the
        // deadline wins even over a HELD end (fail-closed).
        let spent_budget = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() - Duration::from_secs(1),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(wpid, wtick, &want, &spent_budget, &mut spent),
            HoldVerdict::Unverifiable,
            "expired deadline must truncate at once"
        );
        assert_eq!(spent, 0, "expired deadline must scan nothing");
        // Cell 5 (zero cap): likewise scans nothing.
        let zero = PipeScanBudget {
            max_visited_fds: 0,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(wpid, wtick, &want, &zero, &mut spent),
            HoldVerdict::Unverifiable,
            "zero cap must truncate at once"
        );
        assert_eq!(spent, 0, "zero cap must scan nothing");
        // Cell 6 (enlarged table): 150k fds under the shipped
        // default budget — the walk truncates (cap or
        // deadline, whichever bites first under load) to an
        // explicitly-unresolved skip (the finding's headline:
        // unbounded seconds become bounded). Cap-exactness is
        // pinned deterministically by cell 3; here the bound
        // (never over cap) is the assertion.
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(bpid, btick, &want, &PipeScanBudget::default(), &mut spent),
            HoldVerdict::Unverifiable,
            "default budget must truncate on a 150k table"
        );
        assert!(
            spent <= 100_000,
            "default walk must never exceed the 100k cap (spent {spent})"
        );
        if spent < 100_000 {
            eprintln!("cell 6 truncated by deadline at {spent} (cap-trip needs <1s/100k)");
        }
        // Cell 7 (shared spent): two calls, one counter —
        // the second truncates on the first's remainder
        // (mirrors the frame loop; the remainder tightens).
        let shared = PipeScanBudget {
            max_visited_fds: table20k + 10,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &shared, &mut spent),
            HoldVerdict::Shed,
            "first shared call must complete (Shed)"
        );
        assert_eq!(spent, table20k, "first call must spend its table");
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &shared, &mut spent),
            HoldVerdict::Unverifiable,
            "second shared call must truncate on the remainder"
        );
        assert_eq!(
            spent,
            table20k + 10,
            "shared counter must accumulate across calls"
        );
        // Cleanup: all owned children reaped by us.
        kill_and_reap(hpid, htick, "fd-holder");
        kill_and_reap(bpid, btick, "big-holder");
        kill_and_reap(wpid, wtick, "writer");
        drop(holder20k);
        drop(holder150k);
        drop(writer);
        let _ = std::fs::remove_file(&flag_count);
        let _ = std::fs::remove_file(&flag_big);
    }

    /// R22-013: the bigtable regression stages its 150k
    /// fd-holder under `DISCOVERY_POPULATION_SERIAL`
    /// (bound before the first spawn, held to fn end —
    /// the R19-009 precedent): without it the holder's
    /// table overlaps
    /// `discovery_scan_budget_truncates_loud`'s
    /// default-budget complete-discovery assert
    /// (one-sided exclusion is broken — the holder must
    /// serialize too, not just the control). Structural
    /// pin (a behavioral overlap race is nondeterministic
    /// by nature — the suite-green pairing of both tests
    /// is the behavioral leg): the bigtable body must
    /// bind `_pop` from the serial BEFORE the first
    /// holder spawn and never drop it early (held-to-end
    /// covers the holders' whole lifetime — guards and
    /// explicit kills all land before fn end, and `_pop`
    /// is declared first so it drops last). RED: no
    /// acquisition in the body.
    #[test]
    fn bigtable_holder_serial_exclusion_audited() {
        let root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        let audit_rs = std::fs::read_to_string(root.join("src/fixture/linux/audit.rs"))
            .expect("audit.rs readable");
        let head = "    fn reverify_budget_bounds_bigtable_and_reports() {";
        let start = audit_rs
            .find(head)
            .expect("bigtable test must exist (anti-vacuity)");
        let rest = &audit_rs[start..];
        let tail = rest[head.len()..]
            .find("\n    fn ")
            .expect("bigtable body must end at a sibling fn (anti-vacuity)");
        let body = &rest[..head.len() + tail];
        assert!(
            body.len() > 3000,
            "bigtable body implausibly small (extraction broken?)"
        );
        assert!(
            body.contains("stage_holder(\"big\""),
            "bigtable body must stage the 150k holder (anti-vacuity)"
        );
        let acquire = body
            .find("_pop = DISCOVERY_POPULATION_SERIAL")
            .expect("RED: bigtable must acquire DISCOVERY_POPULATION_SERIAL");
        let first_spawn = body
            .find("stage_holder(\"count\"")
            .expect("bigtable body must stage the count holder (anti-vacuity)");
        assert!(
            acquire < first_spawn,
            "RED: serial must be bound BEFORE the first holder spawn"
        );
        assert!(
            !body.contains("drop(_pop"),
            "serial must be held to fn end (never dropped early)"
        );
    }

    /// R21-002(a) outage probe (fresh image only — the
    /// wrapper spawns this with `SCOPEBASE_R21002_OUTAGE`;
    /// a direct run skips loud): stage a holder of a wanted
    /// write end, exhaust OUR fd table (genuine EMFILE —
    /// the first bracket read fails), call reverify, and
    /// report the verdict + birth. `Unverifiable` is the
    /// survival proof (the frame skips it; only
    /// Holds/NotOurs retire — and reverify itself never
    /// kills, so the live holder provably survives the
    /// faulted call). Duration 954 is unique to this probe.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn reverify_outage_probe() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        if std::env::var("SCOPEBASE_R21002_OUTAGE").is_err() {
            eprintln!("skip: probe needs SCOPEBASE_R21002_OUTAGE=1 (run the wrapper)");
            return;
        }
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let writer = std::process::Command::new("/bin/sleep")
            .arg("954")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let _wguard = FixtureGuard::new(wpid);
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "collection pipe must identify");
        // Genuine outage: confine + fill OUR table (fresh
        // image — siblings unaffected, the limit dies with
        // the probe). Declared AFTER the guard (drops first —
        // restores reads before any retire re-verifies).
        let _confined = confine_fd_table_for_exhaustion();
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "fault exhaustion must consume fds");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        let verdict = reverify_pipe_holdership(wpid, wtick, &want, &ample, &mut spent);
        // The verdict IS the survival proof (reads are dead
        // here, so no aliveness sample is possible — but
        // reverify never kills, and Unverifiable is the
        // frame's skip verdict).
        eprintln!("R21002-OUTAGE verdict={verdict:?} pid={wpid} tick={wtick}");
        drop(held);
        drop(_confined);
        // Cleanup (loud): explicitly retire OUR pair now
        // reads work again.
        assert!(
            retire_tick_gated_audit_child(wpid, wtick),
            "probe writer retire readable"
        );
        assert!(
            await_proc_gone_reaping(wpid, wtick, Duration::from_secs(5)),
            "probe writer must drain"
        );
        let _ = writer;
        eprintln!("R21002-OUTAGE-DONE");
    }

    /// R21-002(a) wrapper: the outage probe's verdict must
    /// be `Unverifiable` (a birth-read ERROR never reports
    /// `NotOurs` — retire-anyway on error would murder a
    /// shedder if the error healed before frame entry).
    /// Failure first, then the verdict marker, then the
    /// completion marker (a probe that dies mid-cleanup is
    /// a failed regression even with the right verdict).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn reverify_birth_error_skips_loud() {
        let exe = std::env::current_exe().expect("own test binary");
        let mut out = std::process::Command::new(exe);
        out.arg("--exact")
            .arg("fixture::linux::audit::tests::reverify_outage_probe")
            .arg("--nocapture")
            .env("SCOPEBASE_R21002_OUTAGE", "1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // L144: pre-exec IGN (a group-HUP
        // mid-startup murders default probes).
        arm_hup_immune_spawn(&mut out);
        let out = out.output().expect("probe child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(
            out.status.success(),
            "probe must complete despite the outage\n{stderr}"
        );
        assert!(
            stderr.contains("R21002-OUTAGE verdict=Unverifiable"),
            "birth-read error must report Unverifiable (never NotOurs)\n{stderr}"
        );
        assert!(
            stderr.contains("R21002-OUTAGE-DONE"),
            "probe must retire its writer after restore\n{stderr}"
        );
    }

    /// R21-002(b) + anti-overcorrection (in-process — no
    /// exhaustion, sibling-safe): a predicate observation
    /// fault (the hook kills the holder after the identity
    /// match, before the trailing reads) reports
    /// `Unverifiable`, never a false `Shed`; a dead birth
    /// (gone-or-recycled) still reports `NotOurs` (the
    /// frame-safe retire-anyway — S100-guarded: a same-tick
    /// recycle makes the arm vacuous, never wrong). The
    /// strict-ENTRY arm (2 lines — a readdir error is never
    /// flattened away) is review-covered: procfs getdents
    /// has no deterministic error injection, and `DirEntry`
    /// has no public constructor for a fake iterator.
    /// Duration 955 is unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn reverify_strict_predicate_never_sheds_unobserved() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let writer = std::process::Command::new("/bin/sleep")
            .arg("955")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let _wguard = FixtureGuard::new(wpid);
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let want = collection_pipe_ids(Some(read_fd), None);
        assert!(!want.is_empty(), "collection pipe must identify");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        // Predicate fault: the hook kills OUR writer after
        // the identity match and SYNCHRONOUSLY awaits death
        // (death is async — without the await the trailing
        // read races the dying task and the verdict
        // flaps). The trailing fdinfo read then
        // deterministically fails on the zombie's released
        // table. No reap inside the hook (the zombie pins
        // the birth bracket — the verdict must come from
        // the predicate fault, not the bracket).
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership_with_hook(
                wpid,
                wtick,
                &want,
                &ample,
                &mut spent,
                Some(&|pid| {
                    assert!(kill_tick_gated(pid, wtick), "hook must kill our writer");
                    let end = Instant::now() + Duration::from_secs(5);
                    loop {
                        match proc_starttime(pid) {
                            Ok(Some(t)) if t == wtick => {
                                // Alive or zombie — poll the
                                // state until Z (released).
                                if proc_state(pid) == Some('Z') {
                                    break;
                                }
                            }
                            _ => break,
                        }
                        assert!(Instant::now() < end, "hook-killed writer must reach zombie");
                        std::thread::sleep(Duration::from_millis(1));
                    }
                }),
            ),
            HoldVerdict::Unverifiable,
            "predicate observation fault must report Unverifiable (never false Shed)"
        );
        // Reap the hook-killed writer (bounded, loud), then
        // the anti-overcorrection arm: a dead birth reports
        // NotOurs (S100-guarded — same-tick recycle would
        // pass the bracket and scan a stranger's table, so
        // that arm is vacuous, never wrong).
        let start = Instant::now();
        loop {
            let mut status = 0;
            // SAFETY: WNOHANG reap of our own killed child.
            if unsafe { libc::waitpid(wpid, &mut status, libc::WNOHANG) } == wpid {
                break;
            }
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "hook-killed writer must reap"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        match proc_starttime(wpid) {
            Ok(None) => {
                let mut spent = 0;
                assert_eq!(
                    reverify_pipe_holdership(wpid, wtick, &want, &ample, &mut spent),
                    HoldVerdict::NotOurs,
                    "gone birth must report NotOurs (frame-safe retire-anyway)"
                );
            }
            Ok(Some(now)) if now != wtick => {
                let mut spent = 0;
                assert_eq!(
                    reverify_pipe_holdership(wpid, wtick, &want, &ample, &mut spent),
                    HoldVerdict::NotOurs,
                    "recycled birth must report NotOurs (frame-safe retire-anyway)"
                );
            }
            Ok(Some(_)) => {
                eprintln!("vacuous: same-tick recycle (S100) — bracket would pass");
            }
            Err(error) => panic!("dead-birth stat must stay readable: {error:?}"),
        }
        // Cleanup: the writer is already reaped (discharged
        // above); drop the handle.
        let _ = writer;
    }

    /// R21-003: a stray that sheds the wanted write ends
    /// DURING the retire frame's snapshot window must
    /// survive the frame — the frame re-verifies
    /// holdership adjacent to its kill (the expiry's
    /// pre-snapshot reverify is stale by then: the
    /// snapshot costs ms of /proc walking). The shed
    /// lands deterministically inside the FIRST snapshot
    /// call (control byte in, status byte out — the close
    /// precedes the status write in program order, so the
    /// shed certainly precedes the kill gate). RED:
    /// pre-fix code kills the shedder (the live-assert
    /// fails); GREEN: the frame skips the kill and
    /// honestly reports uncertified (false — the shedder
    /// survives, so disappearance is uncertifiable).
    /// Second cell: an UNSHED holder retires normally
    /// through the production wrapper with its pipe ids
    /// (the screen must not spare genuine holders —
    /// Holds proceeds to the kill; also covers the
    /// wrapper's want-threading).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_shed_during_snapshot_survives() {
        use std::io::{Read as _, Write as _};
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove/Cell-2 Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        // Cell 1: the shedder. sh holds the target write
        // end on fd 1; the first snapshot call hands it a
        // control byte, it closes fd 1 (the shed), echoes
        // status on fd 2, then lives on as sleep.
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let (ctl_read, ctl_write) = std::io::pipe().expect("control pipe");
        let (status_read, status_write) = std::io::pipe().expect("status pipe");
        let shedder = std::process::Command::new("/bin/sh")
            .arg("-c")
            .arg("read x; exec 1>&-; echo s >&2; exec sleep 60")
            .stdin(std::process::Stdio::from(ctl_read))
            .stdout(std::process::Stdio::from(target_write))
            .stderr(std::process::Stdio::from(status_write))
            .spawn()
            .expect("shedder spawns");
        let spid = shedder.id() as libc::pid_t;
        let _sguard = FixtureGuard::new(spid);
        let stick = proc_starttime(spid)
            .expect("shedder stat readable")
            .expect("shedder visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        // Pre-prove Holds (the shedder genuinely holds at
        // frame entry — without this the survival assert
        // would be vacuous: a never-holder survives any
        // frame trivially).
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(spid, stick, &want, &ample, &mut spent),
            HoldVerdict::Holds,
            "shedder must hold the target at frame entry"
        );
        // The choreographed snapshot: the first call sheds
        // (control byte in, status byte out — the close
        // landed before the status write, so the shed
        // precedes the kill gate); later calls are plain
        // snapshots. RefCells: the frame takes `&impl Fn`
        // (no FnMut), so the pipe writes need interior
        // mutability.
        let shed = std::cell::Cell::new(false);
        let ctl_write = std::cell::RefCell::new(ctl_write);
        let status_read = std::cell::RefCell::new(status_read);
        let snapshot = |pid: libc::pid_t| -> (Vec<(libc::pid_t, u64)>, bool) {
            if !shed.get() {
                shed.set(true);
                ctl_write
                    .borrow_mut()
                    .write_all(b"x\n")
                    .expect("control byte lands");
                let mut status = [0u8; 2];
                status_read
                    .borrow_mut()
                    .read_exact(&mut status)
                    .expect("status byte proves the shed landed");
                assert_eq!(status, *b"s\n", "status byte shape");
            }
            snapshot_stray_children(pid)
        };
        // Short deadline: post-fix the frame skips the
        // kill and burns to the deadline by design (live
        // stray, nothing to await — same shape as the
        // pin-failure twin); pre-fix it kills and
        // certifies instantly.
        // R22-011: the family's ONE shared screen
        // budget (top frame creates it).
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = 0;
        let result = retire_stray_tree_frame_with(
            spid,
            stick,
            Instant::now() + Duration::from_secs(2),
            0,
            &snapshot,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        // The shedder must be live (kept, never murdered —
        // asserted BEFORE cleanup like the pin-failure
        // twin; RED-run hygiene rides the FixtureGuard
        // drop).
        assert_proc_settled_live(spid, stick, 1, "shedder must survive the frame");
        // Cleanup before the verdict (RED runs stay clean).
        assert!(
            retire_tick_gated_audit_child(spid, stick),
            "shedder retire readable"
        );
        assert!(
            await_proc_gone_reaping(spid, stick, Duration::from_secs(5)),
            "shedder must drain"
        );
        let _ = shedder;
        assert!(!result, "shedder survival must stay uncertified (false)");
        // Cell 2: an unshed holder retires normally through
        // the production wrapper (Holds proceeds to the
        // kill — the screen must not spare genuine
        // holders).
        let (hread, hwrite) = std::io::pipe().expect("holder pipe");
        let holder = std::process::Command::new("/bin/sleep")
            .arg("956")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(hwrite))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let _hguard = FixtureGuard::new(hpid);
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        let hwant = collection_pipe_ids(Some(hread.as_raw_fd()), None);
        assert!(!hwant.is_empty(), "holder pipe must identify");
        assert!(
            retire_stray_tree_best_effort(hpid, htick, &hwant),
            "unshed holder must retire through the screen"
        );
        assert!(
            await_proc_gone_reaping(hpid, htick, Duration::from_secs(5)),
            "holder must drain"
        );
        let _ = holder;
    }

    /// R22-010: the kids loop must visit ALL captured
    /// children and return the conjunction — a
    /// false-returning FIRST child must not abort the
    /// loop and strand a genuine writer captured after
    /// it. Staging: the root holds (killed, fast gone —
    /// reaches the kids loop, the fail-fast arm, not the
    /// best-effort arm); the fabricated snapshot returns
    /// [shedder, writer] for the root (deterministic
    /// shed-first ordering — capture order is what the
    /// `&impl Fn` seam models). The shedder sheds on its
    /// first snapshot call (control byte in, status byte
    /// out — the shed certainly landed), then EXITS
    /// promptly: shed real, death real, and its frame
    /// returns false WITHOUT burning the shared deadline
    /// (via modeled observation trouble — the bool the
    /// real snapshot returns when /proc reads fail; a
    /// shed + prompt death would otherwise certify true,
    /// and a LIVE shedder would burn the whole deadline
    /// by the accepted R21-003 design, after which
    /// R22-011 fail-closes every later frame — that
    /// combination is honestly unretired, not this
    /// test). RED: pre-fix the loop fail-fasts on the
    /// shedder and the writer survives; GREEN: the
    /// writer retires and the conjunction stays false
    /// (the shedder is uncertified).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_shed_first_writer_second_retires_writer() {
        use std::io::{Read as _, Write as _};
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let root_out = target_write.try_clone().expect("root clone");
        let shed_out = target_write.try_clone().expect("shedder clone");
        let write_out = target_write.try_clone().expect("writer clone");
        drop(target_write);
        let (ctl_read, ctl_write) = std::io::pipe().expect("control pipe");
        let (status_read, status_write) = std::io::pipe().expect("status pipe");
        let root = std::process::Command::new("/bin/sleep")
            .arg("947")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(root_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("root spawns");
        let rpid = root.id() as libc::pid_t;
        let _rguard = FixtureGuard::new(rpid);
        // The shedder sheds on the control byte, echoes
        // status, then EXITS (prompt death — no burn).
        let shedder = std::process::Command::new("/bin/sh")
            .arg("-c")
            .arg("read x; exec 1>&-; echo s >&2; exit 0")
            .stdin(std::process::Stdio::from(ctl_read))
            .stdout(std::process::Stdio::from(shed_out))
            .stderr(std::process::Stdio::from(status_write))
            .spawn()
            .expect("shedder spawns");
        let spid = shedder.id() as libc::pid_t;
        let _sguard = FixtureGuard::new(spid);
        let writer = std::process::Command::new("/bin/sleep")
            .arg("948")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let _wguard = FixtureGuard::new(wpid);
        let rtick = proc_starttime(rpid)
            .expect("root stat readable")
            .expect("root visible");
        let stick = proc_starttime(spid)
            .expect("shedder stat readable")
            .expect("shedder visible");
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        // Pre-prove Holds for all three (without this the
        // retire/survive asserts would be vacuous).
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        for (pid, tick, who) in [
            (rpid, rtick, "root"),
            (spid, stick, "shedder"),
            (wpid, wtick, "writer"),
        ] {
            let mut spent = 0;
            assert_eq!(
                reverify_pipe_holdership(pid, tick, &want, &ample, &mut spent),
                HoldVerdict::Holds,
                "{who} must hold the target at frame entry"
            );
        }
        // The choreographed snapshot: shed-first ordering
        // for the root; the shedder's first call sheds
        // and models observation trouble (see doc);
        // later calls are plain.
        let shed = std::cell::Cell::new(false);
        let ctl_write = std::cell::RefCell::new(ctl_write);
        let status_read = std::cell::RefCell::new(status_read);
        let snapshot = |pid: libc::pid_t| -> (Vec<(libc::pid_t, u64)>, bool) {
            if pid == spid && !shed.get() {
                shed.set(true);
                ctl_write
                    .borrow_mut()
                    .write_all(b"x\n")
                    .expect("control byte lands");
                let mut status = [0u8; 2];
                status_read
                    .borrow_mut()
                    .read_exact(&mut status)
                    .expect("status byte proves the shed landed");
                assert_eq!(status, *b"s\n", "status byte shape");
                return (vec![], true);
            }
            if pid == rpid {
                return (vec![(spid, stick), (wpid, wtick)], false);
            }
            (vec![], false)
        };
        // Generous deadline: no burn is expected (all
        // deaths prompt) — a burn here is a loud-slow
        // regression signal, not a timeout flake.
        // R22-011: the family's ONE shared screen
        // budget (top frame creates it).
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = 0;
        let result = retire_stray_tree_frame_with(
            rpid,
            rtick,
            Instant::now() + Duration::from_secs(10),
            0,
            &snapshot,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        assert!(shed.get(), "shedder must have been screened (shed ran)");
        assert!(
            !result,
            "shedder survival-uncertainty must stay uncertified (false)"
        );
        // The writer MUST retire (RED pre-fix: stranded
        // live by the fail-fast; the reaping await is
        // both evidence and cleanup — RED runs stay clean
        // via the FixtureGuard drop).
        assert!(
            await_proc_gone_reaping(wpid, wtick, Duration::from_secs(5)),
            "writer must retire after the shed-first child (fail-fast strands it)"
        );
        assert!(
            await_proc_gone_reaping(rpid, rtick, Duration::from_secs(5)),
            "root must drain"
        );
        assert!(
            await_proc_gone_reaping(spid, stick, Duration::from_secs(5)),
            "shedder must drain (self-exit)"
        );
        let _ = root;
        let _ = writer;
        let _ = shedder;
    }

    /// R23-005: shed-LIVE-first/writer-second — the shedder
    /// sheds its writer and then SLEEPS (stays live), while
    /// a later captured writer must still retire. The old
    /// frame awaits the shedder's death (never signaled —
    /// never dies), burning the whole shared deadline; the
    /// later writer then hits the expired entry gate and
    /// returns WITHOUT killing (stranded live). The fix
    /// polls a shed-skipped child ONCE (reap + observe)
    /// instead of awaiting it: the shedder survives, the
    /// writer retires, the result stays false (shedder
    /// survival honestly uncertified). RED (old: the writer
    /// strands live — the 10 s burn + 5 s writer await make
    /// RED loud-slow, ~15 s). No observation trouble here
    /// (unlike the R22-010 leg): false must come from
    /// shed-live, not from an unresolved flag. Durations
    /// 901/902/903 are unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_shed_live_first_writer_second_retires_writer() {
        use std::io::{Read as _, Write as _};
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let root_out = target_write.try_clone().expect("root clone");
        let shed_out = target_write.try_clone().expect("shedder clone");
        let write_out = target_write.try_clone().expect("writer clone");
        drop(target_write);
        let (ctl_read, ctl_write) = std::io::pipe().expect("control pipe");
        let (status_read, status_write) = std::io::pipe().expect("status pipe");
        let root = std::process::Command::new("/bin/sleep")
            .arg("901")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(root_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("root spawns");
        let rpid = root.id() as libc::pid_t;
        let _rguard = FixtureGuard::new(rpid);
        // The shedder sheds on the control byte, echoes
        // status, then SLEEPS (stays live — the burn
        // trigger the R22-010 leg's self-exit avoids).
        let shedder = std::process::Command::new("/bin/sh")
            .arg("-c")
            .arg("read x; exec 1>&-; echo s >&2; exec sleep 902")
            .stdin(std::process::Stdio::from(ctl_read))
            .stdout(std::process::Stdio::from(shed_out))
            .stderr(std::process::Stdio::from(status_write))
            .spawn()
            .expect("shedder spawns");
        let spid = shedder.id() as libc::pid_t;
        let _sguard = FixtureGuard::new(spid);
        let writer = std::process::Command::new("/bin/sleep")
            .arg("903")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let mut _wguard = FixtureGuard::new(wpid);
        let rtick = proc_starttime(rpid)
            .expect("root stat readable")
            .expect("root visible");
        let stick = proc_starttime(spid)
            .expect("shedder stat readable")
            .expect("shedder visible");
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        // Pre-prove Holds for all three (without this the
        // retire/survive asserts would be vacuous).
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        for (pid, tick, who) in [
            (rpid, rtick, "root"),
            (spid, stick, "shedder"),
            (wpid, wtick, "writer"),
        ] {
            let mut spent = 0;
            assert_eq!(
                reverify_pipe_holdership(pid, tick, &want, &ample, &mut spent),
                HoldVerdict::Holds,
                "{who} must hold the target at frame entry"
            );
        }
        // The choreographed snapshot: shed-first ordering
        // for the root; the shedder's first call sheds and
        // returns PLAIN (no observation trouble — false
        // must come from shed-live); later calls are plain.
        let shed = std::cell::Cell::new(false);
        let ctl_write = std::cell::RefCell::new(ctl_write);
        let status_read = std::cell::RefCell::new(status_read);
        let snapshot = |pid: libc::pid_t| -> (Vec<(libc::pid_t, u64)>, bool) {
            if pid == spid && !shed.get() {
                shed.set(true);
                ctl_write
                    .borrow_mut()
                    .write_all(b"x\n")
                    .expect("control byte lands");
                let mut status = [0u8; 2];
                status_read
                    .borrow_mut()
                    .read_exact(&mut status)
                    .expect("status byte proves the shed landed");
                assert_eq!(status, *b"s\n", "status byte shape");
                return (vec![], false);
            }
            if pid == rpid {
                return (vec![(spid, stick), (wpid, wtick)], false);
            }
            (vec![], false)
        };
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = 0;
        let result = retire_stray_tree_frame_with(
            rpid,
            rtick,
            Instant::now() + Duration::from_secs(10),
            0,
            &snapshot,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        assert!(shed.get(), "shedder must have been screened (shed ran)");
        assert!(!result, "shedder survival must stay uncertified (false)");
        // The writer MUST retire (RED pre-fix: stranded
        // live behind the shedder's burned deadline).
        assert!(
            await_proc_gone_reaping(wpid, wtick, Duration::from_secs(5)),
            "writer must retire after the shed-live child (burn strands it)"
        );
        // The shedder MUST survive (never signaled) — then
        // explicit tick-gated cleanup (RED runs stay clean
        // via the FixtureGuard drop).
        assert_eq!(
            proc_starttime(spid),
            Ok(Some(stick)),
            "shedder must survive (shed, never signaled)"
        );
        assert_eq!(proc_state(spid), Some('S'), "shedder must be live-sleeping");
        kill_tick_gated(spid, stick);
        assert!(
            await_proc_gone_reaping(spid, stick, Duration::from_secs(5)),
            "shedder cleanup must drain"
        );
        _wguard.disarm();
        assert!(
            await_proc_gone_reaping(rpid, rtick, Duration::from_secs(5)),
            "root must drain"
        );
        let _ = root;
        let _ = writer;
        let _ = shedder;
    }

    /// R22-011 cell A: a frame entered with an EXPIRED
    /// tree deadline must return false WITHOUT killing —
    /// killing on stale evidence after unbounded delay is
    /// the original hole wider. RED: pre-fix no entry
    /// check exists, the holder is killed; GREEN: the
    /// holder survives and the outcome stays uncertified.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_expired_deadline_entry_kills_nothing() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let holder = std::process::Command::new("/bin/sleep")
            .arg("949")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(target_write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let _hguard = FixtureGuard::new(hpid);
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &ample, &mut spent),
            HoldVerdict::Holds,
            "holder must hold the target at frame entry"
        );
        // Expired BEFORE entry (uptime exceeds 1 s on any
        // machine that runs this suite).
        // R22-011: the family's ONE shared screen
        // budget (top frame creates it).
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = 0;
        let result = retire_stray_tree_frame_with(
            hpid,
            htick,
            Instant::now() - Duration::from_secs(1),
            0,
            &snapshot_stray_children,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        assert!(!result, "expired entry must stay uncertified (false)");
        // Asserted BEFORE cleanup (cleanup destroys the
        // evidence; RED-run hygiene rides the
        // FixtureGuard drop).
        assert_proc_settled_live(hpid, htick, 1, "holder must survive expired entry");
        assert!(
            retire_tick_gated_audit_child(hpid, htick),
            "holder retire readable"
        );
        assert!(
            await_proc_gone_reaping(hpid, htick, Duration::from_secs(5)),
            "holder must drain"
        );
        let _ = holder;
    }

    /// R22-011 cell B1: a frame entered with an EXHAUSTED
    /// shared screen remainder must truncate its scan
    /// (Unverifiable) and skip the kill — fail-closed,
    /// never partial evidence. RED (via neuter — the
    /// signature postdates the bug, so pre-fix code does
    /// not compile this test; resetting the remainder at
    /// entry restores fresh-budget behavior and the
    /// holder is killed); GREEN: the holder survives and
    /// the outcome stays uncertified. Zero-room
    /// exhaustion (spent == max) truncates before the
    /// first fd — enumeration-order independent.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_exhausted_screen_remainder_kills_nothing() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let holder = std::process::Command::new("/bin/sleep")
            .arg("950")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(target_write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let _hguard = FixtureGuard::new(hpid);
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let mut spent = 0;
        assert_eq!(
            reverify_pipe_holdership(hpid, htick, &want, &ample, &mut spent),
            HoldVerdict::Holds,
            "holder must hold the target at frame entry"
        );
        // Exhausted remainder (read from the budget — no
        // literal duplication of the cap); budget created
        // adjacent to the call (fresh deadline, though
        // the count truncation fires first regardless).
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = screen_budget.max_visited_fds;
        // Short deadline: post-fix the frame skips the
        // kill and burns to the deadline by design (live
        // stray, nothing to await — the accepted R21-003
        // shape).
        let result = retire_stray_tree_frame_with(
            hpid,
            htick,
            Instant::now() + Duration::from_secs(2),
            0,
            &snapshot_stray_children,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        assert!(!result, "exhausted entry must stay uncertified (false)");
        assert_proc_settled_live(hpid, htick, 1, "holder must survive exhausted entry");
        assert!(
            retire_tick_gated_audit_child(hpid, htick),
            "holder retire readable"
        );
        assert!(
            await_proc_gone_reaping(hpid, htick, Duration::from_secs(5)),
            "holder must drain"
        );
        let _ = holder;
    }

    /// R22-011 cell B2: the family's screen spends must
    /// AGGREGATE into the ONE shared remainder — the
    /// parent frame's visits are visible to the child
    /// frame (this is what bounds the family total to a
    /// single budget instead of one fresh 100k scan per
    /// member). Two genuine holders (both killed, prompt
    /// deaths — no burn): the post-call remainder must
    /// EXACTLY equal the parent's visits-to-hit plus the
    /// child's visits-to-hit (hit positions measured at
    /// runtime — enumeration-order independent; any entry
    /// error or unobservable fd breaks the exactness
    /// LOUD, never silent). RED (via neuter — same
    /// signature note as B1; resetting the remainder at
    /// entry leaves only the last frame's visits and the
    /// exactness assert fails); GREEN: exact aggregate.
    /// Giant-table end-to-end staging was considered and
    /// rejected: the shared 1 s budget deadline makes
    /// count-vs-time truncation timing-dependent (slow
    /// machines would go GREEN pre-fix) — exact small
    /// counts prove the same sharing deterministically.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn retire_frame_screen_spends_aggregate_across_family() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // R22-017: pidfd-grab capability gate (skip loud
        // when the pre-prove Holds positives are
        // unverifiable).
        if !pidfd_grab_capable() {
            eprintln!("skip: pidfd grab unavailable (Yama/deny-profile/old kernel)");
            return;
        }
        fn hit_position(pid: libc::pid_t, target: &str) -> Option<usize> {
            for (position, entry) in std::fs::read_dir(format!("/proc/{pid}/fd"))
                .ok()?
                .enumerate()
            {
                let entry = entry.ok()?;
                let link = std::fs::read_link(entry.path()).ok()?;
                if link.to_str() == Some(target) {
                    return Some(position);
                }
            }
            None
        }
        let (target_read, target_write) = std::io::pipe().expect("target pipe");
        let target_fd = target_read.as_raw_fd();
        let parent_out = target_write.try_clone().expect("parent clone");
        let child_out = target_write.try_clone().expect("child clone");
        drop(target_write);
        let parent = std::process::Command::new("/bin/sleep")
            .arg("952")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(parent_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("parent spawns");
        let ppid = parent.id() as libc::pid_t;
        let _pguard = FixtureGuard::new(ppid);
        let child = std::process::Command::new("/bin/sleep")
            .arg("944")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(child_out))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("child spawns");
        let cpid = child.id() as libc::pid_t;
        let _cguard = FixtureGuard::new(cpid);
        let ptick = proc_starttime(ppid)
            .expect("parent stat readable")
            .expect("parent visible");
        let ctick = proc_starttime(cpid)
            .expect("child stat readable")
            .expect("child visible");
        let want = collection_pipe_ids(Some(target_fd), None);
        assert!(!want.is_empty(), "target pipe must identify");
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        for (pid, tick, who) in [(ppid, ptick, "parent"), (cpid, ctick, "child")] {
            let mut spent = 0;
            assert_eq!(
                reverify_pipe_holdership(pid, tick, &want, &ample, &mut spent),
                HoldVerdict::Holds,
                "{who} must hold the target at frame entry"
            );
        }
        // Hit positions measured on the quiescent tables
        // (no fd activity between here and the frame —
        // sleeps; the frame's own scan order matches this
        // enumeration deterministically).
        let target = format!("pipe:[{}]", want[0].1);
        let hparent = hit_position(ppid, &target).expect("parent hit measurable");
        let hchild = hit_position(cpid, &target).expect("child hit measurable");
        let snapshot = |pid: libc::pid_t| -> (Vec<(libc::pid_t, u64)>, bool) {
            if pid == ppid {
                return (vec![(cpid, ctick)], false);
            }
            (vec![], false)
        };
        let screen_budget = PipeScanBudget::default();
        let mut screen_spent = 0;
        // Generous deadline: no burn expected (both
        // holders die promptly).
        let result = retire_stray_tree_frame_with(
            ppid,
            ptick,
            Instant::now() + Duration::from_secs(10),
            0,
            &snapshot,
            &want,
            &screen_budget,
            &mut screen_spent,
        );
        assert!(result, "both holders must retire (true)");
        assert_eq!(
            screen_spent,
            (hparent + 1) + (hchild + 1),
            "spends must aggregate across the family (fresh-per-frame leaves only the last frame's visits)"
        );
        assert!(
            await_proc_gone_reaping(ppid, ptick, Duration::from_secs(5)),
            "parent must drain"
        );
        assert!(
            await_proc_gone_reaping(cpid, ctick, Duration::from_secs(5)),
            "child must drain"
        );
        let _ = parent;
        let _ = child;
    }

    /// R19-009 (end-to-end): a collection expiry beside a
    /// pathological fd table stays bounded and reports —
    /// the default scan budget truncates the walk (unit cell
    /// asserts the flag directly — deterministic, since the
    /// table alone exceeds the 100k cap whatever the walk
    /// order; STUB-RED fails it) instead of prefixing the 5 s
    /// tree budget with an unbounded scan, and the expiry
    /// still retires the probe group (characterization cell:
    /// pre-fix code also completes here, only slower —
    /// wall-bounded, group-gone, status reaped by the
    /// expiry). A 150k-fd holder parks (skip loud below
    /// 120k); a self-grouped piped probe expires on a short
    /// deadline. Serialized with the other
    /// discovery-population tests (a concurrent
    /// default-budget `!truncated` assert would see this
    /// table).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn expiry_beside_bigtable_stays_bounded_and_loud() {
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        let _pop = DISCOVERY_POPULATION_SERIAL
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Fd-holder: 150k /dev/null fds (same staging as
        // the budget cells). R20-014: report-first (see
        // the budget-cells case — the held handle
        // publishes under a below-`want` limit).
        let script = "import os, resource, sys, time\nwant = int(sys.argv[1])\nreport = open(sys.argv[2], 'w')\ntry:\n    hard = resource.getrlimit(resource.RLIMIT_NOFILE)[1]\n    resource.setrlimit(resource.RLIMIT_NOFILE, (hard, hard))\nexcept Exception:\n    pass\nfds = []\nfor _ in range(want):\n    try:\n        fds.append(os.open('/dev/null', os.O_RDONLY))\n    except OSError:\n        break\nreport.write(str(len(fds)))\nreport.flush()\ntime.sleep(30)\n";
        let me = std::process::id();
        let dir = std::env::temp_dir();
        let flag_count = dir.join(format!("scopebase-r19009e-count-{me}"));
        let _ = std::fs::remove_file(&flag_count);
        let mut holder_cmd = std::process::Command::new("python3");
        holder_cmd
            .arg("-c")
            .arg(script)
            .arg("150000")
            .arg(&flag_count)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        // R20-014: confinement injection (same 1024 clamp
        // as the budget-cells case).
        if std::env::var("SCOPEBASE_R20014_CONFINE").is_ok() {
            // SAFETY: setrlimit on self pre-exec, no userspace state.
            unsafe {
                holder_cmd.pre_exec(|| {
                    let lim = libc::rlimit {
                        rlim_cur: 1024,
                        rlim_max: 1024,
                    };
                    if libc::setrlimit(libc::RLIMIT_NOFILE, &lim) != 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                    Ok(())
                });
            }
        }
        let holder = holder_cmd.spawn().expect("fd-holder spawns");
        let hpid = holder.id() as libc::pid_t;
        // R20-014: unwind backstop (same strand risk as
        // the budget-cells case).
        let _hguard = FixtureGuard::new(hpid);
        assert!(
            _hguard.tick.is_some(),
            "holder custody must pin (stage broken otherwise)"
        );
        let end = Instant::now() + Duration::from_secs(60);
        let opened: usize = loop {
            if let Ok(text) = std::fs::read_to_string(&flag_count) {
                if let Ok(parsed) = text.trim().parse() {
                    break parsed;
                }
            }
            assert!(
                Instant::now() < end,
                "holder must report its fd count (stage broken otherwise)"
            );
            std::thread::sleep(Duration::from_millis(10));
        };
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        // Owned-child cleanup (kill gated, status drains to
        // us — the R19-005/006 self-reap discipline).
        let kill_and_reap = |pid: libc::pid_t, tick: u64, what: &str| {
            let _ = kill_tick_gated(pid, tick);
            let end = Instant::now() + Duration::from_secs(10);
            let mut reaped = None;
            loop {
                let mut st = 0;
                // SAFETY: WNOHANG assist only — our child.
                if unsafe { libc::waitpid(pid, &mut st, libc::WNOHANG) } == pid {
                    reaped = Some(st);
                }
                if proc_starttime(pid) != Ok(Some(tick)) {
                    break;
                }
                assert!(Instant::now() < end, "{what} must die");
                std::thread::sleep(Duration::from_millis(10));
            }
            let st = reaped.expect("status must drain to us (retained, never stolen)");
            assert!(libc::WIFSIGNALED(st), "{what} must die by our signal");
        };
        if opened < 120_000 {
            kill_and_reap(hpid, htick, "fd-holder");
            drop(holder);
            let _ = std::fs::remove_file(&flag_count);
            eprintln!("skip: fd table too small ({opened} < 120000 — no default-cap isolation)");
            return;
        }
        // Self-grouped piped probe (holds EOF open by
        // sleeping — the collection must expire it).
        let mut probe_cmd = std::process::Command::new("python3");
        probe_cmd
            .arg("-c")
            .arg("import time\ntime.sleep(30)\n")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // SAFETY: setpgid on self pre-exec, no userspace state.
        unsafe {
            probe_cmd.pre_exec(|| {
                libc::setpgid(0, 0);
                Ok(())
            });
        }
        let mut probe = probe_cmd.spawn().expect("probe spawns");
        let id = probe.id() as libc::pid_t;
        // R21-009: guard at birth (before the fallible
        // first read — R20-014 armed it after).
        let _pguard = FixtureGuard::new(id);
        // R21-009 fault: fail the first observation (reads
        // dead at the stat below — the `.expect` panics
        // and the guard must unwind-retire before it).
        // Birth captured healthy first (birth-aware
        // wrapper check). Declared AFTER the guard (drops
        // first — restores reads before the retire
        // re-verifies).
        let _fault = std::env::var("SCOPEBASE_R21009_R20014_PROBE_FAIL")
            .is_ok()
            .then(|| {
                let tick = proc_starttime(id)
                    .expect("pre-fault birth readable")
                    .expect("pre-fault probe visible");
                eprintln!("R21009-PROBE pid={id} tick={tick}");
                let confined = confine_fd_table_for_exhaustion();
                let mut held = Vec::new();
                while let Ok(file) = std::fs::File::open("/dev/null") {
                    held.push(file);
                }
                assert!(!held.is_empty(), "fault exhaustion must consume fds");
                (confined, held)
            });
        let probe_tick = proc_starttime(id)
            .expect("probe stat readable")
            .expect("probe visible");
        drop(_fault);
        assert!(
            _pguard.tick.is_some(),
            "probe custody must pin (stage broken otherwise)"
        );
        // SAFETY: getpgid queries only.
        assert_eq!(
            unsafe { libc::getpgid(id) },
            id,
            "probe must self-group (stage broken otherwise)"
        );
        // Unit cell: the default budget truncates on this
        // table (neighbors only add entries — the trip is
        // guaranteed).
        {
            use std::os::unix::io::AsRawFd as _;
            let out_fd = probe.stdout.as_ref().map(|pipe| pipe.as_raw_fd());
            let err_fd = probe.stderr.as_ref().map(|pipe| pipe.as_raw_fd());
            let (_pairs, truncated) = extend_strays_with_pipe_writers_with(
                &[],
                out_fd,
                err_fd,
                None,
                &PipeScanBudget::default(),
            );
            assert!(truncated, "default budget must truncate on the 150k table");
        }
        // E2E cell: the collection expires (short deadline —
        // the probe holds EOF open), bounded wall, probe
        // group gone, probe status reaped by the expiry.
        let start = Instant::now();
        let end = start + Duration::from_secs(1);
        let got = collect_probe_output_bounded(&mut probe, end, probe_tick, &[]);
        let elapsed = start.elapsed();
        assert!(got.is_none(), "live probe must expire, not collect");
        assert!(
            elapsed < Duration::from_secs(30),
            "expiry beside the big table must stay bounded ({elapsed:?})"
        );
        let gend = Instant::now() + Duration::from_secs(10);
        loop {
            // SAFETY: killpg(id, 0) probes existence only.
            if unsafe { libc::killpg(id, 0) } < 0 {
                // SAFETY: errno location for this thread.
                let errno = unsafe { libc::__errno_location().read() };
                assert_eq!(
                    errno,
                    libc::ESRCH,
                    "group probe must fail ESRCH-only, got {errno}"
                );
                break;
            }
            assert!(
                Instant::now() < gend,
                "probe group {id} survived the expiry"
            );
            std::thread::sleep(Duration::from_millis(20));
        }
        // The expiry reaped the probe numerically (the
        // trailing run-proof that expiry, not us, retired
        // it — extracted helper, same step).
        prove_expiry_reaped_probe(id, probe_tick, &mut probe);
        // Cleanup: the fd-holder (owned, gated, self-reaped).
        kill_and_reap(hpid, htick, "fd-holder");
        drop(holder);
        let _ = std::fs::remove_file(&flag_count);
    }

    /// R21-009 (R20-014): a failed FIRST observation over the
    /// writer/probe must panic with the staged fixture
    /// already retired — the birth guard (armed at spawn)
    /// unwind-retires before the `.expect` propagates. Two
    /// cells (writer test + probe test), each fresh-image
    /// with reads dead at its first stat: the probe must
    /// FAIL loud (never complete) and the staged birth must
    /// be gone-or-recycled (birth-aware; unreadable fails).
    /// Pre-fix RED: the post-stat guard never arms and the
    /// sleeper strands.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn first_read_failure_discharges_before_panic() {
        for (test, fault_var, marker, read_name) in [
            (
                "fixture::linux::audit::tests::discovery_scan_budget_truncates_loud",
                "SCOPEBASE_R21009_R20014_WRITER_FAIL",
                "R21009-WRITER",
                "writer stat readable",
            ),
            (
                "fixture::linux::audit::tests::expiry_beside_bigtable_stays_bounded_and_loud",
                "SCOPEBASE_R21009_R20014_PROBE_FAIL",
                "R21009-PROBE",
                "probe stat readable",
            ),
        ] {
            let exe = std::env::current_exe().expect("own test binary");
            let mut out = std::process::Command::new(exe);
            out.arg("--exact")
                .arg(test)
                .arg("--nocapture")
                .env(fault_var, "1")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            // L144: pre-exec IGN (a group-HUP
            // mid-startup murders default probes).
            arm_hup_immune_spawn(&mut out);
            let out = out.output().expect("probe child runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            assert!(
                !out.status.success(),
                "fault probe must fail loud ({marker})\n{stderr}"
            );
            assert!(
                stderr.contains(read_name),
                "probe must name the failed first read ({marker})\n{stderr}"
            );
            let line = stderr
                .lines()
                .find(|line| line.contains(marker))
                .unwrap_or_else(|| {
                    panic!("probe must print the staged birth ({marker})\n{stderr}")
                });
            // {marker} pid={pid} tick={tick}.
            let mut parts = line.split_whitespace().skip(1);
            let pid: libc::pid_t = parts
                .next()
                .expect("pid slot")
                .strip_prefix("pid=")
                .expect("pid shape")
                .parse()
                .expect("pid parses");
            let tick: u64 = parts
                .next()
                .expect("tick slot")
                .strip_prefix("tick=")
                .expect("tick shape")
                .parse()
                .expect("tick parses");
            match proc_starttime(pid) {
                Ok(None) => {}
                Ok(Some(now)) => assert_ne!(
                    now, tick,
                    "staged birth must be retired ({marker} stranded by the failed first read)"
                ),
                Err(error) => panic!("staged retirement unverifiable ({marker}): {error:?}"),
            }
        }
    }

    /// R20-014: a confined holder must still publish its
    /// capacity — both holder scripts filled to OSError
    /// THEN opened the count report, so under a
    /// below-`want` limit the report open EMFILEd, python
    /// traceback-exited with no report and no sleep, and
    /// the 30s/60s harness loops PANICKED (the intended
    /// low-capacity skip unreachable; case one also
    /// stranded its unguarded sleep-918 writer). Runs both
    /// holder tests fresh-image with the holder clamped to
    /// 1024 fds and requires the bounded capacity
    /// report + skip each time. RED (this shape): the
    /// probe panics in the report loop (30s/60s) and the
    /// writer strands. GREEN: report-first scripting
    /// publishes the small count through the held handle,
    /// the skip path retires every fixture (its
    /// kill_and_reap asserts — WIFSIGNALED + retained
    /// status — are the discharge proof; probe success
    /// carries it). Environmental probe skips propagate.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn confined_holder_reports_capacity_and_skips() {
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable");
            return;
        }
        for probe in [
            "fixture::linux::audit::tests::discovery_scan_budget_truncates_loud",
            "fixture::linux::audit::tests::expiry_beside_bigtable_stays_bounded_and_loud",
        ] {
            let exe = std::env::current_exe().expect("own test binary");
            let mut out = std::process::Command::new(exe);
            out.arg("--exact")
                .arg(probe)
                .arg("--nocapture")
                .env("SCOPEBASE_R20014_CONFINE", "1")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            // L144: pre-exec IGN (a group-HUP
            // mid-startup murders default probes).
            arm_hup_immune_spawn(&mut out);
            let out = out.output().expect("probe child runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            assert!(
                out.status.success(),
                "confined probe must report + skip, not panic ({probe})\n{stderr}"
            );
            if stderr.contains("skip: python3 unavailable") {
                eprintln!("skip (probe environmental: {probe})");
                continue;
            }
            assert!(
                stderr.contains("skip: fd table too small"),
                "confined probe must take the capacity skip ({probe})\n{stderr}"
            );
        }
    }

    /// R20-013(a): the shedding guard must never steal a
    /// replacement's status — it waitpided unconditionally
    /// after a possibly-rejecting kill gate, so a sibling
    /// zombie at the recycled number was reaped (status
    /// stolen). Stages a holder, retires it, plants a
    /// different-birth zombie replacement at its number,
    /// then drops the guard: RED (this shape): the drop
    /// reaps the zombie (our retention waitpid finds
    /// ECHILD — stolen). GREEN: the birth match fails and
    /// the drop touches nothing (we reap the retained
    /// status). The naive verdict-gated fix does NOT fix:
    /// the gate returns true on mismatch/gone
    /// (idempotent-success), proven by this test staying
    /// RED under it — the explicit match is required.
    /// The live arm requires bounded completion + survival
    /// (non-discriminating — the gate never signaled a
    /// mismatched birth — but review-required). Contended
    /// or same-tick plants skip loud (established steer
    /// precedent).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn kill_on_drop_never_steals_replacement_status() {
        let Some(_serial) = steer_hold() else {
            return;
        };
        // Holder: retired before the plants (number freed).
        let mut holder = std::process::Command::new("/bin/sleep")
            .arg("0.1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("holder spawns");
        let hpid = holder.id() as libc::pid_t;
        let htick = proc_starttime(hpid)
            .expect("holder stat readable")
            .expect("holder visible");
        let _ = holder.wait();
        assert_eq!(proc_starttime(hpid), Ok(None), "holder number must free");
        // Zombie arm: different-birth replacement, settled
        // to an unreaped zombie (its status is the arm's
        // evidence).
        let (mut kid, mut guard) = match plant_replacement(hpid, htick) {
            Some(planted) => planted,
            None => return,
        };
        assert!(
            settle_replacement_zombie(&mut kid, hpid),
            "replacement must settle zombie (stage broken otherwise)"
        );
        drop(KillOnDrop {
            pid: hpid,
            tick: htick,
        });
        let mut st = 0;
        // SAFETY: WNOHANG retention probe — our own child.
        let got = unsafe { libc::waitpid(hpid, &mut st, libc::WNOHANG) };
        assert_eq!(
            got, hpid,
            "zombie replacement status must be retained (stolen when ECHILD)"
        );
        guard.disarm();
        drop(kid);
        assert_eq!(proc_starttime(hpid), Ok(None), "number freed again");
        // Live arm: bounded completion + survival.
        let (mut live, mut lguard) = match plant_replacement(hpid, htick) {
            Some(planted) => planted,
            None => return,
        };
        let retick = proc_starttime(hpid)
            .expect("live replacement readable")
            .expect("live replacement visible");
        assert_ne!(retick, htick, "live replacement is a different birth");
        drop(KillOnDrop {
            pid: hpid,
            tick: htick,
        });
        assert_eq!(
            proc_starttime(hpid),
            Ok(Some(retick)),
            "live replacement must survive the guard drop"
        );
        let _ = live.kill();
        let _ = live.wait();
        lguard.disarm();
    }

    /// R20-013(b): the frame-drain proof must survive
    /// replacements — the waitpid-ECHILD shape both stole
    /// a replacement zombie's status AND assert-failed
    /// (loud flake + harm), and assert-failed on a live
    /// replacement. Gone arm (production-retire shape):
    /// the proof runs silently. Zombie arm: RED — the
    /// proof panics after stealing (retention finds
    /// ECHILD); GREEN — skips loud, status retained (we
    /// reap). Live arm: RED — panics (got 0); GREEN —
    /// skips loud, occupant survives. Contended plants
    /// skip loud.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn frame_drain_proof_survives_replacements() {
        let Some(_serial) = steer_hold() else {
            return;
        };
        let stage_holder = || {
            // Raw-reaped below (simulated frame reap) —
            // the handle goes stale, never `.wait()`ed.
            #[allow(clippy::zombie_processes)]
            let holder = std::process::Command::new("/bin/sleep")
                .arg("0.1")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("holder spawns");
            let hpid = holder.id() as libc::pid_t;
            let htick = proc_starttime(hpid)
                .expect("holder stat readable")
                .expect("holder visible");
            // Production-retire shape: killed AND reaped by
            // the frame (never by us).
            assert!(kill_tick_gated(hpid, htick), "frame kills");
            let mut st = 0;
            // SAFETY: the frame's targeted reap (simulated).
            let got = unsafe { libc::waitpid(hpid, &mut st, 0) };
            assert_eq!(got, hpid, "frame reaps");
            assert_eq!(proc_starttime(hpid), Ok(None), "number freed");
            (hpid, htick)
        };
        // Gone arm: the proof runs (silently) — the
        // retire-drained shape it was written for.
        let (hpid, _htick) = stage_holder();
        prove_frame_drained_holder(hpid);
        // Zombie arm: different-birth replacement, settled
        // to an unreaped zombie.
        let (hpid, htick) = stage_holder();
        let (mut kid, mut guard) = match plant_replacement(hpid, htick) {
            Some(planted) => planted,
            None => return,
        };
        assert!(
            settle_replacement_zombie(&mut kid, hpid),
            "replacement must settle zombie (stage broken otherwise)"
        );
        let panicked = std::panic::catch_unwind(|| prove_frame_drained_holder(hpid)).is_err();
        assert!(!panicked, "drain proof must not fail on a zombie occupant");
        let mut st = 0;
        // SAFETY: WNOHANG retention probe — our own child.
        let got = unsafe { libc::waitpid(hpid, &mut st, libc::WNOHANG) };
        assert_eq!(got, hpid, "zombie occupant status must be retained");
        guard.disarm();
        drop(kid);
        // Live arm: a different-birth live occupant.
        let (hpid, htick) = stage_holder();
        let (mut live, mut lguard) = match plant_replacement(hpid, htick) {
            Some(planted) => planted,
            None => return,
        };
        let retick = proc_starttime(hpid)
            .expect("live occupant readable")
            .expect("live occupant visible");
        let panicked = std::panic::catch_unwind(|| prove_frame_drained_holder(hpid)).is_err();
        assert!(!panicked, "drain proof must not fail on a live occupant");
        assert_eq!(
            proc_starttime(hpid),
            Ok(Some(retick)),
            "live occupant must survive the proof"
        );
        let _ = live.kill();
        let _ = live.wait();
        lguard.disarm();
    }

    /// R20-013(c): the expiry-reap proof must survive
    /// replacements — the blocking `Child::wait` stalled
    /// on a live replacement and stole a zombie one's
    /// status (reaped ⟹ unpinned: the killpg poll above
    /// the proof stretches the recycle window to ms).
    /// Gone arm (expiry shape): the proof runs silently.
    /// Zombie arm: RED — panics after stealing; GREEN —
    /// skips loud, status retained. Live arm: RED — blocks
    /// until the 5s bounding killer retires the occupant
    /// (then panics); GREEN — skips loud at once,
    /// occupant survives. Ours-zombie arm (expiry killed
    /// but left status): RED — panics (flake, no theft);
    /// GREEN — drains ours + skips loud. Contended plants
    /// skip loud.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn expiry_reap_proof_survives_replacements() {
        let Some(_serial) = steer_hold() else {
            return;
        };
        // Gone arm: killed AND raw-reaped by the expiry
        // (the handle stays stale-unwaited — the real
        // shape); the proof runs silently.
        // Raw-reaped below (simulated expiry reap).
        #[allow(clippy::zombie_processes)]
        let mut probe = std::process::Command::new("/bin/sleep")
            .arg("0.1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("probe spawns");
        let id = probe.id() as libc::pid_t;
        let mut _pguard = FixtureGuard::new(id);
        let tick = proc_starttime(id)
            .expect("probe stat readable")
            .expect("probe visible");
        assert!(kill_tick_gated(id, tick), "expiry kills");
        let mut st = 0;
        // SAFETY: the expiry's raw reap (simulated).
        let got = unsafe { libc::waitpid(id, &mut st, 0) };
        assert_eq!(got, id, "expiry reaps");
        _pguard.disarm();
        prove_expiry_reaped_probe(id, tick, &mut probe);
        drop(probe);
        // Zombie arm: different-birth replacement, settled
        // to an unreaped zombie; the stale handle below is
        // the ORIGINAL probe's (already raw-reaped).
        // Raw-reaped below (simulated expiry reap) — the
        // handle goes stale, never `.wait()`ed.
        #[allow(clippy::zombie_processes)]
        let mut probe = std::process::Command::new("/bin/sleep")
            .arg("0.1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("probe spawns");
        let id = probe.id() as libc::pid_t;
        let mut _pguard = FixtureGuard::new(id);
        let tick = proc_starttime(id)
            .expect("probe stat readable")
            .expect("probe visible");
        assert!(kill_tick_gated(id, tick), "expiry kills");
        // SAFETY: the expiry's raw reap (simulated).
        let got = unsafe { libc::waitpid(id, &mut st, 0) };
        assert_eq!(got, id, "expiry reaps");
        _pguard.disarm();
        let (mut kid, mut guard) = match plant_replacement(id, tick) {
            Some(planted) => planted,
            None => return,
        };
        assert!(
            settle_replacement_zombie(&mut kid, id),
            "replacement must settle zombie (stage broken otherwise)"
        );
        let panicked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            prove_expiry_reaped_probe(id, tick, &mut probe)
        }))
        .is_err();
        assert!(!panicked, "reap proof must not fail on a zombie occupant");
        // SAFETY: WNOHANG retention probe — our own child.
        let got = unsafe { libc::waitpid(id, &mut st, libc::WNOHANG) };
        assert_eq!(got, id, "zombie occupant status must be retained");
        guard.disarm();
        drop(kid);
        drop(probe);
        // Live arm: a different-birth live occupant. The
        // bounding killer retires it after 5s (bounds the
        // RED block; on GREEN the proof returns in ms and
        // the killer finds nothing — gated no-op).
        // Raw-reaped below (simulated expiry reap).
        #[allow(clippy::zombie_processes)]
        let mut probe = std::process::Command::new("/bin/sleep")
            .arg("0.1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("probe spawns");
        let id = probe.id() as libc::pid_t;
        let mut _pguard = FixtureGuard::new(id);
        let tick = proc_starttime(id)
            .expect("probe stat readable")
            .expect("probe visible");
        assert!(kill_tick_gated(id, tick), "expiry kills");
        // SAFETY: the expiry's raw reap (simulated).
        let got = unsafe { libc::waitpid(id, &mut st, 0) };
        assert_eq!(got, id, "expiry reaps");
        _pguard.disarm();
        let (live, mut lguard) = match plant_replacement(id, tick) {
            Some(planted) => planted,
            None => return,
        };
        let retick = proc_starttime(id)
            .expect("live occupant readable")
            .expect("live occupant visible");
        // The bounding killer fires only on RED-timeout (or
        // RED-unwind disconnect — retiring the stranded
        // occupant as hygiene); GREEN signals early exit.
        let (btx, brx) = std::sync::mpsc::channel::<()>();
        let killer = std::thread::spawn(move || {
            if brx.recv_timeout(std::time::Duration::from_secs(5)).is_ok() {
                return;
            }
            bounding_kill_assist(id, retick);
        });
        let panicked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            prove_expiry_reaped_probe(id, tick, &mut probe)
        }))
        .is_err();
        assert!(!panicked, "reap proof must not fail on a live occupant");
        assert_eq!(
            proc_starttime(id),
            Ok(Some(retick)),
            "live occupant must survive the proof"
        );
        drop(live);
        let _ = kill_tick_gated(id, retick);
        // SAFETY: blocking reap of our retired occupant.
        let got = unsafe { libc::waitpid(id, &mut st, 0) };
        assert_eq!(got, id, "live occupant reaped");
        lguard.disarm();
        let _ = btx.send(());
        let _ = killer.join();
        drop(probe);
        // Ours-zombie arm: expiry killed but left status
        // (unreaped) — the proof must drain ours (safe —
        // positively our birth) and skip loud, never
        // assert-fail.
        // Drained by the proof (raw waitpid, never `.wait()`ed).
        #[allow(clippy::zombie_processes)]
        let mut probe = std::process::Command::new("/bin/sleep")
            .arg("0.1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("probe spawns");
        let id = probe.id() as libc::pid_t;
        let mut _pguard = FixtureGuard::new(id);
        let tick = proc_starttime(id)
            .expect("probe stat readable")
            .expect("probe visible");
        assert!(kill_tick_gated(id, tick), "expiry kills");
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if matches!(proc_state(id), Some(state) if state == 'Z') {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "probe must settle zombie (stage broken otherwise)"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let panicked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            prove_expiry_reaped_probe(id, tick, &mut probe)
        }))
        .is_err();
        assert!(!panicked, "reap proof must drain ours-zombie, not fail");
        // SAFETY: WNOHANG drain check — our own child.
        let got = unsafe { libc::waitpid(id, &mut st, libc::WNOHANG) };
        assert!(
            got < 0 && std::io::Error::last_os_error().raw_os_error() == Some(libc::ECHILD),
            "ours-zombie must be drained by the proof, got {got}"
        );
        _pguard.disarm();
        drop(probe);
    }

    /// R21-010-killer: the bounding-killer tail must never
    /// reap. Pre-fix it ran gated-kill + unconditional
    /// WNOHANG waitpid: the gate's `true` covers mismatch
    /// (idempotent-success), so the waitpid fired on a
    /// birth the gate never verified — stealing a
    /// replacement zombie's status in the send/timeout race.
    /// Zombie arm: retire an occupant, plant a
    /// different-birth replacement settled zombie, run the
    /// killer tail with the STALE birth (the race shape) —
    /// the replacement's status must be retained (pre-fix:
    /// stolen, RED). Live arm: same plant left live — the
    /// occupant must survive (the gate must not signal a
    /// birth it cannot verify). No timing: the tail runs
    /// inline, deterministically.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn bounding_killer_tail_never_reaps() {
        let Some(_serial) = steer_hold() else {
            return;
        };
        for live in [false, true] {
            // Raw-reaped below (simulated expiry reap).
            #[allow(clippy::zombie_processes)]
            let probe = std::process::Command::new("/bin/sleep")
                .arg("0.1")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("probe spawns");
            let id = probe.id() as libc::pid_t;
            // R22-014: guard at birth (the tick read below
            // must not strand the probe's zombie).
            let mut _guard = FixtureGuard::new(id);
            let tick = proc_starttime(id)
                .expect("probe stat readable")
                .expect("probe visible");
            assert!(kill_tick_gated(id, tick), "expiry kills");
            let mut st = 0;
            // SAFETY: the expiry's raw reap (simulated).
            let got = unsafe { libc::waitpid(id, &mut st, 0) };
            assert_eq!(got, id, "expiry reaps");
            _guard.disarm();
            drop(probe);
            let (mut kid, mut guard) = match plant_replacement(id, tick) {
                Some(planted) => planted,
                None => return,
            };
            let retick = proc_starttime(id)
                .expect("replacement readable")
                .expect("replacement visible");
            assert_ne!(retick, tick, "plant must be a different birth");
            if !live {
                assert!(
                    settle_replacement_zombie(&mut kid, id),
                    "replacement must settle zombie (stage broken otherwise)"
                );
            }
            // The race shape: the killer tail acts on the
            // stale birth (already reaped) while a foreign
            // birth occupies the number.
            bounding_kill_assist(id, tick);
            if live {
                assert!(
                    matches!(proc_state(id), Some(state) if state != 'Z'),
                    "live replacement must survive the killer tail"
                );
                assert!(kill_tick_gated(id, retick), "retire the survivor");
                // SAFETY: blocking reap of our retired occupant.
                let got = unsafe { libc::waitpid(id, &mut st, 0) };
                assert_eq!(got, id, "survivor reaped");
            } else {
                // SAFETY: WNOHANG retention probe — our own child.
                let got = unsafe { libc::waitpid(id, &mut st, libc::WNOHANG) };
                assert_eq!(
                    got, id,
                    "replacement zombie status must be retained (killer tail stole it)"
                );
            }
            guard.disarm();
            drop(kid);
        }
    }

    /// R20-015: the ≥5000 high-fd control must stage
    /// where stageable and skip where not. A constrained
    /// runner (soft NOFILE ≤ 5000 — ordinary containers at
    /// 1024) failed the bare `F_DUPFD_CLOEXEC ≥ 5000`
    /// assert DETERMINISTICALLY (fd -1); a sibling's
    /// in-process 4096 confinement landing in the µs
    /// gate→fcntl window fails it rarely. Arm 1 (control
    /// preserved): unconstrained staging returns a live fd
    /// ≥ 5000 at once. Arm 2 (overlap): a 200ms sibling
    /// confinement held across the call waits out, then
    /// stages. RED (gate-only shape): the gate sees
    /// 4096 and skips (`None`); GREEN: the serial retries
    /// into `Some` after release.
    /// Arm 3 (constrained runner): the shedding test
    /// fresh-image with ambient soft 1024 skips loud
    /// (pre-fix RED: `high leak copy staged (fd -1)`
    /// panic, proven at baseline). R21-014: ambient ≤ 5000
    /// runs ONLY arm 3 (arms 1–2 skip loud — the
    /// regression itself failed on constrained runners).
    /// The 200ms arm-2 hold
    /// sits inside the accepted FLAKE01 envelope (frame
    /// tests confine for seconds; siblings' ≥5000 staging
    /// now waits rather than fails).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn high_fd_staging_gated_and_serialized() {
        use std::os::unix::io::AsRawFd as _;
        // R21-014: ambient-capacity branch FIRST — arms 1–2
        // stage unconditionally and panic on a constrained
        // runner; below the gate only the constrained arm
        // runs (the regression itself must skip cleanly
        // where it claims support).
        let ambient_stageable = {
            let mut rlim = libc::rlimit {
                rlim_cur: 0,
                rlim_max: 0,
            };
            // SAFETY: getrlimit on self only.
            let rc = unsafe { libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) };
            rc == 0 && rlim.rlim_cur > 5000
        };
        if ambient_stageable {
            let (read, write) = std::io::pipe().expect("staging pipe");
            // Arm 1: unconstrained → immediate stage.
            let staged = stage_high_leak_copy(write.as_raw_fd());
            let owned = staged.expect("control stages where capacity allows");
            assert!(
                owned.as_raw_fd() >= 5000,
                "staged control must sit at fd ≥ 5000"
            );
            drop(owned);
            // Arm 2: a sibling confinement held across the
            // call waits out, then stages.
            let (htx, hrx) = std::sync::mpsc::channel::<()>();
            let holder = std::thread::spawn(move || {
                let _guard = confine_fd_table_for_exhaustion();
                htx.send(()).expect("confinement staged");
                std::thread::sleep(std::time::Duration::from_millis(200));
            });
            hrx.recv().expect("holder confined first");
            let staged = stage_high_leak_copy(write.as_raw_fd());
            let owned = staged.expect("staging waits out a sibling confinement, never skips");
            assert!(
                owned.as_raw_fd() >= 5000,
                "post-wait control must sit at fd ≥ 5000"
            );
            drop(owned);
            drop(read);
            drop(write);
            holder.join().expect("holder rejoins");
        } else {
            eprintln!(
                "skip: ambient soft ≤ 5000 (staging arms need capacity; constrained arm runs)"
            );
        }
        // Arm 3: ambient-1024 runner → the shedding test
        // skips loud (pre_exec clamp — the probe's whole
        // image runs constrained).
        let exe = std::env::current_exe().expect("own test binary");
        let mut cmd = std::process::Command::new(exe);
        cmd.arg("--exact")
            .arg("fixture::linux::audit::tests::shedding_inheritor_survives_expiry_while_holders_retire")
            .arg("--nocapture")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // SAFETY: setrlimit on the child pre-exec, no userspace state.
        use std::os::unix::process::CommandExt as _;
        unsafe {
            cmd.pre_exec(|| {
                let lim = libc::rlimit {
                    rlim_cur: 1024,
                    rlim_max: 1024,
                };
                if libc::setrlimit(libc::RLIMIT_NOFILE, &lim) != 0 {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        // L144: pre-exec IGN (a group-HUP
        // mid-startup murders default probes).
        arm_hup_immune_spawn(&mut cmd);
        let out = cmd.output().expect("probe child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(
            out.status.success(),
            "constrained shedding probe must skip, not fail\n{stderr}"
        );
        assert!(
            stderr.contains("high-fd control unstageable"),
            "constrained probe must take the capacity skip\n{stderr}"
        );
    }

    /// R21-015: the gate boundary is exclusive — fd 5000
    /// needs soft > 5000 (valid fds run below soft), so
    /// exactly-5000 must skip, not proceed to a failing
    /// fcntl. Fresh-image probes clamped to 4999 / 5000 /
    /// 6000. RED: the 5000 probe panics in the fcntl
    /// assert. GREEN: 4999 and 5000 cite the skip, 6000
    /// stages fd ≥ 5000. R22-018: each cell is
    /// attainability-gated on OUR hard cap first —
    /// raising hard is EPERM, so a clamp above hard is
    /// REPORTED unattainable, never attempted (no raising
    /// anywhere, no setup panic on constrained runners).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn high_fd_gate_boundary_5000_skips() {
        use std::os::unix::process::CommandExt as _;
        if let Ok(clamp) = std::env::var("SCOPEBASE_R21015_CLAMP") {
            // Probe body: stage (or skip) under the
            // wrapper's clamp.
            let (_read, write) = std::io::pipe().expect("staging pipe");
            use std::os::unix::io::AsRawFd as _;
            match stage_high_leak_copy(write.as_raw_fd()) {
                Some(owned) => eprintln!("R21015-STAGED fd={}", owned.as_raw_fd()),
                None => eprintln!("R21015-SKIPPED clamp={clamp}"),
            }
            return;
        }
        // R22-018: our hard cap bounds every cell (raising
        // hard is EPERM — a clamp above it is reported,
        // never attempted).
        let mut rlim: libc::rlimit = unsafe { std::mem::zeroed() };
        assert_eq!(
            unsafe { libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) },
            0,
            "own hard cap readable"
        );
        let hard = rlim.rlim_max;
        for (clamp, staged) in [(4999u64, false), (5000, false), (6000, true)] {
            if hard < clamp {
                eprintln!(
                    "R21015-UNATTAINABLE clamp={clamp} hard={hard} (runner cap cannot reach this cell — reported, not staged)"
                );
                continue;
            }
            let exe = std::env::current_exe().expect("own test binary");
            let mut cmd = std::process::Command::new(exe);
            cmd.arg("--exact")
                .arg("fixture::linux::audit::tests::high_fd_gate_boundary_5000_skips")
                .arg("--nocapture")
                .env("SCOPEBASE_R21015_CLAMP", clamp.to_string())
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            // SAFETY: setrlimit on the child pre-exec, no userspace state.
            unsafe {
                cmd.pre_exec(move || {
                    let lim = libc::rlimit {
                        rlim_cur: clamp,
                        rlim_max: clamp,
                    };
                    if libc::setrlimit(libc::RLIMIT_NOFILE, &lim) != 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                    Ok(())
                });
            }
            // L144: pre-exec IGN (a group-HUP
            // mid-startup murders default probes).
            arm_hup_immune_spawn(&mut cmd);
            let out = cmd.output().expect("probe child runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            assert!(
                out.status.success(),
                "boundary probe must complete (clamp {clamp})\n{stderr}"
            );
            if staged {
                let marker = "R21015-STAGED fd=";
                let at = stderr.find(marker).expect("staged citation");
                let fd: libc::c_int = stderr[at + marker.len()..]
                    .split_whitespace()
                    .next()
                    .expect("fd cited")
                    .parse()
                    .expect("fd parses");
                assert!(fd >= 5000, "clamp {clamp} must stage fd ≥ 5000, got {fd}");
            } else {
                assert!(
                    stderr.contains("R21015-SKIPPED"),
                    "clamp {clamp} must skip, not stage\n{stderr}"
                );
            }
        }
    }

    /// R22-018: launch the boundary test itself with low
    /// soft+hard NOFILE (≤1024 — absolute, so this
    /// deterministically forces the EPERM shape even on a
    /// generous host): every cell clamp (4999/5000/6000)
    /// exceeds the runner hard cap, so each cell must
    /// REPORT unattainable (no setup panic, the boundary
    /// test passes). RED (pre-fix: the wrapper's
    /// pre_exec raise attempt fails EPERM and
    /// `output().expect` panics in setup). No probe body
    /// ever runs here (all cells gated) — absence of
    /// STAGED/SKIPPED markers pins that.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn high_fd_gate_boundary_unattainable_cells_reported() {
        use std::os::unix::process::CommandExt as _;
        // Our hard cap (lower-or-keep only below — never
        // raised, even in the child).
        let mut rlim: libc::rlimit = unsafe { std::mem::zeroed() };
        assert_eq!(
            unsafe { libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) },
            0,
            "own hard cap readable"
        );
        let target = rlim.rlim_max.min(1024);
        let exe = std::env::current_exe().expect("own test binary");
        let mut cmd = std::process::Command::new(exe);
        cmd.arg("--exact")
            .arg("fixture::linux::audit::tests::high_fd_gate_boundary_5000_skips")
            .arg("--nocapture")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        // SAFETY: setrlimit on the child pre-exec (lower-or-keep —
        // target ≤ our hard by construction).
        unsafe {
            cmd.pre_exec(move || {
                let lim = libc::rlimit {
                    rlim_cur: target,
                    rlim_max: target,
                };
                if libc::setrlimit(libc::RLIMIT_NOFILE, &lim) != 0 {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        // L144: pre-exec IGN (a group-HUP
        // mid-startup murders default probes).
        arm_hup_immune_spawn(&mut cmd);
        let out = cmd.output().expect("constrained boundary child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(
            out.status.success(),
            "RED: constrained boundary test must pass (cells reported, not panicked)\n{stderr}"
        );
        for clamp in [4999, 5000, 6000] {
            assert!(
                stderr.contains(&format!("R21015-UNATTAINABLE clamp={clamp}")),
                "clamp {clamp} must report unattainable\n{stderr}"
            );
        }
        assert!(
            !stderr.contains("R21015-STAGED"),
            "no cell may stage under the constraint\n{stderr}"
        );
        assert!(
            !stderr.contains("R21015-SKIPPED"),
            "no probe body may run under the constraint\n{stderr}"
        );
    }

    /// R19-007: a fork-only inheritor must not be murdered at
    /// another collection's expiry — fork copies every fd
    /// regardless of CLOEXEC, so a bare pauser landing in a
    /// spawn window keeps the write end for life, blocks EOF,
    /// and is discovered + retired as a stray (brief
    /// EOF-retention acceptance never authorized destruction).
    /// The fix sheds inherited fds in every fork-only child
    /// (close_range minus report fds); discovery needs no
    /// ancestry check (R18-001's writer is orphaned and
    /// middleman-grouped while R19-005's holders live in the
    /// harness group — neither separates inheritors from
    /// holders). This stages the leak deterministically: a
    /// shedding pauser (the fixed artifact) + a bare pauser
    /// (pre-fix shape, mechanism control) forked while the
    /// parent holds the write end plus a high CLOEXEC-marked
    /// dup (F_DUPFD_CLOEXEC ≥ 5000 — inherited despite the
    /// mark, exactly like real racing ends; the PARTIAL-range
    /// mutant keeps it), plus a genuine exec-based writer.
    /// The bare control must attribute (leak genuine), the
    /// shedder must stay invisible, and the expiry must kill
    /// the control + writer while the shedder survives with
    /// its status. STUB-RED (this shape): shed is a no-op and
    /// the shed-proof poll fails. GREEN: exact attribution
    /// set, selective retirement. Ample budget (neighbor-proof
    /// — no population lock needed).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn shedding_inheritor_survives_expiry_while_holders_retire() {
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // Unwind-safe owned-child cleanup: the hoisted
        // `KillOnDrop` (explicit cleanup below runs first
        // on GREEN; the guard turns into a gated no-op).
        // Collection pipe: we keep the READ end.
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let write_fd = write.as_raw_fd();
        let want_ino = pipe_dev_ino(read_fd).expect("collection pipe identified");
        // High leak copy (inherited despite CLOEXEC-marking).
        // R20-015: capacity-gated staging (constrained
        // runners skip loud — the control cannot stage).
        let Some(_high_owned) = stage_high_leak_copy(write_fd) else {
            return;
        };
        // Inheritor: shedding pauser (the fixed artifact) —
        // forks now, sheds, parks.
        // SAFETY: child sheds then pauses (syscalls only).
        let ipid = unsafe { super::super::fork::fork_shedding_pauser() };
        assert!(ipid > 0, "inheritor fork failed");
        // Control: BARE fork-only pauser (pre-fix shape) —
        // inherits and keeps both copies, parks.
        // SAFETY: child pauses forever (async-signal-safe).
        let cpid = unsafe { libc::fork() };
        assert!(cpid >= 0, "control fork failed");
        if cpid == 0 {
            unsafe {
                loop {
                    libc::pause();
                }
            }
        }
        let itick = proc_starttime(ipid)
            .expect("inheritor stat readable")
            .expect("inheritor visible");
        let ctick = proc_starttime(cpid)
            .expect("control stat readable")
            .expect("control visible");
        let _iguard = KillOnDrop {
            pid: ipid,
            tick: itick,
        };
        let _cguard = KillOnDrop {
            pid: cpid,
            tick: ctick,
        };
        // Descendant: genuine exec-based writer.
        let writer = std::process::Command::new("/bin/sleep")
            .arg("919")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let _wguard = KillOnDrop {
            pid: wpid,
            tick: wtick,
        };
        // Pipe-hold probe (our way — readlink scan, not trust).
        let fd_holds_pipe = |pid: libc::pid_t, ino: u64| -> bool {
            let want = format!("pipe:[{ino}]");
            std::fs::read_dir(format!("/proc/{pid}/fd"))
                .map(|entries| {
                    entries.flatten().any(|entry| {
                        std::fs::read_link(entry.path())
                            .is_ok_and(|link| link.to_string_lossy() == want)
                    })
                })
                .unwrap_or(false)
        };
        // Leak proof: the CONTROL holds write copies (single
        // read — inheritance is synchronous at fork).
        assert!(
            fd_holds_pipe(cpid, want_ino.1),
            "control must inherit the write end (mechanism non-vacuity)"
        );
        // Shed proof: poll the INHERITOR until no write copy
        // remains (shed lands in µs; bounded poll — and the
        // inheritor must stay LIVE throughout, else the
        // absence is vacuous).
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            assert_eq!(
                proc_starttime(ipid),
                Ok(Some(itick)),
                "inheritor must live while shedding"
            );
            if !fd_holds_pipe(ipid, want_ino.1) {
                break;
            }
            assert!(
                Instant::now() < end,
                "inheritor must shed inherited write ends"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        // Discovery (ample — neighbor-proof): the bare control
        // + the genuine writer attribute; the shedder stays
        // invisible.
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let (mut found, truncated) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &ample);
        assert!(!truncated, "ample budget must scan fully");
        found.sort();
        let mut expected = vec![(cpid, ctick), (wpid, wtick)];
        expected.sort();
        assert_eq!(
            found, expected,
            "only the bare control + genuine writer attribute"
        );
        // Expiry: retire the discovered; the inheritor
        // survives while holders die.
        for (pid, tick) in &found {
            assert!(
                retire_stray_tree_best_effort(*pid, *tick, &[]),
                "production retire of the attributed holder must succeed (run-proof)"
            );
        }
        assert_proc_settled_live(
            ipid,
            itick,
            2,
            "shedding inheritor must survive discovery + retire",
        );
        // R19003-FLAKE02: no post-hoc waitpid-ECHILD loop.
        // Production-true above already certified the named
        // births gone (observed absence/reuse inside the
        // frame — the ns-anchored proof); our zombie at the
        // number is then impossible (dead-is-dead: the birth
        // cannot return), so a fresh waitpid here asserts
        // suite timing, not production behavior — a frontier-
        // retake lands an ambient suite child (got 0, proven
        // 4/15 runs) or a foreign zombie (numeric waitpid
        // would STEAL its status). The asserted production
        // receipt is the complete proof; this loop could only
        // noise-or-harm.
        drop(writer);
        // Cleanup: the surviving inheritor (gated kill,
        // status drains to us).
        let _ = kill_tick_gated(ipid, itick);
        let end = Instant::now() + Duration::from_secs(10);
        let mut reaped = None;
        loop {
            let mut st = 0;
            // SAFETY: WNOHANG assist only — our child.
            if unsafe { libc::waitpid(ipid, &mut st, libc::WNOHANG) } == ipid {
                reaped = Some(st);
            }
            if proc_starttime(ipid) != Ok(Some(itick)) {
                break;
            }
            assert!(Instant::now() < end, "inheritor must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        let st = reaped.expect("inheritor status must drain to us (retained, never stolen)");
        assert!(libc::WIFSIGNALED(st), "inheritor must die by our signal");
    }

    /// R20-002: a fork→shed inheritor recorded while holding
    /// must not be murdered after it sheds — discovery's
    /// recorded authority does not survive shedding (the
    /// fork→shed window is ms-scale under big tables and the
    /// artifact persists indefinitely — NOT covered by the µs
    /// gate→signal residual). Stages a GATED shedder (held
    /// pre-shed through discovery — attributed, non-vacuous),
    /// releases it to shed (shed-proof poll), then expires
    /// the discovered set through the production collection
    /// path: the shedder is skipped (EOF already achieved)
    /// and survives, while the bare control + genuine writer
    /// retire. A never-holding union member proves the
    /// boundary (union prefix retires unconditionally).
    /// RED (this shape): expiry retires the recorded pair
    /// unconditionally and the shedder dies. GREEN:
    /// holdership re-verification skips it. `group_died`
    /// isolates the individual-retire path (no killpg); the
    /// bogus probe tick spares `id`. Durations 921 (writer) /
    /// 922 (union non-holder) are unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn shed_recorded_inheritor_skipped_at_expiry_while_holders_retire() {
        use std::os::unix::ffi::OsStrExt as _;
        use std::os::unix::io::AsRawFd as _;
        use std::time::{Duration, Instant};
        // Unwind-safe owned-child cleanup: the hoisted
        // `KillOnDrop`.
        // Collection pipe: we keep the READ end.
        let (read, write) = std::io::pipe().expect("collection pipe");
        let read_fd = read.as_raw_fd();
        let want_ino = pipe_dev_ino(read_fd).expect("collection pipe identified");
        // Shed gate (absent — the shedder holds pre-shed).
        let gate =
            std::env::temp_dir().join(format!("scopebase-r20002-shed-gate-{}", std::process::id()));
        let _ = std::fs::remove_file(&gate);
        let gate_c =
            std::ffi::CString::new(gate.as_os_str().as_bytes()).expect("gate path encodes");
        // Shedder: gated (holds through discovery below).
        // SAFETY: child waits the gate, sheds, pauses.
        let spid = unsafe { super::super::fork::fork_gated_shedding_pauser(&gate_c) };
        assert!(spid > 0, "shedder fork failed");
        // Control: BARE fork-only pauser (holds for life).
        // SAFETY: child pauses forever (async-signal-safe).
        let cpid = unsafe { libc::fork() };
        assert!(cpid >= 0, "control fork failed");
        if cpid == 0 {
            unsafe {
                loop {
                    libc::pause();
                }
            }
        }
        let stick = proc_starttime(spid)
            .expect("shedder stat readable")
            .expect("shedder visible");
        let ctick = proc_starttime(cpid)
            .expect("control stat readable")
            .expect("control visible");
        let _sguard = KillOnDrop {
            pid: spid,
            tick: stick,
        };
        let _cguard = KillOnDrop {
            pid: cpid,
            tick: ctick,
        };
        // Writer: genuine exec-based holder.
        let writer = std::process::Command::new("/bin/sleep")
            .arg("921")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::from(write))
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("writer spawns");
        let wpid = writer.id() as libc::pid_t;
        let wtick = proc_starttime(wpid)
            .expect("writer stat readable")
            .expect("writer visible");
        let _wguard = KillOnDrop {
            pid: wpid,
            tick: wtick,
        };
        // Union: live non-holder (never touches the pipe).
        let extra = std::process::Command::new("/bin/sleep")
            .arg("922")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("union extra spawns");
        let xpid = extra.id() as libc::pid_t;
        let xtick = proc_starttime(xpid)
            .expect("extra stat readable")
            .expect("extra visible");
        let _xguard = KillOnDrop {
            pid: xpid,
            tick: xtick,
        };
        // Pipe-hold probe (readlink scan, not trust).
        let fd_holds_pipe = |pid: libc::pid_t, ino: u64| -> bool {
            let want = format!("pipe:[{ino}]");
            std::fs::read_dir(format!("/proc/{pid}/fd"))
                .map(|entries| {
                    entries.flatten().any(|entry| {
                        std::fs::read_link(entry.path())
                            .is_ok_and(|link| link.to_string_lossy() == want)
                    })
                })
                .unwrap_or(false)
        };
        // Discovery: shedder (holding) + control + writer
        // attribute; the union extra stays out.
        let ample = PipeScanBudget {
            max_visited_fds: usize::MAX,
            deadline: Instant::now() + Duration::from_secs(60),
        };
        let (mut found, truncated) =
            extend_strays_with_pipe_writers_with(&[], Some(read_fd), None, None, &ample);
        assert!(!truncated, "ample budget must scan fully");
        found.sort();
        let mut expected = vec![(spid, stick), (cpid, ctick), (wpid, wtick)];
        expected.sort();
        assert_eq!(
            found, expected,
            "pre-shed holder + control + writer attribute (shedder held through discovery)"
        );
        // Release: the shedder sheds (live throughout —
        // absence is non-vacuous).
        std::fs::write(&gate, "go").expect("gate created");
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            assert_eq!(
                proc_starttime(spid),
                Ok(Some(stick)),
                "shedder must live while shedding"
            );
            if !fd_holds_pipe(spid, want_ino.1) {
                break;
            }
            assert!(
                Instant::now() < end,
                "shedder must shed inherited write ends"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        // Non-vacuity: the control still holds (the expiry
        // must kill it but skip the shedder).
        assert!(
            fd_holds_pipe(cpid, want_ino.1),
            "control must still hold its write end"
        );
        // Expiry through the production path: union prefix
        // (extra) + discovered holders; group_died isolates
        // the individual-retire path (no killpg); the bogus
        // probe tick spares `id`.
        let mut strays = vec![(xpid, xtick)];
        strays.extend(found.iter().copied());
        let bogus = ctick.wrapping_add(1);
        expire_probe_collection(cpid, bogus, &strays, true, false, &[want_ino], 1);
        // The shedder survives (skipped — EOF achieved);
        // control + writer + union extra retire.
        assert_proc_settled_live(
            spid,
            stick,
            2,
            "shed recorded inheritor must survive expiry",
        );
        assert!(
            await_proc_gone_reaping(cpid, ctick, Duration::from_secs(5)),
            "bare control must retire at expiry"
        );
        assert!(
            await_proc_gone_reaping(wpid, wtick, Duration::from_secs(5)),
            "genuine writer must retire at expiry"
        );
        assert!(
            await_proc_gone_reaping(xpid, xtick, Duration::from_secs(5)),
            "union non-holder must retire unconditionally"
        );
        drop(writer);
        drop(extra);
        // Cleanup: the surviving shedder (gated kill, status
        // drains to us) + the gate file.
        let _ = kill_tick_gated(spid, stick);
        let end = Instant::now() + Duration::from_secs(10);
        let mut reaped = None;
        loop {
            let mut st = 0;
            // SAFETY: WNOHANG assist only — our child.
            if unsafe { libc::waitpid(spid, &mut st, libc::WNOHANG) } == spid {
                reaped = Some(st);
            }
            if proc_starttime(spid) != Ok(Some(stick)) {
                break;
            }
            assert!(Instant::now() < end, "shedder must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        let st = reaped.expect("shedder status must drain to us (retained, never stolen)");
        assert!(libc::WIFSIGNALED(st), "shedder must die by our signal");
        let _ = std::fs::remove_file(&gate);
    }

    /// R19-008 staging: a reformable group — steered leader L
    /// (pid G, self-grouped, sleep 920) + a caller-spawned
    /// member C (joined to G while L lives), then L killed +
    /// self-reaped, leaving group#G populated-only-by-C with
    /// number G free for a steered reform. The caller holds
    /// AUDIT_STEER_SERIAL + the ns_last_pid flock across
    /// staging AND the retire (the reform hook steers under
    /// them); this NEVER restores (locked restore nests the
    /// flock — caller drops it first, then restores).
    /// `spawn_member` runs while L is alive and returns C's
    /// (pid, tick). Returns None on steering miss (caller
    /// drops the flock, restores, skips loud — L retired).
    #[cfg(target_arch = "x86_64")]
    fn stage_reformable_group(
        last_before: &str,
        spawn_member: &dyn Fn(libc::pid_t) -> (libc::pid_t, u64),
    ) -> Option<(libc::pid_t, u64, libc::pid_t, u64)> {
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};
        let g = last_before.trim().parse::<i32>().unwrap_or(0) + 1;
        if g <= 1 || !audit_steer_next_pid_unlocked(g) {
            return None;
        }
        let mut leader_cmd = std::process::Command::new("/bin/sleep");
        leader_cmd
            .arg("920")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        // SAFETY: setpgid on self pre-exec, no userspace state.
        unsafe {
            leader_cmd.pre_exec(|| {
                libc::setpgid(0, 0);
                Ok(())
            });
        }
        let leader = leader_cmd.spawn().expect("leader spawns");
        let lpid = leader.id() as libc::pid_t;
        // Rides to return (no disarm): the miss path's
        // reap loop can timeout-break with L live (the
        // drop retires it), and the success path's owned
        // reap silences the drop.
        let _lguard = FixtureGuard::new(lpid);
        if lpid != g {
            // Steering miss: retire the misplaced leader
            // (bounded numeric reap — never a blocking wait),
            // signal skip.
            if let Some(mtick) = proc_starttime(lpid).ok().flatten() {
                let _ = kill_tick_gated(lpid, mtick);
                let end = Instant::now() + Duration::from_secs(10);
                loop {
                    let mut st = 0;
                    // SAFETY: WNOHANG assist only — our child.
                    if unsafe { libc::waitpid(lpid, &mut st, libc::WNOHANG) } == lpid {
                        break;
                    }
                    if proc_starttime(lpid).ok().flatten() != Some(mtick) {
                        break;
                    }
                    if Instant::now() >= end {
                        break;
                    }
                    std::thread::sleep(Duration::from_millis(10));
                }
            }
            drop(leader);
            return None;
        }
        let ltick = proc_starttime(lpid)
            .expect("leader stat readable")
            .expect("leader visible");
        // SAFETY: getpgid queries only.
        assert_eq!(
            unsafe { libc::getpgid(lpid) },
            lpid,
            "leader must self-group (stage broken otherwise)"
        );
        // Member joins while the group lives; the join is
        // proven (a failed setpgid is stage-broken, loud).
        let (cpid, ctick) = spawn_member(g);
        // SAFETY: getpgid queries only.
        assert_eq!(
            unsafe { libc::getpgid(cpid) },
            g,
            "member must join the group (stage broken otherwise)"
        );
        // Covers the leader-retire asserts below; disarmed
        // at handoff (the caller arms its own — the gap
        // holds zero fallible ops).
        let mut _cguard = FixtureGuard::new_expected(cpid, ctick);
        assert!(
            _cguard.tick.is_some(),
            "reformable-group staging: member birth pinned at handoff"
        );
        // Leader retires (owned, gated, self-reaped — no
        // drain has run, so the status is ours); the number
        // must free for the reform.
        let _ = kill_tick_gated(lpid, ltick);
        drop(leader);
        let end = Instant::now() + Duration::from_secs(10);
        let mut reaped = None;
        loop {
            let mut st = 0;
            // SAFETY: WNOHANG assist only — our child.
            if unsafe { libc::waitpid(lpid, &mut st, libc::WNOHANG) } == lpid {
                reaped = Some(st);
            }
            if proc_starttime(lpid) != Ok(Some(ltick)) {
                break;
            }
            assert!(Instant::now() < end, "leader must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        let st = reaped.expect("leader status must drain to us (retained, never stolen)");
        assert!(libc::WIFSIGNALED(st), "leader must die by our signal");
        assert_eq!(
            proc_starttime(g),
            Ok(None),
            "group number must free for the reform"
        );
        _cguard.disarm();
        Some((g, ltick, cpid, ctick))
    }

    /// R21-001: C's reaped-state at a skip-path retire
    /// site. KnownUnreaped (C live-or-zombie, never
    /// reaped — its number cannot host a sibling, so the
    /// retire-first body is sound) vs Unknown (reaped or
    /// not — the helper tick-checks first when reads work,
    /// fails loud under outage). Known-drained sites skip
    /// this helper and call [`prove_drained_for_skip`]
    /// (proof-only — no waitpid/kill over a released
    /// number, where a sibling's zombie would be stolen
    /// and a sibling's live child murdered).
    #[cfg(target_arch = "x86_64")]
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum SkipCRetireState {
        KnownUnreaped,
        Unknown,
    }

    /// R21-001: proof-only tail — requires `Ok(None)` or a
    /// foreign birth; still-ours or `Err` fails loud. Pure
    /// reads: safe over any state (never steals, never
    /// signals).
    #[cfg(target_arch = "x86_64")]
    fn prove_drained_for_skip(cpid: libc::pid_t, ctick: u64, context: &str) {
        // Explicit drained-proof (never vacuous on Err).
        match proc_starttime(cpid) {
            Ok(None) => {}
            Ok(Some(t)) if t != ctick => {}
            Ok(Some(_)) => panic!("C survived skip-path retire ({context})"),
            Err(error) => panic!("C drain unprovable under outage ({context}): {error:?}"),
        }
    }

    /// R20-010(3): skip-path C custody for the drain-mandate
    /// skips — retire C, then prove drained. `context`
    /// carries the site's drained-expectation rationale.
    /// R21-001: the retire-first body runs only when C is
    /// known-unreaped (sound — no sibling can occupy the
    /// number) or unknown-but-tick-verified-ours; unknown +
    /// outage fails loud (an ours-vs-sibling zombie is
    /// indistinguishable without birth reads).
    #[cfg(target_arch = "x86_64")]
    fn retire_and_prove_drained_for_skip(
        cpid: libc::pid_t,
        ctick: u64,
        state: SkipCRetireState,
        context: &str,
    ) {
        use std::time::{Duration, Instant};
        // R21-001: unknown reaped-state tick-checks FIRST
        // (reads-OK): ours ⟹ fall through to the retire;
        // gone/foreign ⟹ proof-only (no waitpid/kill over
        // a number that may host a sibling). Unknown +
        // outage fails loud (an ours-vs-sibling zombie is
        // indistinguishable without birth reads — neither
        // stealing nor murdering blind).
        if state == SkipCRetireState::Unknown {
            match proc_starttime(cpid) {
                Ok(Some(now)) if now == ctick => {}
                Ok(_) => {
                    prove_drained_for_skip(cpid, ctick, context);
                    return;
                }
                Err(error) => panic!(
                    "C state unknown under outage ({context}) — refusing blind retire: {error:?}"
                ),
            }
        }
        // Retire first WITHOUT reads (the tick gate needs
        // /proc — dead under outage): discriminate by
        // kernel parenthood instead. waitpid == cpid ⟹ our
        // zombie, reaped; ECHILD ⟹ foreign-or-gone, hands
        // off; 0 ⟹ OUR live child (a foreigner would
        // ECHILD), safe to signal — the µs waitpid→kill
        // window matches the accepted gate→signal residual.
        // Sound: C is known-unreaped or tick-verified-ours
        // above, so no sibling can occupy the number.
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            let mut status = 0;
            // SAFETY: WNOHANG waitpid on the staged pid.
            let waited = unsafe { libc::waitpid(cpid, &mut status, libc::WNOHANG) };
            if waited == cpid {
                break;
            }
            if waited == -1 {
                let errno = std::io::Error::last_os_error().raw_os_error();
                if errno == Some(libc::ECHILD) {
                    break;
                }
                if errno == Some(libc::EINTR) {
                    continue;
                }
                panic!("waitpid on C failed unexpectedly: {errno:?} ({context})");
            }
            // Proven-ours live child — signal it (an ESRCH
            // race just means the next waitpid reaps).
            // SAFETY: signal-only to our proven-own child.
            unsafe {
                libc::kill(cpid, libc::SIGKILL);
            }
            assert!(
                Instant::now() < end,
                "C must drain for the skip ({context})"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        prove_drained_for_skip(cpid, ctick, context);
    }

    /// R20-010(3): an anchor/stat outage on the skip path
    /// must fail loud, never skip over an unproven C — the
    /// vacuous `assert_ne!` passed on `Err` (same outage as
    /// the anchor's, realistic under ambient EMFILE
    /// pressure) and skipped with a known-zombie C
    /// undrained. Stages a live own child C, exhausts the fd
    /// table, runs the skip-path helper: RED (vacuous
    /// shape): the assert passes on `Err` and returns
    /// normally (silent skip over a live C). GREEN: the
    /// helper retires C (fd-less kill+reap works exhausted),
    /// then the drained proof fails loud on `Err`. Requires
    /// the panic (loud) + C gone after restore (nothing
    /// stranded). Duration 929 is unique to this test.
    /// Fresh-image probe body (exhausts the fd table).
    #[cfg(target_arch = "x86_64")]
    fn skip_path_outage_fails_loud_probe() {
        let mut child = std::process::Command::new("/bin/sleep")
            .arg("929")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("sleeper spawns");
        let cpid = child.id() as libc::pid_t;
        let mut _cguard = FixtureGuard::new(cpid);
        let ctick = proc_starttime(cpid)
            .expect("sleeper stat readable")
            .expect("sleeper visible");
        let _confined = confine_fd_table_for_exhaustion();
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "exhaustion must consume fds");
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            retire_and_prove_drained_for_skip(
                cpid,
                ctick,
                SkipCRetireState::KnownUnreaped,
                "probe outage",
            );
        }));
        drop(held);
        let gone = proc_starttime(cpid) != Ok(Some(ctick));
        let _ = kill_tick_gated(cpid, ctick);
        let _ = child.kill();
        let _ = child.wait();
        _cguard.disarm();
        assert!(failed.is_err(), "outage must fail loud, never skip silent");
        assert!(gone, "outage path must not strand C");
        eprintln!("R20010-SKIP-OUTAGE-DONE");
    }

    /// R20-010(3) wrapper: the skip-outage probe runs
