    /// the parent cannot compare them).
    #[cfg(target_arch = "x86_64")]
    fn hup_probe_noop_body() {
        let want = super::super::orphan_hup_noop as *const () as usize;
        match super::super::hup_disposition_for_test() {
            Some(d) if d == want => eprintln!("HUP-PROBE-NOOP MATCH"),
            other => eprintln!("HUP-PROBE-NOOP MISMATCH {other:?}"),
        }
    }

    /// XRV1-R24 P4: re-exec'd probes carry
