    /// XRV1-R24-B: staged-python HUP shape —
    /// BARE (no immunity) dies of a directed
    /// HUP (proves the oracle: default
    /// disposition + the field murder shape),
    /// ARMORED (the SHARED production
    /// snippet) survives it. Directed kill()
    /// at our OWN children only (no group
    /// sends — no suite friendly fire).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn staged_python_hup_immunity_shape() {
        if !staged_probe_python3() {
            eprintln!("skip: python3 unavailable (no staged probes)");
            return;
        }
        let bare = "import os,sys,time\nprint('READY',flush=True)\ntime.sleep(30)\n";
        let armored = format!(
            "import os,sys,time{imm}\nprint('READY',flush=True)\ntime.sleep(30)\n",
            imm = STAGED_PROBE_HUP_IMMUNITY
        );
        for (name, script, must_die) in [
            ("bare", bare.to_string(), true),
            ("armored", armored, false),
        ] {
            let mut probe = std::process::Command::new("python3")
                .arg("-c")
                .arg(&script)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("staged python spawns");
            // Wait for READY (one line) —
            // the snippet installed before
            // it (both variants print first).
            let mut ready = String::new();
            {
                use std::io::BufRead as _;
                let out = probe.stdout.take().expect("piped stdout");
                std::io::BufReader::new(out)
                    .read_line(&mut ready)
                    .expect("READY readable");
            }
            assert!(
                ready.contains("READY"),
                "{name}: python must print READY\n{ready}"
            );
            let pid = probe.id() as libc::pid_t;
            assert_eq!(
                unsafe { libc::kill(pid, libc::SIGHUP) },
                0,
                "{name}: directed HUP sends"
            );
            std::thread::sleep(std::time::Duration::from_millis(200));
            let status = probe.try_wait().expect("try_wait works");
            if must_die {
                assert!(status.is_some(), "bare: unprotected python must die of HUP");
            } else {
                assert!(status.is_none(), "armored: immune python must survive HUP");
                let _ = probe.kill();
            }
            let _ = probe.wait();
        }
        eprintln!("STAGED-PYTHON-HUP-SHAPE bare-dies/armored-survives");
    }

    /// XRV1-R24-C: the immune sleeper
    /// survives a directed HUP (bare
    /// /bin/sleep dies — proving the oracle
    /// and the field murder shape). Directed
    /// kill() at our OWN children only (no
    /// group sends — no suite friendly
    /// fire). Also pins transparency: pid
    /// stable + comm/cmdline read `sleep`.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn hup_immune_sleeper_survives_directed_hup() {
        let mut bare = std::process::Command::new("/bin/sleep")
            .arg("30")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("bare sleep spawns");
        let mut immune = spawn_hup_immune_sleeper("30");
        // Settle (exec done): cmdline must
        // read `sleep 30` (exec replaced sh).
        let ipid = immune.id() as libc::pid_t;
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let cmd = std::fs::read_to_string(format!("/proc/{ipid}/cmdline"))
                .unwrap_or_default()
                .replace('\0', " ");
            if cmd.contains("sleep 30") {
                break;
            }
            assert!(
                std::time::Instant::now() < end,
                "immune sleeper must exec to sleep 30 (got {cmd:?})"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let bpid = bare.id() as libc::pid_t;
        assert_eq!(
            unsafe { libc::kill(bpid, libc::SIGHUP) },
            0,
            "HUP to bare sends"
        );
        assert_eq!(
            unsafe { libc::kill(ipid, libc::SIGHUP) },
            0,
            "HUP to immune sends"
        );
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(
            bare.try_wait().expect("try_wait works").is_some(),
            "bare sleep must die of HUP (oracle)"
        );
        assert!(
            immune.try_wait().expect("try_wait works").is_none(),
            "immune sleeper must survive HUP"
        );
        let _ = immune.kill();
        let _ = bare.wait();
        let _ = immune.wait();
        eprintln!("HUP-IMMUNE-SLEEPER bare-dies/immune-survives");
    }

    /// XRV1-R25 L145 probe body (fresh
    /// image, SCOPEBASE_SLEEPER_NOPATH=1,
    /// PATH=/nonexistent): BOTH sleeper
    /// variants must still exec to sleep
    /// (absolute path — no PATH lookup).
    /// Pre-fix RED: `exec sleep` exits 127
    /// under empty PATH.
    #[cfg(target_arch = "x86_64")]
    fn hup_immune_sleeper_nopath_body() {
        let mut plain = spawn_hup_immune_sleeper("31");
        let mut grouped = spawn_hup_immune_sleeper_grouped("32");
        // SAFETY: getpgid queries only.
        let gpid = grouped.id() as libc::pid_t;
        assert_eq!(
            unsafe { libc::getpgid(gpid) },
            gpid,
            "grouped variant must lead its own group"
        );
        for (child, want) in [(&mut plain, "sleep 31"), (&mut grouped, "sleep 32")] {
            let pid = child.id();
            let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                assert!(
                    child.try_wait().expect("try_wait works").is_none(),
                    "{want}: sleeper must not exit (127 = PATH lookup)"
                );
                let cmd = std::fs::read_to_string(format!("/proc/{pid}/cmdline"))
                    .unwrap_or_default()
                    .replace('\0', " ");
                if cmd.contains(want) {
                    break;
                }
                assert!(
                    std::time::Instant::now() < end,
                    "{want}: sleeper must exec (got {cmd:?})"
                );
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
        }
        let _ = plain.kill();
        let _ = grouped.kill();
        let _ = plain.wait();
        let _ = grouped.wait();
        eprintln!("HUP-SLEEPER-NOPATH both-variants-exec");
    }

    /// XRV1-R25 L145: immune sleepers must
    /// not depend on PATH (regression vs
    /// the prior absolute /bin/sleep
    /// launches). Re-exec under
    /// PATH=/nonexistent (P4/P5 pattern —
