                        | "enum"
                        | "extern"
                        | "fn"
                        | "for"
                        | "if"
                        | "impl"
                        | "in"
                        | "let"
                        | "loop"
                        | "match"
                        | "mod"
                        | "move"
                        | "mut"
                        | "pub"
                        | "ref"
                        | "return"
                        | "static"
                        | "struct"
                        | "trait"
                        | "type"
                        | "unsafe"
                        | "use"
                        | "where"
                        | "while"
                        | "async"
                        | "await"
                        | "dyn"
                        | "abstract"
                        | "become"
                        | "box"
                        | "do"
                        | "final"
                        | "macro"
                        | "override"
                        | "priv"
                        | "super"
                        | "typeof"
                        | "unsized"
                        | "virtual"
                        | "yield"
                        | "try"
                        | "true"
